// ── CENTRAL ERROR LOGGING ─────────────────────────────────────
// Generates unique error ID for support tracking
function generateErrorId(){
  return 'ERR-'+Date.now().toString(36).toUpperCase()+'-'+Math.random().toString(36).substr(2,4).toUpperCase();
}

// Determine severity from error content
function getErrorSeverity(msg='',module=''){
  if(!msg) return 'error';
  const m=msg.toLowerCase();
  if(m.includes('jwt expired')||m.includes('session')||m.includes('unauthorized'))return 'warning';
  if(m.includes('payment')||m.includes('invoice')||m.includes('payroll')||m.includes('finance'))return 'critical';
  if(m.includes('network')||m.includes('failed to fetch'))return 'warning';
  if(m.includes('insufficient')||m.includes('not found'))return 'warning';
  return 'error';
}

// Central error logger — writes to error_logs table
async function logError(module, action, error, context={}){
  try{
    const errId  = generateErrorId();
    const errMsg = error?.message || String(error||'Unknown error');
    const severity = getErrorSeverity(errMsg, module);

    // Log to console with error ID (for support)
    console.error(`[${errId}] ${module}/${action}:`, errMsg, context);

    // Skip logging auth errors (not meaningful to store)
    if(errMsg.includes('JWT expired')||errMsg.includes('Invalid JWT')) return errId;

    // Write to error_logs (non-blocking — never throws)
    sb.from('error_logs').insert({
      error_id:    errId,
      user_id:     currentProfile?.id || null,
      user_role:   currentProfile?.role || null,
      module:      module,
      action:      action,
      error_msg:   errMsg.substring(0, 1000),
      error_code:  error?.code || error?.status || null,
      stack:       error?.stack?.substring(0,500) || null,
      url:         window.location.pathname,
      user_agent:  navigator.userAgent.substring(0,200),
      severity:    severity,
      created_at:  new Date().toISOString()
    }).then(({error:dbErr})=>{
      if(dbErr) console.warn('Error log write failed (non-critical):',dbErr.message);
    }).catch(()=>{});

    return errId;
  }catch(e){
    console.warn('logError itself failed:',e);
    return null;
  }
}

// Show user-friendly error toast with error ID
async function showErrorWithId(module, action, error, userMessage=''){
  const errId = await logError(module, action, error);
  const msg = userMessage || error?.message || 'An error occurred';
  const display = errId ? `${msg} [${errId}]` : msg;
  showToast(display, 'error');
  return errId;
}

window.addEventListener('unhandledrejection', e=>{
  const msg = e.reason?.message||String(e.reason||'');
  // Session expired — force logout
  if(msg.includes('JWT expired')||msg.includes('Invalid JWT')||msg.includes('token is expired')){
    showToast('Session expired — please sign in again','error');
    setTimeout(()=>doLogout(), 1500);
    e.preventDefault(); return;
  }
  // Network error
  if(msg.includes('Failed to fetch')||msg.includes('NetworkError')){
    showToast('Network error — check your connection','error');
    logError('Network','unhandled_rejection',e.reason);
    e.preventDefault(); return;
  }
  // Numbering failures must be visible (the record was NOT saved)
  if(e.reason?.name==='NumberingError'){ showToast(msg,'error'); e.preventDefault(); return; }
  // Log everything else
  logError('Unknown','unhandled_rejection',e.reason);
  console.warn('Unhandled rejection:', msg);
});

