// ── BUTTON PROTECTION ────────────────────────────────────────
// Prevent double-clicks on any .btn-primary or .btn-danger
document.addEventListener('click', e=>{
  const btn = e.target.closest('button');
  if(!btn) return;
  if(btn.dataset.protected) return; // already protected
  if(btn.classList.contains('btn-primary')||btn.classList.contains('btn-danger')){
    btn.dataset.protected = '1';
    setTimeout(()=>{ delete btn.dataset.protected; }, 3000);
  }
}, true);

