// ── FORM VALIDATION HELPERS ─────────────────────────────────
function validNum(id,label,min=0,max=Infinity){
  const el=document.getElementById(id);
  if(!el) return null;
  const raw=el.value.trim();
  if(raw===''||raw===null){showToast(label+' is required','error');el.focus();return null;}
  const n=Number(raw);
  if(isNaN(n)){showToast(label+' must be a valid number','error');el.focus();return null;}
  if(n<min){showToast(label+' must be ≥ '+min,'error');el.focus();return null;}
  if(n>max){showToast(label+' must be ≤ '+max,'error');el.focus();return null;}
  return n;
}
function validText(id,label,minLen=1){
  const el=document.getElementById(id);
  if(!el) return null;
  const v=el.value.trim();
  if(v.length<minLen){showToast(label+' is required','error');el.focus();return null;}
  return v;
}
function validSelect(id,label){
  const el=document.getElementById(id);
  if(!el||!el.value){showToast(label+' is required','error');if(el)el.focus();return null;}
  return el.value;
}

const fmtK = v=>{v=Number(v||0);if(v>=1e6)return(v/1e6).toFixed(2)+'M';if(v>=1e3)return(v/1e3).toFixed(0)+'K';return v.toFixed(0)};
const fmtKWD = v=>'KWD '+fmtK(v);
const pill = (v,c)=>{const col=c||SC[v]||'#94A3B8';return`<span class="pill" style="color:${esc(col)};background:${esc(col)}22;border:1px solid ${esc(col)}44">${esc(String(v||'').replace(/_/g,' '))}</span>`};
const kpi = (lbl,val,c,sub)=>`<div class="kpi" style="--kpi-color:${c||'#C9A84C'}"><div class="kpi-lbl">${lbl}</div><div class="kpi-val">${val}</div>${sub?`<div class="kpi-sub">${sub}</div>`:''}</div>`;
const cpiColor = v=>Number(v)>=1?'#10B981':Number(v)>=0.9?'#F97316':'#EF4444';
const ragScore = p=>{const cpi=Number(p.cpi);if(p.spi==null)return null;return Math.min(cpi,Number(p.spi));};
const rag = v=>v===null?'⚪':v>=1?'🟢':v>=0.9?'🟡':'🔴';
const esc = s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
// Safe JavaScript argument for inline event handlers. HTML escaping alone is not sufficient
// because the browser decodes entities before evaluating the onclick JavaScript.
const jsArg = v=>esc(JSON.stringify(String(v==null?'':v)));

let _toastT;
// Network failures from supabase-js surface as "Failed to fetch" — translate to an actionable message
const NET_ERR_RE=/Failed to fetch|NetworkError|Load failed|network request failed|ERR_INTERNET_DISCONNECTED/i;
function showToast(msg,type='success'){
  if(NET_ERR_RE.test(String(msg))){
    msg='⚠️ Network error — nothing was saved. Your form is still open: check the connection and try again.';
    type='error';
  }
  const t=document.getElementById('toast');
  if(_toastT)clearTimeout(_toastT);
  t.textContent=msg;t.className=`toast show ${type}`;
  _toastT=setTimeout(()=>{t.className='toast';},3500);
}

// ── OFFLINE INDICATOR ─────────────────────────────────────────
// Persistent banner while the browser is offline; saves made offline fail with a clear message
// (showToast above) and modals stay open, so no typed data is lost.
(function(){
  const show=()=>{
    if(document.getElementById('sp360-offline')) return;
    const b=document.createElement('div');
    b.id='sp360-offline'; b.setAttribute('role','status');
    b.textContent='⚠️ You are offline — changes cannot be saved until the connection is restored.';
    b.style.cssText='position:fixed;top:0;left:0;right:0;z-index:10000;background:#EF4444;color:#fff;'+
      'font-family:inherit;font-size:12px;font-weight:600;line-height:1.4;text-align:center;padding:6px 12px;box-shadow:0 2px 8px #0006';
    document.body.appendChild(b);
  };
  const hide=()=>{ const b=document.getElementById('sp360-offline'); if(b){ b.remove(); showToast('✅ Back online'); } };
  window.addEventListener('offline',show);
  window.addEventListener('online',hide);
  if(navigator.onLine===false) document.addEventListener('DOMContentLoaded',show);
})();

// CRITICAL_AUDIT_ACTIONS: audit failure on these is surfaced to user, not silently swallowed
const CRITICAL_AUDIT_ACTIONS=new Set([
  'SUBMITTED','APPROVED','REJECTED','INVOICE_CREATED','INVOICE_APPROVED',
  'PO_APPROVED','BASELINE_SET','USER_MODIFIED','VENDOR_APPROVED',
  'LIFECYCLE_ADVANCE','PROGRESS_UPDATE'
]);
async function writeAudit(entity_type,entity_id,action,old_val,new_val,notes='',{strict=false}={}){
  if(!currentProfile?.id) return;
  const isCritical=strict||CRITICAL_AUDIT_ACTIONS.has(action);
  try{
    const {error}=await sb.from('audit_log').insert({
      entity_type,entity_id,action,
      old_values:old_val?JSON.stringify(old_val):null,
      new_values:new_val?JSON.stringify(new_val):null,
      performed_by:currentProfile.id,
      notes
    });
    if(error) throw error;
  }catch(e){
    if(isCritical){
      showToast(`⚠️ Audit log failed for ${action}. Operation recorded but not audited. Contact PMO.`,'error');
      console.error('CRITICAL audit write failed:',entity_type,action,e);
    } else {
      console.warn('Audit write failed:',e);
    }
  }
}

