// Wrap any page load in a safe container that shows errors clearly
function pageError(pageId, err){
  const el=document.getElementById(pageId);
  if(!el) return;
  const msg=err?.message||String(err||'Unknown error');
  // Session expired
  if(msg.includes('JWT')||msg.includes('not authenticated')||msg.includes('401')){
    showToast('Session expired — please sign in again','error');
    setTimeout(()=>doLogout(), 1500);
    return;
  }
  el.innerHTML=`
  <div style="padding:40px;text-align:center">
    <div style="font-size:32px;margin-bottom:12px">⚠️</div>
    <div style="font-size:14px;font-weight:700;color:var(--text);margin-bottom:8px">Failed to load page</div>
    <div style="font-size:11px;color:var(--muted);margin-bottom:16px;font-family:monospace;background:#0D1B2A;padding:8px 12px;border-radius:6px;display:inline-block">${esc(msg)}</div>
    <br><button class="btn btn-ghost btn-sm" data-h-click="h76">↺ Refresh Page</button>
  </div>`;
}

// ── AUTH ─────────────────────────────────────────────────────
async function doLogin(){
  if(_mfaLock||_loginBusy) return; // P0-1: no re-entry while MFA gate is open / login in flight
  _loginBusy=true;
  try{ await _doLogin(); } finally{ _loginBusy=false; }
}
let _loginBusy=false;
async function _doLogin(){
  const email=document.getElementById('login-email').value.trim();
  const pass=document.getElementById('login-pass').value;
  const errEl=document.getElementById('auth-error');
  const btn=document.getElementById('btn-login');
  errEl.style.display='none';
  if(!email||!pass){errEl.textContent='Email and password required.';errEl.style.display='block';return;}
  btn.disabled=true;btn.textContent='Signing in…';
  try{
    const {data,error}=await sb.auth.signInWithPassword({email,password:pass});
    if(error){
      errEl.textContent='Invalid email or password.';
      errEl.style.display='block';
      btn.disabled=false;btn.textContent='Sign In';
      return;
    }
    currentUser=data.user;
    await loadProfile(); // throws if profile missing/error → stops here
    // P0-1: Mandatory MFA gate — fails CLOSED; app stays hidden until aal2 is confirmed
    if(!(await enforceMFA())) return;
    if(!localStorage.getItem('sp360_session_start'))
      localStorage.setItem('sp360_session_start',String(Date.now()));
    enterApp();
  }catch(e){
    // loadProfile already handled the UI error message
    btn.disabled=false;btn.textContent='Sign In';
    currentUser=null;
    currentProfile=null;
  }
}

async function loadProfile(){
  const errEl=document.getElementById('auth-error');
  try{
    const {data,error}=await sb.from('user_profiles').select('*').eq('id',currentUser.id).single();

    // 🔴 CRITICAL: فشل قراءة الـ profile أو عدم وجوده = logout فوري — ممنوع أي fallback
    if(error){
      console.error('Profile load error:',error.message);
      await sb.auth.signOut().catch(()=>{});
      currentUser=null;
      errEl.textContent='Account not configured. Contact your system administrator.';
      errEl.style.display='block';
      document.getElementById('btn-login').disabled=false;
      document.getElementById('btn-login').textContent='Sign In';
      throw new Error('Profile error: '+error.message);
    }
    if(!data){
      console.error('Profile not found for user:', currentUser.id);
      await sb.auth.signOut().catch(()=>{});
      currentUser=null;
      errEl.textContent='User profile not found. Contact your system administrator.';
      errEl.style.display='block';
      document.getElementById('btn-login').disabled=false;
      document.getElementById('btn-login').textContent='Sign In';
      throw new Error('Profile not found');
    }

    // Profile loaded successfully
    currentProfile=data;
    document.getElementById('user-av').textContent=data.initials||data.full_name?.substring(0,2)||'?';
    document.getElementById('user-av').style.background=(data.color||'#C9A84C')+'33';
    document.getElementById('user-av').style.color=data.color||'#C9A84C';
    document.getElementById('user-name').textContent=data.full_name||'—';
    document.getElementById('user-role').textContent=data.role||'—';

  }catch(e){
    // Re-throw so doLogin() stops and doesn't call enterApp()
    throw e;
  }
}

// ── P0-1: MFA GATE (single enforcement point for ALL entry paths) ─────────
// Contract: returns true ONLY when the role does not require MFA, or the
// session is confirmed aal2 by Supabase. Any error/cancel → sign out → false.
// Called by doLogin() and bootstrapSession() BEFORE enterApp().
// NOTE: This is UX enforcement. The authoritative control is RLS checking
// (auth.jwt()->>'aal')='aal2' — see sp360_security_migration.sql.
const MFA_FLOOR_ROLES=['Admin','PMO Manager','Finance Manager']; // DB config may ADD roles, never remove these
let _mfaPassed=false;        // set ONLY by enforceMFA(); enterApp() refuses MFA roles without it
let _mfaLock=false;           // while true, closeModal()/Escape/overlay-click cannot dismiss the gate
let _mfaGate=null;            // {resolve, factorId, mode}
function mfaRequiredFor(role){
  const req=new Set([...MFA_FLOOR_ROLES,...(SESSION_CONFIG.MFA_REQUIRED_ROLES||[])]);
  return req.has(role);
}
async function _mfaFail(msg){
  _mfaLock=false;_mfaGate=null;
  closeModal();
  try{ await sb.auth.signOut(); }catch(_){}
  currentUser=null;currentProfile=null;
  const loader=document.getElementById('app-loading');if(loader)loader.style.display='none';
  const app=document.getElementById('app');if(app)app.style.display='none';
  const auth=document.getElementById('auth-screen');if(auth)auth.style.display='flex';
  const errEl=document.getElementById('auth-error');
  if(errEl){errEl.textContent=msg;errEl.style.display='block';}
  const btn=document.getElementById('btn-login');
  if(btn){btn.disabled=false;btn.textContent='Sign In';}
}
function _mfaGateModal(title,bodyHtml){
  _mfaLock=true;
  openModal(title,bodyHtml+
    '<div class="modal-foot">'+
      '<button class="btn btn-ghost" data-h-click="h77">Sign out</button>'+
      '<button class="btn btn-primary" id="mfa-gate-btn" data-h-click="h78">Verify</button>'+
    '</div>');
  setTimeout(()=>document.getElementById('mfa-gate-code')?.focus(),50);
}
const _mfaCodeInput='<div class="form-field"><label>6-Digit Code</label>'+
  '<input id="mfa-gate-code" type="text" placeholder="000000" maxlength="6" inputmode="numeric" autocomplete="one-time-code" '+
  ' data-h-keydown="h79" '+
  'style="font-size:22px;text-align:center;letter-spacing:6px;font-family:monospace;width:100%"/></div>';

async function mfaGateVerify(e){
  if(!_mfaGate) return;
  const btn=document.getElementById('mfa-gate-btn');
  const code=(document.getElementById('mfa-gate-code')?.value||'').trim();
  if(!/^\d{6}$/.test(code)){showToast('Enter the 6-digit code','error');return;}
  if(btn){btn.disabled=true;btn.textContent='Verifying…';}
  try{
    const {data:ch,error:ce}=await sb.auth.mfa.challenge({factorId:_mfaGate.factorId});
    if(ce) throw ce;
    const {error:ve}=await sb.auth.mfa.verify({factorId:_mfaGate.factorId,challengeId:ch.id,code});
    if(ve){showToast('Invalid code — try again','error');return;}
    const g=_mfaGate;_mfaGate=null;_mfaLock=false;closeModal();
    g.resolve(true);
  }catch(err){
    showToast('MFA error: '+(err?.message||err),'error');
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Verify';}
  }
}
function mfaGateCancel(){
  const g=_mfaGate;_mfaGate=null;_mfaLock=false;closeModal();
  if(g) g.resolve(false);
}

async function enforceMFA(){
  if(!currentProfile?.role) { await _mfaFail('Profile not loaded.'); return false; }
  _mfaPassed=false;
  if(!mfaRequiredFor(currentProfile.role)) return true;
  try{
    const {data:aal,error:aalErr}=await sb.auth.mfa.getAuthenticatorAssuranceLevel();
    if(aalErr) throw aalErr;
    if(aal?.currentLevel==='aal2'){ _mfaPassed=true; return true; }

    const {data:f,error:fErr}=await sb.auth.mfa.listFactors();
    if(fErr) throw fErr;
    const allTotp=(f?.all||[]).filter(x=>x.factor_type==='totp');
    const verified=allTotp.filter(x=>x.status==='verified');

    const loader=document.getElementById('app-loading');if(loader)loader.style.display='none';
    document.getElementById('app').style.display='none';
    document.getElementById('auth-screen').style.display='flex';

    let factorId,title,body;
    if(verified.length){
      factorId=verified[0].id;
      title='MFA Required';
      body='<p style="font-size:12px;color:var(--muted);margin:0 0 12px">Role <b>'+esc(currentProfile.role)+'</b> requires Two-Factor Authentication. Enter the code from your authenticator app.</p>'+_mfaCodeInput;
    }else{
      // Remove abandoned (unverified) enrollments so enroll() does not collide
      for(const u of allTotp.filter(x=>x.status!=='verified')){
        await sb.auth.mfa.unenroll({factorId:u.id}).catch(()=>{});
      }
      const {data:en,error:er}=await sb.auth.mfa.enroll({factorType:'totp',friendlyName:'SP360-'+Date.now()});
      if(er||!en?.id) throw (er||new Error('enrollment returned no factor'));
      factorId=en.id;
      const qr=String(en.totp?.qr_code||'');
      const qrSafe=/^data:image\/(svg\+xml|png)/.test(qr)?qr:'';
      title='Enable MFA (mandatory)';
      body='<p style="color:var(--muted);font-size:12px;margin:0 0 12px">Your role <b>'+esc(currentProfile.role)+'</b> requires MFA. Scan with Google/Microsoft Authenticator or Authy, then enter the 6-digit code.</p>'+
        (qrSafe?'<div style="text-align:center;margin:10px 0"><img src="'+esc(qrSafe)+'" alt="MFA QR" style="width:160px;height:160px;border:3px solid var(--gold);border-radius:8px;background:#fff;padding:4px"/></div>':'')+
        '<p style="font-size:10px;color:var(--muted);text-align:center;font-family:monospace;margin-bottom:10px;word-break:break-all">'+esc(en.totp?.secret||'')+'</p>'+
        _mfaCodeInput;
    }
    const ok=await new Promise(resolve=>{
      _mfaGate={resolve,factorId,mode:verified.length?'challenge':'enroll'};
      _mfaGateModal(title,body);
    });
    if(!ok){ if(currentUser) await _mfaFail('MFA is required for your role. Signed out.'); return false; }

    // Re-confirm with Supabase — never trust the UI path alone
    const {data:aal2,error:e2}=await sb.auth.mfa.getAuthenticatorAssuranceLevel();
    if(e2||aal2?.currentLevel!=='aal2'){ await _mfaFail('MFA verification could not be confirmed. Signed out.'); return false; }
    if(verified.length===0) showToast('✅ MFA enabled');
    _mfaPassed=true;
    return true;
  }catch(e){
    console.error('MFA gate error:',e);
    const m=String(e?.message||'');
    const hint=/enroll is disabled/i.test(m)
      ? 'TOTP enrollment is disabled in Supabase (Authentication → Multi-Factor). Ask the system administrator to enable it.'
      : /verif\w* (is )?disabled/i.test(m)
      ? 'TOTP verification is disabled in Supabase (Authentication → Multi-Factor). Ask the system administrator to enable it.'
      : m;
    await _mfaFail('MFA check failed — access denied. '+hint);
    return false;
  }
}

// ── SINGLE AUTH BOOTSTRAP GUARD (P0-FIX) ─────────────────────────────────
// enterApp() is the sole entry point into the application.
// _enterAppDone prevents concurrent or duplicate calls from bootstrapSession()
// and the window.load handler. Do NOT call enterApp() from any other path.
let _enterAppDone=false;
function enterApp(){
  if(_enterAppDone)return;
  // P0-1 defense-in-depth: MFA roles cannot enter unless enforceMFA() confirmed aal2
  if(!currentProfile || (mfaRequiredFor(currentProfile.role) && !_mfaPassed)){
    console.error('enterApp blocked: MFA gate not satisfied');
    return;
  }
  _enterAppDone=true;
  document.getElementById('auth-screen').style.display='none';
  document.getElementById('app').style.display='flex';
  requestAnimationFrame(()=>{const n=document.querySelector('aside nav');if(n)n.scrollTop=0;});

  // ── Apply role-based nav visibility ──────────────────────
  const allowed = ROLE_PAGES[currentProfile?.role] || ['dashboard']; // P0-FIX: unknown role gets dashboard only, not all pages
  document.querySelectorAll('.nav-btn[id^="nav-"]').forEach(btn=>{
    const pageId = btn.id.replace('nav-','');
    if(pageId==='dashboard') return;
    btn.style.display = allowed.includes(pageId) ? '' : 'none';
  });

  // ── Grouped, collapsible sidebar + Ctrl+K page search ─────
  initNavGroups();

  // ── Apply role badge color in sidebar ─────────────────────
  const roleEl = document.getElementById('user-role');
  if(roleEl){
    roleEl.style.display = '';
    roleEl.style.color   = roleBadgeColor(currentProfile?.role);
    roleEl.style.fontWeight = '700';
  }

  // ── Hide action buttons based on permissions ──────────────
  // Delete buttons
  document.querySelectorAll('.btn-delete,[data-perm="delete"]').forEach(el=>{
    el.style.display = can('delete') ? '' : 'none';
  });
  // Manage Users link
  const navUsers = document.getElementById('nav-users');
  if(navUsers) navUsers.style.display = can('manageUsers') ? '' : 'none';

  // ── Access denied guard for direct navTo calls ────────────
  window._rbacReady = true;
  // Pre-cache lookups for modals
  Promise.all([
    sb.from('employees').select('id,full_name,employee_no').eq('status','active').order('full_name'),
    sb.from('user_profiles').select('id,full_name,role').order('full_name'),
    sb.from('projects').select('id,project_no,name').in('status',['planning','execution','monitoring','closeout']).order('project_no'),
    sb.from('material_master').select('id,item_code,item_name').eq('is_active',true).order('item_code')
  ]).then(([{data:_e},{data:_u},{data:_p},{data:_i}])=>{
    window._cachedEmployees=_e||[];
    window._cachedUsers=_u||[];
    window._cachedProjects=_p||[];
    window._cachedItems=_i||[];
  });
  const sn=document.querySelector('aside nav');
  if(sn){sn.scrollTop=0;}
  requestAnimationFrame(()=>{const n=document.querySelector('aside nav');if(n)n.scrollTop=0;});
  setTimeout(()=>{const n=document.querySelector('aside nav');if(n)n.scrollTop=0;},500);
  navTo('dashboard',document.querySelector('.nav-btn.active'));
  // P2-1: Init Notifications Center
  setTimeout(()=>{ initNotifRealtime(); _silentRefreshNotifs(); }, 1200);
  setTimeout(()=>{ runScheduledNotifications(); }, 3000);
  setTimeout(()=>{ initFAB(); }, 1500);
  setTimeout(()=>{runKPIAlerts(false);},4000);
  setTimeout(()=>{ checkCRMAlerts(); }, 5000); // P1-C: CRM overdue + expiring alerts
  loadWfBadge();
  initRealtime();
  initSessionGuard();
  // Show MFA button for roles that require it
  if(SESSION_CONFIG.MFA_REQUIRED_ROLES.includes(currentProfile?.role)){
    const mfaBtn=document.getElementById('mfa-btn');
    if(mfaBtn) mfaBtn.style.display='inline-block';
  }
}

// ── Session Configuration (single source of truth) ──────────
const SESSION_CONFIG = {
  IDLE_MS:     30 * 60 * 1000,            // 30 min idle (matches sp360_config)
  ABSOLUTE_MS:  8 * 60 * 60 * 1000,       // 8 hours absolute (matches sp360_config)
  MFA_REQUIRED_ROLES: ['Admin','PMO Manager','Finance Manager'], // Mandatory for sensitive roles
};
// Load session config from database (overrides defaults if available)
(async()=>{
  try{
    const {data:cfg}=await sb.from('sp360_config')
      .select('key,value')
      .in('key',['session_idle_ms','session_absolute_ms','mfa_required_roles']);
    if(cfg&&cfg.length){
      cfg.forEach(row=>{
        if(row.key==='session_idle_ms') SESSION_CONFIG.IDLE_MS=Number(row.value);
        if(row.key==='session_absolute_ms') SESSION_CONFIG.ABSOLUTE_MS=Number(row.value);
        if(row.key==='mfa_required_roles') SESSION_CONFIG.MFA_REQUIRED_ROLES=row.value.split(',').map(r=>r.trim());
      });
    }
  }catch(e){ console.warn('sp360_config load failed, using defaults:',e?.message); }
})();
const SESSION_IDLE_MS = SESSION_CONFIG.IDLE_MS;
const SESSION_ABS_MS  = SESSION_CONFIG.ABSOLUTE_MS;
let _idleTimer=null,_absTimer=null;
function resetIdleTimer(){clearTimeout(_idleTimer);_idleTimer=setTimeout(()=>{showToast('Session expired','error');setTimeout(doLogout,2000);},SESSION_IDLE_MS);}
function initSessionGuard(){['mousemove','keydown','click','touchstart'].forEach(e=>document.addEventListener(e,resetIdleTimer,{passive:true}));resetIdleTimer();clearTimeout(_absTimer);_absTimer=setTimeout(()=>{showToast('Session exceeded 8 hours','error');setTimeout(doLogout,2000);},SESSION_ABS_MS);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&_notifDrawerOpen)closeNotifDrawer();},{passive:true});}
function clearSessionGuard(){clearTimeout(_idleTimer);clearTimeout(_absTimer);}

// ── REALTIME ─────────────────────────────────────────────────
let _realtimeChannel = null;
let _realtimeDebounce = {};

function initRealtime(){
  // Clean up existing subscription
  if(_realtimeChannel){
    try{ sb.removeChannel(_realtimeChannel); }catch(e){}
    _realtimeChannel = null;
  }

  _realtimeChannel = sb
    .channel('sp360-erp-live')
    .on('postgres_changes',
      { event:'*', schema:'public', table:'projects' },
      (payload) => handleRealtimeUpdate('projects', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'workflow_items' },
      (payload) => handleRealtimeUpdate('workflow_items', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'change_orders' },
      (payload) => handleRealtimeUpdate('change_orders', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'invoices' },
      (payload) => handleRealtimeUpdate('invoices', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'crm_leads' },
      (payload) => handleRealtimeUpdate('crm_leads', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'crm_opportunities' },
      (payload) => handleRealtimeUpdate('crm_opportunities', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'crm_quotations' },
      (payload) => handleRealtimeUpdate('crm_quotations', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'crm_activities' },
      (payload) => handleRealtimeUpdate('crm_activities', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'crm_customers' },
      (payload) => handleRealtimeUpdate('crm_customers', payload)
    )
    .on('postgres_changes',
      { event:'*', schema:'public', table:'contracts' },
      (payload) => handleRealtimeUpdate('contracts', payload)
    )
    .subscribe((status) => {
      if(status === 'SUBSCRIBED'){
        console.log('SP360 Realtime: connected');
        showRealtimeBadge(true);
      } else if(status === 'CHANNEL_ERROR' || status === 'TIMED_OUT'){
        console.warn('SP360 Realtime:', status);
        showRealtimeBadge(false);
      }
    });
}

function showRealtimeBadge(connected){
  const badge = document.getElementById('pending-badge');
  if(!badge) return;
  // Show live indicator
  const liveEl = document.getElementById('realtime-dot');
  if(liveEl) liveEl.style.background = connected ? '#10B981' : '#EF4444';
}

function handleRealtimeUpdate(table, payload){
  // Debounce: avoid rapid re-renders (wait 800ms after last event)
  if(_realtimeDebounce[table]) clearTimeout(_realtimeDebounce[table]);
  _realtimeDebounce[table] = setTimeout(()=>{
    const activePage = document.querySelector('.page.active')?.id?.replace('page-','');
    // Show live toast for workflow changes
    if(table === 'workflow_items'){
      const evt = payload.eventType;
      const newRec = payload.new;
      if(evt === 'INSERT' || (evt === 'UPDATE' && newRec?.status)){
        showToast(`⚡ Workflow updated: ${newRec?.ref_no || 'item'} — ${newRec?.status || ''}`, 'success');
      }
      loadWfBadge(); // Always refresh badge
    }
    if(table === 'change_orders' && payload.eventType !== 'DELETE'){
      const newRec = payload.new;
      if(newRec?.workflow_status === 'submitted'){
        showToast(`📋 New CO submitted: ${newRec.co_no || ''}`, 'success');
      }
    }
    // ── CRM Realtime Toasts (P0-A) ──────────────────────────────────────────
    if(table === 'crm_leads' && payload.eventType === 'INSERT'){
      showToast(`🔍 New lead: ${payload.new?.company || payload.new?.full_name || '—'}`, 'success');
    }
    if(table === 'crm_opportunities'){
      const rec = payload.new;
      if(payload.eventType === 'INSERT') showToast(`🎯 New opportunity: ${rec?.title || '—'}`, 'success');
      else if(payload.eventType === 'UPDATE' && rec?.stage === 'won')  showToast(`🏆 Opportunity WON: ${rec?.title || '—'}`, 'success');
      else if(payload.eventType === 'UPDATE' && rec?.stage === 'lost') showToast(`❌ Opportunity lost: ${rec?.title || '—'}`, 'error');
    }
    if(table === 'crm_quotations' && payload.eventType === 'INSERT'){
      showToast(`📄 New quotation: ${payload.new?.quotation_no || '—'}`, 'success');
    }
    if(table === 'contracts' && payload.eventType === 'INSERT'){
      showToast(`✍️ New contract: ${payload.new?.contract_no || '—'}`, 'success');
    }
    // Refresh active page if relevant
    const pageMap = {
      projects:          ['projects','dashboard','ceo'],
      workflow_items:    ['workflow','dashboard','ceo'],
      change_orders:     ['projects','ceo'],
      invoices:          ['finance','dashboard','ceo'],
      crm_leads:         ['crm','dashboard'],
      crm_opportunities: ['crm','dashboard'],
      crm_quotations:    ['crm'],
      crm_activities:    ['crm'],
      crm_customers:     ['crm'],
      contracts:         ['crm','finance','dashboard']
    };
    const refreshPages = pageMap[table] || [];
    if(refreshPages.includes(activePage)){
      const loaders = {
        dashboard: loadDashboard, projects: ()=>loadProjects(curProjTab),
        workflow: loadWorkflow, finance: loadFinance, ceo: loadCEO,
        crm: ()=>{ if(typeof loadCRM==='function') loadCRM(curCRMTab||'customers'); }
      };
      if(loaders[activePage]) loaders[activePage]();
    }
  }, 800);
}

async function doLogout(){
  if(typeof clearSessionGuard==='function')clearSessionGuard();
  // Cleanup Realtime subscription first
  if(_realtimeChannel){
    try{ sb.removeChannel(_realtimeChannel); }catch(e){}
    _realtimeChannel = null;
  }
  // Sign out server-side
  try{ await sb.auth.signOut(); }catch(e){ console.warn('SignOut error:',e); }
  // Reset state
  currentUser=null; currentProfile=null; _enterAppDone=false;
  // Reload page for clean state — most reliable approach
  window.location.reload();
}

async function loadWfBadge(){
  // Update notification bell in header
  try{
    const {data:pending}=await sb.from('workflow_items')
      .select('id',{count:'exact'})
      .in('status',['pending','overdue'])
      .limit(1);
    const count=pending?.length||0;
    const bell=document.getElementById('notif-bell');
    const countEl=document.getElementById('notif-count');
    if(bell&&countEl){
      countEl.textContent=count;
      bell.style.display=count>0?'inline-block':'none';
    }
  }catch{}
  // Also update page title with pending count for awareness
  const {data}=await sb.from('workflow_items').select('id').in('status',['pending','overdue']);
  const count=(data||[]).length;
  document.getElementById('pending-badge').textContent=`⚡ ${count} pending`;
  const badge=document.getElementById('wf-badge');
  badge.style.display=count>0?'':'none';
  badge.textContent=count;
}

// ── NAVIGATION ───────────────────────────────────────────────
function toggleSide(){
  const side = document.getElementById('sidebar');
  if(window.innerWidth <= 600){
    // Mobile: overlay drawer from left
    const isOpen = side.classList.contains('mob-open');
    if(isOpen){
      side.classList.remove('mob-open');
      document.getElementById('mob-side-overlay')?.remove();
    } else {
      side.classList.add('mob-open');
      const ov = document.createElement('div');
      ov.id = 'mob-side-overlay';
      ov.style.cssText = 'position:fixed;inset:0;background:#00000066;z-index:899;';
      ov.onclick = toggleSide;
      document.body.appendChild(ov);
    }
  } else {
    side.classList.toggle('collapsed');
  }
}
function navTo(id,btn){
  // ── RBAC guard ─────────────────────────────────────────────
  if(window._rbacReady && id !== 'dashboard' && !canView(id)){
    showToast(`⛔ Access denied — your role (${currentProfile?.role||'Unknown'}) cannot view this page`,'error');
    return;
  }
  // ── Auto-close mobile sidebar ─────────────────────────────
  if(window.innerWidth <= 600){
    const side = document.getElementById('sidebar');
    if(side?.classList.contains('mob-open')) toggleSide();
  }
  document.querySelectorAll('.nav-btn').forEach(b=>b.classList.remove('active'));
  if(!btn) btn=document.getElementById('nav-'+id);
  if(btn)btn.classList.add('active');
  if(typeof navGroupReveal==='function') navGroupReveal(id);
  document.querySelectorAll('.page').forEach(p=>p.classList.remove('active'));
  const pg=document.getElementById('page-'+id);
  if(pg)pg.classList.add('active');
  const loaders={
    dashboard:loadDashboard,bizdev:loadBizdev,projects:loadProjects,
    gantt:loadGantt,
    procurement:()=>loadProc(curProcTab),finance:loadFinance,
    hr:()=>loadHR(curHRTab),qhse:()=>loadQHSE(curQHSETab),
    inventory:loadInventory,documents:()=>loadDocs(curDocTab),workflow:loadWorkflow,audit:loadAudit,
    users:loadUsers,ceo:loadCEO,system:loadSystem,resources:loadResources,scorecard:loadScorecard,contracts:loadContracts,lessons:loadLessons,forecast:loadForecast,reports:loadReports,training:loadTraining,assets:loadAssets,subcon:loadSubcon,meetings:loadMeetings,analytics:loadAnalytics,tender:loadTender,insurance:loadInsurance,appraisal:loadAppraisalB3,budget:loadBudget,correspondence:loadCorrespondence,benchmark:loadBenchmark,import:loadImportExport,sitediary:loadSiteDiary,punchlist:loadPunchList,expenses:loadExpenses,ai:loadAI,retention:loadRetention,sla:loadSLA,templates:loadTemplates,
    'crm-customers':loadCRMCustomers,'crm-leads':loadCRMLeads,'crm-opportunities':loadCRMOpportunities,
    'crm-pipeline':loadCRMPipeline,'crm-quotations':loadCRMQuotations,'crm-activities':loadCRMActivities,
    timetracking:loadTimeTracking, ratios:loadFinancialRatios, bulk:loadBulkOperations, weekly:loadWeeklyReport
  };
  if(loaders[id])loaders[id]();
}

// ── MODAL ────────────────────────────────────────────────────
function openModal(title,html){
  document.getElementById('modal-title').textContent=title;
  document.getElementById('modal-body').innerHTML=html;
  document.getElementById('modal-overlay').classList.add('open');
}
function closeModal(){
  if(_mfaLock) return; // P0-1: MFA gate cannot be dismissed — only Verify or Sign out
  document.getElementById('modal-overlay').classList.remove('open');
}

