function previewEV(projId, bac){
  const pct=Number(document.getElementById('pct_'+projId).value)||0;
  const ac=Number(document.getElementById('ac_'+projId).value)||0;
  const ev=bac*pct/100;
  const cpi=ac>0?(ev/ac).toFixed(2):'1.00';
  const evEl=document.getElementById('ev_'+projId);
  const cpiEl=document.getElementById('cpi_'+projId);
  if(evEl)evEl.textContent=fmtKWD(ev);
  if(cpiEl){cpiEl.textContent=cpi;cpiEl.style.color=cpiColor(cpi);}
}

async function saveProgress(e, projId, bac){
  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const pct      = Number(document.getElementById('pct_'+projId).value)||0;
    const ac       = Number(document.getElementById('ac_'+projId).value)||0;
    const evMethod = document.getElementById('evm_'+projId)?.value||'percent';
    // ── EV Calculation Engine — method-aware ──────────────────
    let ev;
    if(evMethod==='manual'){
      // Manual EV: read from dedicated input if present, else fall back to pct-based
      const manualEvEl = document.getElementById('manualev_'+projId);
      ev = manualEvEl ? Math.round(Number(manualEvEl.value)*1000)/1000
                      : Math.round(bac*pct/100*1000)/1000;
    } else if(evMethod==='milestone'){
      // Milestone EV: sum of approved milestone EVs stored on the project
      // Falls back to pct-based until milestone_ev field is populated
      const {data:msData}=await sb.from('projects').select('milestone_ev').eq('id',projId).single().catch(()=>({data:null}));
      ev = (msData&&msData.milestone_ev!=null)
           ? Math.round(Number(msData.milestone_ev)*1000)/1000
           : Math.round(bac*pct/100*1000)/1000;
    } else {
      // Percent Complete (default): EV = BAC × %
      ev = Math.round(bac*pct/100*1000)/1000;
    }
    const cpi = ac>0 ? Math.round(ev/ac*1000)/1000 : 1;

    // SPI from Baseline — null if no baseline (never fake 1.00)
    let pv=null;
    try{
      const {data:pvData}=await sb.rpc('get_current_pv',{p_project_id:projId});
      if(pvData&&Number(pvData)>0) pv=Number(pvData);
    }catch(e2){}
    const spi = pv!==null ? Math.round(ev/pv*1000)/1000 : null;

    const {data:proj}=await sb.from('projects').select('pct,ac,ev,cpi,spi').eq('id',projId).single();
    const upd={pct,ac,ev,cpi,ev_method:evMethod};
    if(pv!==null) upd.pv=pv;
    if(spi!==null) upd.spi=spi;

    const {error}=await sb.from('projects').update(upd).eq('id',projId);
    if(error){showToast('Error: '+error.message,'error');return;}

    await writeAudit('projects',projId,'PROGRESS_UPDATE',
      {pct:proj?.pct,ac:proj?.ac,ev:proj?.ev,cpi:proj?.cpi,spi:proj?.spi},
      {pct,ac,ev,cpi,spi:spi??'N/A',ev_method:evMethod},
      'Progress updated — Method: '+evMethod);

    // Live cell updates — no full page reload
    const evEl =document.getElementById('ev_'+projId);
    const cpiEl=document.getElementById('cpi_'+projId);
    const spiEl=document.getElementById('spi_'+projId);
    if(evEl)  evEl.textContent=fmtKWD(ev);
    if(cpiEl){cpiEl.textContent=cpi.toFixed(2); cpiEl.style.color=cpiColor(cpi);}
    if(spiEl){
      spiEl.textContent=spi!==null?spi.toFixed(2):'N/A';
      spiEl.style.color=spi!==null?cpiColor(spi):'#94A3B8';
      spiEl.title=spi===null?'Create a Baseline to calculate SPI':'SPI = EV / PV from Baseline';
    }
    showToast(spi===null
      ? `Saved ✓ | CPI: ${cpi.toFixed(2)} | SPI: N/A (no baseline)`
      : `Saved ✓ | CPI: ${cpi.toFixed(2)} | SPI: ${spi.toFixed(2)}`);
  }catch(e3){showToast('Error: '+e3.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save';}}
}

// Lifecycle Transition Matrix
// Forward progression: Initiation→Planning→Execution→Monitoring→Closeout→Completed
// On Hold: any active stage can pause; resumes to same or adjacent stage
// Back-transitions (Monitoring→Execution, Closeout→Execution) are permitted for re-work
const LIFECYCLE_TRANSITIONS = {
  'initiation':  ['planning','cancelled'],
  'planning':    ['execution','on_hold','cancelled'],
  'execution':   ['monitoring','on_hold','cancelled'],
  'monitoring':  ['closeout','execution','on_hold','cancelled'],
  'closeout':    ['completed','execution'],
  'on_hold':     ['planning','execution','monitoring','cancelled'],
  'completed':   [],
  'cancelled':   []
};

async function advanceProject(projId, newStatus, event){
  if(!newStatus) return;
  // Validate transition
  const {data:proj}=await sb.from('projects').select('status,name').eq('id',projId).single();
  const currentStatus=proj?.status||'initiation';
  const allowed=LIFECYCLE_TRANSITIONS[currentStatus]||[];
  if(!allowed.includes(newStatus)){
    showToast(`Invalid transition: ${PROJ_LIFECYCLE_LABELS[currentStatus]||currentStatus} → ${PROJ_LIFECYCLE_LABELS[newStatus]||newStatus}`,'error');
    loadProjects('lifecycle'); // reset dropdown
    return;
  }
  const {data:rpcData,error}=await sb.rpc('advance_project_lifecycle',{
    p_project_id:   projId,
    p_new_status:   newStatus,
    p_performed_by: currentProfile?.id
  });
  if(error){showToast('Error: '+error.message,'error');return;}
  if(!rpcData?.ok){showToast('Transition not allowed: '+(rpcData?.error||'Unknown'),'error');loadProjects('lifecycle');return;}
  showToast(`${proj?.name?.split('—')[0]?.trim()||'Project'} → ${PROJ_LIFECYCLE_LABELS[newStatus]||newStatus} ✓`);
  loadProjects('lifecycle');
}

