async function savePO(e){
  const projId=validSelect('po-proj','Project'); if(!projId) return;
  const vendId=validSelect('po-vendor','Vendor'); if(!vendId) return;
  const desc=validText('po-desc','Description'); if(!desc) return;
  const val=validNum('po-val','Total Value',0.001); if(val===null) return;
  const poNo=document.getElementById('po-no').value.trim();
  const issueDate=document.getElementById('po-date').value;
  const delivery=document.getElementById('po-delivery').value;
  const terms=document.getElementById('po-terms').value.trim();

  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Creating…';}
  try{
    // ATOMIC: po_no generation + insert + audit in single DB transaction
    const {data,error}=await sb.rpc('save_po_atomic',{
      p_po_no:          poNo||null,
      p_project_id:     projId,
      p_vendor_id:      vendId,
      p_description:    desc,
      p_total_value:    val,
      p_issue_date:     issueDate||null,
      p_delivery_date:  delivery||null,
      p_terms:          terms||null,
      p_created_by:     currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Error: '+(data?.error||'Unknown error'),'error');return;}
    showToast(`PO ${data.po_no} created — click Submit to start approval ✓`);
    closeModal(); loadProc('pos');
  }catch(e){showToast('Error: '+e.message,'error');logError('Procurement','savePO',e);}
  finally{if(btn){btn.disabled=false;btn.textContent='Create PO (Draft)';}}
}

async function submitPO(e,poId){
  if(!confirm('Submit this PO for Dept. Approval?')) return;
  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Submitting…';}
  try{
    const {data,error}=await sb.rpc('submit_purchase_order',{p_po_id:poId});
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Submit failed: '+(data?.error||'Unknown'),'error');return;}
    showToast(`PO submitted — Ref: ${data.ref_no} ✓`);
    loadProc('pos'); loadWfBadge();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Submit ▶';}}
}

