// ── FINANCE ──────────────────────────────────────────────────
async function loadFinance(tab='overview'){
  curFinTab=tab||'overview';
  const el=document.getElementById('page-finance');
  try{
  el.innerHTML=`<div class="loading">Loading…</div>`;

  const {data:invList}=await sb.from('invoices')
    .select('*,project:projects(project_no,name,bac)')
    .order('created_at',{ascending:false});
  const ALL=invList||[];
  const today=new Date();
  const curMonth=new Date().toISOString().slice(0,7);

  const clientPaid   =ALL.filter(i=>i.invoice_type==='client'&&i.status==='paid');
  const clientPend   =ALL.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status));
  const supplierPaid =ALL.filter(i=>i.invoice_type!=='client'&&i.status==='paid');
  const supplierPend =ALL.filter(i=>i.invoice_type!=='client'&&!['paid','cancelled'].includes(i.status));

  const totalRevenue  =clientPaid.reduce((s,i)=>s+Number(i.net_amount),0);
  const totalCost     =supplierPaid.reduce((s,i)=>s+Number(i.net_amount),0);
  const arOutstanding =clientPend.reduce((s,i)=>s+Number(i.net_amount),0);
  const apOutstanding =supplierPend.reduce((s,i)=>s+Number(i.net_amount),0);
  const grossProfit   =totalRevenue-totalCost;
  const margin        =totalRevenue>0?(grossProfit/totalRevenue*100):0;
  const retentionHeld =ALL.filter(i=>i.invoice_type==='client'&&Number(i.retention_pct)>0)
    .reduce((s,i)=>s+Number(i.gross_amount)*Number(i.retention_pct)/100,0);
  const overdueAR=clientPend.filter(i=>i.due_date&&new Date(i.due_date)<today);

  const tabs=`<div class="tabs">
    ${['overview','ar','ap','cashflow','retention','coa','journal','trial','pl'].map((t,idx)=>
    `<button class="tab${t===tab?' act':''}" data-h-click="h140" data-ha-click="${esc(JSON.stringify([String((t)??'')]))}">
      ${['📊 Overview','📥 AR','📤 AP','💹 Cash Flow','🔒 Retention','📋 COA','📒 Journal','⚖️ Trial','📈 P&L'][idx]}
    </button>`).join('')}
  </div>`;

  let body='';

  if(tab==='overview'){
    body=`
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Revenue Collected',fmtKWD(totalRevenue),'#10B981','Client invoices paid')}
      ${kpi('AR Outstanding',fmtKWD(arOutstanding),overdueAR.length>0?'#EF4444':'#F97316',overdueAR.length>0?'⚠️ '+overdueAR.length+' overdue':'Pending collection')}
      ${kpi('Cost Paid',fmtKWD(totalCost),'#EF4444','Supplier invoices paid')}
      ${kpi('Gross Profit',fmtKWD(grossProfit),grossProfit>=0?'#C9A84C':'#EF4444',margin.toFixed(1)+'% of collected revenue')}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('AP Outstanding',fmtKWD(apOutstanding),'#8B5CF6','Supplier bills due')}
      ${kpi('Retention Held',fmtKWD(retentionHeld),'#3B82F6','Client retention')}
      ${kpi('Net Cash',fmtKWD(totalRevenue-totalCost-apOutstanding),totalRevenue-totalCost-apOutstanding>=0?'#10B981':'#EF4444','Collected minus paid')}
      ${kpi('This Month',ALL.filter(i=>i.created_at?.startsWith(curMonth)).length,'#E2E8F0','Invoices created')}
    </div>
    <table><thead><tr>
      <th>Invoice No</th><th>Project</th><th style="text-align:center">Type</th>
      <th style="text-align:right">Net (KWD)</th><th>Due Date</th>
      <th style="text-align:center">Status</th><th style="text-align:center">Action</th>
    </tr></thead><tbody>
    ${ALL.slice(0,20).map(i=>{
      const ov=i.due_date&&new Date(i.due_date)<today&&i.status!=='paid';
      const canSubmit=i.status==='draft';
      const canPaid=i.status==='approved'&&(currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager');
      return`<tr>
        <td style="color:var(--gold);font-size:10px;white-space:nowrap">${esc(i.invoice_no)}</td>
        <td style="color:var(--muted);font-size:11px">${esc(i.project?.project_no||'—')}</td>
        <td style="text-align:center">${pill(i.invoice_type,i.invoice_type==='client'?'#10B981':i.invoice_type==='supplier'?'#F97316':'#8B5CF6')}</td>
        <td style="text-align:right;font-weight:800;color:var(--gold)">${fmtKWD(i.net_amount)}</td>
        <td style="color:${ov?'#EF4444':'#94A3B8'};font-size:11px">${esc(i.due_date||'—')}${ov?' ⚠️':''}</td>
        <td style="text-align:center">${pill(i.status)}</td>
        <td style="text-align:center">
          ${canSubmit?`<button class="btn btn-primary btn-sm" style="font-size:10px;padding:3px 8px" data-h-click="h141" data-ha-click="${esc(JSON.stringify([String((i.id)??'')]))}">Submit ▶</button>`:''}
          ${canPaid?`<button class="btn btn-ghost btn-sm" style="font-size:10px;padding:3px 8px" data-h-click="h142" data-ha-click="${esc(JSON.stringify([String((i.id)??'')]))}">Mark Paid</button>`:''}
        </td>
      </tr>`;
    }).join('')}
    </tbody></table>`;

  } else if(tab==='ar'){
    const ar=ALL.filter(i=>i.invoice_type==='client');
    const aging={current:0,d30:0,d60:0,d90:0,d90p:0};
    ar.filter(i=>!['paid','cancelled'].includes(i.status)).forEach(i=>{
      if(!i.due_date){aging.current+=Number(i.net_amount);return;}
      const days=Math.floor((today-new Date(i.due_date))/(86400000));
      if(days<=0)aging.current+=Number(i.net_amount);
      else if(days<=30)aging.d30+=Number(i.net_amount);
      else if(days<=60)aging.d60+=Number(i.net_amount);
      else if(days<=90)aging.d90+=Number(i.net_amount);
      else aging.d90p+=Number(i.net_amount);
    });
    body=`
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total AR',fmtKWD(ar.reduce((s,i)=>s+Number(i.net_amount),0)),'#E2E8F0','All client invoices')}
      ${kpi('Collected',fmtKWD(totalRevenue),'#10B981','Paid')}
      ${kpi('Outstanding',fmtKWD(arOutstanding),overdueAR.length>0?'#EF4444':'#F97316',overdueAR.length+' overdue')}
      ${kpi('Collection Rate',totalRevenue+arOutstanding>0?((totalRevenue/(totalRevenue+arOutstanding))*100).toFixed(1)+'%':'—','#C9A84C','')}
    </div>
    <div class="card" style="margin-bottom:14px;padding:14px 16px">
      <div class="sec-title" style="margin-bottom:10px"><span>📅</span>AR Aging Analysis</div>
      <div style="display:grid;grid-template-columns:repeat(5,1fr);gap:8px;text-align:center">
        ${[['Current',aging.current,'#10B981'],['1–30 Days',aging.d30,'#F97316'],['31–60 Days',aging.d60,'#EF444499'],['61–90 Days',aging.d90,'#EF4444'],['90+ Days',aging.d90p,'#7F1D1D']].map(([l,v,c])=>
        `<div style="padding:10px;background:${c}18;border:1px solid ${c}44;border-radius:8px">
          <div style="font-size:10px;color:var(--muted);margin-bottom:4px">${l}</div>
          <div style="font-size:13px;font-weight:800;color:${c}">${fmtKWD(v)}</div>
        </div>`).join('')}
      </div>
    </div>
    <table><thead><tr>
      <th>Invoice No</th><th>Project</th><th style="text-align:right">Net (KWD)</th>
      <th>Due Date</th><th style="text-align:center">Days O/S</th>
      <th style="text-align:center">Status</th><th style="text-align:center">Action</th>
    </tr></thead><tbody>
    ${ar.map(i=>{
      const days=i.due_date&&!['paid','cancelled'].includes(i.status)?Math.floor((today-new Date(i.due_date))/86400000):null;
      const ov=days!==null&&days>0;
      const canPaid=i.status==='approved'&&(currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager');
      return`<tr>
        <td style="color:var(--gold);font-size:10px">${esc(i.invoice_no)}</td>
        <td style="font-size:11px;color:var(--muted)">${esc(i.project?.project_no||'—')}</td>
        <td style="text-align:right;font-weight:800;color:var(--gold)">${fmtKWD(i.net_amount)}</td>
        <td style="font-size:11px;color:${ov?'#EF4444':'var(--muted)'}">${esc(i.due_date||'—')}</td>
        <td style="text-align:center;font-weight:700;color:${ov?'#EF4444':days===null?'var(--faint)':'#10B981'}">
          ${days===null?'—':days<=0?Math.abs(days)+'d left':days+'d OD'}
        </td>
        <td style="text-align:center">${pill(i.status)}</td>
        <td style="text-align:center">
          ${canPaid?`<button class="btn btn-ghost btn-sm" style="font-size:10px;padding:2px 7px" data-h-click="h142" data-ha-click="${esc(JSON.stringify([String((i.id)??'')]))}">Paid ✓</button>`:''}
        </td>
      </tr>`;
    }).join('')}
    </tbody></table>`;

  } else if(tab==='ap'){
    const ap=ALL.filter(i=>i.invoice_type!=='client');
    const apPaid=ap.filter(i=>i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
    const apOv=supplierPend.filter(i=>i.due_date&&new Date(i.due_date)<today);
    body=`
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total AP',fmtKWD(ap.reduce((s,i)=>s+Number(i.net_amount),0)),'#E2E8F0','')}
      ${kpi('Paid',fmtKWD(apPaid),'#10B981','Settled')}
      ${kpi('Outstanding',fmtKWD(apOutstanding),apOv.length>0?'#EF4444':'#8B5CF6',apOv.length+' overdue')}
      ${kpi('Payment Rate',apPaid+apOutstanding>0?((apPaid/(apPaid+apOutstanding))*100).toFixed(1)+'%':'—','#C9A84C','')}
    </div>
    <table><thead><tr>
      <th>Invoice No</th><th>Project</th><th style="text-align:center">Type</th>
      <th style="text-align:right">Net (KWD)</th><th>Due Date</th>
      <th style="text-align:center">Days O/S</th><th style="text-align:center">Status</th>
      <th style="text-align:center">Action</th>
    </tr></thead><tbody>
    ${ap.map(i=>{
      const days=i.due_date&&!['paid','cancelled'].includes(i.status)?Math.floor((today-new Date(i.due_date))/86400000):null;
      const ov=days!==null&&days>0;
      const canPay=i.status==='approved'&&(currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager');
      return`<tr>
        <td style="color:var(--gold);font-size:10px">${esc(i.invoice_no)}</td>
        <td style="font-size:11px;color:var(--muted)">${esc(i.project?.project_no||'—')}</td>
        <td style="text-align:center">${pill(i.invoice_type,i.invoice_type==='supplier'?'#F97316':'#8B5CF6')}</td>
        <td style="text-align:right;font-weight:800;color:${ov?'#EF4444':'var(--gold)'}">${fmtKWD(i.net_amount)}</td>
        <td style="font-size:11px;color:${ov?'#EF4444':'var(--muted)'}">${esc(i.due_date||'—')}${ov?' ⚠️':''}</td>
        <td style="text-align:center;font-weight:700;color:${ov?'#EF4444':days===null?'var(--faint)':'#10B981'}">
          ${days===null?'—':days<=0?Math.abs(days)+'d left':days+'d OD'}
        </td>
        <td style="text-align:center">${pill(i.status)}</td>
        <td style="text-align:center">
          ${canPay?`<button class="btn btn-ghost btn-sm" style="font-size:10px;padding:2px 7px" data-h-click="h142" data-ha-click="${esc(JSON.stringify([String((i.id)??'')]))}">Pay ✓</button>`:''}
          <button data-h-click="h143" data-ha-click="${esc(JSON.stringify([String((i.id)??'')]))}" style="background:none;border:none;color:#8B5CF6;cursor:pointer;font-size:11px" title="Invoice Matching">🔗</button>
        </td>
      </tr>`;
    }).join('')}
    </tbody></table>`;

  } else if(tab==='cashflow'){
    const months=[];
    for(let i=-5;i<=3;i++){
      const d=new Date(today.getFullYear(),today.getMonth()+i,1);
      months.push(d.toISOString().slice(0,7));
    }
    const cfData=months.map(m=>{
      const isFuture=m>curMonth;
      const inflow =ALL.filter(i=>i.invoice_type==='client'&&i.status==='paid'&&i.paid_date?.startsWith(m)).reduce((s,i)=>s+Number(i.net_amount),0);
      const outflow=ALL.filter(i=>i.invoice_type!=='client'&&i.status==='paid'&&i.paid_date?.startsWith(m)).reduce((s,i)=>s+Number(i.net_amount),0);
      const fcIn   =ALL.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)&&i.due_date?.startsWith(m)).reduce((s,i)=>s+Number(i.net_amount),0);
      const fcOut  =ALL.filter(i=>i.invoice_type!=='client'&&!['paid','cancelled'].includes(i.status)&&i.due_date?.startsWith(m)).reduce((s,i)=>s+Number(i.net_amount),0);
      const fin=isFuture?fcIn:inflow, fout=isFuture?fcOut:outflow;
      return{m,inflow:fin,outflow:fout,isFuture,net:fin-fout};
    });
    const maxVal=Math.max(...cfData.map(d=>Math.max(d.inflow,d.outflow)),1);
    body=`
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('YTD Inflow',fmtKWD(ALL.filter(i=>i.invoice_type==='client'&&i.status==='paid'&&i.paid_date?.startsWith(String(today.getFullYear()))).reduce((s,i)=>s+Number(i.net_amount),0)),'#10B981','This year collected')}
      ${kpi('YTD Outflow',fmtKWD(ALL.filter(i=>i.invoice_type!=='client'&&i.status==='paid'&&i.paid_date?.startsWith(String(today.getFullYear()))).reduce((s,i)=>s+Number(i.net_amount),0)),'#EF4444','This year paid')}
      ${kpi('Forecast Inflow',fmtKWD(arOutstanding),'#3B82F6','Pending AR')}
      ${kpi('Forecast Outflow',fmtKWD(apOutstanding),'#8B5CF6','Pending AP')}
    </div>
    <div class="card" style="padding:16px 18px;margin-bottom:14px">
      <div class="sec-title" style="margin-bottom:14px"><span>💹</span>Monthly Cash Flow — Actual + Forecast</div>
      <div style="display:grid;grid-template-columns:repeat(9,1fr);gap:6px;align-items:end;min-height:140px">
        ${cfData.map(d=>{
          const inH=Math.round((d.inflow/maxVal)*120)||2;
          const outH=Math.round((d.outflow/maxVal)*120)||2;
          return`<div style="text-align:center">
            <div style="display:flex;gap:2px;align-items:flex-end;justify-content:center;height:120px">
              <div style="width:12px;height:${inH}px;background:${d.isFuture?'#10B98166':'#10B981'};border-radius:3px 3px 0 0" title="Inflow ${fmtKWD(d.inflow)}"></div>
              <div style="width:12px;height:${outH}px;background:${d.isFuture?'#EF444466':'#EF4444'};border-radius:3px 3px 0 0" title="Outflow ${fmtKWD(d.outflow)}"></div>
            </div>
            <div style="font-size:8px;color:var(--muted);margin-top:3px">${d.m.slice(5)}/${d.m.slice(2,4)}</div>
            <div style="font-size:8px;font-weight:700;color:${d.net>=0?'#10B981':'#EF4444'}">${d.net>=0?'+':''}${Math.round(d.net/1000)}K</div>
          </div>`;
        }).join('')}
      </div>
      <div style="display:flex;gap:16px;margin-top:10px;font-size:10px;color:var(--muted)">
        <span><span style="display:inline-block;width:10px;height:10px;background:#10B981;border-radius:2px;margin-right:4px"></span>Inflow (faded=forecast)</span>
        <span><span style="display:inline-block;width:10px;height:10px;background:#EF4444;border-radius:2px;margin-right:4px"></span>Outflow</span>
      </div>
    </div>
    <table><thead><tr>
      <th>Month</th><th style="text-align:right">Inflow (KWD)</th>
      <th style="text-align:right">Outflow (KWD)</th><th style="text-align:right">Net</th>
      <th style="text-align:center">Type</th>
    </tr></thead><tbody>
    ${cfData.map(d=>`<tr>
      <td style="font-weight:700;font-size:11px">${esc(d.m)}</td>
      <td style="text-align:right;color:#10B981">${fmtKWD(d.inflow)}</td>
      <td style="text-align:right;color:#EF4444">${fmtKWD(d.outflow)}</td>
      <td style="text-align:right;font-weight:800;color:${d.net>=0?'#10B981':'#EF4444'}">${fmtKWD(d.net)}</td>
      <td style="text-align:center">${pill(d.isFuture?'forecast':'actual',d.isFuture?'#3B82F6':'#10B981')}</td>
    </tr>`).join('')}
    </tbody></table>`;

  } else if(tab==='retention'){
    const retInvs=ALL.filter(i=>i.invoice_type==='client'&&Number(i.retention_pct)>0);
    const totHeld=retInvs.filter(i=>i.status!=='cancelled').reduce((s,i)=>s+Number(i.gross_amount)*Number(i.retention_pct)/100,0);
    const totRel =retInvs.filter(i=>i.retention_released).reduce((s,i)=>s+Number(i.gross_amount)*Number(i.retention_pct)/100,0);
    body=`
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Retention Held',fmtKWD(totHeld),'#3B82F6','Client retention balance')}
      ${kpi('Released',fmtKWD(totRel),'#10B981','Released to date')}
      ${kpi('Net Retention',fmtKWD(totHeld-totRel),'#C9A84C','Still held')}
      ${kpi('Retention Invoices',retInvs.length,'#E2E8F0','With retention')}
    </div>
    <table><thead><tr>
      <th>Invoice No</th><th>Project</th><th style="text-align:right">Gross</th>
      <th style="text-align:center">Ret%</th><th style="text-align:right">Retention Amt</th>
      <th style="text-align:center">Status</th><th style="text-align:center">Retention</th>
    </tr></thead><tbody>
    ${retInvs.map(i=>{
      const retAmt=Number(i.gross_amount)*Number(i.retention_pct)/100;
      const canRelease=i.status==='paid'&&!i.retention_released&&(currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager');
      return`<tr>
        <td style="color:var(--gold);font-size:10px">${esc(i.invoice_no)}</td>
        <td style="font-size:11px;color:var(--muted)">${esc(i.project?.project_no||'—')}</td>
        <td style="text-align:right;color:var(--muted)">${fmtKWD(i.gross_amount)}</td>
        <td style="text-align:center;font-weight:700;color:#3B82F6">${esc(i.retention_pct)}%</td>
        <td style="text-align:right;font-weight:800;color:#3B82F6">${fmtKWD(retAmt)}</td>
        <td style="text-align:center">${pill(i.status)}</td>
        <td style="text-align:center">
          ${i.retention_released?pill('Released','#10B981'):pill('Held','#3B82F6')}
          ${canRelease?`<button class="btn btn-ghost btn-sm" style="font-size:9px;padding:2px 6px;margin-left:4px" data-h-click="h144" data-ha-click="${esc(JSON.stringify([String((i.id)??''),String((fmtKWD(retAmt))??'')]))}">Release</button>`:''}
        </td>
      </tr>`;
    }).join('')}
    </tbody></table>`;

  } else if(tab==='coa'){
    const isPMO=currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager';
    const {data:list}=await sb.from('chart_of_accounts').select('*').order('account_code');
    const L=list||[];
    const byType={};L.forEach(a=>{byType[a.account_type]=(byType[a.account_type]||0)+1;});
    kpis=kpi('Total',L.length,'#E2E8F0')+kpi('Asset',byType['Asset']||0,'#3B82F6')+kpi('Liability',byType['Liability']||0,'#EF4444')+kpi('Revenue',byType['Revenue']||0,'#10B981')+kpi('Expense',byType['Expense']||0,'#F97316');
    const tc={Asset:'#3B82F6',Liability:'#EF4444',Equity:'#8B5CF6',Revenue:'#10B981',Expense:'#F97316',COGS:'#EAB308'};
    body=`<div style="display:flex;justify-content:flex-end;margin-bottom:10px">${isPMO?`<button class="btn btn-primary btn-sm" data-h-click="h145">+ Add Account</button>`:''}</div>
    <table><thead><tr><th>Code</th><th>Account Name</th><th>Type</th><th style="text-align:center">Normal Balance</th><th style="text-align:center">Active</th></tr></thead><tbody>
    ${L.map(a=>`<tr>
      <td style="color:var(--gold);font-weight:700;font-family:monospace">${esc(a.account_code)}</td>
      <td style="font-weight:600;font-size:11px">${esc(a.account_name)}</td>
      <td>${pill(a.account_type,tc[a.account_type]||'#94A3B8')}</td>
      <td style="text-align:center;font-size:11px;color:var(--muted)">${esc(a.normal_balance||'Debit')}</td>
      <td style="text-align:center">${a.is_active!==false?'<span style="color:#10B981">✓</span>':'<span style="color:#EF4444">✗</span>'}</td>
    </tr>`).join('')}</tbody></table>`;

  } else if(tab==='journal'){
    const isPMO=currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager';
    const {data:list}=await sb.from('journal_entries').select('*').order('entry_date',{ascending:false}).limit(50);
    const L=list||[];
    kpis=kpi('Entries',L.length,'#E2E8F0')+kpi('Posted',L.filter(j=>j.status==='posted').length,'#10B981')+kpi('Draft',L.filter(j=>j.status==='draft').length,'#F97316')+kpi('Total Debit',fmtKWD(L.filter(j=>j.status==='posted').reduce((s,j)=>s+(j.total_debit||0),0)),'#3B82F6');
    body=`<div style="display:flex;justify-content:flex-end;margin-bottom:10px">${isPMO?`<button class="btn btn-primary btn-sm" data-h-click="h146">+ New Entry</button>`:''}</div>
    <table><thead><tr><th>Entry No</th><th>Date</th><th>Description</th><th style="text-align:right">Debit</th><th style="text-align:right">Credit</th><th style="text-align:center">Status</th></tr></thead><tbody>
    ${L.map(j=>`<tr>
      <td style="color:var(--gold);font-size:10px">${esc(j.entry_no||'—')}</td>
      <td style="color:var(--muted);font-size:11px">${esc(j.entry_date||'—')}</td>
      <td style="font-weight:600;font-size:11px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(j.description)}</td>
      <td style="text-align:right;font-weight:700;color:#3B82F6">${fmtKWD(j.total_debit||0)}</td>
      <td style="text-align:right;font-weight:700;color:#EF4444">${fmtKWD(j.total_credit||0)}</td>
      <td style="text-align:center">${pill(j.status,j.status==='posted'?'#10B981':'#F97316')}</td>
    </tr>`).join('')}</tbody></table>`;

  } else if(tab==='trial'){
    const {data:list}=await sb.from('v_trial_balance').select('*').order('account_code');
    const L=list||[];
    const totalDr=L.reduce((s,r)=>s+Number(r.total_debit||0),0);
    const totalCr=L.reduce((s,r)=>s+Number(r.total_credit||0),0);
    const balanced=Math.abs(totalDr-totalCr)<0.01;
    kpis=kpi('Accounts',L.length,'#E2E8F0')+kpi('Total Debit',fmtKWD(totalDr),'#3B82F6')+kpi('Total Credit',fmtKWD(totalCr),'#EF4444')+kpi('Balanced',balanced?'✅ Yes':'❌ No',balanced?'#10B981':'#EF4444');
    body=`<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:10px;gap:8px;flex-wrap:wrap">
      <div style="padding:8px 12px;background:${balanced?'#10B98122':'#EF444422'};border:1px solid ${balanced?'#10B98144':'#EF444444'};border-radius:6px;font-size:12px;font-weight:700;color:${balanced?'#10B981':'#EF4444'}">${balanced?'✅ Trial Balance is balanced':'❌ Trial Balance is NOT balanced — check journal entries'}</div>
      <button data-h-click="h147" class="btn btn-ghost btn-sm" style="white-space:nowrap">📊 Export Excel</button>
    </div>
    <table><thead><tr><th>Code</th><th>Account</th><th>Type</th><th style="text-align:right">Debit</th><th style="text-align:right">Credit</th><th style="text-align:right">Balance</th></tr></thead><tbody>
    ${L.map(r=>{const bal=Number(r.balance||0);return`<tr>
      <td style="color:var(--gold);font-size:10px">${esc(r.account_code)}</td>
      <td style="font-weight:600;font-size:11px">${esc(r.account_name)}</td>
      <td style="color:var(--muted);font-size:11px">${esc(r.account_type)}</td>
      <td style="text-align:right;color:#3B82F6">${fmtKWD(r.total_debit||0)}</td>
      <td style="text-align:right;color:#EF4444">${fmtKWD(r.total_credit||0)}</td>
      <td style="text-align:right;font-weight:700;color:${bal>=0?'#10B981':'#EF4444'}">${fmtKWD(Math.abs(bal))}</td>
    </tr>`;}).join('')}</tbody></table>`;

  } else if(tab==='pl'){
    const {data:plData}=await sb.from('v_income_statement').select('*');
    const PL=plData?.[0]||{};
    const rev=Number(PL.total_revenue||0),cogs=Number(PL.total_cogs||0),exp=Number(PL.total_expenses||0);
    const gp=rev-cogs,np=gp-exp;
    kpis=kpi('Revenue',fmtKWD(rev),'#10B981')+kpi('Gross Profit',fmtKWD(gp),gp>=0?'#10B981':'#EF4444')+kpi('Net Profit',fmtKWD(np),np>=0?'#10B981':'#EF4444')+kpi('Net Margin',rev>0?((np/rev)*100).toFixed(1)+'%':'—',np>=0?'#10B981':'#EF4444');
    body=`<div style="max-width:500px;margin:0 auto"><div class="card" style="margin-bottom:12px"><h3 style="color:var(--gold);font-size:14px;margin:0 0 12px">Income Statement — ${new Date().getFullYear()}</h3>
    <table>
      <tr><td style="font-weight:700;padding:6px 0">Revenue</td><td style="text-align:right;font-weight:700;color:#10B981">${fmtKWD(rev)}</td></tr>
      <tr><td style="color:var(--muted);padding:4px 0 4px 16px">Cost of Goods Sold</td><td style="text-align:right;color:#EF4444">(${fmtKWD(cogs)})</td></tr>
      <tr style="border-top:1px solid var(--bdr)"><td style="font-weight:700;padding:6px 0">Gross Profit</td><td style="text-align:right;font-weight:700;color:${gp>=0?'#10B981':'#EF4444'}">${fmtKWD(gp)}</td></tr>
      <tr><td style="color:var(--muted);padding:4px 0 4px 16px">Operating Expenses</td><td style="text-align:right;color:#EF4444">(${fmtKWD(exp)})</td></tr>
      <tr style="border-top:2px solid var(--bdr);background:#0F2744"><td style="font-weight:900;font-size:14px;padding:8px 0;color:var(--gold)">Net Profit / Loss</td><td style="text-align:right;font-weight:900;font-size:14px;color:${np>=0?'#10B981':'#EF4444'}">${fmtKWD(np)}</td></tr>
    </table></div></div>`;

  } else {
    kpis=''; body='';
  }

  el.innerHTML=`
  <div class="page-head">
    <div class="page-head-left"><span style="font-size:22px">💰</span>
      <div><h1>Finance</h1><div class="sub">AR · AP · Cash Flow · Retention</div></div>
    </div>
    <div style="display:flex;gap:8px">
      <button class="btn btn-ghost btn-sm" data-h-click="h149" style="background:#F9731611;border-color:#F9731633;color:#F97316">🔒 Retention</button>
      ${(currentProfile?.role==='PMO Manager'||currentProfile?.role==='Finance Manager')?
        `<button class="btn btn-primary btn-sm" data-h-click="h148">+ New Invoice</button>`:''}
    </div>
  </div>
  </div>
  <div class="card">${tabs}${body}</div>`;
  }catch(e){ pageError('page-finance',e); }
}
// ── VENDOR MANAGEMENT ────────────────────────────────────────
async function approveVendor(vendorId, approve){
  const action=approve?'approve':'revoke approval for';
  if(!confirm(`Are you sure you want to ${action} this vendor?`)) return;
  const {error}=await sb.from('vendors').update({
    is_approved:approve, updated_at:new Date().toISOString()
  }).eq('id',vendorId);
  if(error){showToast('Error: '+error.message,'error');return;}
  await writeAudit('vendors',vendorId,approve?'VENDOR_APPROVED':'VENDOR_APPROVAL_REVOKED',
    {is_approved:!approve},{is_approved:approve},
    approve?'Vendor approved':'Vendor approval revoked');
  showToast(approve?'Vendor approved ✓':'Vendor approval revoked');
  loadProc('vendors');
}

async function blacklistVendor(vendorId, vendorName){
  const reason=prompt(`Reason for blacklisting "${vendorName}":`);
  if(!reason||!reason.trim()) return;
  const {error}=await sb.from('vendors').update({
    is_approved:false, status:'blacklisted', updated_at:new Date().toISOString()
  }).eq('id',vendorId);
  if(error){showToast('Error: '+error.message,'error');return;}
  await writeAudit('vendors',vendorId,'VENDOR_BLACKLISTED',
    {status:'active'},{status:'blacklisted',reason:reason.trim()},
    'Vendor blacklisted: '+reason.trim());
  showToast('Vendor blacklisted ✓');
  loadProc('vendors');
}

// ── HR ───────────────────────────────────────────────────────
