function openRunPayrollModal(){
  const empSel=window._cachedEmployees||[];
  const period=new Date().toISOString().slice(0,7);
  openModal('Run Payroll',`
    <div class="form-row"><div class="form-field"><label>Period *</label><input id="pay-period" type="month" value="${period}"/></div><div class="form-field"><label>Employee (blank = all)</label><select id="pay-emp" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)"><option value="">— All Active —</option>${empSel.map(e=>`<option value="${esc(e.id)}">${esc(e.full_name)}</option>`).join('')}</select></div></div>
    <div class="form-field" style="padding:10px;background:#1E3A5F;border-radius:8px;font-size:11px;color:var(--muted)">Pulls Basic + Allowances from active contracts. Deductions calculated from Payroll Config (NSSF, Tax, Working Days).</div>
    <div class="modal-foot"><button class="btn btn-ghost" data-h-click="h61">Cancel</button><button class="btn btn-primary" data-h-click="h195">Process Payroll</button></div>
  `);
}

async function runPayroll(e){
  const btn=e?.target;if(btn){btn.disabled=true;btn.textContent='Processing...';}
  try{
    const period=document.getElementById('pay-period').value;
    const empId=document.getElementById('pay-emp').value||null;
    if(!period){showToast('Period required','error');return;}
    let q=sb.from('employees').select('id,full_name,employee_no,department,employee_contracts!inner(basic_salary,allowances,status)').eq('status','active').eq('employee_contracts.status','active');
    if(empId) q=q.eq('id',empId);
    const {data:emps}=await q;
    if(!emps||emps.length===0){showToast('No employees with active contracts','error');return;}
    const {data:existing}=await sb.from('payroll_runs').select('employee_id').eq('period_month',period).in('employee_id',emps.map(e=>e.id));
    const existIds=new Set((existing||[]).map(r=>r.employee_id));
    const toProcess=emps.filter(e=>!existIds.has(e.id));
    if(toProcess.length===0){showToast('All employees already processed for this period','error');return;}
    // ATOMIC: server-side RPC reads config from payroll_config table
    const {data:payResult,error}=await sb.rpc('process_payroll_atomic',{
      p_period_month: period,
      p_employee_id:  empId||null,
      p_working_days: null,  // null = use payroll_config
      p_processed_by: currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!payResult?.ok){showToast('Error: '+(payResult?.error||'Unknown'),'error');return;}
    showToast('Payroll processed for '+payResult.processed+' employees ✓ ('+payResult.skipped+' skipped)');
    closeModal();loadHR('payroll');
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Process Payroll';}}
}

