async function openStockMovementModal(){
  const today=new Date().toISOString().split('T')[0];
  openModal('Record Stock Movement',`
    <div class="form-row"><div class="form-field"><label>Type *</label><select id="st-type" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)"><option value="GRN">GRN - Goods Received</option><option value="ISSUE">ISSUE - Issue to Project</option><option value="RETURN">RETURN - Return to Stock</option><option value="ADJUSTMENT">ADJUSTMENT</option></select></div><div class="form-field"><label>Date *</label><input id="st-date" type="date" value="${today}"/></div></div>
    <div class="form-field"><label>Item *</label><select id="st-item" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)"><option value="">— Loading items... —</option></select></div>
    <div class="form-row"><div class="form-field"><label>Quantity *</label><input id="st-qty" type="number" min="0" step="0.01" placeholder="0.00"/></div><div class="form-field"><label>Unit Cost (KWD)</label><input id="st-cost" type="number" min="0" step="0.001" placeholder="0.000"/></div></div>
    <div class="form-field"><label>Reference</label><input id="st-ref" placeholder="PO No, MRV No..."/></div>
    <div class="modal-foot"><button class="btn btn-ghost" data-h-click="h61">Cancel</button><button class="btn btn-primary" data-h-click="h201">Record</button></div>
  `);
  // Fetch items fresh (bypass cache to ensure RLS-filtered results)
  try{
    const {data:items,error}=await sb.from('material_master')
      .select('id,item_code,item_name,current_stock')
      .eq('is_active',true)
      .order('item_code');
    const sel=document.getElementById('st-item');
    if(!sel) return;
    if(error||!items||items.length===0){
      sel.innerHTML='<option value="">— No items available —</option>';
      return;
    }
    window._cachedItems=items; // update cache too
    sel.innerHTML='<option value="">— Select Item —</option>'+
      items.map(i=>`<option value="${esc(i.id)}">${esc(i.item_code)} — ${esc(i.item_name)} (Stock: ${i.current_stock??0})</option>`).join('');
  }catch(e){
    const sel=document.getElementById('st-item');
    if(sel) sel.innerHTML='<option value="">— Error loading items —</option>';
    console.error('Items load error:',e);
  }
}

async function saveStockMovement(e){
  const btn=e?.target;if(btn){btn.disabled=true;btn.textContent='Saving...';}
  try{
    const typeRaw=document.getElementById('st-type').value;
    const typeMap={'GRN':'IN','ISSUE':'OUT','RETURN':'RETURN','ADJUSTMENT':'ADJUSTMENT'};
    const type=typeMap[typeRaw]||typeRaw;
    const itemId=document.getElementById('st-item').value;
    const qty=Number(document.getElementById('st-qty').value)||0;
    const date=document.getElementById('st-date').value;
    if(!itemId||qty<=0||!date){showToast('Item, quantity and date required','error');return;}
    // ATOMIC: ledger + stock update + audit in ONE transaction (server-side RPC)
    const {data:stockResult,error}=await sb.rpc('record_stock_movement_atomic',{
      p_movement_type: type,
      p_item_id:       itemId,
      p_quantity:      qty,
      p_unit_cost:     Number(document.getElementById('st-cost').value)||0,
      p_reference:     document.getElementById('st-ref').value.trim()||null,
      p_notes:         null
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!stockResult?.success){showToast('Error: '+(stockResult?.error||'Unknown'),'error');return;}
    showToast((stockResult.transaction_no||type)+' recorded ✓');closeModal();loadInventory('ledger');
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Record';}}
}

