function autoInitials(){
  const name=document.getElementById('nu-name')?.value||'';
  const init=name.trim().split(/\s+/).map(w=>w[0]||'').join('').substring(0,2).toUpperCase();
  const el=document.getElementById('nu-initials');
  if(el&&!el._manuallyEdited) el.value=init;
}

async function saveNewUser(e){
  const name   =document.getElementById('nu-name').value.trim();
  const email  =document.getElementById('nu-email').value.trim();
  const role   =document.getElementById('nu-role').value;
  const initials=(document.getElementById('nu-initials').value.trim()||name.split(' ').map(w=>w[0]).join('').substring(0,2)).toUpperCase();
  const pass   =document.getElementById('nu-pass').value;
  const pass2  =document.getElementById('nu-pass2').value;
  const errEl  =document.getElementById('nu-err');
  const btn    =event?.target;

  const showErr=msg=>{errEl.textContent=msg;errEl.style.display='block';};
  errEl.style.display='none';

  if(!name||!email||!pass){showErr('Name, Email and Password are required');return;}
  if(pass.length<8){showErr('Password must be at least 8 characters');return;}
  if(pass!==pass2){showErr('Passwords do not match');return;}
  if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){showErr('Invalid email address');return;}

  if(btn){btn.disabled=true;btn.textContent='Creating…';}
  try{
    const {data:{session}}=await sb.auth.getSession();
    const token=session?.access_token;
    if(!token){showErr('Session expired — please log in again');return;}

    const res=await fetch(CREATE_USER_URL,{
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`,'apikey':SUPABASE_KEY},
      body:JSON.stringify({email,password:pass,full_name:name,role,initials})
    });
    const data=await res.json();

    if(!res.ok||!data.ok){
      showErr(data.error||'User creation failed');
      return;
    }
    showToast(`User ${name} created ✓`);
    closeModal();loadUsers();
  }catch(e){
    showErr('Network error: '+e.message);
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Create User';}
  }
}

