async function doResetPassword(userId){
  const pass =document.getElementById('rp-pass').value;
  const pass2=document.getElementById('rp-pass2').value;
  const errEl=document.getElementById('rp-err');
  const btn  =event?.target;
  errEl.style.display='none';
  if(pass.length<8){errEl.textContent='Min 8 characters';errEl.style.display='block';return;}
  if(pass!==pass2){errEl.textContent='Passwords do not match';errEl.style.display='block';return;}
  if(btn){btn.disabled=true;btn.textContent='Resetting…';}
  try{
    const {data:{session}}=await sb.auth.getSession();
    const token=session?.access_token;
    if(!token){errEl.textContent='Session expired';errEl.style.display='block';return;}
    const res=await fetch(RESET_PWD_URL,{
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':`Bearer ${token}`,'apikey':SUPABASE_KEY},
      body:JSON.stringify({user_id:userId,new_password:pass})
    });
    const data=await res.json();
    if(!data.ok){errEl.textContent=data.error||'Reset failed';errEl.style.display='block';return;}
    showToast('Password reset ✓ — Inform user of new password');
    closeModal();
  }catch(e){
    errEl.textContent='Network error: '+e.message;errEl.style.display='block';
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Reset Password';}
  }
}

