async function openCreateBaselineModal(){
  const {data:projs}=await sb.from('projects')
    .select('id,project_no,name,start_date,end_date,bac,status')
    .in('status',ACTIVE_STATUSES)
    .order('project_no');

  // Load existing baselines
  const {data:baselines}=await sb.from('project_baselines')
    .select('project_id,version,version_label,bac,is_current,created_at')
    .order('created_at',{ascending:false})
    .limit(20);

  const blByProj={};
  (baselines||[]).forEach(b=>{
    if(!blByProj[b.project_id]) blByProj[b.project_id]=[];
    blByProj[b.project_id].push(b);
  });

  openModal('Baseline Management',`
  <div style="margin-bottom:12px;padding:8px 12px;background:#1E3A5F22;border-radius:6px;font-size:11px;color:var(--muted)">
    Create a baseline to enable time-phased PV calculation and accurate SPI reporting.
    Monthly PV is distributed linearly across the project duration.
  </div>
  <div class="form-row">
    <div class="form-field"><label>Project *</label>
      <select id="bl-proj" data-h-change="h224">
        <option value="">— Select Project —</option>
        ${(projs||[]).map(p=>`<option value="${esc(p.id)}" data-start="${esc(p.start_date||'')}" data-end="${esc(p.end_date||'')}" data-bac="${esc(p.bac||0)}">${esc(p.project_no)} — ${esc(p.name)}</option>`).join('')}
      </select>
    </div>
  </div>
  <div id="bl-existing" style="margin-bottom:10px;font-size:10px;color:var(--muted)"></div>
  <div class="form-row">
    <div class="form-field"><label>Start Date *</label><input id="bl-start" type="date"/></div>
    <div class="form-field"><label>End Date *</label><input id="bl-end" type="date"/></div>
  </div>
  <div class="form-field"><label>Notes</label>
    <input id="bl-notes" placeholder="e.g. Original baseline — contract award date"/>
  </div>
  <div id="bl-preview" style="padding:8px 12px;background:#10B98111;border:1px solid #10B98133;border-radius:6px;font-size:11px;color:var(--muted);display:none"></div>
  <div class="modal-foot">
    <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
    <button class="btn btn-primary" data-h-click="h225">Create Baseline</button>
  </div>`);

  // Store baselines data for onchange
  window._blByProj=blByProj;
}

function updateBaselineInfo(){
  const sel=document.getElementById('bl-proj');
  const opt=sel.options[sel.selectedIndex];
  if(!opt||!opt.value) return;

  const start=opt.dataset.start;
  const end=opt.dataset.end;
  const bac=Number(opt.dataset.bac)||0;
  const projId=opt.value;

  if(start) document.getElementById('bl-start').value=start;
  if(end) document.getElementById('bl-end').value=end;

  // Show existing baselines
  const existing=(window._blByProj||{})[projId]||[];
  const existEl=document.getElementById('bl-existing');
  if(existing.length>0){
    existEl.innerHTML=`<div style="padding:6px 10px;background:#F97316
11;border:1px solid #F9741633;border-radius:5px">
      ⚠️ This project already has ${esc(existing.length)} baseline(s). Creating a new one will mark the current as superseded.
      <br>Current: <b>${esc(existing[0].version_label)}</b> — BAC: ${fmtKWD(existing[0].bac)}
    </div>`;
  } else {
    existEl.innerHTML='<div style="color:#10B981;font-size:10px">✓ No existing baseline — this will be the original baseline.</div>';
  }

  // Preview months
  const s=document.getElementById('bl-start').value;
  const e=document.getElementById('bl-end').value;
  if(s&&e){
    const months=Math.max(1,Math.round((new Date(e)-new Date(s))/(1000*60*60*24*30.5)));
    const monthly=bac/months;
    const prev=document.getElementById('bl-preview');
    prev.style.display='block';
    prev.innerHTML=`📐 BAC: ${fmtKWD(bac)} over <b>${months} months</b> = ${fmtKWD(monthly)}/month (linear distribution)`;
  }
}

async function saveBaseline(e){
  const projId=document.getElementById('bl-proj').value;
  const start=document.getElementById('bl-start').value;
  const end=document.getElementById('bl-end').value;
  const notes=document.getElementById('bl-notes').value.trim();

  if(!projId||!start||!end){showToast('Project, Start Date and End Date required','error');return;}
  if(new Date(end)<=new Date(start)){showToast('End date must be after start date','error');return;}

  const btn=event?.target;
  if(btn){btn.disabled=true;btn.textContent='Creating…';}
  try{
    const {data,error}=await sb.rpc('create_project_baseline',{
      p_project_id: projId,
      p_start_date:  start,
      p_end_date:    end,
      p_notes:       notes||null
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Failed: '+(data?.error||'Unknown'),'error');return;}
    showToast(`Baseline v${data.version} created — ${data.months} months ✓`);
    closeModal();
    loadProjects('baseline');
  }catch(e){
    showToast('Error: '+e.message,'error');
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Create Baseline';}
  }
}

async function submitCO(coId){
  const {error}=await sb.from('change_orders').update({
    workflow_status:'submitted',
    submitted_by:currentUser.id,
    submitted_at:new Date().toISOString()
  }).eq('id',coId);
  if(error){showToast('Error: '+error.message,'error');return;}
  await writeAudit('change_orders',coId,'CO_SUBMITTED',null,{workflow_status:'submitted'},'CO submitted for review');
  showToast('CO submitted for review');
  loadProjects('changeorders');
}

async function reviewCO(coId, action){
  const comments=prompt((action==='approve'?'Approval':'Rejection')+' comments (optional):');
  if(comments===null)return;
  const {data,error}=await sb.rpc('apply_co_to_baseline',{
    p_co_id:coId,
    p_reviewed_by:currentUser.id,
    p_action:action,
    p_comments:comments||null
  });
  if(error||!data?.success){showToast(error?.message||data?.error||'Review failed','error');return;}
  await writeAudit('change_orders',coId,action==='approve'?'CO_APPROVED':'CO_REJECTED',null,{action,comments},'CO reviewed');
  showToast(action==='approve'?'CO Approved — Baseline updated ✓':'CO Rejected');
  loadProjects('changeorders');
}

