async function saveSnapshot(projId){
  const label=document.getElementById('f-snap-label').value.trim();
  const date=document.getElementById('f-snap-date').value;
  if(!label||!date){showToast('Label and date required','error');return;}
  const pv=Number(document.getElementById('f-snap-pv').value)||0;
  const ev=Number(document.getElementById('f-snap-ev').value)||0;
  const ac=Number(document.getElementById('f-snap-ac').value)||0;
  const spi=pv>0?Math.round(ev/pv*10000)/10000:null;
  const cpi=ac>0?Math.round(ev/ac*10000)/10000:null;
  const {error}=await sb.from('project_evm_snapshots').upsert({
    project_id:projId,snapshot_date:date,period_label:label,
    pv,ev,ac,spi,cpi,created_by:currentProfile?.id
  },{onConflict:'project_id,snapshot_date'});
  if(error){showToast('Error: '+error.message,'error');return;}
  await writeAudit('project_evm_snapshots',projId,'SNAPSHOT_ADDED',null,{label,pv,ev,ac,spi,cpi},'EVM snapshot saved');
  showToast('Snapshot saved ✓');
  closeModal();loadProjects('scurve');
}

