async function saveOpp(){
  const title=document.getElementById('f-title').value.trim();
  const client=document.getElementById('f-client').value.trim();
  if(!title||!client){showToast('Title and Client required','error');return;}
  const btn=event?.target;
  if(btn){btn.disabled=true;btn.textContent='Creating…';}
  try{
    const opp_no=await nextRefNo('BD');
    const {data:oppData,error}=await sb.from('opportunities').insert({
      opp_no, title, client,
      department:document.getElementById('f-dept').value,
      est_value:Number(document.getElementById('f-value').value)||0,
      probability:Number(document.getElementById('f-prob').value)||50,
      status:'identified',
      deadline:document.getElementById('f-deadline').value||null,
      notes:document.getElementById('f-notes').value||null,
      created_by:currentProfile?.id
    }).select('id').single();
    if(error){showToast('Error: '+error.message,'error');return;}
    // FIX: pass oppData.id (was null before)
    await writeAudit('opportunities',oppData?.id,'CREATED',null,{opp_no,title},'New opportunity',{strict:true});
    showToast('Opportunity '+opp_no+' created ✓');
    closeModal(); loadBizdev();
  }catch(e){showToast('Error: '+e.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Create Opportunity';}}
}

