async function saveProject(e){
  const name   = validText('f-pname','Project Name'); if(!name) return;
  const client = validText('f-pclient','Client'); if(!client) return;
  const val    = validNum('f-pvalue','Contract Value',0.001); if(val===null) return;
  const bac    = validNum('f-pbac','Approved Budget (BAC)',0.001); if(bac===null) return;
  const dept   = document.getElementById('f-pdept').value;
  const start  = document.getElementById('f-pstart').value||null;
  const end    = document.getElementById('f-pend').value||null;
  if(start&&end&&end<start){showToast('End date must be after start date','error');return;}

  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Creating…';}
  try{
    // ATOMIC: number generation + insert + audit in single DB transaction
    const deptCode={Security:'SEC','AV/Broadcast':'AV',IT:'IT',Power:'PW',Civil:'CV',Wireless:'WL',Trading:'TR'}[dept]||'XX';
    const {data,error}=await sb.rpc('save_project_atomic',{
      p_prefix:       `SP360-${deptCode}`,
      p_name:         name,
      p_client:       client,
      p_department:   dept,
      p_contract_value: val,
      p_bac:          bac,
      p_priority:     document.getElementById('f-ppriority').value,
      p_start_date:   start,
      p_end_date:     end,
      p_pm_id:        currentProfile?.id,
      p_created_by:   currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Error: '+(data?.error||'Unknown error'),'error');return;}
    showToast(`Project ${data.project_no} created ✓`);
    closeModal(); loadProjects();
  }catch(e2){showToast('Error: '+e2.message,'error');logError('Projects','saveProject',e2);}
  finally{if(btn){btn.disabled=false;btn.textContent='Create Project';}}
}

