async function saveInvoice(){
  const proj=document.getElementById('f-iproj').value;
  const gross=Number(document.getElementById('f-igross').value)||0;
  const date=document.getElementById('f-idate').value;
  if(!proj||!gross||!date){showToast('Project, Amount and Date required','error');return;}
  if(gross<=0){showToast('Invoice amount must be greater than 0','error');return;} // P0-C
  const ret=Number(document.getElementById('f-iret').value)||0;
  const retAmt=Math.round(gross*ret/100*1000)/1000;
  const net=gross-retAmt;
  const type=document.getElementById('f-itype').value;

  // ── 3-Way Match Validation (Supplier / Subcontractor invoices) ──────────────
  // FIX v2.3: PO-SPECIFIC matching (was project-level, now per-PO per-vendor)
  // Rule: Invoice → specific PO → MRVs linked to that PO → sum received_value ≥ invoice gross
  if(type==='supplier'||type==='subcontractor'){
    // Step 1: Load issued POs for this project
    const {data:pos}=await sb.from('purchase_orders')
      .select('id,po_no,total_value,status,vendor_id,vendors(name)')
      .eq('project_id',proj)
      .in('status',['issued','received','partial_receipt'])
      .order('created_at',{ascending:false});

    if(!pos||pos.length===0){
      showToast('⚠️ 3-Way Match: No issued PO found for this project. Issue a PO before invoicing.','error');
      return;
    }

    // Step 2: Let user select which PO this invoice is against
    const poOptions=pos.map(p=>`<option value="${esc(p.id)}" data-val="${esc(p.total_value)}">${esc(p.po_no)} — ${esc(p.vendors?.name||'Vendor')} — ${fmtKWD(p.total_value)}</option>`).join('');
    const poSelectHtml=`<div style="margin:12px 0"><label style="font-size:11px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.6px">Select PO for this invoice *</label><select id="match-po-select" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text);margin-top:6px">${poOptions}</select></div>`;

    // Inject PO selector into open modal
    const modalBody=document.querySelector('#modal-overlay .modal-body, #modal-overlay form');
    if(modalBody&&!document.getElementById('match-po-select')){
      const foot=modalBody.querySelector('.modal-foot');
      if(foot) foot.insertAdjacentHTML('beforebegin',poSelectHtml);
      else modalBody.insertAdjacentHTML('beforeend',poSelectHtml);
    }

    const selectedPoId=document.getElementById('match-po-select')?.value;
    if(!selectedPoId){
      showToast('⚠️ 3-Way Match: Please select the PO this invoice is against.','error');
      return;
    }

    const selectedPo=pos.find(p=>p.id===selectedPoId);

    // Step 3: Load MRVs specifically linked to the selected PO
    const {data:poMrvs}=await sb.from('mrvs')
      .select('id,mrv_no,received_value,condition')
      .eq('po_id',selectedPoId)
      .neq('condition','rejected');

    if(!poMrvs||poMrvs.length===0){
      showToast(`⚠️ 3-Way Match: No Goods Receipt (MRV) found for PO ${selectedPo?.po_no}. Receive goods against this PO before invoicing.`,'error');
      return;
    }

    // Step 4: PO-specific received value check (5% tolerance)
    const poReceivedValue=poMrvs.reduce((s,m)=>s+Number(m.received_value||0),0);
    const TOLERANCE=1.05;
    if(gross>poReceivedValue*TOLERANCE){
      showToast(`⚠️ 3-Way Match: Invoice (${fmtKWD(gross)}) exceeds goods received against PO ${selectedPo?.po_no} (${fmtKWD(poReceivedValue)}) by more than 5%. Check MRVs or reduce invoice amount.`,'error');
      return;
    }

    // Step 5: Check for duplicate active invoice against same PO
    const {data:existingInv}=await sb.from('invoices')
      .select('id,invoice_no,gross_amount,status')
      .eq('po_id',selectedPoId)
      .in('status',['draft','submitted','approved','pending_approval']);
    if(existingInv&&existingInv.length>0){
      const dupWarning=existingInv.map(i=>`${i.invoice_no} (${i.status})`).join(', ');
      if(!confirm(`⚠️ 3-Way Match Notice: Active invoice(s) already exist for PO ${selectedPo?.po_no}: ${dupWarning}.\n\nProceed anyway?`)) return;
    }

    // Store selected PO id for invoice record linkage below
    window._matchedPoId=selectedPoId;
  }
  // ── End 3-Way Match ─────────────────────────────────────────────────────────

  const prefix=type==='client'?'INV-C':type==='supplier'?'INV-S':'INV-SC';
  const invoice_no=await nextRefNo(prefix);
  // FIX v2.3: store po_id from PO-specific 3-way match
  const linkedPoId=(type==='supplier'||type==='subcontractor')?window._matchedPoId||null:null;
  const {data:inv,error}=await sb.from('invoices').insert({
    invoice_no,project_id:proj,invoice_type:type,
    gross_amount:gross,vat_pct:0,vat_amount:0,
    retention_pct:ret,retention_amt:retAmt,net_amount:net,
    status:'draft',invoice_date:date,
    po_id:linkedPoId,
    due_date:document.getElementById('f-idue').value||null,
    created_by:currentProfile?.id
  }).select().single();
  window._matchedPoId=null; // cleanup
  if(error){showToast('Error: '+error.message,'error');return;}
  await writeAudit('invoices',inv?.id,'INVOICE_CREATED',null,{invoice_no,gross_amount:gross,net_amount:net,po_id:linkedPoId,status:'draft'},'New invoice created',{strict:true});
  showToast('Invoice created — click Submit to start approval workflow');
  closeModal();loadFinance();
}

async function submitInvoice(e,invoiceId){
  if(!confirm('Submit this invoice for approval? This will start the PM Verification workflow.')) return;
  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Submitting…';}
  try{
    const {data,error}=await sb.rpc('submit_invoice',{p_invoice_id:invoiceId});
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Submit failed: '+(data?.error||'Unknown error'),'error');return;}
    showToast(`Invoice submitted — Ref: ${data.ref_no} ✓`);
    loadFinance();
    loadWfBadge();
  }catch(e){
    showToast('Error: '+e.message,'error');
  }finally{
    if(btn){btn.disabled=false;btn.textContent='Submit ▶';}
  }
}

async function markInvoicePaid(e,invoiceId){
  if(!confirm('Mark this invoice as PAID?\n\nNote: Invoice must be APPROVED through workflow first.')) return;
  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Processing…';}
  try{
    const {data,error}=await sb.rpc('mark_invoice_paid',{p_invoice_id:invoiceId});
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Cannot mark paid: '+(data?.error||'Unknown'),'error');return;}
    showToast(`Invoice ${data.invoice_no} marked as paid ✓`);
    loadFinance(curFinTab);
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Mark Paid';}}
}

async function releaseRetention(e,invoiceId,retAmtStr){
  if(!confirm('Release retention of '+retAmtStr+' for this invoice?\n\nNote: Invoice must be PAID first.')) return;
  const btn=e?.currentTarget||e?.target;
  if(btn){btn.disabled=true;btn.textContent='Releasing…';}
  try{
    const {data,error}=await sb.rpc('release_retention',{p_invoice_id:invoiceId});
    if(error){showToast('Error: '+error.message,'error');return;}
    if(!data?.ok){showToast('Cannot release: '+(data?.error||'Unknown'),'error');return;}
    showToast(`Retention released — KWD ${data.amount} ✓`);
    loadFinance('retention');
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Release';}}
}

