// ── SESSION RESTORE ─────────────────────────────────────────
// Session security policy:
// - Restore a valid Supabase session after refresh/PWA resume
// - Idle timeout: auto-logout after 30 minutes of inactivity (SESSION_IDLE_MS)
// - Absolute timeout: force re-login every 12 hours
(()=>{
  const IDLE_MS = SESSION_CONFIG.IDLE_MS; // unified
  const ABS_MS = SESSION_CONFIG.ABSOLUTE_MS; // unified
  const SESSION_START_KEY = 'sp360_session_start';
  let _idleTimer;

  function resetIdleTimer(){
    clearTimeout(_idleTimer);
    _idleTimer=setTimeout(()=>{
      if(typeof doLogout==='function') doLogout();
      if(typeof showToast==='function') showToast('Session expired due to inactivity — please sign in again','error');
    },IDLE_MS);
  }
  ['click','keydown','mousemove','touchstart'].forEach(ev=>
    document.addEventListener(ev,resetIdleTimer,{passive:true})
  );

  async function bootstrapSession(){
    const app=document.getElementById('app');
    const auth=document.getElementById('auth-screen');
    if(!app||!auth) return;
    app.style.display='none';
    auth.style.display='flex';

    try{
      // Check absolute timeout first
      const started=Number(localStorage.getItem(SESSION_START_KEY)||0);
      if(started && Date.now()-started>ABS_MS){
        await sb.auth.signOut().catch(()=>{});
        localStorage.removeItem(SESSION_START_KEY);
        return; // show login
      }

      // Get session from local storage (fast, no network)
      const {data:sessionData,error:sessionError}=await sb.auth.getSession();
      if(sessionError || !sessionData?.session){
        return; // no session → show login
      }

      const session=sessionData.session;

      // Check if token is expired or about to expire (within 60s)
      const expiresAt=(session.expires_at||0)*1000;
      const needsRefresh=expiresAt - Date.now() < 60*1000;

      if(needsRefresh){
        // Refresh token silently
        const {data:refreshed,error:refreshErr}=await sb.auth.refreshSession();
        if(refreshErr || !refreshed?.session){
          await sb.auth.signOut().catch(()=>{});
          return; // refresh failed → show login
        }
        currentUser=refreshed.session.user;
      } else {
        // Use cached session user (no network call needed on every refresh)
        currentUser=session.user;
      }

      if(!currentUser){
        await sb.auth.signOut().catch(()=>{});
        return;
      }

      await loadProfile();
      if(!currentProfile){
        await sb.auth.signOut().catch(()=>{});
        return;
      }

      // P0-1: restored sessions go through the same MFA gate as fresh logins
      if(!(await enforceMFA())) return;

      if(!localStorage.getItem(SESSION_START_KEY))
        localStorage.setItem(SESSION_START_KEY,String(Date.now()));

      enterApp();
      resetIdleTimer();

    }catch(e){
      currentUser=null;
      currentProfile=null;
      await sb.auth.signOut().catch(()=>{});
      console.warn('Session restore failed:',e?.message||e);
    }finally{
      const loader=document.getElementById('app-loading');
      if(loader) loader.style.display='none';
    }
  }

  // Session restore: validate with server, require login if invalid session
  bootstrapSession();
})();

document.addEventListener('keydown',e=>{
  if(e.key==='Enter'&&document.getElementById('auth-screen').style.display!=='none')doLogin();
  if(e.key==='?'&&e.shiftKey&&document.getElementById('app').style.display!=='none')openAboutModal();
  if(e.key==='Escape')closeModal();
});

// ── SYSTEM HEALTH CHECK ──────────────────────────────────────
async function runHealthCheck(){
  const el=document.getElementById('health-results');
  if(!el) return;
  el.innerHTML=`<div style="padding:8px 10px;font-size:11px;color:var(--muted)">⏳ Running health check…</div>`;

  // P1: every check returns an explicit {status:'PASS'|'WARN'|'FAIL', msg}. Anything else = FAIL.
  const PASS=(msg='')=>({status:'PASS',msg}), WARN=(msg='')=>({status:'WARN',msg}), FAIL=(msg='')=>({status:'FAIL',msg});
  const checks=[];
  const check=async(name, fn)=>{
    const start=Date.now();
    try{
      const r=await fn();
      const ok=r&&['PASS','WARN','FAIL'].includes(r.status);
      checks.push({name, status:ok?r.status:'FAIL', ms:Date.now()-start, msg:ok?String(r.msg||''):'Invalid check result'});
    }catch(e){
      checks.push({name, status:'FAIL', ms:Date.now()-start, msg:e?.message||String(e)});
    }
  };
  // Table read check: RLS "permission denied" for a role that is not expected to read the table = WARN, other errors = FAIL
  const tbl=(table,label)=>check(label, async()=>{
    const {error}=await sb.from(table).select('id').limit(1);
    if(!error) return PASS('Accessible');
    if(error.code==='42501'||/permission|policy/i.test(error.message)) return WARN('Blocked by RLS for role '+(currentProfile?.role||'—'));
    return FAIL(error.message);
  });

  await check('Supabase Connection', async()=>{
    const {error}=await sb.from('user_profiles').select('id').limit(1);
    return error?FAIL(error.message):PASS('Connected');
  });
  await check('Auth Session', async()=>{
    const {data:{session},error}=await sb.auth.getSession();
    if(error) return FAIL(error.message);
    if(!session) return FAIL('No session');
    const left=Math.round(((session.expires_at||0)*1000-Date.now())/60000);
    return left<0?FAIL('Token expired'):PASS(`Logged in as ${currentProfile?.full_name||'—'} · token ${left} min`);
  });
  await check('MFA Assurance Level', async()=>{
    const {data,error}=await sb.auth.mfa.getAuthenticatorAssuranceLevel();
    if(error) return FAIL(error.message);
    const need=mfaRequiredFor(currentProfile?.role);
    if(need && data?.currentLevel!=='aal2') return FAIL(`Role requires aal2 — session is ${data?.currentLevel||'unknown'}`);
    return PASS(`${data?.currentLevel||'—'}${need?' (required)':''}`);
  });
  // NOTE: next_ref_no deliberately excluded — it consumes a sequence number.
  await check('RPC: sp360_role (read-only)', async()=>{
    const {data,error}=await sb.rpc('sp360_role');
    if(error) return FAIL(error.message);
    if(!data) return WARN('RPC returned no role');
    if(data!==currentProfile?.role) return FAIL(`DB role "${data}" ≠ UI role "${currentProfile?.role}"`);
    return PASS(`Role: ${data}`);
  });
  await tbl('projects','Projects Table');
  await tbl('workflow_items','Workflow Items');
  await tbl('audit_log','Audit Log (read)');
  await tbl('crm_customers','CRM Customers');
  await tbl('crm_leads','CRM Leads');
  await tbl('crm_opportunities','CRM Opportunities');
  await tbl('crm_quotations','CRM Quotations');
  await tbl('crm_activities','CRM Activities');
  await tbl('contracts','Contracts');
  await tbl('invoices','Invoices');
  await tbl('purchase_orders','Purchase Orders');
  await tbl('employees','Employees');
  await tbl('inventory_items','Inventory Items');
  await check('PWA Service Worker', async()=>{
    if(!('serviceWorker' in navigator)) return WARN('Not supported');
    const regs=await navigator.serviceWorker.getRegistrations();
    return regs.length>0?PASS('Registered'):WARN('Not registered (normal in dev)');
  });

  const n={PASS:0,WARN:0,FAIL:0}; checks.forEach(c=>n[c.status]++);
  const total=checks.length;
  const head=n.FAIL?{c:'#EF4444',i:'❌'}:n.WARN?{c:'#F97316',i:'⚠️'}:{c:'#10B981',i:'✅'};
  const ico={PASS:'✅',WARN:'⚠️',FAIL:'❌'}, clr={PASS:'var(--muted)',WARN:'#F97316',FAIL:'#EF4444'};

  el.innerHTML=`
  <div style="margin-bottom:8px;padding:8px 12px;background:${esc(head.c)}22;border:1px solid ${esc(head.c)}44;border-radius:6px;font-size:11px;font-weight:700;color:${esc(head.c)}">
    ${esc(head.i)} ${esc(n.PASS)}/${total} PASS · ${esc(n.WARN)} WARN · ${esc(n.FAIL)} FAIL
  </div>
  ${checks.map(c=>`
  <div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--bdr);font-size:11px">
    <span style="font-size:14px">${ico[c.status]}</span>
    <span style="flex:1;color:var(--text)">${esc(c.name)}</span>
    <span style="color:var(--faint);font-size:10px">${esc(c.ms)}ms</span>
    <span style="color:${clr[c.status]};font-size:10px">${esc(c.msg)}</span>
  </div>`).join('')}`;
}

