// ══════════════════════════════════════════════════════════════
//  P2-1 · NOTIFICATIONS CENTER
//  Types: workflow_pending | invoice_overdue | co_approval |
//         project_rag | budget_alert | general
// ══════════════════════════════════════════════════════════════

let _notifData       = [];   // full list (in-memory)
let _notifReadSet    = new Set(JSON.parse(localStorage.getItem('sp360_notif_read')||'[]'));
let _notifTab        = 'all';
let _notifDrawerOpen = false;
let _notifChannel    = null;

// ── Persist read state ────────────────────────────────────────
function _saveNotifRead(){
  localStorage.setItem('sp360_notif_read', JSON.stringify([..._notifReadSet]));
}

// ── Fetch & build notifications from live data ────────────────
async function fetchNotifications(){
  const notifs = [];
  const now    = Date.now();

  try{
    // 1. Workflow — pending / overdue items
    // FIX: workflow_items has no title/assigned_to/created_at columns (HTTP 400) — use real columns
    const {data:wf} = await sb.from('workflow_items')
      .select('*')
      .in('status',['pending','overdue'])
      .order('raised_date',{ascending:false})
      .limit(30);

    (wf||[]).forEach(w=>{
      w.created_at = w.raised_date || w.created_at;
      w.title = w.title || [w.ref_no, w.current_step].filter(Boolean).join(' — ');
      const age = Math.floor((now - new Date(w.created_at))/86400000);
      const isOverdue = w.status==='overdue' || age>3;
      notifs.push({
        id:        'wf_'+w.id,
        type:      'workflow',
        icon:      isOverdue ? '🔴' : '⚡',
        title:     isOverdue ? 'Overdue Approval' : 'Pending Approval',
        body:      w.title || w.entity_type,
        sub:       age===0 ? 'Today' : `${age}d ago`,
        severity:  isOverdue ? 'critical' : 'warning',
        action:    ()=>{ navTo('workflow',document.getElementById('nav-workflow')); closeNotifDrawer(); },
        ts:        new Date(w.created_at).getTime()
      });
    });

    // 2. Finance — overdue invoices
    // FIX: real invoice columns are invoice_no / net_amount (HTTP 400); overdue = unpaid & past due
    const {data:inv} = await sb.from('invoices')
      .select('*')
      .not('status','in','(paid,cancelled)')
      .lt('due_date', new Date().toISOString().split('T')[0])
      .order('due_date',{ascending:true})
      .limit(20);
    (inv||[]).forEach(i=>{ i.invoice_number=i.invoice_no||i.invoice_number; i.vendor_name=i.vendor_name||i.client||i.invoice_type; i.amount=i.net_amount??i.amount; });

    (inv||[]).forEach(i=>{
      const due  = new Date(i.due_date);
      const days = Math.floor((now - due)/86400000);
      if(days > 0 || i.status==='overdue'){
        notifs.push({
          id:        'inv_'+i.id,
          type:      'finance',
          icon:      '💰',
          title:     'Invoice Overdue',
          body:      `${i.invoice_number||'Invoice'} — ${i.vendor_name||'Vendor'}`,
          sub:       `${days}d overdue · KWD ${Number(i.amount||0).toLocaleString()}`,
          severity:  days>7 ? 'critical' : 'warning',
          action:    ()=>{ navTo('finance',document.getElementById('nav-finance')); closeNotifDrawer(); },
          ts:        due.getTime()
        });
      }
    });

    // 3. Projects — RAG Red alerts
    // FIX: 'active' is not a project status — use ACTIVE_STATUSES and only CPI/SPI < 0.90 (RAG red)
    const {data:projAll} = await sb.from('projects')
      .select('id,name,project_no,cpi,spi,status')
      .in('status',ACTIVE_STATUSES);
    const proj=(projAll||[]).filter(p=>Math.min(Number(p.cpi??1),Number(p.spi??1))<0.9).slice(0,15);

    (proj||[]).forEach(p=>{
      const cpi = Number(p.cpi||1).toFixed(2);
      const spi = Number(p.spi||1).toFixed(2);
      notifs.push({
        id:        'rag_'+p.id,
        type:      'projects',
        icon:      '🔴',
        title:     'Project RAG: Red',
        body:      p.name,
        sub:       `CPI ${cpi} · SPI ${spi}`,
        severity:  'critical',
        action:    ()=>{ navTo('projects',document.getElementById('nav-projects')); closeNotifDrawer(); },
        ts:        now - 1000
      });
    });

    // 4. Change Orders pending approval
    const {data:cos} = await sb.from('change_orders')
      .select('*')
      .eq('workflow_status','submitted')
      .limit(15);
    (cos||[]).forEach(c=>{ c.co_number=c.co_no||c.co_number; c.amount=c.amount??c.cost_impact; });

    (cos||[]).forEach(c=>{
      notifs.push({
        id:        'co_'+c.id,
        type:      'workflow',
        icon:      '📋',
        title:     'CO Awaiting Approval',
        body:      `${c.co_number||'Change Order'} · KWD ${Number(c.amount||0).toLocaleString()}`,
        sub:       'Submitted for approval',
        severity:  'info',
        action:    ()=>{ navTo('workflow',document.getElementById('nav-workflow')); closeNotifDrawer(); },
        ts:        new Date(c.created_at||now).getTime()
      });
    });

  }catch(e){ console.warn('fetchNotifications:',e); }

  // Sort: critical first, then by timestamp desc
  notifs.sort((a,b)=>{
    const sp = {critical:0,warning:1,info:2};
    const sd = (sp[a.severity]||2)-(sp[b.severity]||2);
    return sd!==0 ? sd : b.ts-a.ts;
  });

  _notifData = notifs;
  return notifs;
}

// ── Render drawer list ────────────────────────────────────────
function renderNotifList(){
  const list = document.getElementById('notif-list');
  if(!list) return;

  const filtered = _notifTab==='all'
    ? _notifData
    : _notifData.filter(n=>n.type===_notifTab);

  if(filtered.length===0){
    list.innerHTML=`<div style="padding:40px 20px;text-align:center;color:var(--muted);font-size:12px">
      <div style="font-size:32px;margin-bottom:8px">✅</div>
      No notifications${_notifTab!=='all'?' in this category':''}
    </div>`;
    return;
  }

  const sevColor = {critical:'#EF4444',warning:'#F97316',info:'#06B6D4'};

  list.innerHTML = filtered.map(n=>{
    const read    = _notifReadSet.has(n.id);
    const col     = sevColor[n.severity]||'#94A3B8';
    return `<div data-h-click="h248" data-ha-click="${esc(JSON.stringify([String((n.id)??'')]))}"
      style="display:flex;align-items:flex-start;gap:10px;padding:11px 16px;cursor:pointer;
             border-bottom:1px solid var(--bdr);transition:background .1s;
             background:${read?'transparent':'var(--card2)'};
             border-left:3px solid ${read?'transparent':col}">
      <span style="font-size:18px;line-height:1.3;flex-shrink:0">${esc(n.icon)}</span>
      <div style="flex:1;min-width:0">
        <div style="display:flex;align-items:center;gap:6px;margin-bottom:2px">
          <span style="font-size:11px;font-weight:700;color:${read?'var(--muted)':col}">${esc(n.title)}</span>
          ${!read?`<span style="width:6px;height:6px;border-radius:50%;background:${col};flex-shrink:0"></span>`:''}
        </div>
        <div style="font-size:12px;color:var(--text);white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(n.body)}</div>
        <div style="font-size:10px;color:var(--faint);margin-top:2px">${esc(n.sub)}</div>
      </div>
    </div>`;
  }).join('');
}

function _notifClick(id){
  _notifReadSet.add(id);
  _saveNotifRead();
  const n = _notifData.find(x=>x.id===id);
  if(n?.action) n.action();
  renderNotifList();
  _updateNotifBell();
}

// ── Tab switching ─────────────────────────────────────────────
function setNotifTab(tab){
  _notifTab = tab;
  ['all','workflow','finance','projects'].forEach(t=>{
    const btn = document.getElementById('nf-tab-'+t);
    if(!btn) return;
    const active = t===tab;
    btn.style.borderBottomColor = active ? 'var(--gold)' : 'transparent';
    btn.style.color = active ? 'var(--gold)' : 'var(--muted)';
    btn.style.fontWeight = active ? '700' : '600';
  });
  renderNotifList();
}

// ── Open / Close ──────────────────────────────────────────────
async function openNotifDrawer(){
  _notifDrawerOpen = true;
  const overlay = document.getElementById('notif-overlay');
  const drawer  = document.getElementById('notif-drawer');
  overlay.style.display = 'block';
  drawer.style.display  = 'flex';
  drawer.style.transform = 'translateX(100%)';
  requestAnimationFrame(()=>{ drawer.style.transform='translateX(0)'; });

  const sub = document.getElementById('notif-drawer-sub');
  if(sub) sub.textContent = 'Refreshing…';

  await fetchNotifications();
  renderNotifList();

  const unread = _notifData.filter(n=>!_notifReadSet.has(n.id)).length;
  if(sub) sub.textContent = `${_notifData.length} alerts · ${unread} unread`;
  _updateNotifBell();
}

function closeNotifDrawer(){
  _notifDrawerOpen = false;
  const drawer  = document.getElementById('notif-drawer');
  const overlay = document.getElementById('notif-overlay');
  if(drawer){ drawer.style.transform='translateX(100%)'; setTimeout(()=>{ drawer.style.display='none'; },250); }
  if(overlay) overlay.style.display='none';
}

// ── Mark all read / Clear read ────────────────────────────────
function markAllNotifsRead(){
  _notifData.forEach(n=>_notifReadSet.add(n.id));
  _saveNotifRead();
  renderNotifList();
  _updateNotifBell();
  const sub = document.getElementById('notif-drawer-sub');
  if(sub) sub.textContent = `${_notifData.length} alerts · 0 unread`;
  showToast('All notifications marked as read');
}

function clearReadNotifs(){
  _notifData = _notifData.filter(n=>!_notifReadSet.has(n.id));
  renderNotifList();
  showToast('Read notifications cleared');
}

// ── Update header bell badge ──────────────────────────────────
function _updateNotifBell(){
  const unread = _notifData.filter(n=>!_notifReadSet.has(n.id)).length;
  const badge  = document.getElementById('notif-count-badge');
  const bell   = document.getElementById('notif-bell');
  if(!badge||!bell) return;
  if(unread>0){
    badge.style.display = 'block';
    badge.textContent   = unread>99?'99+':unread;
    bell.style.color    = '#F97316';
    bell.style.borderColor = '#F9731633';
    bell.style.background  = '#F9731610';
  } else {
    badge.style.display = 'none';
    bell.style.color    = 'var(--muted)';
    bell.style.borderColor = 'transparent';
    bell.style.background  = 'none';
  }
}

// ── Realtime push integration ─────────────────────────────────
function initNotifRealtime(){
  if(_notifChannel) try{ sb.removeChannel(_notifChannel); }catch(e){}

  _notifChannel = sb.channel('notif-center')
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'workflow_items'},
      async ()=>{ await _silentRefreshNotifs(); })
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'workflow_items'},
      async ()=>{ await _silentRefreshNotifs(); })
    .on('postgres_changes',{event:'UPDATE',schema:'public',table:'invoices'},
      async ()=>{ await _silentRefreshNotifs(); })
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'change_orders'},
      async ()=>{ await _silentRefreshNotifs(); })
    .subscribe();
}

async function _silentRefreshNotifs(){
  await fetchNotifications();
  _updateNotifBell();
  if(_notifDrawerOpen) renderNotifList();
}

// ── loadWfBadge upgrade — also updates notif bell ─────────────
const _origLoadWfBadge = loadWfBadge;
loadWfBadge = async function(){
  await _origLoadWfBadge();
  // Silently refresh notif counts in background
  try{ await _silentRefreshNotifs(); }catch(e){}
};

