async function biPortfolioKPIs(){
  const [projR, snapR] = await Promise.all([
    sb.from('projects').select('id,project_no,name,status,bac,ev,ac,pv,cpi,spi,pct,department,client'),
    sb.from('project_evm_snapshots').select('project_id,snapshot_date,pv,ev,ac').order('snapshot_date',{ascending:false}).limit(1)
  ]);
  const projs = (projR.data||[]).filter(p=>['planning','execution','monitoring','closeout'].includes(p.status));
  const totalBAC = projs.reduce((s,p)=>s+Number(p.bac),0);
  const totalEV  = projs.reduce((s,p)=>s+Number(p.ev),0);
  const totalAC  = projs.reduce((s,p)=>s+Number(p.ac),0);
  const totalPV  = projs.reduce((s,p)=>s+Number(p.pv),0);
  const portCPI  = totalAC>0 ? totalEV/totalAC : 1;
  const portSPI  = totalPV>0 ? totalEV/totalPV : null;
  const totalEAC = projs.reduce((s,p)=>{
    const cpi=Number(p.cpi)||1;
    return s+(cpi>0 ? Number(p.ac)+(Number(p.bac)-Number(p.ev))/cpi : Number(p.bac));
  },0);
  const totalVAC  = totalBAC - totalEAC;
  const totalETC  = Math.max(totalEAC - totalAC, 0);
  const wRem      = totalBAC - totalEV;
  const bRem      = totalBAC - totalAC;
  const portTCPI  = wRem>0 && bRem>0 ? wRem/bRem : null;
  const ragCounts = projs.reduce((m,p)=>{ const r=ragScore(p)>=1?'green':ragScore(p)>=0.9?'amber':'red'; m[r]=(m[r]||0)+1; return m; },{});

  return {
    generated_at:   new Date().toISOString(),
    report_date:    new Date().toLocaleDateString('en-GB'),
    source:         'SP360 v4.1 — Smart Projects 360 Kuwait',
    data: [{
      metric: 'Portfolio Summary',
      active_projects:   projs.length,
      total_bac_kwd:     Math.round(totalBAC),
      total_ev_kwd:      Math.round(totalEV),
      total_ac_kwd:      Math.round(totalAC),
      total_pv_kwd:      Math.round(totalPV),
      total_eac_kwd:     Math.round(totalEAC),
      total_etc_kwd:     Math.round(totalETC),
      total_vac_kwd:     Math.round(totalVAC),
      portfolio_cpi:     Number(portCPI.toFixed(3)),
      portfolio_spi:     portSPI !== null ? Number(portSPI.toFixed(3)) : null,
      portfolio_tcpi:    portTCPI !== null ? Number(portTCPI.toFixed(3)) : null,
      cpi_status:        portCPI>=1?'On Track':portCPI>=0.9?'At Risk':'Critical',
      rag_green:         ragCounts['green']||0,
      rag_amber:         ragCounts['amber']||0,
      rag_red:           ragCounts['red']||0,
      overall_pct:       projs.length>0?Math.round(projs.reduce((s,p)=>s+Number(p.pct||0),0)/projs.length):0
    }]
  };
}

async function biProjectEVM(){
  const {data:projs} = await sb.from('projects')
    .select('id,project_no,name,client,status,department,bac,ev,ac,pv,cpi,spi,pct,start_date,end_date,contract_value')
    .order('project_no');

  const data = (projs||[]).map(p=>{
    const bac=Number(p.bac)||0, ev=Number(p.ev)||0, ac=Number(p.ac)||0, pv=Number(p.pv)||0;
    const cpi=Number(p.cpi)||0, spi=p.spi!=null?Number(p.spi):null;
    const eac = cpi>0 ? ac+(bac-ev)/cpi : bac;
    const etc = Math.max(eac-ac,0);
    const vac = bac-eac;
    const cv  = ev-ac;
    const sv  = ev-pv;
    const wRem=bac-ev, bRem=bac-ac;
    const tcpi = wRem>0&&bRem>0 ? wRem/bRem : null;
    return {
      project_no:      p.project_no,
      name:            p.name,
      client:          p.client,
      department:      p.department,
      status:          p.status,
      pct_complete:    Number(p.pct)||0,
      rag_status_calc: ragScore(p)>=1?'green':ragScore(p)>=0.9?'amber':'red',
      contract_value:  Math.round(Number(p.contract_value)||0),
      bac:             Math.round(bac),
      ev:              Math.round(ev),
      ac:              Math.round(ac),
      pv:              Math.round(pv),
      cpi:             Number(cpi.toFixed(3)),
      spi:             spi!==null ? Number(spi.toFixed(3)) : null,
      eac:             Math.round(eac),
      etc:             Math.round(etc),
      vac:             Math.round(vac),
      cv:              Math.round(cv),
      sv:              Math.round(sv),
      tcpi:            tcpi!==null ? Number(tcpi.toFixed(3)) : null,
      cpi_status:      cpi>=1?'On Track':cpi>=0.9?'At Risk':'Critical',
      start_date:      p.start_date,
      end_date:        p.end_date
    };
  });
  return { generated_at:new Date().toISOString(), source:'SP360 v4.1', data };
}

async function biFinancialSummary(){
  const {data:invs} = await sb.from('invoices').select('*');
  const today = new Date();
  const I = invs||[];

  const rev   = I.filter(i=>i.invoice_type==='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
  const cost  = I.filter(i=>i.invoice_type!=='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
  const gp    = rev-cost;
  const arOut = I.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount),0);
  const apOut = I.filter(i=>i.invoice_type!=='client'&&!['paid','cancelled'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount),0);
  const overdue = I.filter(i=>!['paid','cancelled'].includes(i.status)&&i.due_date&&new Date(i.due_date)<today).reduce((s,i)=>s+Number(i.net_amount),0);

  // Cash flow last 6 months
  const cfRows = [];
  for(let i=-5;i<=0;i++){
    const d=new Date(today.getFullYear(),today.getMonth()+i,1);
    const m=d.toISOString().slice(0,7);
    const inflow  = I.filter(x=>x.invoice_type==='client'&&x.status==='paid'&&x.paid_date?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
    const outflow = I.filter(x=>x.invoice_type!=='client'&&x.status==='paid'&&x.paid_date?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
    cfRows.push({ month:m, inflow:Math.round(inflow), outflow:Math.round(outflow), net:Math.round(inflow-outflow) });
  }

  return {
    generated_at: new Date().toISOString(),
    source: 'SP360 v4.1',
    summary: {
      revenue_collected_kwd:  Math.round(rev),
      cost_paid_kwd:          Math.round(cost),
      gross_profit_kwd:       Math.round(gp),
      gp_margin_pct:          rev>0 ? Number(((gp/rev)*100).toFixed(1)) : 0,
      ar_outstanding_kwd:     Math.round(arOut),
      ap_outstanding_kwd:     Math.round(apOut),
      overdue_total_kwd:      Math.round(overdue),
      total_invoices:         I.length,
      paid_invoices:          I.filter(i=>i.status==='paid').length,
      pending_invoices:       I.filter(i=>i.status==='pending').length
    },
    cash_flow_6m: cfRows
  };
}

async function biWorkflowStatus(){
  const {data:wfs} = await sb.from('workflow_items').select('id,title,entity_type,status,created_at,due_date,assigned_to');
  const today = new Date();
  const W = wfs||[];

  const byType = W.reduce((m,w)=>{ const t=w.entity_type||'other'; m[t]=(m[t]||{count:0,pending:0,overdue:0}); m[t].count++; if(w.status==='pending')m[t].pending++; if(w.status==='overdue')m[t].overdue++; return m; },{});

  const data = Object.entries(byType).map(([type,v])=>({
    entity_type: type,
    total:       v.count,
    pending:     v.pending,
    overdue:     v.overdue
  }));

  const aging = W.filter(w=>['pending','overdue'].includes(w.status)).map(w=>{
    const age = Math.floor((today-new Date(w.created_at))/86400000);
    return {
      id:          w.id,
      title:       w.title,
      entity_type: w.entity_type,
      status:      w.status,
      age_days:    age,
      due_date:    w.due_date,
      bucket:      age<=3?'0-3d':age<=7?'4-7d':age<=14?'8-14d':'14d+'
    };
  });

  return {
    generated_at: new Date().toISOString(),
    source: 'SP360 v4.1',
    summary: {
      total_items:    W.length,
      pending:        W.filter(w=>w.status==='pending').length,
      overdue:        W.filter(w=>w.status==='overdue').length,
      approved:       W.filter(w=>w.status==='approved').length,
      rejected:       W.filter(w=>w.status==='rejected').length
    },
    by_type: data,
    aging_detail: aging
  };
}

async function biQHSEHR(){
  const [{data:ncrs},{data:emps}] = await Promise.all([
    sb.from('ncrs').select('id,ncr_no,severity,status,department,created_at'),
    sb.from('employees').select('id,department,status,employment_type')
  ]);
  const N=ncrs||[], E=emps||[];

  const ncrBySev = ['critical','major','minor','observation'].map(sev=>({
    severity: sev,
    total:    N.filter(n=>n.severity===sev).length,
    open:     N.filter(n=>n.severity===sev&&n.status==='open').length,
    closed:   N.filter(n=>n.severity===sev&&n.status==='closed').length
  }));

  const depts = [...new Set(E.map(e=>e.department).filter(Boolean))];
  const headcount = depts.map(d=>({
    department:  d,
    total:       E.filter(e=>e.department===d).length,
    active:      E.filter(e=>e.department===d&&e.status==='active').length,
    permanent:   E.filter(e=>e.department===d&&e.employment_type==='permanent').length,
    contract:    E.filter(e=>e.department===d&&e.employment_type==='contract').length
  }));

  return {
    generated_at: new Date().toISOString(),
    source: 'SP360 v4.1',
    qhse_summary: {
      total_ncrs:    N.length,
      open_ncrs:     N.filter(n=>n.status==='open').length,
      closed_ncrs:   N.filter(n=>n.status==='closed').length,
      critical_open: N.filter(n=>n.severity==='critical'&&n.status==='open').length
    },
    ncr_by_severity: ncrBySev,
    hr_summary: {
      total_employees:  E.length,
      active:           E.filter(e=>e.status==='active').length,
      on_leave:         E.filter(e=>e.status==='on_leave').length,
      terminated:       E.filter(e=>e.status==='terminated').length
    },
    headcount_by_dept: headcount
  };
}

