// ── Open / Close ──────────────────────────────────────────────
function openEmailCenter(){
  const overlay = document.getElementById('email-center-overlay');
  const panel   = document.getElementById('email-center-panel');
  overlay.style.display = 'block';
  panel.style.display   = 'flex';
  panel.style.transform = 'translateX(100%)';
  requestAnimationFrame(()=>{ panel.style.transform = 'translateX(0)'; });
  renderEmailTemplates();
  checkEmailConnection();
  loadEmailHistory();
}

function closeEmailCenter(){
  const panel   = document.getElementById('email-center-panel');
  const overlay = document.getElementById('email-center-overlay');
  if(panel){ panel.style.transform='translateX(100%)'; setTimeout(()=>{ panel.style.display='none'; },250); }
  if(overlay) overlay.style.display='none';
}

// ── Render template cards ─────────────────────────────────────
function renderEmailTemplates(){
  const el = document.getElementById('email-templates-list');
  if(!el) return;
  el.innerHTML = EMAIL_TEMPLATES.map(t=>`
    <div style="border:1px solid var(--bdr);border-radius:10px;padding:12px 14px;margin-bottom:10px;background:var(--card2)">
      <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
        <span style="font-size:18px">${esc(t.icon)}</span>
        <div style="flex:1">
          <div style="font-size:12px;font-weight:700;color:${esc(t.color)}">${esc(t.name)}</div>
          <div style="font-size:10px;color:var(--muted)">${esc(t.desc)}</div>
        </div>
      </div>
      <div style="display:flex;gap:6px">
        <button data-h-click="h253" data-ha-click="${esc(JSON.stringify([String((t.id)??'')]))}"
          style="background:var(--n4);border:1px solid var(--bdr);color:var(--muted);border-radius:6px;padding:5px 10px;font-size:10px;cursor:pointer">
          👁 Preview
        </button>
        <button data-h-click="h254" data-ha-click="${esc(JSON.stringify([String((t.id)??'')]))}"
          style="flex:1;background:${esc(t.color)}22;border:1px solid ${esc(t.color)}44;color:${esc(t.color)};border-radius:6px;padding:5px 10px;font-size:10px;font-weight:700;cursor:pointer">
          📤 Send Now
        </button>
      </div>
      <div id="email-status-${esc(t.id)}" style="font-size:9px;color:var(--faint);margin-top:4px;min-height:14px"></div>
    </div>`).join('');
}

// ── Check edge function connection ────────────────────────────
async function checkEmailConnection(){
  const statusEl = document.getElementById('email-center-status');
  const bannerEl = document.getElementById('email-conn-banner');
  try{
    const {data:{session}} = await sb.auth.getSession();
    if(!session){ throw new Error('No session'); }
    const res = await fetch(EMAIL_EDGE_URL, {
      method:'POST',
      headers:{'Content-Type':'application/json','Authorization':`Bearer ${session.access_token}`,'apikey':SUPABASE_KEY},
      body: JSON.stringify({to:['test@test.com'],subject:'ping',text:'ping',_test:true})
    });
    if(res.status===404){
      _edgeFnAvailable=false;
      if(statusEl) statusEl.textContent='Edge Function not deployed — using mailto fallback';
      if(bannerEl) bannerEl.innerHTML='<span style="color:#F97316">⚠️ Edge Function not deployed.</span> Emails will open your local mail client. <a href="#" data-h-click="h255" style="color:#C9A84C">Setup instructions →</a>';
      bannerEl.style.background='#F9731611'; bannerEl.style.border='1px solid #F9731633';
    } else {
      _edgeFnAvailable=true;
      if(statusEl) statusEl.textContent='✓ Connected to Resend API via Edge Function';
      if(bannerEl) bannerEl.innerHTML='<span style="color:#10B981">✓ Resend API connected</span> — emails send directly without opening mail client.';
      bannerEl.style.background='#10B98111'; bannerEl.style.border='1px solid #10B98133';
    }
  }catch(e){
    _edgeFnAvailable=false;
    if(statusEl) statusEl.textContent='Connection check failed — using mailto fallback';
  }
}

// ── Trigger notification with status feedback ─────────────────
async function triggerEmailNotif(type, btn){
  const statusEl = document.getElementById('email-status-'+type);
  if(btn){ btn.disabled=true; btn.textContent='Sending…'; }
  if(statusEl) statusEl.textContent='⏳ Sending…';
  try{
    await sendEmailNotification(type);
    if(statusEl) statusEl.innerHTML='<span style="color:#10B981">✓ Sent successfully</span> · '+new Date().toLocaleTimeString('en-GB');
    loadEmailHistory(); // refresh history
  }catch(e){
    if(statusEl) statusEl.innerHTML='<span style="color:#EF4444">✗ '+esc(e.message)+'</span>';
  }finally{
    if(btn){ btn.disabled=false; btn.textContent='📤 Send Now'; }
  }
}

// ── Preview email before sending ──────────────────────────────
async function previewEmailNotif(type){
  const t = EMAIL_TEMPLATES.find(x=>x.id===type);
  if(!t) return;
  // Build preview data
  const [projR,wfR,invR,ncrR] = await Promise.all([
    sb.from('projects').select('name,cpi,spi,status,ev,ac'),
    sb.from('workflow_items').select('ref_no,current_step,status').in('status',['pending','overdue']),
    sb.from('invoices').select('invoice_no,net_amount,due_date,status').eq('invoice_type','client').neq('status','paid').neq('status','cancelled'),
    sb.from('ncrs').select('ncr_no,severity,status').eq('status','open').eq('severity','critical')
  ]);
  const projs=projR.data||[], wfs=wfR.data||[], invs=invR.data||[], ncrs=ncrR.data||[];
  const today=new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});
  let subject='',body='';

  if(type==='pending_approvals'){
    subject=`⚡ ${wfs.length} Pending Approvals — SP360 ERP — ${today}`;
    body=`${wfs.length} item(s) awaiting approval:\n\n`+wfs.slice(0,5).map(w=>`• ${w.ref_no} — ${w.current_step} [${w.status.toUpperCase()}]`).join('\n')+(wfs.length>5?`\n…and ${wfs.length-5} more`:'');
  } else if(type==='weekly_evm'){
    const active=projs.filter(p=>['planning','execution','monitoring','closeout'].includes(p.status));
    const cpi=active.length>0?(active.reduce((s,p)=>s+Number(p.ev||0),0)/Math.max(active.reduce((s,p)=>s+Number(p.ac||0),0),1)).toFixed(2):'—';
    subject=`📊 Weekly EVM Summary — SP360 ERP — ${today}`;
    body=`Portfolio CPI: ${cpi}\nActive Projects: ${active.length}\n\n`+active.slice(0,5).map(p=>`• ${(p.name||'').split('—')[0].trim()} | CPI: ${Number(p.cpi||1).toFixed(2)}`).join('\n');
  } else if(type==='ceo_report'){
    subject=`👔 CEO Flash Report Ready — SP360 ERP — ${today}`;
    body=`The CEO Flash Report for ${today} has been updated.\n\nLog in → CEO Report → Export PDF`;
  } else if(type==='overdue_invoices'){
    const overdue=invs.filter(i=>i.due_date&&new Date(i.due_date)<new Date());
    subject=`💰 ${overdue.length} Overdue AR Invoices — SP360 ERP — ${today}`;
    body=`${overdue.length} AR invoice(s) are overdue:\n\n`+overdue.slice(0,5).map(i=>`• ${i.invoice_no} — KWD ${Number(i.net_amount).toLocaleString()} (due ${new Date(i.due_date).toLocaleDateString('en-GB')})`).join('\n');
  } else if(type==='ncr_alert'){
    subject=`🛡 ${ncrs.length} Critical NCR(s) Open — SP360 ERP — ${today}`;
    body=`${ncrs.length} critical NCR(s) require immediate action:\n\n`+ncrs.slice(0,5).map(n=>`• ${n.ncr_no} — CRITICAL / OPEN`).join('\n');
  }

  openModal(`📧 Preview — ${t.name}`,`
    <div style="margin-bottom:12px;padding:10px;background:var(--n3);border-radius:6px">
      <div style="font-size:10px;color:var(--muted);margin-bottom:4px">SUBJECT</div>
      <div style="font-size:12px;font-weight:700;color:var(--text)">${esc(subject)}</div>
    </div>
    <div style="margin-bottom:12px;padding:10px;background:var(--n3);border-radius:6px">
      <div style="font-size:10px;color:var(--muted);margin-bottom:4px">BODY PREVIEW</div>
      <pre style="font-size:11px;color:var(--text);white-space:pre-wrap;font-family:inherit;margin:0">${esc(body)}</pre>
    </div>
    <div style="margin-bottom:12px;padding:10px;background:#C9A84C11;border:1px solid #C9A84C33;border-radius:6px;font-size:10px;color:var(--muted)">
      Recipients: all active users in their respective roles
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h256" data-ha-click="${esc(JSON.stringify([String((type)??'')]))}">📤 Send Now</button>
    </div>`);
}

// ── Load email history from audit trail ───────────────────────
async function loadEmailHistory(){
  const el = document.getElementById('email-history-list');
  if(!el) return;
  try{
    const {data} = await sb.from('audit_log')
      .select('created_at,action,new_data,performed_by')
      .eq('table_name','email_notifications')
      .order('created_at',{ascending:false})
      .limit(10);
    if(!data||data.length===0){ el.innerHTML='<div style="color:var(--faint);font-style:italic">No emails sent yet</div>'; return; }
    el.innerHTML = data.map(r=>{
      const d=r.new_data||{};
      const ts=new Date(r.created_at).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit'});
      return `<div style="display:flex;justify-content:space-between;align-items:center;padding:7px 0;border-bottom:1px solid var(--bdr)">
        <div>
          <div style="font-size:11px;color:var(--text)">${esc(d.subject||d.type||'Email Sent')}</div>
          <div style="font-size:9px;color:var(--faint)">${esc(d.recipients||'—')} recipients · ${ts}</div>
        </div>
        <span style="font-size:9px;background:#10B98122;color:#10B981;border:1px solid #10B98133;border-radius:4px;padding:2px 6px">✓ Sent</span>
      </div>`;
    }).join('');
  }catch(e){
    el.innerHTML='<div style="color:var(--faint)">History unavailable</div>';
  }
}

