// ── Additional notification types ─────────────────────────────
// Extend sendEmailNotification to handle new types
const _origSendEmailNotification = sendEmailNotification;
async function sendEmailNotification(type){
  const today = new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});

  // New types added in P3-3
  if(type==='overdue_invoices'){
    const [{data:invs},{data:users}] = await Promise.all([
      sb.from('invoices').select('invoice_no,net_amount,due_date,client').eq('invoice_type','client').neq('status','paid').neq('status','cancelled'),
      sb.from('user_profiles').select('email,role').eq('is_active',true)
    ]);
    const overdue=(invs||[]).filter(i=>i.due_date&&new Date(i.due_date)<new Date());
    const recipients=(users||[]).filter(u=>['Finance Manager','PMO Manager','Admin'].includes(u.role)).map(u=>u.email).filter(Boolean);
    if(!recipients.length){ showToast('No Finance recipients found','error'); return; }
    const subject=`💰 ${overdue.length} Overdue AR Invoices — SP360 ERP — ${today}`;
    const body=`Dear Finance Team,\n\n${overdue.length} AR invoice(s) are overdue:\n\n`
      +overdue.slice(0,10).map(i=>`  • ${i.invoice_no} — KWD ${Number(i.net_amount).toLocaleString()} (due ${new Date(i.due_date).toLocaleDateString('en-GB')})`).join('\n')
      +`\n\nLog in to SP360 ERP:\nhttps://falconbold1999-ops.github.io/sp360-erp/\n\nRegards,\nSP360 PMO Team`;
    showToast(`Sending Overdue AR Alert to ${recipients.length} users…`);
    const sent=await sendViaEdge(recipients,subject,body);
    if(sent){ showToast('Overdue AR Alert sent ✓'); await writeAudit('email_notifications',null,'EMAIL_SENT',null,{type,recipients:recipients.length,subject},'Overdue AR alert sent'); }
    else { fallbackMailto(recipients,subject,body); showToast('Email client opened'); }
    return;
  }

  if(type==='ncr_alert'){
    const [{data:ncrs},{data:users}] = await Promise.all([
      sb.from('ncrs').select('ncr_no,severity,department,description').eq('status','open').eq('severity','critical'),
      sb.from('user_profiles').select('email,role').eq('is_active',true)
    ]);
    const recipients=(users||[]).filter(u=>['QHSE Engineer','PMO Manager','Admin'].includes(u.role)).map(u=>u.email).filter(Boolean);
    if(!recipients.length){ showToast('No QHSE recipients found','error'); return; }
    const subject=`🛡 ${(ncrs||[]).length} Critical NCR(s) Open — SP360 ERP — ${today}`;
    const body=`Dear QHSE Team,\n\n${(ncrs||[]).length} critical NCR(s) require immediate action:\n\n`
      +(ncrs||[]).slice(0,10).map(n=>`  • ${n.ncr_no} — ${n.department||'N/A'} — CRITICAL / OPEN`).join('\n')
      +`\n\nLog in to SP360 ERP:\nhttps://falconbold1999-ops.github.io/sp360-erp/\n\nRegards,\nSP360 PMO Team`;
    showToast(`Sending Critical NCR Alert to ${recipients.length} users…`);
    const sent=await sendViaEdge(recipients,subject,body);
    if(sent){ showToast('Critical NCR Alert sent ✓'); await writeAudit('email_notifications',null,'EMAIL_SENT',null,{type,recipients:recipients.length,subject},'Critical NCR alert sent'); }
    else { fallbackMailto(recipients,subject,body); showToast('Email client opened'); }
    return;
  }

  // Delegate original types to original function
  return _origSendEmailNotification(type);
}

