// ══════════════════════════════════════════════════════════════
//  P4-1 · SYSTEM HEALTH DASHBOARD
// ══════════════════════════════════════════════════════════════
async function loadSystem(){
  const el = document.getElementById('page-system');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading System Dashboard…</div>';

  try{
    const today = new Date();
    const [errR, auditR, wfR, projR, invR, userR] = await Promise.all([
      sb.from('error_logs').select('id,severity,module,created_at,error_msg').order('created_at',{ascending:false}).limit(50),
      sb.from('audit_log').select('id,table_name,action,created_at').order('created_at',{ascending:false}).limit(100),
      sb.from('workflow_items').select('id,status,entity_type').in('status',['pending','overdue']),
      sb.from('projects').select('id,status,cpi,pct').in('status',['planning','execution','monitoring','closeout']),
      sb.from('material_master').select('*').not('reorder_level','is',null),   // FIX: material_items does not exist; stock lives in material_master
      sb.from('user_profiles').select('id,role,is_active,last_sign_in_at')
    ]);

    const errs   = errR.data||[];
    const audits = auditR.data||[];
    const wfs    = wfR.data||[];
    const projs  = projR.data||[];
    const items  = invR.data||[];
    const users  = userR.data||[];

    // Health scores
    const critErrs   = errs.filter(e=>e.severity==='critical').length;
    const overdueWF  = wfs.filter(w=>w.status==='overdue').length;
    const critCPI    = projs.filter(p=>Number(p.cpi)<0.9).length;
    const lowStock   = items.filter(i=>Number(i.current_stock??i.current_qty??0)<=Number(i.reorder_level)).length;
    const activeUsers= users.filter(u=>u.is_active!==false).length;

    // Overall health score
    let healthScore = 100;
    if(critErrs>0)  healthScore -= Math.min(critErrs*5, 25);
    if(overdueWF>0) healthScore -= Math.min(overdueWF*3, 15);
    if(critCPI>0)   healthScore -= Math.min(critCPI*5, 20);
    if(lowStock>0)  healthScore -= Math.min(lowStock*2, 10);
    healthScore = Math.max(healthScore, 0);

    const healthColor = healthScore>=85?'#10B981':healthScore>=70?'#F97316':'#EF4444';
    const healthLabel = healthScore>=85?'Healthy':healthScore>=70?'Needs Attention':'Critical';

    // Error breakdown by module
    const byModule = errs.reduce((m,e)=>{ m[e.module||'Unknown']=(m[e.module||'Unknown']||0)+1; return m; },{});
    const topModules = Object.entries(byModule).sort((a,b)=>b[1]-a[1]).slice(0,5);

    // Activity timeline (last 10 audits)
    const recent = audits.slice(0,10);

    // Error trend (last 7 days)
    const trend = [];
    for(let i=6;i>=0;i--){
      const d = new Date(today); d.setDate(d.getDate()-i);
      const ds = d.toISOString().split('T')[0];
      const cnt = errs.filter(e=>e.created_at?.startsWith(ds)).length;
      trend.push({day:d.toLocaleDateString('en-GB',{weekday:'short'}), cnt});
    }
    const maxTrend = Math.max(...trend.map(t=>t.cnt), 1);

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">⚙️</span>
        <div><h1>System Health Dashboard</h1><div class="sub">Real-time monitoring · SP360 v4.1 · ${today.toLocaleString('en-GB')}</div></div>
      </div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-ghost btn-sm" data-h-click="h257">🔄 Refresh</button>
        <button class="btn btn-ghost btn-sm" data-h-click="h258">📋 Audit Trail</button>
        <button class="btn btn-ghost btn-sm" data-h-click="h259" style="background:#F9731611;border-color:#F9731633;color:#F97316">🔔 KPI Alerts</button>
        <button class="btn btn-ghost btn-sm" data-h-click="h260" style="background:#8B5CF611;border-color:#8B5CF633;color:#8B5CF6">🏭 Vendor Portal</button>
      </div>
    </div>

    <!-- Health Score + KPIs -->
    <div style="display:grid;grid-template-columns:200px 1fr;gap:14px;margin-bottom:14px">
      <!-- Score gauge -->
      <div class="card" style="display:flex;flex-direction:column;align-items:center;justify-content:center;padding:20px">
        <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:8px">System Health</div>
        <div style="position:relative;width:100px;height:100px">
          <svg viewBox="0 0 100 100" style="width:100%;transform:rotate(-90deg)">
            <circle cx="50" cy="50" r="40" fill="none" stroke="var(--bdr)" stroke-width="12"/>
            <circle cx="50" cy="50" r="40" fill="none" stroke="${healthColor}" stroke-width="12"
              stroke-dasharray="${2*Math.PI*40*healthScore/100} ${2*Math.PI*40*(1-healthScore/100)}"
              stroke-linecap="round"/>
          </svg>
          <div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center">
            <div style="font-size:22px;font-weight:900;color:${healthColor}">${healthScore}</div>
            <div style="font-size:8px;color:var(--faint)">/100</div>
          </div>
        </div>
        <div style="font-size:12px;font-weight:700;color:${healthColor};margin-top:6px">${healthLabel}</div>
      </div>

      <!-- KPIs grid -->
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
        ${kpi('Critical Errors', critErrs, critErrs>0?'#EF4444':'#10B981', 'Last 50 logged')}
        ${kpi('Overdue Workflows', overdueWF, overdueWF>0?'#F97316':'#10B981', 'Pending action')}
        ${kpi('At-Risk Projects', critCPI, critCPI>0?'#EF4444':'#10B981', 'CPI < 0.90')}
        ${kpi('Low Stock Items', lowStock, lowStock>0?'#F97316':'#10B981', 'Below reorder level')}
        ${kpi('Active Users', activeUsers, '#C9A84C', `${esc(users.length)} total accounts`)}
        ${kpi('Audit Events', audits.length, '#3B82F6', 'Last 100 actions')}
      </div>
    </div>

    <div class="grid2" style="margin-bottom:14px">
      <!-- Error Trend (7 days) -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>📈</span>Error Trend — Last 7 Days</div></div>
        <div style="display:flex;align-items:flex-end;gap:6px;height:80px;padding-top:8px">
          ${trend.map(t=>`
          <div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:3px">
            <div style="font-size:9px;color:${t.cnt>0?'#EF4444':'var(--faint)'};font-weight:700">${esc(t.cnt||'')}</div>
            <div style="width:100%;background:${t.cnt>0?'#EF4444':'var(--bdr)'};border-radius:3px 3px 0 0;height:${Math.max(t.cnt/maxTrend*60,2)}px;min-height:2px"></div>
            <div style="font-size:8px;color:var(--faint)">${esc(t.day)}</div>
          </div>`).join('')}
        </div>
      </div>

      <!-- Error by Module -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🔴</span>Errors by Module</div></div>
        ${topModules.length===0
          ? '<div class="empty">No errors logged ✅</div>'
          : topModules.map(([mod,cnt])=>`
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
            <div style="font-size:11px;color:var(--text);width:100px;flex-shrink:0">${esc(mod)}</div>
            <div style="flex:1;background:var(--bdr);border-radius:3px;height:8px;overflow:hidden">
              <div style="height:100%;width:${(cnt/topModules[0][1]*100).toFixed(0)}%;background:#EF4444;border-radius:3px"></div>
            </div>
            <div style="font-size:11px;font-weight:700;color:#EF4444;width:24px;text-align:right">${cnt}</div>
          </div>`).join('')}
      </div>
    </div>

    <div class="grid2" style="margin-bottom:14px">
      <!-- Recent Activity -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>⚡</span>Recent System Activity</div></div>
        ${recent.length===0
          ? '<div class="empty">No recent activity</div>'
          : recent.map(a=>{
              const ts = new Date(a.created_at).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit'});
              const actColor = a.action?.includes('DELETE')?'#EF4444':a.action?.includes('CREATE')?'#10B981':'#3B82F6';
              return `<div style="display:flex;align-items:center;gap:8px;padding:5px 0;border-bottom:1px solid var(--bdr)">
                <span style="font-size:9px;background:${actColor}22;color:${actColor};border-radius:3px;padding:1px 5px;font-weight:700;flex-shrink:0">${esc(a.action?.split('_')[0]||'—')}</span>
                <span style="font-size:10px;color:var(--text);flex:1">${esc(a.table_name||'—')}</span>
                <span style="font-size:9px;color:var(--faint)">${ts}</span>
              </div>`;
            }).join('')}
      </div>

      <!-- System Checks -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🔍</span>Live System Checks</div></div>
        <div id="sys-health-results" style="font-size:11px;color:var(--muted)">Click Run to check…</div>
        <button data-h-click="h261" class="btn btn-primary btn-sm" style="margin-top:12px;width:100%">🔍 Run All Checks</button>
      </div>
    </div>

    <!-- Recent Critical Errors -->
    ${critErrs>0 ? `
    <div class="card" style="border-left:3px solid #EF4444">
      <div class="sec-head"><div class="sec-title"><span>🚨</span>Critical Errors — Requires Attention</div></div>
      <table><thead><tr><th>Error ID</th><th>Module</th><th>Action</th><th>Time</th><th>Message</th></tr></thead><tbody>
      ${errs.filter(e=>e.severity==='critical').slice(0,10).map(e=>`<tr>
        <td style="font-family:monospace;font-size:9px;color:var(--gold)">${esc(e.error_id||'—')}</td>
        <td style="font-size:10px">${esc(e.module||'—')}</td>
        <td style="font-size:10px;color:var(--muted)">${esc(e.action||'—')}</td>
        <td style="font-size:10px;color:var(--faint);white-space:nowrap">${new Date(e.created_at).toLocaleString('en-GB',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})}</td>
        <td style="font-size:10px;color:#EF4444;max-width:300px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(e.error_msg||'—')}</td>
      </tr>`).join('')}
      </tbody></table>
    </div>` : `
    <div class="card" style="text-align:center;padding:20px;border-left:3px solid #10B981">
      <div style="font-size:24px;margin-bottom:6px">✅</div>
      <div style="font-size:13px;font-weight:700;color:#10B981">No Critical Errors</div>
      <div style="font-size:11px;color:var(--muted);margin-top:4px">System running cleanly</div>
    </div>`}`;

  }catch(err){
    el.innerHTML = `<div class="empty">Error loading system dashboard: ${esc(err.message)}</div>`;
    console.error('loadSystem error:',err);
  }
}

// ── Live system checks (extended version of health check) ─────
async function runSystemChecks(){
  const el = document.getElementById('sys-health-results');
  if(!el) return;
  el.innerHTML = '<div style="color:var(--muted)">⏳ Running checks…</div>';

  const checks = [];
  const check = async(name, fn)=>{
    const start = Date.now();
    try{
      const result = await fn();
      // P1: explicit failure semantics — false, '✗…' or empty result = FAIL ("No session" is no longer a PASS)
      const txt=result===true?'':String(result??'');
      checks.push({name, ok:result!==false && result!=null && !/^\s*✗/.test(txt), ms:Date.now()-start, msg:txt});
    }catch(e){
      checks.push({name, ok:false, ms:Date.now()-start, msg:e.message});
    }
  };

  await check('Database Connection',    async()=>{ const {error}=await sb.from('user_profiles').select('id').limit(1); return error?false:'✓ Connected'; });
  await check('Auth Session',           async()=>{ const {data:{session}}=await sb.auth.getSession(); return session?`✓ ${currentProfile?.full_name}`:'✗ No session'; });
  await check('Projects Table',         async()=>{ const {error}=await sb.from('projects').select('id').limit(1); return error?false:'✓ Accessible'; });
  await check('Workflow Items',         async()=>{ const {error}=await sb.from('workflow_items').select('id').limit(1); return error?false:'✓ Accessible'; });
  await check('Invoice Table',          async()=>{ const {error}=await sb.from('invoices').select('id').limit(1); return error?false:'✓ Accessible'; });
  await check('Payroll Config',         async()=>{ const {data,error}=await sb.from('payroll_config').select('id').eq('is_active',true).limit(1); return error?false:data?.length>0?'✓ Config active':'⚠ No active config'; });
  await check('Error Log Table',        async()=>{ const {error}=await sb.from('error_logs').select('id').limit(1); return error?false:'✓ Accessible'; });
  await check('Audit Log',             async()=>{ const {error}=await sb.from('audit_log').select('id').limit(1); return error?false:'✓ Accessible'; });
  await check('RPC sp360_role',         async()=>{ const {data,error}=await sb.rpc('sp360_role'); return error?false:`✓ Role: ${data||'—'}`; });
  await check('PWA Service Worker',     async()=>{ if(!('serviceWorker' in navigator)) return '⚠ Not supported'; const r=await navigator.serviceWorker.getRegistrations(); return r.length>0?'✓ Registered':'⚠ Not registered'; });

  const passed = checks.filter(c=>c.ok).length;
  el.innerHTML = `
    <div style="margin-bottom:8px;padding:6px 10px;background:${passed===checks.length?'#10B98122':'#EF444422'};border-radius:5px;font-size:10px;font-weight:700;color:${passed===checks.length?'#10B981':'#EF4444'}">
      ${passed===checks.length?'✅':'⚠️'} ${passed}/${esc(checks.length)} passed
    </div>
    ${checks.map(c=>`
    <div style="display:flex;align-items:center;gap:6px;padding:4px 0;border-bottom:1px solid var(--bdr);font-size:10px">
      <span>${c.ok?'✅':'❌'}</span>
      <span style="flex:1;color:var(--text)">${esc(c.name)}</span>
      <span style="color:var(--faint)">${esc(c.ms)}ms</span>
      <span style="color:${c.ok?'var(--muted)':'#EF4444'}">${esc(c.msg)}</span>
    </div>`).join('')}`;
}

// ══════════════════════════════════════════════════════════════
//  P4-2 · PAYROLL SLIP (PDF Export per employee)
// ══════════════════════════════════════════════════════════════
async function exportPayslip(runId){
  try{
    const {data:run,error}=await sb.from('payroll_runs')
      .select('*,employee:employees(full_name,employee_no,department,position,employee_contracts(basic_salary,allowances))')
      .eq('id',runId).single();
    if(error||!run){showToast('Payroll record not found','error');return;}

    const {data:cfg}=await sb.from('payroll_config').select('*').eq('is_active',true).limit(1);
    const payConfig=cfg?.[0]||{};

    const emp  = run.employee||{};
    const basic= Number(run.basic_salary||0);
    const allow= Number(run.allowances||0);
    const gross= Number(run.gross_salary||0);
    const nssf = Number(run.nssf_deduction||0);
    const tax  = Number(run.tax_deduction||0);
    const other= Number(run.other_deductions||0);
    const net  = Number(run.net_salary||0);
    const erNSSF= basic*Number(payConfig.nssf_employer_pct||11)/100;

    // Build PDF using jsPDF
    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});

    // Header — navy background
    doc.setFillColor(30,58,95);
    doc.rect(0,0,210,40,'F');
    doc.setTextColor(201,168,76);
    doc.setFontSize(18);
    doc.setFont('helvetica','bold');
    doc.text('SMART PROJECTS 360',14,16);
    doc.setTextColor(148,163,184);
    doc.setFontSize(9);
    doc.setFont('helvetica','normal');
    doc.text('Kuwait · SP360 v4.1 · Payroll Management System',14,23);
    doc.setTextColor(255,255,255);
    doc.setFontSize(14);
    doc.setFont('helvetica','bold');
    doc.text('PAYROLL SLIP',14,33);
    doc.setFontSize(10);
    doc.text(`Period: ${run.period_month||'—'}`,120,20);
    doc.text(`Generated: ${new Date().toLocaleDateString('en-GB')}`,120,27);
    doc.text(`Status: ${(run.status||'').toUpperCase()}`,120,34);

    // Employee info box
    doc.setFillColor(241,245,249);
    doc.rect(0,44,210,28,'F');
    doc.setTextColor(30,58,95);
    doc.setFontSize(11);
    doc.setFont('helvetica','bold');
    doc.text('EMPLOYEE INFORMATION',14,53);
    doc.setFont('helvetica','normal');
    doc.setFontSize(9);
    doc.setTextColor(71,85,105);
    doc.text(`Name: ${emp.full_name||'—'}`,14,60);
    doc.text(`Employee No: ${emp.employee_no||'—'}`,14,66);
    doc.text(`Department: ${emp.department||'—'}`,100,60);
    doc.text(`Position: ${emp.position||'—'}`,100,66);

    // Earnings table
    let y=82;
    doc.setFillColor(30,58,95);
    doc.rect(14,y-5,182,7,'F');
    doc.setTextColor(201,168,76);
    doc.setFontSize(9);
    doc.setFont('helvetica','bold');
    doc.text('EARNINGS',16,y);
    doc.text('AMOUNT (KWD)',160,y,'right');
    y+=6;

    const earningsRows=[
      ['Basic Salary',basic],
      ['Allowances',allow],
    ];
    earningsRows.forEach(([lbl,val],i)=>{
      doc.setFillColor(i%2===0?255:248,i%2===0?255:250,i%2===0?255:252);
      doc.rect(14,y-4,182,7,'F');
      doc.setTextColor(15,23,42);
      doc.setFont('helvetica','normal');
      doc.text(lbl,16,y);
      doc.text(`KWD ${val.toFixed(3)}`,196,y,'right');
      y+=7;
    });

    // Gross total
    doc.setFillColor(30,58,95);
    doc.rect(14,y-4,182,7,'F');
    doc.setTextColor(255,255,255);
    doc.setFont('helvetica','bold');
    doc.text('GROSS SALARY',16,y);
    doc.text(`KWD ${gross.toFixed(3)}`,196,y,'right');
    y+=14;

    // Deductions table
    doc.setFillColor(239,68,68);
    doc.rect(14,y-5,182,7,'F');
    doc.setTextColor(255,255,255);
    doc.text('DEDUCTIONS',16,y);
    doc.text('AMOUNT (KWD)',160,y,'right');
    y+=6;

    const deductRows=[
      ['NSSF (Employee '+( payConfig.nssf_employee_pct||5)+'%)', nssf],
      ['Income Tax ('+(payConfig.income_tax_pct||0)+'%)', tax],
      ['Other Deductions', other],
    ];
    deductRows.forEach(([lbl,val],i)=>{
      doc.setFillColor(i%2===0?255:254,i%2===0?242:242,i%2===0?242:242);
      doc.rect(14,y-4,182,7,'F');
      doc.setTextColor(15,23,42);
      doc.setFont('helvetica','normal');
      doc.text(lbl,16,y);
      doc.text(`KWD ${val.toFixed(3)}`,196,y,'right');
      y+=7;
    });

    // Total deductions
    const totalDeduct = nssf+tax+other;
    doc.setFillColor(220,38,38);
    doc.rect(14,y-4,182,7,'F');
    doc.setTextColor(255,255,255);
    doc.setFont('helvetica','bold');
    doc.text('TOTAL DEDUCTIONS',16,y);
    doc.text(`KWD ${totalDeduct.toFixed(3)}`,196,y,'right');
    y+=14;

    // NET SALARY — prominent
    doc.setFillColor(16,185,129);
    doc.rect(14,y-6,182,12,'F');
    doc.setTextColor(255,255,255);
    doc.setFontSize(13);
    doc.text('NET SALARY',16,y+1);
    doc.text(`KWD ${net.toFixed(3)}`,196,y+1,'right');
    y+=20;

    // Employer contribution
    doc.setFontSize(8);
    doc.setTextColor(100,116,139);
    doc.setFont('helvetica','normal');
    doc.text(`Employer NSSF Contribution (${payConfig.nssf_employer_pct||11}%): KWD ${erNSSF.toFixed(3)} (not deducted from employee)`,14,y);
    y+=10;

    // Footer
    doc.setDrawColor(201,168,76);
    doc.line(14,y,196,y);
    y+=5;
    doc.setTextColor(100,116,139);
    doc.setFontSize(8);
    doc.text('This is a computer-generated payslip. SP360 v4.1 · Smart Projects 360 · Kuwait · Confidential',105,y,'center');

    doc.save(`Payslip_${emp.employee_no||'EMP'}_${run.period_month||'period'}.pdf`);
    showToast('Payslip exported ✓');

  }catch(e){
    showToast('Payslip error: '+e.message,'error');
    logError('HR','exportPayslip',e);
  }
}

// ══════════════════════════════════════════════════════════════
//  P4-3 · GL AUTO-POSTING ENGINE
//  Generates journal entries from invoice events
// ══════════════════════════════════════════════════════════════

// Auto-post GL entries when invoice status changes
async function glAutoPost(invoiceId, eventType){
  try{
    const {data:inv} = await sb.from('invoices')
      .select('*,project:projects(name,project_no)')
      .eq('id',invoiceId).single();
    if(!inv) return;

    const amount = Number(inv.net_amount)||0;
    if(amount<=0) return;

    let entries = [];
    const ref   = inv.invoice_no || inv.id;
    const desc  = `${inv.invoice_type==='client'?'AR':'AP'} — ${inv.invoice_no} — ${inv.project?.project_no||'N/A'}`;
    const today = new Date().toISOString().split('T')[0];

    if(eventType==='invoice_created'){
      if(inv.invoice_type==='client'){
        // DR Accounts Receivable, CR Revenue
        entries=[
          {account_code:'1100',account_name:'Accounts Receivable',debit:amount,credit:0,description:desc},
          {account_code:'4000',account_name:'Revenue',debit:0,credit:amount,description:desc}
        ];
      } else {
        // DR Expense, CR Accounts Payable
        entries=[
          {account_code:'5000',account_name:'Cost of Services',debit:amount,credit:0,description:desc},
          {account_code:'2100',account_name:'Accounts Payable',debit:0,credit:amount,description:desc}
        ];
      }
    } else if(eventType==='invoice_paid'){
      if(inv.invoice_type==='client'){
        // DR Cash/Bank, CR Accounts Receivable
        entries=[
          {account_code:'1000',account_name:'Cash & Bank',debit:amount,credit:0,description:'Receipt — '+desc},
          {account_code:'1100',account_name:'Accounts Receivable',debit:0,credit:amount,description:'Receipt — '+desc}
        ];
      } else {
        // DR Accounts Payable, CR Cash/Bank
        entries=[
          {account_code:'2100',account_name:'Accounts Payable',debit:amount,credit:0,description:'Payment — '+desc},
          {account_code:'1000',account_name:'Cash & Bank',debit:0,credit:amount,description:'Payment — '+desc}
        ];
      }
    }

    if(entries.length===0) return;

    // Get next journal number
    const jNo=await nextRefNo('JE');

    // Insert journal entry header
    const {data:je,error:jeErr} = await sb.from('journal_entries').insert({
      entry_no:       jNo,
      entry_date:     today,
      entry_type:     'auto',
      reference_type: 'invoice',
      reference_id:   invoiceId,
      description:    desc,
      total_debit:    amount,
      total_credit:   amount,
      status:         'posted',
      posted_by:      currentProfile?.id,
      created_by:     currentProfile?.id
    }).select('id').single();

    if(jeErr){
      console.warn('GL auto-post header failed:',jeErr.message);
      return;
    }

    // Insert journal lines
    const lines = entries.map((e,i)=>({
      journal_id:   je.id,
      line_no:      i+1,
      account_code: e.account_code,
      account_name: e.account_name,
      debit:        e.debit,
      credit:       e.credit,
      description:  e.description,
      project_id:   inv.project_id||null
    }));

    const {error:linesErr} = await sb.from('journal_lines').insert(lines);
    if(linesErr) console.warn('GL auto-post lines failed:',linesErr.message);
    else console.log(`GL auto-posted: ${jNo} for invoice ${ref} (${eventType})`);

  }catch(e){
    console.warn('glAutoPost failed (non-blocking):',e.message);
  }
}

// ── Hook GL auto-posting into invoice save ────────────────────
// Call this after saveInvoice succeeds
async function _afterInvoiceSave(invoiceId, isNew, isPaid){
  if(isNew) await glAutoPost(invoiceId, 'invoice_created');
  if(isPaid) await glAutoPost(invoiceId, 'invoice_paid');
}

// ══════════════════════════════════════════════════════════════
//  P4-4 · INVENTORY ATOMIC GUARD
//  Prevents split-brain stock movements in the UI
// ══════════════════════════════════════════════════════════════
let _inventoryLocked = false;

async function recordStockMovementSafe(params){
  if(_inventoryLocked){
    showToast('⚠️ Another stock movement is in progress — please wait','error');
    return false;
  }
  _inventoryLocked = true;
  try{
    // Try atomic RPC first (if deployed)
    const {data,error} = await sb.rpc('record_stock_movement_atomic',{
      p_item_id:       params.itemId,
      p_movement_type: params.type,
      p_quantity:      params.qty,
      p_unit_cost:     params.unitCost||0,
      p_reference_type:params.refType||null,
      p_reference_id:  params.refId||null,
      p_project_id:    params.projectId||null,
      p_notes:         params.notes||null,
      p_created_by:    currentProfile?.id
    });

    if(error){
      // Fallback: check if it's a "function doesn't exist" error
      if(error.message?.includes('does not exist')||error.code==='42883'){
        console.warn('record_stock_movement_atomic not deployed — using fallback');
        return await _recordStockMovementFallback(params);
      }
      showToast('Stock movement error: '+error.message,'error');
      logError('Inventory','recordStockMovement',error,params);
      return false;
    }

    if(!data?.ok){
      showToast('Stock movement failed: '+(data?.error||'Unknown error'),'error');
      return false;
    }

    await writeAudit('stock_movements',data.movement_id,'STOCK_MOVEMENT',null,params,'Stock movement recorded');
    return data;

  }catch(e){
    showToast('Stock movement error: '+e.message,'error');
    logError('Inventory','recordStockMovement',e,params);
    return false;
  }finally{
    _inventoryLocked = false;
  }
}

// Fallback when atomic RPC not deployed — still with guards
async function _recordStockMovementFallback(params){
  try{
    // Step 1: Get current stock with row-level check
    const {data:item,error:itemErr} = await sb.from('material_items')
      .select('id,current_qty,item_code,item_name')
      .eq('id',params.itemId).single();

    if(itemErr||!item){
      showToast('Item not found','error');
      return false;
    }

    // Step 2: Validate stock availability for outbound
    if(['issue','transfer_out'].includes(params.type)){
      if(Number(item.current_qty)<params.qty){
        showToast(`Insufficient stock: available ${item.current_qty}, requested ${params.qty}`,'error');
        return false;
      }
    }

    // Step 3: Get movement number
    const mvNo=await nextRefNo('MV');

    // Step 4: Insert ledger entry
    const newQty = ['issue','transfer_out','return_vendor'].includes(params.type)
      ? Number(item.current_qty)-params.qty
      : Number(item.current_qty)+params.qty;

    const {data:mv,error:mvErr} = await sb.from('stock_movements').insert({
      movement_no:    mvNo,
      item_id:        params.itemId,
      movement_type:  params.type,
      quantity:       params.qty,
      unit_cost:      params.unitCost||0,
      total_value:    params.qty*(params.unitCost||0),
      qty_before:     Number(item.current_qty),
      qty_after:      newQty,
      reference_type: params.refType||null,
      reference_id:   params.refId||null,
      project_id:     params.projectId||null,
      notes:          params.notes||null,
      created_by:     currentProfile?.id
    }).select('id').single();

    if(mvErr){
      showToast('Ledger insert failed: '+mvErr.message,'error');
      logError('Inventory','stockLedgerInsert',mvErr,params);
      return false;
    }

    // Step 5: Update stock balance
    const {error:updErr} = await sb.from('material_items')
      .update({current_qty:newQty, updated_at:new Date().toISOString()})
      .eq('id',params.itemId);

    if(updErr){
      // CRITICAL: ledger inserted but stock not updated — log as critical
      await logError('Inventory','stockBalanceUpdate',updErr,{...params,mvId:mv.id,severity:'critical'});
      showToast('⚠️ CRITICAL: Ledger recorded but stock balance failed to update. Contact Admin.','error');
      return false;
    }

    return {ok:true, movement_id:mv.id, movement_no:mvNo, new_qty:newQty};

  }catch(e){
    logError('Inventory','stockMovementFallback',e,params);
    return false;
  }
}

