// ══════════════════════════════════════════════════════════════
//  P4-6 · VALIDATION ENGINE
//  Server-side style validation for critical forms
// ══════════════════════════════════════════════════════════════
const VALIDATION_RULES = {
  invoice: {
    net_amount:      {min:0.001, msg:'Invoice amount must be > 0'},
    invoice_date:    {required:true, msg:'Invoice date required'},
    invoice_type:    {required:true, msg:'Invoice type required'},
  },
  project: {
    bac:             {min:0.001, msg:'BAC must be > 0'},
    contract_value:  {min:0.001, msg:'Contract value must be > 0'},
    name:            {required:true, minLen:3, msg:'Project name must be at least 3 characters'},
  },
  purchase_order: {
    total_amount:    {min:0.001, msg:'PO amount must be > 0'},
    vendor_id:       {required:true, msg:'Vendor required'},
  },
  stock_movement: {
    quantity:        {min:0.001, msg:'Quantity must be > 0'},
    item_id:         {required:true, msg:'Item required'},
  }
};

function validateForm(entity, data){
  const rules = VALIDATION_RULES[entity];
  if(!rules) return {ok:true};
  const errors = [];
  for(const [field,rule] of Object.entries(rules)){
    const val = data[field];
    if(rule.required && (val===null||val===undefined||val===''))
      errors.push(rule.msg||`${field} is required`);
    if(rule.min!==undefined && Number(val)<rule.min)
      errors.push(rule.msg||`${field} minimum is ${rule.min}`);
    if(rule.minLen!==undefined && String(val||'').length<rule.minLen)
      errors.push(rule.msg||`${field} too short`);
  }
  return {ok:errors.length===0, errors};
}

// ══════════════════════════════════════════════════════════════
//  P5-1 · RESOURCE MANAGEMENT
//  Employee allocation across projects + utilization tracking
// ══════════════════════════════════════════════════════════════
async function loadResources(){
  const el = document.getElementById('page-resources');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading Resources…</div>';
  try{
    const [empR, projR, allocR] = await Promise.all([
      sb.from('employees').select('id,full_name,employee_no,department,position,status').eq('status','active').order('full_name'),
      sb.from('projects').select('id,project_no,name,status,department,pct').in('status',['planning','execution','monitoring']).order('project_no'),
      sb.from('resource_allocations').select('*,employee:employees(full_name,employee_no,department),project:projects(project_no,name,status)').order('created_at',{ascending:false}).limit(200)
    ]);
    const emps  = empR.data||[];
    const projs = projR.data||[];
    const allocs = allocR.data||[];

    // Utilization per employee
    const utilMap = {};
    allocs.filter(a=>a.status==='active').forEach(a=>{
      if(!utilMap[a.employee_id]) utilMap[a.employee_id] = 0;
      utilMap[a.employee_id] += Number(a.allocation_pct||0);
    });

    // Dept summary
    const depts = [...new Set(emps.map(e=>e.department).filter(Boolean))].sort();
    const deptUtil = depts.map(d=>{
      const dEmps = emps.filter(e=>e.department===d);
      const avgUtil = dEmps.length ? dEmps.reduce((s,e)=>s+(utilMap[e.id]||0),0)/dEmps.length : 0;
      return {dept:d, count:dEmps.length, avgUtil:Math.round(avgUtil)};
    });

    const overAllocated = emps.filter(e=>(utilMap[e.id]||0)>100).length;
    const unallocated   = emps.filter(e=>!(utilMap[e.id]>0)).length;

    const canEdit = can('create');

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">👷</span>
        <div><h1>Resource Management</h1><div class="sub">Employee Allocation · Utilization · Project Staffing</div></div>
      </div>
      ${canEdit ? `<button class="btn btn-primary btn-sm" data-h-click="h262">+ Allocate Resource</button>` : ''}
    </div>

    <!-- KPIs -->
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Active Employees', emps.length, '#C9A84C', 'Available for allocation')}
      ${kpi('Active Projects',  projs.length, '#3B82F6', 'Requiring resources')}
      ${kpi('Over-Allocated',   overAllocated, overAllocated>0?'#EF4444':'#10B981', '>100% allocation')}
      ${kpi('Unallocated',      unallocated, unallocated>0?'#F97316':'#10B981', 'No active project')}
    </div>

    <div class="grid2" style="margin-bottom:14px">
      <!-- Utilization by department -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>📊</span>Utilization by Department</div></div>
        ${deptUtil.map(d=>`
        <div style="margin-bottom:10px">
          <div style="display:flex;justify-content:space-between;margin-bottom:4px">
            <span style="font-size:11px;font-weight:700;color:var(--text)">${esc(d.dept)}</span>
            <span style="font-size:10px;color:${d.avgUtil>100?'#EF4444':d.avgUtil>80?'#F97316':'#10B981'};font-weight:700">${esc(d.avgUtil)}% avg · ${esc(d.count)} staff</span>
          </div>
          <div style="background:var(--bdr);border-radius:4px;height:8px;overflow:hidden">
            <div style="height:100%;width:${Math.min(d.avgUtil,100)}%;background:${d.avgUtil>100?'#EF4444':d.avgUtil>80?'#F97316':'#3B82F6'};border-radius:4px;transition:width .3s"></div>
          </div>
        </div>`).join('')}
      </div>

      <!-- Project capacity -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🏗</span>Project Headcount</div></div>
        ${projs.slice(0,8).map(p=>{
          const pAllocs = allocs.filter(a=>a.project_id===p.id&&a.status==='active');
          return `<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--bdr)">
            <div style="flex:1;min-width:0">
              <div style="font-size:11px;font-weight:700;color:var(--gold)">${esc(p.project_no)}</div>
              <div style="font-size:10px;color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(p.name)}</div>
            </div>
            <div style="text-align:right;flex-shrink:0">
              <div style="font-size:14px;font-weight:800;color:var(--text)">${esc(pAllocs.length)}</div>
              <div style="font-size:9px;color:var(--faint)">staff</div>
            </div>
          </div>`;
        }).join('')}
      </div>
    </div>

    <!-- Allocation table -->
    <div class="card">
      <div class="sec-head">
        <div class="sec-title"><span>📋</span>Active Allocations</div>
        <div style="font-size:10px;color:var(--muted)">${allocs.filter(a=>a.status==='active').length} active</div>
      </div>
      ${allocs.length===0
        ? '<div class="empty">No allocations yet — click + Allocate Resource to start</div>'
        : `<table><thead><tr>
            <th>Employee</th><th>Department</th><th>Project</th><th style="text-align:center">Allocation %</th><th>Role</th><th>From</th><th>To</th><th style="text-align:center">Status</th>
            ${canEdit?'<th></th>':''}
          </tr></thead><tbody>
          ${allocs.slice(0,50).map(a=>{
            const util = utilMap[a.employee_id]||0;
            const pct  = Number(a.allocation_pct||0);
            const col  = util>100?'#EF4444':util>80?'#F97316':'#10B981';
            return `<tr>
              <td style="font-weight:700;font-size:11px">${esc(a.employee?.full_name||'—')}</td>
              <td style="font-size:10px;color:var(--muted)">${esc(a.employee?.department||'—')}</td>
              <td style="color:var(--gold);font-size:10px">${esc(a.project?.project_no||'—')}</td>
              <td style="text-align:center">
                <div style="display:flex;align-items:center;gap:4px;justify-content:center">
                  <div style="width:40px;background:var(--bdr);border-radius:3px;height:6px;overflow:hidden">
                    <div style="height:100%;width:${Math.min(pct,100)}%;background:${col};border-radius:3px"></div>
                  </div>
                  <span style="font-size:10px;font-weight:700;color:${col}">${pct}%</span>
                </div>
              </td>
              <td style="font-size:10px;color:var(--muted)">${esc(a.role_on_project||'—')}</td>
              <td style="font-size:10px;color:var(--faint)">${esc(a.start_date||'—')}</td>
              <td style="font-size:10px;color:var(--faint)">${esc(a.end_date||'Open')}</td>
              <td style="text-align:center">${pill(a.status||'active',a.status==='active'?'#10B981':'#94A3B8')}</td>
              ${canEdit?`<td><button data-h-click="h263" data-ha-click="${esc(JSON.stringify([String((a.id)??'')]))}" style="background:none;border:none;color:var(--faint);cursor:pointer;font-size:11px" title="End allocation">✕</button></td>`:''}
            </tr>`;
          }).join('')}
          </tbody></table>`}
    </div>`;

  }catch(err){
    el.innerHTML = `<div class="empty">Error: ${esc(err.message)}</div>`;
  }
}

function openAllocModal(){
  const emps  = window._cachedEmployees||[];
  const projs = window._cachedProjects||[];
  const today = new Date().toISOString().split('T')[0];
  openModal('Allocate Resource to Project',`
    <div class="form-row">
      <div class="form-field"><label>Employee *</label>
        <select id="alloc-emp" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="">— Select Employee —</option>
          ${emps.map(e=>`<option value="${esc(e.id)}">${esc(e.full_name)} (${esc(e.employee_no||'')})</option>`).join('')}
        </select>
      </div>
      <div class="form-field"><label>Project *</label>
        <select id="alloc-proj" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="">— Select Project —</option>
          ${projs.map(p=>`<option value="${esc(p.id)}">${esc(p.project_no)} — ${esc(p.name)}</option>`).join('')}
        </select>
      </div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Allocation % *</label><input id="alloc-pct" type="number" min="1" max="100" value="100" placeholder="100"/></div>
      <div class="form-field"><label>Role on Project</label><input id="alloc-role" placeholder="e.g. Site Engineer"/></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Start Date *</label><input id="alloc-start" type="date" value="${today}"/></div>
      <div class="form-field"><label>End Date (blank = open)</label><input id="alloc-end" type="date"/></div>
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h264">Allocate</button>
    </div>`);
}

async function saveAllocation(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const empId  = document.getElementById('alloc-emp').value;
    const projId = document.getElementById('alloc-proj').value;
    const pct    = Number(document.getElementById('alloc-pct').value)||100;
    const role   = document.getElementById('alloc-role').value.trim();
    const start  = document.getElementById('alloc-start').value;
    const end    = document.getElementById('alloc-end').value||null;
    if(!empId){showToast('Employee required','error');return;}
    if(!projId){showToast('Project required','error');return;}
    if(!start){showToast('Start date required','error');return;}
    if(pct<1||pct>100){showToast('Allocation must be 1-100%','error');return;}
    const {error}=await sb.from('resource_allocations').insert({
      employee_id:empId, project_id:projId, allocation_pct:pct,
      role_on_project:role||null, start_date:start, end_date:end,
      status:'active', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Resource allocated ✓');
    closeModal(); loadResources();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Allocate';}}
}

async function endAllocation(id){
  if(!confirm('End this allocation?')) return;
  const {error}=await sb.from('resource_allocations').update({
    status:'ended', end_date:new Date().toISOString().split('T')[0]
  }).eq('id',id);
  if(error){showToast('Error: '+error.message,'error');return;}
  showToast('Allocation ended ✓');
  loadResources();
}

// ══════════════════════════════════════════════════════════════
//  P5-2 · KPI SCORECARD
//  Executive KPI dashboard with targets, actuals, trend
// ══════════════════════════════════════════════════════════════
async function loadScorecard(){
  const el = document.getElementById('page-scorecard');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading Scorecard…</div>';
  try{
    const today = new Date();
    const [projR, invR, wfR, ncrR, empR] = await Promise.all([
      sb.from('projects').select('id,status,cpi,spi,pct,bac,ev,ac,pv,department').order('project_no'),
      sb.from('invoices').select('id,invoice_type,status,net_amount,due_date,created_at').order('created_at',{ascending:false}),
      sb.from('workflow_items').select('id,status,created_at').in('status',['pending','overdue']),
      sb.from('ncrs').select('id,severity,status'),
      sb.from('employees').select('id,status').eq('status','active')
    ]);
    const projs  = projR.data||[];
    const invs   = invR.data||[];
    const wfs    = wfR.data||[];
    const ncrs   = ncrR.data||[];
    const emps   = empR.data||[];

    const active = projs.filter(p=>ACTIVE_STATUSES.includes(p.status));
    const totalBAC = active.reduce((s,p)=>s+Number(p.bac),0);
    const totalEV  = active.reduce((s,p)=>s+Number(p.ev),0);
    const totalAC  = active.reduce((s,p)=>s+Number(p.ac),0);
    const totalPV  = active.reduce((s,p)=>s+Number(p.pv),0);
    const portCPI  = totalAC>0?(totalEV/totalAC):1;
    const portSPI  = totalPV>0?(totalEV/totalPV):1;
    const rev      = invs.filter(i=>i.invoice_type==='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
    const cost     = invs.filter(i=>i.invoice_type!=='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
    const arOut    = invs.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount),0);
    const overdueAR= invs.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)&&i.due_date&&new Date(i.due_date)<today).length;
    const gp       = rev-cost;
    const gpPct    = rev>0?(gp/rev*100):0;
    const avgPct   = active.length>0?active.reduce((s,p)=>s+Number(p.pct||0),0)/active.length:0;
    const openNCR  = ncrs.filter(n=>n.status==='open').length;
    const critNCR  = ncrs.filter(n=>n.severity==='critical'&&n.status==='open').length;
    const pendWF   = wfs.length;

    // KPI definitions: {label, value, target, unit, icon, color, desc, direction}
    const kpis = [
      // Project Controls
      {cat:'📊 Project Performance', items:[
        {label:'Portfolio CPI',      val:portCPI,         target:1.00, fmt:v=>v.toFixed(3), unit:'ratio', dir:'higher', desc:'Cost Performance Index — ≥1.00 target'},
        {label:'Portfolio SPI',      val:portSPI,         target:1.00, fmt:v=>v.toFixed(3), unit:'ratio', dir:'higher', desc:'Schedule Performance Index — ≥1.00 target'},
        {label:'Avg % Complete',     val:avgPct,          target:50,   fmt:v=>v.toFixed(1)+'%', unit:'%',  dir:'higher', desc:'Average progress across active projects'},
        {label:'Active Projects',    val:active.length,   target:null, fmt:v=>v, unit:'count', dir:null,  desc:'Projects in active status'},
      ]},
      // Finance
      {cat:'💰 Financial Performance', items:[
        {label:'GP Margin',          val:gpPct,           target:25,   fmt:v=>v.toFixed(1)+'%', unit:'%',  dir:'higher', desc:'Gross profit as % of collected revenue'},
        {label:'AR Outstanding',     val:arOut/1000,      target:null, fmt:v=>'KD '+v.toFixed(0)+'K', unit:'KD', dir:'lower', desc:'Total AR awaiting collection'},
        {label:'Overdue AR Count',   val:overdueAR,       target:0,    fmt:v=>v, unit:'invoices', dir:'lower', desc:'AR invoices past due date'},
        {label:'Revenue Collected',  val:rev/1000,        target:null, fmt:v=>'KD '+v.toFixed(0)+'K', unit:'KD', dir:'higher', desc:'Total client invoices paid'},
      ]},
      // Quality & Operations
      {cat:'🛡 Quality & Operations', items:[
        {label:'Open NCRs',          val:openNCR,         target:0,    fmt:v=>v, unit:'count', dir:'lower', desc:'Non-Conformance Reports open'},
        {label:'Critical NCRs',      val:critNCR,         target:0,    fmt:v=>v, unit:'count', dir:'lower', desc:'Critical severity NCRs open'},
        {label:'Pending Approvals',  val:pendWF,          target:0,    fmt:v=>v, unit:'count', dir:'lower', desc:'Workflow items awaiting action'},
        {label:'Active Headcount',   val:emps.length,     target:null, fmt:v=>v, unit:'staff', dir:null,  desc:'Active employees'},
      ]},
    ];

    const renderKPICard = (item)=>{
      const v = item.val;
      const t = item.target;
      let status='neutral', statusColor='#94A3B8', statusIcon='—';
      if(t!==null && item.dir){
        const ok = item.dir==='higher' ? v>=t : v<=t;
        const warn = item.dir==='higher' ? v>=t*0.9 : v<=t*1.1;
        if(ok){ status='on-track'; statusColor='#10B981'; statusIcon='✅'; }
        else if(warn){ status='at-risk'; statusColor='#F97316'; statusIcon='⚠️'; }
        else { status='critical'; statusColor='#EF4444'; statusIcon='🔴'; }
      }
      const pct = t!==null ? Math.min(Math.abs(item.dir==='higher'?v/t:(t>0?t/Math.max(v,0.001):1))*100,100) : 50;
      return `<div style="background:var(--card2);border:1px solid ${statusColor}33;border-left:3px solid ${statusColor};border-radius:8px;padding:12px 14px">
        <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:6px">
          <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.3px">${esc(item.label)}</div>
          <span style="font-size:14px">${statusIcon}</span>
        </div>
        <div style="font-size:20px;font-weight:900;color:${statusColor};margin-bottom:2px">${item.fmt(v)}</div>
        ${t!==null?`<div style="font-size:9px;color:var(--faint);margin-bottom:6px">Target: ${item.fmt(t)}</div>
        <div style="background:var(--bdr);border-radius:3px;height:4px;overflow:hidden">
          <div style="height:100%;width:${pct.toFixed(0)}%;background:${statusColor};border-radius:3px"></div>
        </div>`:'<div style="font-size:9px;color:var(--faint);margin-bottom:6px">No target set</div>'}
        <div style="font-size:9px;color:var(--faint);margin-top:4px">${esc(item.desc)}</div>
      </div>`;
    };

    // Score summary
    const allKPIs   = kpis.flatMap(c=>c.items).filter(k=>k.target!==null&&k.dir);
    const onTrack   = allKPIs.filter(k=>k.dir==='higher'?k.val>=k.target:k.val<=k.target).length;
    const scorecard = Math.round(onTrack/allKPIs.length*100);

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🎯</span>
        <div><h1>Executive KPI Scorecard</h1><div class="sub">Real-time performance vs targets · ${today.toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</div></div>
      </div>
      <button class="btn btn-ghost btn-sm" data-h-click="h265">🔄 Refresh</button>
    </div>

    <!-- Scorecard summary -->
    <div style="display:grid;grid-template-columns:auto 1fr;gap:16px;margin-bottom:16px;align-items:center">
      <div class="card" style="text-align:center;padding:20px 28px">
        <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;margin-bottom:6px">Overall Score</div>
        <div style="font-size:42px;font-weight:900;color:${scorecard>=75?'#10B981':scorecard>=50?'#F97316':'#EF4444'}">${scorecard}%</div>
        <div style="font-size:11px;color:var(--muted);margin-top:4px">${onTrack}/${esc(allKPIs.length)} KPIs on target</div>
      </div>
      <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:10px">
        ${kpi('On Target', onTrack, '#10B981', 'KPIs meeting target')}
        ${kpi('At Risk', allKPIs.filter(k=>{ const ok=k.dir==='higher'?k.val>=k.target:k.val<=k.target; const warn=k.dir==='higher'?k.val>=k.target*0.9:k.val<=k.target*1.1; return !ok&&warn; }).length, '#F97316', 'Within 10% of target')}
        ${kpi('Critical', allKPIs.filter(k=>{ const warn=k.dir==='higher'?k.val>=k.target*0.9:k.val<=k.target*1.1; return !warn; }).length, '#EF4444', 'Needs immediate action')}
      </div>
    </div>

    <!-- KPI categories -->
    ${kpis.map(cat=>`
    <div class="card" style="margin-bottom:14px">
      <div class="sec-head"><div class="sec-title"><span>${cat.cat.split(' ')[0]}</span>${cat.cat.split(' ').slice(1).join(' ')}</div></div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px">
        ${cat.items.map(renderKPICard).join('')}
      </div>
    </div>`).join('')}`;

  }catch(err){
    el.innerHTML = `<div class="empty">Error: ${esc(err.message)}</div>`;
    console.error('loadScorecard error:',err);
  }
}

// ══════════════════════════════════════════════════════════════
//  P5-3 · BUDGET vs ACTUAL (per project)
//  Added as a tab in the Projects page
// ══════════════════════════════════════════════════════════════
async function loadBudgetVsActual(projectId){
  if(!projectId){
    // Show project selector
    const {data:projs}=await sb.from('projects').select('id,project_no,name,status').in('status',ACTIVE_STATUSES).order('project_no');
    openModal('Budget vs Actual — Select Project',`
      <div class="form-field"><label>Project</label>
        <select id="bva-proj" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          ${(projs||[]).map(p=>`<option value="${esc(p.id)}">${esc(p.project_no)} — ${esc(p.name)}</option>`).join('')}
        </select>
      </div>
      <div class="modal-foot">
        <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
        <button class="btn btn-primary" data-h-click="h266">View</button>
      </div>`);
    return;
  }

  const [projR, snapR, invR] = await Promise.all([
    sb.from('projects').select('*').eq('id',projectId).single(),
    sb.from('project_evm_snapshots').select('*').eq('project_id',projectId).order('snapshot_date'),
    sb.from('invoices').select('net_amount,invoice_type,status,paid_date').eq('project_id',projectId)
  ]);
  const p    = projR.data||{};
  const snaps= snapR.data||[];
  const invs = invR.data||[];

  const bac  = Number(p.bac||0);
  const ev   = Number(p.ev||0);
  const ac   = Number(p.ac||0);
  const pv   = Number(p.pv||0);
  const eac  = Number(p.cpi||1)>0 ? ac+(bac-ev)/Number(p.cpi||1) : bac;
  const vac  = bac-eac;
  const cpi  = ac>0?ev/ac:1;
  const spi  = pv>0?ev/pv:1;

  const revInvs  = invs.filter(i=>i.invoice_type==='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
  const costInvs = invs.filter(i=>i.invoice_type!=='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);

  openModal(`📊 Budget vs Actual — ${p.project_no||''}`,`
    <div style="font-size:12px;font-weight:700;color:var(--muted);margin-bottom:12px">${esc(p.name||'')}</div>

    <!-- EVM Summary -->
    <div style="display:grid;grid-template-columns:repeat(3,1fr);gap:8px;margin-bottom:14px">
      ${[
        ['BAC',fmtKWD(bac),'#C9A84C','Budget at Completion'],
        ['EAC',fmtKWD(eac),eac>bac?'#EF4444':'#10B981','Estimate at Completion'],
        ['VAC',fmtKWD(vac),vac>=0?'#10B981':'#EF4444','Variance at Completion'],
        ['EV', fmtKWD(ev),'#3B82F6','Earned Value'],
        ['AC', fmtKWD(ac),ac>ev?'#EF4444':'#10B981','Actual Cost'],
        ['PV', fmtKWD(pv),'#8B5CF6','Planned Value'],
      ].map(([l,v,col,d])=>`
      <div style="background:var(--n3);border-radius:7px;padding:10px;border-left:3px solid ${col}">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase">${l}</div>
        <div style="font-size:15px;font-weight:800;color:${col};margin:3px 0">${v}</div>
        <div style="font-size:9px;color:var(--faint)">${d}</div>
      </div>`).join('')}
    </div>

    <!-- Performance indices -->
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:14px">
      <div style="background:var(--n3);border-radius:7px;padding:10px;text-align:center">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase;margin-bottom:4px">CPI</div>
        <div style="font-size:24px;font-weight:900;color:${cpi>=1?'#10B981':cpi>=0.9?'#F97316':'#EF4444'}">${cpi.toFixed(3)}</div>
        <div style="font-size:9px;color:var(--faint)">${cpi>=1?'On/Under Budget':'Over Budget'}</div>
      </div>
      <div style="background:var(--n3);border-radius:7px;padding:10px;text-align:center">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase;margin-bottom:4px">SPI</div>
        <div style="font-size:24px;font-weight:900;color:${spi>=1?'#10B981':spi>=0.9?'#F97316':'#EF4444'}">${spi.toFixed(3)}</div>
        <div style="font-size:9px;color:var(--faint)">${spi>=1?'On/Ahead Schedule':'Behind Schedule'}</div>
      </div>
    </div>

    <!-- Invoice summary -->
    <div style="margin-bottom:12px;padding:10px;background:var(--n3);border-radius:7px">
      <div style="font-size:10px;font-weight:700;color:var(--gold);margin-bottom:6px">Invoice-Based Cash Flow</div>
      <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px">
        <span style="color:var(--muted)">Revenue Invoiced & Collected:</span>
        <span style="font-weight:700;color:#10B981">${fmtKWD(revInvs)}</span>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px">
        <span style="color:var(--muted)">Cost Invoices Paid:</span>
        <span style="font-weight:700;color:#EF4444">${fmtKWD(costInvs)}</span>
      </div>
      <div style="display:flex;justify-content:space-between;font-size:12px;font-weight:700;padding-top:6px;border-top:1px solid var(--bdr)">
        <span style="color:var(--text)">Cash Profit:</span>
        <span style="color:${revInvs-costInvs>=0?'#10B981':'#EF4444'}">${fmtKWD(revInvs-costInvs)}</span>
      </div>
    </div>

    <!-- EVM trend if snapshots exist -->
    ${snaps.length>1?`
    <div style="font-size:10px;font-weight:700;color:var(--gold);margin-bottom:6px">EVM Trend (${esc(snaps.length)} snapshots)</div>
    <div style="overflow-x:auto">
      <table style="font-size:10px;min-width:400px"><thead><tr>
        <th>Date</th><th style="text-align:right">PV</th><th style="text-align:right">EV</th><th style="text-align:right">AC</th><th style="text-align:right">CPI</th>
      </tr></thead><tbody>
      ${snaps.slice(-8).map(s=>{
        const cpiS=Number(s.ac)>0?Number(s.ev)/Number(s.ac):1;
        return`<tr>
          <td style="color:var(--faint)">${esc(s.snapshot_date)}</td>
          <td style="text-align:right">${fmtKWD(s.pv||0)}</td>
          <td style="text-align:right;color:#10B981">${fmtKWD(s.ev||0)}</td>
          <td style="text-align:right;color:#EF4444">${fmtKWD(s.ac||0)}</td>
          <td style="text-align:right;color:${cpiS>=1?'#10B981':cpiS>=0.9?'#F97316':'#EF4444'};font-weight:700">${cpiS.toFixed(2)}</td>
        </tr>`;}).join('')}
      </tbody></table>
    </div>`:'<div style="font-size:10px;color:var(--faint)">No EVM snapshots recorded yet</div>'}

    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      <button class="btn btn-primary" data-h-click="h235">Open Projects</button>
    </div>`);
}

// ══════════════════════════════════════════════════════════════
//  P5-4 · FINANCE GL ENHANCEMENTS
//  Enhanced Trial Balance export + COA hierarchy view
// ══════════════════════════════════════════════════════════════
async function exportTrialBalanceExcel(){
  try{
    showToast('Building Trial Balance Excel…');
    const [{data:tb},{data:je}] = await Promise.all([
      sb.from('v_trial_balance').select('*').order('account_code'),
      sb.from('journal_entries').select('*').order('entry_date',{ascending:false}).limit(100)
    ]);
    const L = tb||[];
    const J = je||[];
    const totalDr = L.reduce((s,r)=>s+Number(r.total_debit||0),0);
    const totalCr = L.reduce((s,r)=>s+Number(r.total_credit||0),0);
    const balanced= Math.abs(totalDr-totalCr)<0.01;

    const wb = new ExcelJS.Workbook();
    wb.creator = 'SP360 v4.1';
    wb.created = new Date();

    // Sheet 1 — Trial Balance
    const ws1 = wb.addWorksheet('Trial Balance');
    xlTitleBlock(ws1,'SP360 ERP — Trial Balance',
      `Generated: ${new Date().toLocaleDateString('en-GB')} · Balanced: ${balanced?'YES ✓':'NO ✗'}`, 6);
    xlKPIBand(ws1,[
      ['Total Debit',    fmtKWD(totalDr), XL.gold],
      ['Total Credit',   fmtKWD(totalCr), XL.gold],
      ['Difference',     fmtKWD(Math.abs(totalDr-totalCr)), balanced?XL.green:XL.red],
      ['Status',         balanced?'BALANCED':'UNBALANCED', balanced?XL.green:XL.red]
    ], 6);

    const hdr1 = ws1.addRow(['Code','Account Name','Type','Sub-Type','Total Debit','Total Credit','Balance']);
    hdr1.eachCell(cell=>{
      cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1E3A5F'}};
      cell.font={name:'Calibri',size:10,bold:true,color:{argb:'FFC9A84C'}};
      cell.border=XL.thinBorder;
      cell.alignment={horizontal:'center',vertical:'middle'};
    });
    hdr1.height=18;
    ws1.columns=[{width:10},{width:35},{width:15},{width:15},{width:16},{width:16},{width:16}];

    L.forEach((r,i)=>{
      const bal=Number(r.balance||0);
      const row=ws1.addRow([
        r.account_code, r.account_name, r.account_type, r.sub_type||'—',
        Number(r.total_debit||0), Number(r.total_credit||0), Math.abs(bal)
      ]);
      row.eachCell(cell=>{cell.border=XL.thinBorder;cell.font={name:'Calibri',size:10};});
      row.getCell(5).numFmt='#,##0.000'; row.getCell(5).alignment={horizontal:'right'};
      row.getCell(6).numFmt='#,##0.000'; row.getCell(6).alignment={horizontal:'right'};
      const balCell=row.getCell(7);
      balCell.numFmt='#,##0.000'; balCell.alignment={horizontal:'right'};
      balCell.font={...balCell.font,bold:true,color:{argb:bal>=0?'FF10B981':'FFEF4444'}};
      if(i%2===0) row.eachCell(c=>{if(!c.fill?.fgColor?.argb||c.fill.fgColor.argb==='00000000') c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF8FAFC'}};});
    });

    // Totals row
    const totRow=ws1.addRow(['','TOTAL','','',totalDr,totalCr,Math.abs(totalDr-totalCr)]);
    totRow.eachCell(cell=>{
      cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1E3A5F'}};
      cell.font={name:'Calibri',size:10,bold:true,color:{argb:'FFC9A84C'}};
      cell.border=XL.thinBorder;
    });
    totRow.getCell(5).numFmt='#,##0.000'; totRow.getCell(6).numFmt='#,##0.000'; totRow.getCell(7).numFmt='#,##0.000';
    ws1.views=[{state:'frozen',ySplit:6}];
    ws1.autoFilter={from:{row:6,column:1},to:{row:6,column:7}};

    // Sheet 2 — Journal Entries
    const ws2=wb.addWorksheet('Journal Entries');
    xlTitleBlock(ws2,'SP360 ERP — Journal Entries (Last 100)',`Generated: ${new Date().toLocaleDateString('en-GB')}`,6);
    const hdr2=ws2.addRow(['Entry No','Date','Description','Reference','Total Debit','Total Credit','Status']);
    hdr2.eachCell(cell=>{
      cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1E3A5F'}};
      cell.font={name:'Calibri',size:10,bold:true,color:{argb:'FFC9A84C'}};
      cell.border=XL.thinBorder;
    });
    ws2.columns=[{width:14},{width:12},{width:40},{width:16},{width:16},{width:16},{width:12}];
    J.forEach((j,i)=>{
      const row=ws2.addRow([j.entry_no,j.entry_date,j.description,j.reference||'—',Number(j.total_debit||0),Number(j.total_credit||0),j.status]);
      row.eachCell(cell=>{cell.border=XL.thinBorder;cell.font={name:'Calibri',size:10};});
      row.getCell(5).numFmt='#,##0.000'; row.getCell(6).numFmt='#,##0.000';
      if(i%2===0) row.getCell(3).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF8FAFC'}};
    });

    await xlSave(wb,`SP360_Trial_Balance_${new Date().toISOString().split('T')[0]}.xlsx`);
    showToast('Trial Balance Excel exported ✓');
  }catch(e){
    showToast('Export error: '+e.message,'error');
    logError('Finance','exportTrialBalanceExcel',e);
  }
}

// ══════════════════════════════════════════════════════════════
//  P5-5 · DOCUMENT REVISION LOCK
//  Prevents concurrent revision uploads
// ══════════════════════════════════════════════════════════════
let _docRevisionLocked = false;

async function saveDocumentRevisionSafe(docId, revData){
  if(_docRevisionLocked){
    showToast('⚠️ Another document revision is in progress','error');
    return false;
  }
  _docRevisionLocked = true;
  try{
    // Try atomic RPC first
    const {data,error} = await sb.rpc('save_document_revision_atomic',{
      p_document_id:    docId,
      p_revision_no:    revData.revision_no,
      p_revision_title: revData.title,
      p_file_name:      revData.file_name||null,
      p_change_notes:   revData.change_notes||null,
      p_created_by:     currentProfile?.id
    });

    if(error){
      if(error.message?.includes('does not exist')||error.code==='42883'){
        // Fallback: manual steps with audit
        return await _saveDocRevisionFallback(docId, revData);
      }
      showToast('Revision error: '+error.message,'error');
      return false;
    }

    if(!data?.ok){ showToast('Revision failed: '+(data?.error||'Unknown'),'error'); return false; }
    return data;

  }catch(e){
    showToast('Revision error: '+e.message,'error');
    logError('Documents','saveRevision',e);
    return false;
  }finally{
    _docRevisionLocked = false;
  }
}

async function _saveDocRevisionFallback(docId, revData){
  try{
    // Step 1: Supersede all current revisions
    const {error:supErr}=await sb.from('document_revisions')
      .update({status:'superseded'})
      .eq('document_id',docId)
      .eq('status','current');
    if(supErr){ logError('Documents','supersede',supErr); }

    // Step 2: Insert new revision
    const {data:rev,error:insErr}=await sb.from('document_revisions').insert({
      document_id:  docId,
      revision_no:  revData.revision_no,
      title:        revData.title,
      file_name:    revData.file_name||null,
      change_notes: revData.change_notes||null,
      status:       'current',
      created_by:   currentProfile?.id
    }).select('id').single();
    if(insErr){ showToast('Revision insert failed: '+insErr.message,'error'); return false; }

    // Step 3: Update document master
    const {error:docErr}=await sb.from('documents')
      .update({current_revision:revData.revision_no, updated_at:new Date().toISOString()})
      .eq('id',docId);
    if(docErr){ logError('Documents','updateMaster',docErr,{severity:'critical'}); }

    // Step 4: Audit
    await writeAudit('document_revisions',rev.id,'REVISION_CREATED',null,revData,'New revision uploaded');
    return {ok:true, revision_id:rev.id};

  }catch(e){
    logError('Documents','revisionFallback',e);
    return false;
  }
}

