async function loadContracts(tab='active'){
  const el = document.getElementById('page-contracts');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading Contracts…</div>';
  try{
    const [ctrR, projR, vendR] = await Promise.all([
      sb.from('contracts').select('*,project:projects(project_no,name),vendor:vendors(vendor_name)').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name').in('status',ACTIVE_STATUSES).order('project_no'),
      sb.from('vendors').select('id,vendor_name').eq('is_approved',true).order('vendor_name')
    ]);
    const ctrs  = ctrR.data||[];
    const projs = projR.data||[];
    const vends = vendR.data||[];

    const today   = new Date();
    const active  = ctrs.filter(c=>c.status==='active');
    const expiring= ctrs.filter(c=>c.status==='active'&&c.end_date&&Math.ceil((new Date(c.end_date)-today)/86400000)<=30);
    const expired = ctrs.filter(c=>c.status==='active'&&c.end_date&&new Date(c.end_date)<today);
    const totalVal= active.reduce((s,c)=>s+Number(c.contract_value||0),0);

    const tabs = `<div class="tabs">
      <button class="tab${tab==='active'?' act':''}" data-h-click="h267">✅ Active (${esc(active.length)})</button>
      <button class="tab${tab==='expiring'?' act':''}" data-h-click="h268" style="color:${expiring.length>0?'#F97316':'inherit'}">⚠️ Expiring (${esc(expiring.length)})</button>
      <button class="tab${tab==='all'?' act':''}" data-h-click="h269">📋 All (${esc(ctrs.length)})</button>
    </div>`;

    let list = tab==='active'?active : tab==='expiring'?expiring : ctrs;

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📜</span>
        <div><h1>Contract Management</h1><div class="sub">Client & Vendor Contracts · Expiry Tracking · Value Monitoring</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h159">+ New Contract</button>`:''}
    </div>

    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Active Contracts', active.length, '#C9A84C', 'Currently active')}
      ${kpi('Total Value', fmtKWD(totalVal), '#10B981', 'Active contracts')}
      ${kpi('Expiring ≤30d', expiring.length, expiring.length>0?'#F97316':'#10B981', 'Require renewal')}
      ${kpi('Expired', expired.length, expired.length>0?'#EF4444':'#10B981', 'Overdue for renewal')}
    </div>

    <div class="card">
      ${tabs}
      ${list.length===0
        ? '<div class="empty">No contracts found</div>'
        : `<table><thead><tr>
            <th>Contract No</th><th>Title</th><th>Type</th><th>Party</th><th>Project</th>
            <th style="text-align:right">Value (KWD)</th><th>Start</th><th>End</th>
            <th style="text-align:center">Status</th><th></th>
          </tr></thead><tbody>
          ${list.map(c=>{
            const daysLeft = c.end_date ? Math.ceil((new Date(c.end_date)-today)/86400000) : null;
            const expiryColor = daysLeft===null?'var(--faint)':daysLeft<0?'#EF4444':daysLeft<=30?'#F97316':'#10B981';
            const party = c.contract_type==='client' ? (c.client_name||'—') : (c.vendor?.vendor_name||'—');
            return `<tr>
              <td style="color:var(--gold);font-size:10px;font-weight:700">${esc(c.contract_no||'—')}</td>
              <td style="font-weight:600;font-size:11px">${esc(c.title||'—')}</td>
              <td><span style="font-size:9px;background:${c.contract_type==='client'?'#10B98122':'#3B82F622'};color:${c.contract_type==='client'?'#10B981':'#3B82F6'};border-radius:4px;padding:2px 6px">${esc(c.contract_type||'—')}</span></td>
              <td style="font-size:11px">${esc(party)}</td>
              <td style="font-size:10px;color:var(--muted)">${esc(c.project?.project_no||'—')}</td>
              <td style="text-align:right;font-weight:700">${fmtKWD(c.contract_value||0)}</td>
              <td style="font-size:10px;color:var(--faint)">${esc(c.start_date||'—')}</td>
              <td style="font-size:10px;color:${expiryColor};font-weight:700">${esc(c.end_date||'Open')}${daysLeft!==null&&daysLeft<=30?` <span style="font-size:9px">(${daysLeft<0?Math.abs(daysLeft)+'d ago':daysLeft+'d'})</span>`:''}</td>
              <td style="text-align:center">${pill(c.status||'active',c.status==='active'?'#10B981':c.status==='expired'?'#EF4444':'#94A3B8')}</td>
              <td><button data-h-click="h270" data-ha-click="${esc(JSON.stringify([String((c.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px">👁</button></td>
            </tr>`;
          }).join('')}
          </tbody></table>`}
    </div>`;

  }catch(err){
    el.innerHTML = `<div class="empty">Error: ${esc(err.message)}</div>`;
  }
}

