async function openRiskRegister(projectId, projectNo){
  const {data:risks}=await sb.from('project_risks')
    .select('*')
    .eq('project_id',projectId)
    .order('created_at',{ascending:false});
  const R=risks||[];

  const riskScore=(r)=>Number(r.probability||1)*Number(r.impact||1);
  const riskColor=(s)=>s>=15?'#EF4444':s>=8?'#F97316':s>=4?'#C9A84C':'#10B981';
  const riskLabel=(s)=>s>=15?'Critical':s>=8?'High':s>=4?'Medium':'Low';

  openModal(`⚠️ Risk Register — ${projectNo}`,`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
      <div style="font-size:11px;color:var(--muted)">${esc(R.length)} risk(s) registered</div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h272" data-ha-click="${esc(JSON.stringify([String((projectId)??''),String((projectNo)??'')]))}">+ Add Risk</button>`:''}
    </div>

    ${R.length===0
      ? '<div style="text-align:center;padding:20px;color:var(--faint)">No risks registered yet</div>'
      : `<div style="overflow-x:auto;max-height:400px;overflow-y:auto">
          <table style="font-size:10px"><thead><tr>
            <th>Risk</th><th>Category</th><th style="text-align:center">P</th><th style="text-align:center">I</th><th style="text-align:center">Score</th><th>Mitigation</th><th style="text-align:center">Status</th>
          </tr></thead><tbody>
          ${R.map(r=>{
            const s=riskScore(r);
            return`<tr>
              <td style="font-weight:600;max-width:200px">${esc(r.description||'—')}</td>
              <td style="color:var(--muted)">${esc(r.category||'—')}</td>
              <td style="text-align:center;font-weight:700">${esc(r.probability||'—')}</td>
              <td style="text-align:center;font-weight:700">${esc(r.impact||'—')}</td>
              <td style="text-align:center"><span style="background:${riskColor(s)}22;color:${riskColor(s)};border-radius:4px;padding:2px 7px;font-weight:700">${s} ${riskLabel(s)}</span></td>
              <td style="color:var(--muted);max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(r.mitigation_plan||'—')}</td>
              <td style="text-align:center">${pill(r.status||'open',r.status==='closed'?'#10B981':r.status==='mitigated'?'#3B82F6':'#F97316')}</td>
            </tr>`;
          }).join('')}
          </tbody></table>
        </div>`}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
    </div>`);
}

