async function loadLessons(tab='all'){
  const el = document.getElementById('page-lessons');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading Lessons Learned…</div>';
  try{
    const [lessR, projR] = await Promise.all([
      sb.from('lessons_learned').select('*,project:projects(project_no,name)').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name').order('project_no')
    ]);
    const L    = lessR.data||[];
    const projs= projR.data||[];

    const catColors={
      'Technical':'#3B82F6','Process':'#8B5CF6','Communication':'#10B981',
      'Risk':'#EF4444','Commercial':'#C9A84C','QHSE':'#F97316','Other':'#94A3B8'
    };

    const cats = [...new Set(L.map(l=>l.category).filter(Boolean))];
    const filtered = tab==='all' ? L : L.filter(l=>l.category===tab);

    const tabBar = `<div class="tabs" style="flex-wrap:wrap">
      <button class="tab${tab==='all'?' act':''}" data-h-click="h275">All (${esc(L.length)})</button>
      ${cats.map(c=>`<button class="tab${tab===c?' act':''}" data-h-click="h274" data-ha-click="${esc(JSON.stringify([String((c)??'')]))}" style="color:${catColors[c]||'#94A3B8'}">${esc(c)} (${L.filter(l=>l.category===c).length})</button>`).join('')}
    </div>`;

    const posCount  = L.filter(l=>l.lesson_type==='positive').length;
    const impCount  = L.filter(l=>l.lesson_type==='improvement').length;
    const projCount = new Set(L.map(l=>l.project_id).filter(Boolean)).size;

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📚</span>
        <div><h1>Lessons Learned</h1><div class="sub">Knowledge Base · Project Insights · Continuous Improvement</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h276">+ Add Lesson</button>`:''}
    </div>

    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total Lessons',    L.length,    '#C9A84C', 'Knowledge captured')}
      ${kpi('Positive',         posCount,    '#10B981', 'What went well')}
      ${kpi('Improvements',     impCount,    '#F97316', 'Areas to improve')}
      ${kpi('Projects Covered', projCount,   '#3B82F6', 'Unique projects')}
    </div>

    <div class="card">
      ${tabBar}
      ${filtered.length===0
        ? '<div class="empty">No lessons found — start capturing knowledge!</div>'
        : filtered.map(l=>{
            const typeColor = l.lesson_type==='positive'?'#10B981':l.lesson_type==='improvement'?'#F97316':'#3B82F6';
            const catColor  = catColors[l.category]||'#94A3B8';
            return `<div style="border:1px solid var(--bdr);border-left:3px solid ${typeColor};border-radius:8px;padding:14px;margin-bottom:10px;background:var(--card2)">
              <div style="display:flex;align-items:flex-start;gap:10px;margin-bottom:8px">
                <div style="flex:1;min-width:0">
                  <div style="display:flex;gap:6px;flex-wrap:wrap;margin-bottom:4px">
                    <span style="font-size:9px;background:${typeColor}22;color:${typeColor};border-radius:4px;padding:2px 7px;font-weight:700">${l.lesson_type==='positive'?'✅ Positive':l.lesson_type==='improvement'?'🔄 Improvement':'ℹ️ Neutral'}</span>
                    <span style="font-size:9px;background:${catColor}22;color:${catColor};border-radius:4px;padding:2px 7px">${esc(l.category||'—')}</span>
                    ${l.project?.project_no?`<span style="font-size:9px;color:var(--gold)">${esc(l.project.project_no)}</span>`:''}
                    <span style="font-size:9px;color:var(--faint)">${l.created_at?new Date(l.created_at).toLocaleDateString('en-GB'):'—'}</span>
                  </div>
                  <div style="font-size:12px;font-weight:700;color:var(--text);margin-bottom:4px">${esc(l.title||'—')}</div>
                </div>
              </div>
              <div style="font-size:11px;color:var(--muted);margin-bottom:6px">${esc(l.description||'')}</div>
              ${l.recommendation?`<div style="font-size:10px;background:var(--n3);border-radius:5px;padding:6px 10px;color:var(--text)">💡 <b>Recommendation:</b> ${esc(l.recommendation)}</div>`:''}
            </div>`;
          }).join('')}
    </div>`;

  }catch(err){
    el.innerHTML = `<div class="empty">Error: ${esc(err.message)}</div>`;
  }
}

