// ══════════════════════════════════════════════════════════════
//  P6-4 · SUPPLIER PERFORMANCE
//  Rating system for vendors in Procurement
// ══════════════════════════════════════════════════════════════
async function loadSupplierPerformance(){
  const {data:ratings} = await sb.from('vendor_performance')
    .select('*,vendor:vendors(vendor_name,vendor_code,category)')
    .order('rating_date',{ascending:false});
  const R = ratings||[];

  // Aggregate per vendor
  const byVendor = {};
  R.forEach(r=>{
    if(!byVendor[r.vendor_id]) byVendor[r.vendor_id]={
      id:r.vendor_id, name:r.vendor?.vendor_name||'—', code:r.vendor?.vendor_code||'—',
      category:r.vendor?.category||'—', ratings:[]
    };
    byVendor[r.vendor_id].ratings.push(r);
  });

  const vendors = Object.values(byVendor).map(v=>{
    const avg = v.ratings.reduce((s,r)=>s+Number(r.overall_score||0),0)/v.ratings.length;
    v.avgScore = Math.round(avg*10)/10;
    v.lastRating = v.ratings[0];
    return v;
  }).sort((a,b)=>b.avgScore-a.avgScore);

  const scoreColor = s => s>=4?'#10B981':s>=3?'#F97316':'#EF4444';
  const stars = s => '★'.repeat(Math.round(s))+'☆'.repeat(5-Math.round(s));

  openModal('📊 Supplier Performance Ratings',`
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
      <div style="font-size:11px;color:var(--muted)">${esc(vendors.length)} vendors rated · ${esc(R.length)} total evaluations</div>
      <button class="btn btn-primary btn-sm" data-h-click="h278">+ Rate Vendor</button>
    </div>
    ${vendors.length===0
      ? '<div style="text-align:center;padding:20px;color:var(--faint)">No performance ratings yet</div>'
      : `<div style="max-height:420px;overflow-y:auto">
          ${vendors.map(v=>`
          <div style="border:1px solid var(--bdr);border-radius:8px;padding:12px 14px;margin-bottom:8px;display:flex;align-items:center;gap:12px">
            <div style="flex:1;min-width:0">
              <div style="font-size:12px;font-weight:700;color:var(--text)">${esc(v.name)}</div>
              <div style="font-size:10px;color:var(--muted)">${esc(v.code)} · ${esc(v.category)} · ${esc(v.ratings.length)} evaluation(s)</div>
            </div>
            <div style="text-align:center;flex-shrink:0">
              <div style="font-size:20px;font-weight:900;color:${scoreColor(v.avgScore)}">${esc(v.avgScore)}</div>
              <div style="font-size:12px;color:${scoreColor(v.avgScore)}">${stars(v.avgScore)}</div>
              <div style="font-size:9px;color:var(--faint)">/5.0</div>
            </div>
          </div>`).join('')}
        </div>`}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
    </div>`);
}

