// ══════════════════════════════════════════════════════════════
//  P6-5 · MULTI-CURRENCY SUPPORT
//  Helper functions for currency conversion display
// ══════════════════════════════════════════════════════════════
const CURRENCIES = {
  KWD: {symbol:'KD',  name:'Kuwaiti Dinar',    decimals:3, toUSD:3.28},
  USD: {symbol:'$',   name:'US Dollar',         decimals:2, toUSD:1},
  EUR: {symbol:'€',   name:'Euro',              decimals:2, toUSD:1.08},
  SAR: {symbol:'SR',  name:'Saudi Riyal',       decimals:2, toUSD:0.267},
  AED: {symbol:'AED', name:'UAE Dirham',        decimals:2, toUSD:0.272},
  GBP: {symbol:'£',   name:'British Pound',     decimals:2, toUSD:1.27},
};

// Convert amount from one currency to another (via USD)
function convertCurrency(amount, fromCcy, toCcy){
  const from = CURRENCIES[fromCcy] || CURRENCIES.KWD;
  const to   = CURRENCIES[toCcy]   || CURRENCIES.KWD;
  const usd  = amount * from.toUSD;
  return usd / to.toUSD;
}

// Format with currency symbol
function fmtCurrency(amount, ccy='KWD'){
  const c = CURRENCIES[ccy] || CURRENCIES.KWD;
  return `${c.symbol} ${Number(amount).toLocaleString('en-US',{minimumFractionDigits:c.decimals,maximumFractionDigits:c.decimals})}`;
}

// Multi-currency display — shows primary + converted
function fmtMultiCcy(kwdAmount, targetCcy='USD'){
  const converted = convertCurrency(kwdAmount,'KWD',targetCcy);
  return `${fmtKWD(kwdAmount)} <span style="font-size:9px;color:var(--faint)">(≈${fmtCurrency(converted,targetCcy)})</span>`;
}

// Currency selector widget HTML
function currencySelector(id='ccy-select', defaultVal='KWD'){
  return `<select id="${id}" style="background:var(--card);border:1px solid var(--bdr);border-radius:6px;padding:4px 8px;color:var(--text);font-size:11px">
    ${Object.entries(CURRENCIES).map(([code,c])=>`<option value="${code}"${code===defaultVal?' selected':''}>${code} — ${esc(c.name)}</option>`).join('')}
  </select>`;
}

// ══════════════════════════════════════════════════════════════
//  P7-1 · CASH FLOW FORECASTING
// ══════════════════════════════════════════════════════════════
async function loadForecast(){
  const el = document.getElementById('page-forecast');
  if(!el) return;
  el.innerHTML = '<div class="loading">Building Cash Flow Forecast…</div>';
  try{
    const today = new Date();
    const [invR, projR, poR] = await Promise.all([
      sb.from('invoices').select('*').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name,bac,ac,ev,pct,status,end_date').in('status',ACTIVE_STATUSES),
      sb.from('purchase_orders').select('total_amount,status,created_at').in('status',['approved','partial'])
    ]);
    const invs  = invR.data||[];
    const projs = projR.data||[];
    const pos   = poR.data||[];

    // ── Historical 6 months ───────────────────────────────────
    const hist = [];
    for(let i=-5;i<=0;i++){
      const d = new Date(today.getFullYear(), today.getMonth()+i, 1);
      const m = d.toISOString().slice(0,7);
      const inflow  = invs.filter(x=>x.invoice_type==='client'&&x.status==='paid'&&x.paid_date?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
      const outflow = invs.filter(x=>x.invoice_type!=='client'&&x.status==='paid'&&x.paid_date?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
      hist.push({m, label:d.toLocaleDateString('en-GB',{month:'short',year:'2-digit'}), inflow, outflow, net:inflow-outflow, type:'actual'});
    }

    // ── Forecast 6 months ─────────────────────────────────────
    // Based on: avg monthly collections + pending AR aging + project completion curve
    const avgInflow  = hist.reduce((s,h)=>s+h.inflow,0)/6 || 0;
    const avgOutflow = hist.reduce((s,h)=>s+h.outflow,0)/6 || 0;

    // Pending AR — distribute over next 3 months
    const pendingAR = invs.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status));
    const pendingAP = invs.filter(i=>i.invoice_type!=='client'&&!['paid','cancelled'].includes(i.status));

    // Project completion-based revenue forecast
    const projForecast = projs.map(p=>{
      const remaining = Number(p.bac||0) - Number(p.ac||0);
      const pctLeft   = Math.max(100 - Number(p.pct||0), 0) / 100;
      const monthsLeft= p.end_date ? Math.max(Math.ceil((new Date(p.end_date)-today)/2592000000),1) : 6;
      return {monthly: (remaining * pctLeft) / monthsLeft};
    });
    const projMonthlyRev = projForecast.reduce((s,p)=>s+p.monthly,0);

    const fcast = [];
    for(let i=1;i<=6;i++){
      const d = new Date(today.getFullYear(), today.getMonth()+i, 1);
      const label = d.toLocaleDateString('en-GB',{month:'short',year:'2-digit'});
      // Decay factor — confidence decreases over time
      const confidence = Math.max(1 - (i-1)*0.1, 0.5);
      // AR collection: spread pending AR over 3 months
      const arCollection = i<=3 ? pendingAR.reduce((s,i2)=>s+Number(i2.net_amount),0)/3 : 0;
      const apPayment    = i<=3 ? pendingAP.reduce((s,i2)=>s+Number(i2.net_amount),0)/3 : 0;
      const inflow  = Math.round((avgInflow * 0.3 + projMonthlyRev * 0.5 + arCollection * 0.2) * confidence);
      const outflow = Math.round((avgOutflow * 0.4 + apPayment * 0.4 + avgOutflow * 0.2) * confidence);
      fcast.push({m:d.toISOString().slice(0,7), label, inflow, outflow, net:inflow-outflow, type:'forecast', confidence:Math.round(confidence*100)});
    }

    const all = [...hist, ...fcast];
    const maxVal = Math.max(...all.map(m=>Math.max(m.inflow,m.outflow)), 1);

    // Running balance
    let balance = hist.reduce((s,h)=>s+h.net, 0);
    const withBalance = all.map(m=>{ balance+=m.net; return {...m, balance}; });

    // KPIs
    const totalFcastInflow  = fcast.reduce((s,f)=>s+f.inflow,0);
    const totalFcastOutflow = fcast.reduce((s,f)=>s+f.outflow,0);
    const netFcast          = totalFcastInflow - totalFcastOutflow;
    const currentBalance    = hist.reduce((s,h)=>s+h.net,0);

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📈</span>
        <div><h1>Cash Flow Forecast</h1><div class="sub">6-month historical + 6-month forecast · Model-based projection</div></div>
      </div>
      <button class="btn btn-ghost btn-sm" data-h-click="h280">🔄 Refresh</button>
    </div>

    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Current Balance',  fmtKWD(currentBalance),   currentBalance>=0?'#10B981':'#EF4444', 'Last 6 months net')}
      ${kpi('Forecast Inflow',  fmtKWD(totalFcastInflow),  '#3B82F6', 'Next 6 months projected')}
      ${kpi('Forecast Outflow', fmtKWD(totalFcastOutflow), '#EF4444', 'Next 6 months projected')}
      ${kpi('Net Forecast',     fmtKWD(netFcast),          netFcast>=0?'#10B981':'#EF4444', 'Projected net cash')}
    </div>

    <!-- Chart -->
    <div class="card" style="margin-bottom:14px">
      <div class="sec-head">
        <div class="sec-title"><span>📊</span>Cash Flow — 12 Month View</div>
        <div style="display:flex;gap:12px;font-size:10px;color:var(--muted)">
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:10px;background:#10B981;border-radius:2px"></span>Inflow</span>
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:10px;background:#EF4444;border-radius:2px"></span>Outflow</span>
          <span style="display:flex;align-items:center;gap:4px"><span style="width:2px;height:10px;background:#C9A84C"></span>Net Balance</span>
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:10px;background:#94A3B833;border:1px dashed #94A3B8;border-radius:2px"></span>Forecast</span>
        </div>
      </div>
      <div style="overflow-x:auto">
        <div style="min-width:700px;padding:8px 0">
          <!-- Bar chart -->
          <div style="display:flex;align-items:flex-end;gap:4px;height:160px;padding-bottom:4px;border-bottom:1px solid var(--bdr)">
            ${all.map((m,i)=>{
              const isFcast = m.type==='forecast';
              const inH  = Math.max(m.inflow/maxVal*140,2);
              const outH = Math.max(m.outflow/maxVal*140,2);
              return `<div style="flex:1;display:flex;flex-direction:column;align-items:center;gap:2px;min-width:0">
                <div style="display:flex;gap:1px;align-items:flex-end;height:140px">
                  <div style="width:10px;background:${isFcast?'#10B98155':'#10B981'};height:${inH}px;border-radius:2px 2px 0 0;${isFcast?'border:1px dashed #10B981':''}" title="Inflow: ${fmtKWD(m.inflow)}"></div>
                  <div style="width:10px;background:${isFcast?'#EF444455':'#EF4444'};height:${outH}px;border-radius:2px 2px 0 0;${isFcast?'border:1px dashed #EF4444':''}" title="Outflow: ${fmtKWD(m.outflow)}"></div>
                </div>
              </div>`;
            }).join('')}
          </div>
          <!-- Labels -->
          <div style="display:flex;gap:4px;margin-top:4px">
            ${all.map(m=>`<div style="flex:1;text-align:center;font-size:8px;color:${m.type==='forecast'?'#C9A84C':'var(--faint)'};min-width:0;overflow:hidden;white-space:nowrap">${esc(m.label)}</div>`).join('')}
          </div>
        </div>
      </div>
    </div>

    <!-- Data table -->
    <div class="card">
      <div class="sec-head"><div class="sec-title"><span>📋</span>Monthly Breakdown</div></div>
      <div style="overflow-x:auto">
        <table><thead><tr>
          <th>Month</th><th>Type</th>
          <th style="text-align:right">Inflow</th>
          <th style="text-align:right">Outflow</th>
          <th style="text-align:right">Net</th>
          <th style="text-align:right">Running Balance</th>
          <th style="text-align:center">Confidence</th>
        </tr></thead><tbody>
        ${withBalance.map(m=>`<tr style="background:${m.type==='forecast'?'#C9A84C08':''}">
          <td style="font-weight:600;color:${m.type==='forecast'?'#C9A84C':'var(--text)'}">${esc(m.label)}</td>
          <td><span style="font-size:9px;background:${m.type==='forecast'?'#C9A84C22':'#3B82F622'};color:${m.type==='forecast'?'#C9A84C':'#3B82F6'};border-radius:4px;padding:2px 6px">${m.type==='forecast'?'Forecast':'Actual'}</span></td>
          <td style="text-align:right;color:#10B981;font-weight:600">${fmtKWD(m.inflow)}</td>
          <td style="text-align:right;color:#EF4444;font-weight:600">${fmtKWD(m.outflow)}</td>
          <td style="text-align:right;font-weight:700;color:${m.net>=0?'#10B981':'#EF4444'}">${fmtKWD(m.net)}</td>
          <td style="text-align:right;font-weight:700;color:${m.balance>=0?'#C9A84C':'#EF4444'}">${fmtKWD(m.balance)}</td>
          <td style="text-align:center;font-size:10px;color:var(--muted)">${m.type==='forecast'?m.confidence+'%':'100%'}</td>
        </tr>`).join('')}
        </tbody></table>
      </div>
      <div style="margin-top:10px;padding:8px 10px;background:var(--n3);border-radius:6px;font-size:10px;color:var(--faint)">
        ⚠️ Forecast is model-based: 30% avg trend + 50% project completion curve + 20% AR collection. Confidence decreases by 10% per month.
        Always review against actual pipeline and signed contracts.
      </div>
    </div>`;

  }catch(err){
    el.innerHTML = `<div class="empty">Error: ${esc(err.message)}</div>`;
  }
}

