async function loadTraining(tab='overview'){
  const el = document.getElementById('page-training');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading Training…</div>';
  try{
    const today = new Date();
    const [trR, certR, empR] = await Promise.all([
      sb.from('training_records').select('*,employee:employees(full_name,employee_no,department)').order('training_date',{ascending:false}),
      sb.from('employee_certifications').select('*,employee:employees(full_name,employee_no,department)').order('expiry_date'),
      sb.from('employees').select('id,full_name,employee_no,department').eq('status','active').order('full_name')
    ]);
    const trainings = trR.data||[];
    const certs     = certR.data||[];
    const emps      = empR.data||[];

    const expiringSoon = certs.filter(c=>c.expiry_date&&Math.ceil((new Date(c.expiry_date)-today)/86400000)<=30&&Math.ceil((new Date(c.expiry_date)-today)/86400000)>0);
    const expired      = certs.filter(c=>c.expiry_date&&new Date(c.expiry_date)<today);
    const dueTraining  = trainings.filter(t=>t.status==='planned'&&t.training_date&&new Date(t.training_date)>=today).sort((a,b)=>new Date(a.training_date)-new Date(b.training_date));

    const tabBtns = `<div class="tabs">
      <button class="tab${tab==='overview'?' act':''}" data-h-click="h284">📊 Overview</button>
      <button class="tab${tab==='records'?' act':''}" data-h-click="h285">📋 Training Records</button>
      <button class="tab${tab==='certs'?' act':''}" data-h-click="h286" style="color:${expiringSoon.length>0||expired.length>0?'#F97316':'inherit'}">🏆 Certifications</button>
    </div>`;

    let body='';

    if(tab==='overview'){
      const totalHours = trainings.filter(t=>t.status==='completed').reduce((s,t)=>s+Number(t.duration_hours||0),0);
      const completedThisMonth = trainings.filter(t=>t.status==='completed'&&t.training_date?.startsWith(new Date().toISOString().slice(0,7))).length;
      body=`
      <div class="grid4" style="margin-bottom:14px">
        ${kpi('Total Training Hours', Math.round(totalHours), '#C9A84C', 'Completed sessions')}
        ${kpi('Certifications',        certs.length,          '#3B82F6', 'Across all employees')}
        ${kpi('Expiring ≤30d',         expiringSoon.length,    expiringSoon.length>0?'#F97316':'#10B981', 'Need renewal')}
        ${kpi('Expired',               expired.length,         expired.length>0?'#EF4444':'#10B981', 'Overdue renewal')}
      </div>

      ${expiringSoon.length>0||expired.length>0?`
      <div class="card" style="border-left:3px solid #F97316;margin-bottom:14px">
        <div class="sec-head"><div class="sec-title"><span>⚠️</span>Certification Alerts</div></div>
        ${[...expired,...expiringSoon].slice(0,10).map(c=>{
          const daysLeft=Math.ceil((new Date(c.expiry_date)-today)/86400000);
          return`<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid var(--bdr)">
            <span style="font-size:14px">${daysLeft<0?'🔴':'🟡'}</span>
            <div style="flex:1">
              <div style="font-size:11px;font-weight:700">${esc(c.certification_name||'—')}</div>
              <div style="font-size:10px;color:var(--muted)">${esc(c.employee?.full_name||'—')} · ${esc(c.employee?.department||'—')}</div>
            </div>
            <div style="text-align:right;font-size:10px;color:${daysLeft<0?'#EF4444':'#F97316'};font-weight:700">
              ${daysLeft<0?Math.abs(daysLeft)+'d expired':daysLeft+'d left'}
            </div>
          </div>`;
        }).join('')}
      </div>`:``}

      ${dueTraining.length>0?`
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>📅</span>Upcoming Training Sessions</div></div>
        ${dueTraining.slice(0,8).map(t=>`
        <div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid var(--bdr)">
          <div style="flex:1">
            <div style="font-size:11px;font-weight:700">${esc(t.training_name||'—')}</div>
            <div style="font-size:10px;color:var(--muted)">${esc(t.employee?.full_name||'All')} · ${esc(t.training_type||'—')}</div>
          </div>
          <div style="text-align:right;font-size:10px;color:var(--gold);font-weight:700">${esc(t.training_date)}</div>
        </div>`).join('')}
      </div>`:``}`;

    } else if(tab==='records'){
      body=`<table><thead><tr>
        <th>Employee</th><th>Department</th><th>Training</th><th>Type</th><th>Date</th>
        <th style="text-align:right">Hours</th><th style="text-align:center">Status</th>
      </tr></thead><tbody>
      ${trainings.slice(0,100).map(t=>`<tr>
        <td style="font-weight:600">${esc(t.employee?.full_name||'—')}</td>
        <td style="color:var(--muted)">${esc(t.employee?.department||'—')}</td>
        <td style="font-size:11px">${esc(t.training_name||'—')}</td>
        <td style="color:var(--muted)">${esc(t.training_type||'—')}</td>
        <td style="color:var(--faint)">${esc(t.training_date||'—')}</td>
        <td style="text-align:right">${esc(t.duration_hours||'—')}</td>
        <td style="text-align:center">${pill(t.status||'planned',t.status==='completed'?'#10B981':t.status==='planned'?'#3B82F6':'#94A3B8')}</td>
      </tr>`).join('')}
      </tbody></table>`;

    } else if(tab==='certs'){
      body=`<table><thead><tr>
        <th>Employee</th><th>Department</th><th>Certification</th><th>Issuer</th>
        <th>Issue Date</th><th>Expiry</th><th style="text-align:center">Status</th>
      </tr></thead><tbody>
      ${certs.map(c=>{
        const daysLeft=c.expiry_date?Math.ceil((new Date(c.expiry_date)-today)/86400000):null;
        const col=daysLeft===null?'#94A3B8':daysLeft<0?'#EF4444':daysLeft<=30?'#F97316':'#10B981';
        return`<tr>
          <td style="font-weight:600">${esc(c.employee?.full_name||'—')}</td>
          <td style="color:var(--muted)">${esc(c.employee?.department||'—')}</td>
          <td style="font-weight:700;color:var(--text)">${esc(c.certification_name||'—')}</td>
          <td style="color:var(--muted)">${esc(c.issuing_body||'—')}</td>
          <td style="color:var(--faint)">${esc(c.issue_date||'—')}</td>
          <td style="color:${col};font-weight:700">${esc(c.expiry_date||'No Expiry')}${daysLeft!==null&&daysLeft<=30?` <small>(${daysLeft<0?Math.abs(daysLeft)+'d ago':daysLeft+'d'})</small>`:''}</td>
          <td style="text-align:center">${pill(daysLeft===null?'valid':daysLeft<0?'expired':daysLeft<=30?'expiring':'valid',daysLeft===null||daysLeft>30?'#10B981':daysLeft<=0?'#EF4444':'#F97316')}</td>
        </tr>`;}).join('')}
      </tbody></table>`;
    }

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🎓</span>
        <div><h1>Training & Certifications</h1><div class="sub">Employee Development · Skill Tracking · Compliance</div></div>
      </div>
      <div style="display:flex;gap:8px">
        ${can('create')?`<button class="btn btn-ghost btn-sm" data-h-click="h287">+ Training</button>`:''}
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h288">+ Certification</button>`:''}
      </div>
    </div>
    <div class="card">${tabBtns}${body}</div>`;

  }catch(err){
    el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;
  }
}

