async function saveTraining(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const empId=document.getElementById('tr-emp').value;
    const name =document.getElementById('tr-name').value.trim();
    const date =document.getElementById('tr-date').value;
    if(!empId||!name||!date){showToast('Employee, name, date required','error');return;}
    const {error}=await sb.from('training_records').insert({
      employee_id:document.getElementById('tr-emp').value, training_name:name,
      training_type:document.getElementById('tr-type').value, training_date:date,
      duration_hours:Number(document.getElementById('tr-hours').value)||null,
      status:document.getElementById('tr-status').value, created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Training record saved ✓'); closeModal(); loadTraining();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save';}}
}

