async function loadAssets(tab='assets'){
  const el = document.getElementById('page-assets');
  if(!el) return;
  el.innerHTML = '<div class="loading">Loading Assets…</div>';
  try{
    const today = new Date();
    const [assR, maintR] = await Promise.all([
      sb.from('assets').select('*,project:projects(project_no,name),assigned_to:employees(full_name)').order('asset_no'),
      sb.from('asset_maintenance').select('*,asset:assets(asset_no,asset_name)').order('scheduled_date').limit(50)
    ]);
    const assets = assR.data||[];
    const maints = maintR.data||[];

    const dueMaint   = maints.filter(m=>m.status==='scheduled'&&m.scheduled_date&&new Date(m.scheduled_date)<=new Date(today.getTime()+30*86400000));
    const totalValue = assets.reduce((s,a)=>s+Number(a.purchase_value||0),0);
    const bookValue  = assets.reduce((s,a)=>s+Number(a.book_value||a.purchase_value||0),0);

    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='assets'?' act':''}" data-h-click="h291">🔧 Assets (${esc(assets.length)})</button>
      <button class="tab${tab==='maintenance'?' act':''}" data-h-click="h292" style="color:${dueMaint.length>0?'#F97316':'inherit'}">🔨 Maintenance (${esc(dueMaint.length)} due)</button>
    </div>`;

    let body='';
    if(tab==='assets'){
      body=`
      <div style="display:flex;justify-content:flex-end;margin-bottom:8px">
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h293">+ New Asset</button>`:''}
      </div>
      ${assets.length===0
        ? '<div class="empty">No assets registered yet</div>'
        : `<table><thead><tr>
            <th>Asset No</th><th>Name</th><th>Category</th><th>Location/Project</th>
            <th>Assigned To</th><th style="text-align:right">Purchase Value</th><th style="text-align:right">Book Value</th>
            <th style="text-align:center">Condition</th><th style="text-align:center">Status</th>
          </tr></thead><tbody>
          ${assets.map(a=>{
            const condColor=a.condition==='good'?'#10B981':a.condition==='fair'?'#F97316':'#EF4444';
            return`<tr>
              <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(a.asset_no||'—')}</td>
              <td style="font-weight:600;font-size:11px">${esc(a.asset_name||'—')}</td>
              <td style="color:var(--muted)">${esc(a.category||'—')}</td>
              <td style="color:var(--muted);font-size:10px">${esc(a.location||a.project?.project_no||'—')}</td>
              <td style="font-size:10px">${esc(a.assigned_to?.full_name||'Unassigned')}</td>
              <td style="text-align:right">${fmtKWD(a.purchase_value||0)}</td>
              <td style="text-align:right;color:${Number(a.book_value||a.purchase_value||0)<Number(a.purchase_value||0)*0.5?'#F97316':'var(--text)'}">${fmtKWD(a.book_value||a.purchase_value||0)}</td>
              <td style="text-align:center"><span style="font-size:9px;background:${condColor}22;color:${condColor};border-radius:4px;padding:2px 7px;font-weight:700">${esc(a.condition||'—')}</span></td>
              <td style="text-align:center">${pill(a.status||'active',a.status==='active'?'#10B981':a.status==='in_maintenance'?'#F97316':'#94A3B8')}</td>
            </tr>`;}).join('')}
          </tbody></table>`}`;

    } else {
      body=`
      <div style="display:flex;justify-content:flex-end;margin-bottom:8px">
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h294">+ Schedule Maintenance</button>`:''}
      </div>
      ${dueMaint.length>0?`<div style="margin-bottom:10px;padding:8px 12px;background:#F9731622;border:1px solid #F9731633;border-radius:6px;font-size:11px;color:#F97316;font-weight:700">⚠️ ${esc(dueMaint.length)} maintenance task(s) due within 30 days</div>`:''}
      ${maints.length===0?'<div class="empty">No maintenance records</div>':`
      <table><thead><tr>
        <th>Asset</th><th>Type</th><th>Scheduled</th><th>Description</th>
        <th style="text-align:right">Est. Cost</th><th style="text-align:center">Status</th>
      </tr></thead><tbody>
      ${maints.map(m=>{
        const daysLeft=m.scheduled_date?Math.ceil((new Date(m.scheduled_date)-today)/86400000):null;
        const col=m.status==='completed'?'#10B981':daysLeft!==null&&daysLeft<=0?'#EF4444':daysLeft!==null&&daysLeft<=7?'#F97316':'#94A3B8';
        return`<tr>
          <td style="color:var(--gold);font-weight:700">${esc(m.asset?.asset_no||'—')}<br><span style="color:var(--muted);font-size:10px">${esc(m.asset?.asset_name||'—')}</span></td>
          <td>${esc(m.maintenance_type||'—')}</td>
          <td style="color:${col};font-weight:700">${esc(m.scheduled_date||'—')}${daysLeft!==null&&m.status!=='completed'?`<br><span style="font-size:9px">${daysLeft<0?Math.abs(daysLeft)+'d overdue':daysLeft+'d left'}</span>`:''}</td>
          <td style="color:var(--muted);font-size:10px">${esc(m.description||'—')}</td>
          <td style="text-align:right">${m.estimated_cost?fmtKWD(m.estimated_cost):'—'}</td>
          <td style="text-align:center">${pill(m.status||'scheduled',m.status==='completed'?'#10B981':col)}</td>
        </tr>`;}).join('')}
      </tbody></table>`}`;
    }

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🔧</span>
        <div><h1>Asset Management</h1><div class="sub">Equipment · Machinery · Vehicles · Tools</div></div>
      </div>
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total Assets',   assets.length,  '#C9A84C', 'Registered assets')}
      ${kpi('Total Value',    fmtKWD(totalValue), '#10B981', 'Purchase value')}
      ${kpi('Book Value',     fmtKWD(bookValue),  '#3B82F6', 'Current book value')}
      ${kpi('Due Maintenance',dueMaint.length,     dueMaint.length>0?'#F97316':'#10B981', 'Within 30 days')}
    </div>
    <div class="card">${tabBtns}${body}</div>`;

  }catch(err){
    el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;
  }
}

