async function saveMaintenance(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const assetNo=document.getElementById('mnt-asset-no').value.trim();
    const date   =document.getElementById('mnt-date').value;
    if(!assetNo||!date){showToast('Asset No and date required','error');return;}
    const {data:asset}=await sb.from('assets').select('id').eq('asset_no',assetNo).single();
    if(!asset){showToast('Asset not found: '+assetNo,'error');return;}
    const {error}=await sb.from('asset_maintenance').insert({
      asset_id:asset.id, maintenance_type:document.getElementById('mnt-type').value,
      scheduled_date:date, description:document.getElementById('mnt-desc').value.trim()||null,
      estimated_cost:Number(document.getElementById('mnt-cost').value)||null,
      status:'scheduled', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Maintenance scheduled ✓'); closeModal(); loadAssets('maintenance');
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Schedule';}}
}

// ══════════════════════════════════════════════════════════════
//  P7-6 · CLIENT PORTAL SUMMARY (PDF for external clients)
// ══════════════════════════════════════════════════════════════
async function exportClientPortal(projectId, projectNo){
  try{
    showToast('Generating Client Report…');
    const [projR, snapR, invoiceR, wfR] = await Promise.all([
      sb.from('projects').select('*').eq('id',projectId).single(),
      sb.from('project_evm_snapshots').select('*').eq('project_id',projectId).order('snapshot_date').limit(8),
      sb.from('invoices').select('invoice_no,net_amount,status,invoice_date,due_date').eq('project_id',projectId).eq('invoice_type','client').order('invoice_date',{ascending:false}).limit(10),
      sb.from('workflow_items').select('ref_no,title,status,current_step').eq('entity_id',projectId).in('status',['pending','approved']).limit(5)
    ]);
    const p     = projR.data||{};
    const snaps = snapR.data||[];
    const invs  = invoiceR.data||[];
    const today = new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});

    const { jsPDF } = window.jspdf;
    const doc = new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});

    // Header
    doc.setFillColor(30,58,95);
    doc.rect(0,0,210,45,'F');
    doc.setTextColor(201,168,76); doc.setFontSize(20); doc.setFont('helvetica','bold');
    doc.text('PROJECT STATUS REPORT',14,18);
    doc.setTextColor(255,255,255); doc.setFontSize(13);
    doc.text(p.name||'—',14,28);
    doc.setFontSize(9); doc.setFont('helvetica','normal'); doc.setTextColor(148,163,184);
    doc.text(`${p.project_no||'—'} · Prepared: ${today} · Smart Projects 360 · Kuwait`,14,36);
    doc.text(`Client: ${p.client||'—'}`,14,42);

    // Project Overview
    let y=55;
    doc.setFillColor(241,245,249); doc.rect(14,y-5,182,8,'F');
    doc.setTextColor(30,58,95); doc.setFontSize(11); doc.setFont('helvetica','bold');
    doc.text('PROJECT OVERVIEW',16,y); y+=10;

    const cpi=Number(p.cpi||1), eac=cpi>0?Number(p.ac)+(Number(p.bac)-Number(p.ev))/cpi:Number(p.bac);
    const infoRows=[
      ['Contract Value', `KD ${Number(p.contract_value||0).toLocaleString('en-US',{minimumFractionDigits:3})}`,'Start Date', p.start_date||'—'],
      ['Budget (BAC)',   `KD ${Number(p.bac||0).toLocaleString('en-US',{minimumFractionDigits:3})}`,'End Date',   p.end_date||'—'],
      ['% Complete',    `${p.pct||0}%`,'Status', (p.status||'—').toUpperCase()],
      ['EAC',           `KD ${eac.toLocaleString('en-US',{minimumFractionDigits:3})}`,'CPI', cpi.toFixed(3)],
    ];
    doc.setFont('helvetica','normal'); doc.setFontSize(9);
    infoRows.forEach(([l1,v1,l2,v2])=>{
      doc.setTextColor(100,116,139); doc.text(l1+':',16,y); doc.setTextColor(15,23,42); doc.text(v1,55,y);
      if(l2){doc.setTextColor(100,116,139); doc.text(l2+':',116,y); doc.setTextColor(15,23,42); doc.text(String(v2),150,y);}
      y+=6;
    });

    // Progress bar
    y+=4;
    const pct=Math.min(Number(p.pct||0),100);
    doc.setFillColor(220,230,240); doc.rect(14,y,182,6,'F');
    doc.setFillColor(cpi>=1?16:cpi>=0.9?249:239, cpi>=1?185:cpi>=0.9?115:68, cpi>=1?129:cpi>=0.9?22:68);
    doc.rect(14,y,182*pct/100,6,'F');
    doc.setTextColor(30,58,95); doc.setFontSize(8); doc.setFont('helvetica','bold');
    doc.text(`${pct}% Complete`,105,y+4.5,'center');
    y+=14;

    // Invoice summary
    doc.setFillColor(241,245,249); doc.rect(14,y-5,182,8,'F');
    doc.setTextColor(30,58,95); doc.setFontSize(11); doc.setFont('helvetica','bold');
    doc.text('INVOICE SUMMARY',16,y); y+=8;
    doc.setFontSize(8); doc.setFont('helvetica','normal');
    doc.setTextColor(100,116,139);
    doc.text('Invoice No',16,y); doc.text('Date',60,y); doc.text('Amount',100,y); doc.text('Due Date',140,y); doc.text('Status',175,y);
    y+=5;
    doc.setTextColor(15,23,42);
    invs.slice(0,8).forEach((inv,i)=>{
      if(i%2===0){doc.setFillColor(248,250,252); doc.rect(14,y-3,182,5,'F');}
      doc.text(inv.invoice_no||'—',16,y); doc.text(inv.invoice_date||'—',60,y);
      doc.text(`KD ${Number(inv.net_amount||0).toFixed(3)}`,100,y); doc.text(inv.due_date||'—',140,y);
      const sc=inv.status==='paid'?[16,185,129]:inv.status==='overdue'?[239,68,68]:[249,115,22];
      doc.setTextColor(sc[0],sc[1],sc[2]); doc.text((inv.status||'—').toUpperCase(),175,y);
      doc.setTextColor(15,23,42); y+=5;
    });

    // EVM trend
    if(snaps.length>1){
      y+=6;
      doc.setFillColor(241,245,249); doc.rect(14,y-5,182,8,'F');
      doc.setTextColor(30,58,95); doc.setFontSize(11); doc.setFont('helvetica','bold');
      doc.text('EVM PERFORMANCE TREND',16,y); y+=8;
      doc.setFontSize(8); doc.setFont('helvetica','normal'); doc.setTextColor(100,116,139);
      doc.text('Date',16,y); doc.text('PV (KD)',55,y); doc.text('EV (KD)',90,y); doc.text('AC (KD)',125,y); doc.text('CPI',160,y); doc.text('SPI',175,y); y+=5;
      doc.setTextColor(15,23,42);
      snaps.forEach((s,i)=>{
        if(i%2===0){doc.setFillColor(248,250,252); doc.rect(14,y-3,182,5,'F');}
        const sc=Number(s.ac)>0?Number(s.ev)/Number(s.ac):1;
        doc.text(s.snapshot_date||'—',16,y);
        doc.text(Math.round(s.pv||0).toLocaleString(),55,y); doc.text(Math.round(s.ev||0).toLocaleString(),90,y); doc.text(Math.round(s.ac||0).toLocaleString(),125,y);
        doc.setTextColor(sc>=1?16:sc>=0.9?249:239, sc>=1?185:sc>=0.9?115:68, sc>=1?129:sc>=0.9?22:68);
        doc.text(sc.toFixed(2),160,y); doc.setTextColor(15,23,42); y+=5;
      });
    }

    // Footer
    doc.setFontSize(8); doc.setTextColor(148,163,184);
    doc.line(14,282,196,282);
    doc.text('This report was generated by SP360 v4.1. Smart Projects 360 · Kuwait. For client use only.',105,288,'center');

    doc.save(`ClientReport_${p.project_no||'Project'}_${new Date().toISOString().split('T')[0]}.pdf`);
    showToast('Client report exported ✓');
  }catch(e){
    showToast('Client report error: '+e.message,'error');
    logError('Reports','exportClientPortal',e);
  }
}

