//  P8-1 · SUBCONTRACTOR MANAGEMENT
// ══════════════════════════════════════════════════════════════
async function loadSubcon(tab='list'){
  const el=document.getElementById('page-subcon');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Subcontractors…</div>';
  try{
    const today=new Date();
    const [subR,projR,payR]=await Promise.all([
      sb.from('subcontractors').select('*,project:projects(project_no,name)').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name').in('status',ACTIVE_STATUSES).order('project_no'),
      sb.from('subcontractor_payments').select('*,subcon:subcontractors(subcon_no,subcon_name)').order('payment_date',{ascending:false}).limit(50)
    ]);
    const subs=subR.data||[], projs=projR.data||[], pays=payR.data||[];

    const active=subs.filter(s=>s.status==='active');
    const totalContract=subs.reduce((s,x)=>s+Number(x.contract_value||0),0);
    const totalPaid=pays.filter(p=>p.status==='paid').reduce((s,p)=>s+Number(p.amount||0),0);
    const totalPending=subs.reduce((s,x)=>s+Number(x.contract_value||0),0)-totalPaid;

    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='list'?' act':''}" data-h-click="h297">🏢 Subcontractors (${esc(subs.length)})</button>
      <button class="tab${tab==='payments'?' act':''}" data-h-click="h298">💳 Payments (${esc(pays.length)})</button>
    </div>`;

    let body='';
    if(tab==='list'){
      body=`
      <div style="display:flex;justify-content:flex-end;margin-bottom:8px">
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h299">+ New Subcontractor</button>`:''}
      </div>
      ${subs.length===0?'<div class="empty">No subcontractors registered</div>':`
      <table><thead><tr>
        <th>Subcon No</th><th>Name</th><th>Scope</th><th>Project</th>
        <th style="text-align:right">Contract Value</th><th>Start</th><th>End</th>
        <th style="text-align:center">Status</th><th></th>
      </tr></thead><tbody>
      ${subs.map(s=>{
        const paid=pays.filter(p=>p.subcontractor_id===s.id&&p.status==='paid').reduce((t,p)=>t+Number(p.amount||0),0);
        const pct=Number(s.contract_value)>0?Math.round(paid/Number(s.contract_value)*100):0;
        return`<tr>
          <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(s.subcon_no||'—')}</td>
          <td style="font-weight:600">${esc(s.subcon_name||'—')}</td>
          <td style="color:var(--muted);font-size:10px;max-width:150px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(s.scope||'—')}</td>
          <td style="font-size:10px;color:var(--gold)">${esc(s.project?.project_no||'—')}</td>
          <td style="text-align:right;font-weight:700">${fmtKWD(s.contract_value||0)}</td>
          <td style="font-size:10px;color:var(--faint)">${esc(s.start_date||'—')}</td>
          <td style="font-size:10px;color:var(--faint)">${esc(s.end_date||'—')}</td>
          <td style="text-align:center">${pill(s.status||'active',s.status==='active'?'#10B981':s.status==='completed'?'#3B82F6':'#94A3B8')}</td>
          <td>
            <button data-h-click="h301" data-ha-click="${esc(JSON.stringify([String((s.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px" title="View detail">👁</button>
            ${can('create')?`<button data-h-click="h300" data-ha-click="${esc(JSON.stringify([String((s.id)??''),String((s.subcon_no)??''),String((s.subcon_name)??'')]))}" style="background:none;border:none;color:#10B981;cursor:pointer;font-size:11px" title="Add payment">💳</button>`:''}
          </td>
        </tr>`;}).join('')}
      </tbody></table>`}`;
    } else {
      body=`
      ${pays.length===0?'<div class="empty">No payments recorded</div>':`
      <table><thead><tr>
        <th>Payment No</th><th>Subcontractor</th><th>Description</th>
        <th style="text-align:right">Amount</th><th>Date</th>
        <th style="text-align:center">Status</th>
      </tr></thead><tbody>
      ${pays.map(p=>`<tr>
        <td style="color:var(--gold);font-size:10px;font-weight:700">${esc(p.payment_no||'—')}</td>
        <td style="font-weight:600">${esc(p.subcon?.subcon_name||'—')}</td>
        <td style="color:var(--muted);font-size:10px">${esc(p.description||'—')}</td>
        <td style="text-align:right;font-weight:700;color:#10B981">${fmtKWD(p.amount||0)}</td>
        <td style="font-size:10px;color:var(--faint)">${esc(p.payment_date||'—')}</td>
        <td style="text-align:center">${pill(p.status||'pending',p.status==='paid'?'#10B981':'#F97316')}</td>
      </tr>`).join('')}
      </tbody></table>`}`;
    }

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🏢</span>
        <div><h1>Subcontractor Management</h1><div class="sub">Contracts · Payments · Performance</div></div>
      </div>
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Active Subcons',  active.length,    '#C9A84C', 'Currently active')}
      ${kpi('Total Contract',  fmtKWD(totalContract), '#3B82F6', 'Combined value')}
      ${kpi('Total Paid',      fmtKWD(totalPaid),     '#10B981', 'Payments released')}
      ${kpi('Balance Due',     fmtKWD(Math.max(totalContract-totalPaid,0)), '#F97316', 'Remaining')}
    </div>
    <div class="card">${tabBtns}${body}</div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

