async function saveSubcon(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const name=document.getElementById('sc-name').value.trim();
    const projId=document.getElementById('sc-proj').value;
    if(!name){showToast('Company name required','error');return;}
    if(!projId){showToast('Project required','error');return;}
    const no=await nextRefNo('SC');
    const {error}=await sb.from('subcontractors').insert({
      subcon_no:no, subcon_name:name,
      contact_person:document.getElementById('sc-contact').value.trim()||null,
      project_id:projId,
      contract_value:Number(document.getElementById('sc-val').value)||0,
      start_date:document.getElementById('sc-start').value||null,
      end_date:document.getElementById('sc-end').value||null,
      scope:document.getElementById('sc-scope').value.trim()||null,
      status:'active', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    await writeAudit('subcontractors',null,'SUBCON_CREATED',null,{subcon_no:no,name},'Subcontractor created');
    showToast(no+' created ✓'); closeModal(); loadSubcon();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Create';}}
}

async function openSubconDetail(id){
  const {data:s}=await sb.from('subcontractors').select('*,project:projects(project_no,name)').eq('id',id).single();
  const {data:pays}=await sb.from('subcontractor_payments').select('*').eq('subcontractor_id',id).order('payment_date',{ascending:false});
  if(!s) return;
  const totalPaid=(pays||[]).filter(p=>p.status==='paid').reduce((t,p)=>t+Number(p.amount||0),0);
  const pct=Number(s.contract_value)>0?Math.round(totalPaid/Number(s.contract_value)*100):0;
  openModal(`🏢 ${s.subcon_no} — ${s.subcon_name}`,`
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">
      ${[['Project',s.project?.project_no||'—'],['Status',pill(s.status||'active',s.status==='active'?'#10B981':'#94A3B8')],
         ['Contract',fmtKWD(s.contract_value||0)],['Paid So Far',fmtKWD(totalPaid)],
         ['Start',s.start_date||'—'],['End',s.end_date||'—']
      ].map(([l,v])=>`<div style="background:var(--n3);border-radius:6px;padding:8px">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase">${l}</div>
        <div style="font-size:12px;color:var(--text);margin-top:2px">${v}</div>
      </div>`).join('')}
    </div>
    <div style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;font-size:10px;color:var(--muted);margin-bottom:4px">
        <span>Payment Progress</span><span>${pct}% paid</span>
      </div>
      <div style="background:var(--bdr);border-radius:4px;height:8px;overflow:hidden">
        <div style="height:100%;width:${pct}%;background:#10B981;border-radius:4px"></div>
      </div>
    </div>
    ${s.scope?`<div style="padding:8px;background:var(--n3);border-radius:6px;font-size:11px;color:var(--muted);margin-bottom:12px"><b>Scope:</b> ${esc(s.scope)}</div>`:''}
    <div style="font-size:11px;font-weight:700;color:var(--gold);margin-bottom:6px">Payment History</div>
    ${(pays||[]).length===0?'<div style="color:var(--faint);font-size:10px">No payments yet</div>':
      (pays||[]).map(p=>`<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--bdr);font-size:10px">
        <span style="color:var(--muted)">${esc(p.description||p.payment_no)}</span>
        <span style="font-weight:700;color:#10B981">${fmtKWD(p.amount||0)}</span>
        <span style="color:var(--faint)">${esc(p.payment_date||'—')}</span>
        <span>${pill(p.status||'pending',p.status==='paid'?'#10B981':'#F97316')}</span>
      </div>`).join('')}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      ${can('create')?`<button class="btn btn-primary" data-h-click="h303" data-ha-click="${esc(JSON.stringify([String((id)??''),String((s.subcon_no)??''),String((s.subcon_name)??'')]))}">💳 Add Payment</button>`:''}
    </div>`);
}

function openAddSubconPayment(subconId, subconNo, subconName){
  openModal(`💳 Payment — ${subconNo}`,`
    <div style="margin-bottom:10px;font-size:11px;color:var(--muted)">${esc(subconName)}</div>
    <div class="form-row">
      <div class="form-field"><label>Amount (KWD) *</label><input id="sp-amt" type="number" step="0.001" placeholder="0.000"/></div>
      <div class="form-field"><label>Payment Date *</label><input id="sp-date" type="date" value="${new Date().toISOString().split('T')[0]}"/></div>
    </div>
    <div class="form-field"><label>Description *</label><input id="sp-desc" placeholder="e.g. Progress Payment #1 — 30%"/></div>
    <div class="form-field"><label>Status</label>
      <select id="sp-status" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
        <option value="paid">Paid</option><option value="pending">Pending</option>
      </select>
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h304" data-ha-click="${esc(JSON.stringify([String((subconId)??'')]))}">Save Payment</button>
    </div>`);
}

async function saveSubconPayment(e,subconId){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const amt=Number(document.getElementById('sp-amt').value);
    const date=document.getElementById('sp-date').value;
    const desc=document.getElementById('sp-desc').value.trim();
    if(!amt||!date||!desc){showToast('Amount, date and description required','error');return;}
    const no=await nextRefNo('SPY');
    const {error}=await sb.from('subcontractor_payments').insert({
      payment_no:no, subcontractor_id:subconId, amount:amt,
      payment_date:date, description:desc,
      status:document.getElementById('sp-status').value,
      created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Payment recorded ✓'); closeModal(); loadSubcon('payments');
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save Payment';}}
}

