async function loadMeetings(tab='list'){
  const el=document.getElementById('page-meetings');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Meetings…</div>';
  try{
    const [meetR,projR]=await Promise.all([
      sb.from('meeting_minutes').select('*,project:projects(project_no,name)').order('meeting_date',{ascending:false}),
      sb.from('projects').select('id,project_no,name').in('status',ACTIVE_STATUSES).order('project_no')
    ]);
    const meets=meetR.data||[], projs=projR.data||[];
    const today=new Date();
    const thisMonth=today.toISOString().slice(0,7);
    const thisMonthMeets=meets.filter(m=>m.meeting_date?.startsWith(thisMonth));
    const withActions=meets.filter(m=>m.action_items&&m.action_items.length>0);

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📝</span>
        <div><h1>Meeting Minutes</h1><div class="sub">Site Meetings · Progress Reviews · Technical Discussions</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h305">+ Record Meeting</button>`:''}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total Meetings',  meets.length,           '#C9A84C', 'All recorded')}
      ${kpi('This Month',      thisMonthMeets.length,  '#3B82F6', today.toLocaleDateString('en-GB',{month:'long'}))}
      ${kpi('With Actions',    withActions.length,     '#F97316', 'Have action items')}
      ${kpi('Projects',        new Set(meets.map(m=>m.project_id).filter(Boolean)).size, '#10B981', 'Covered')}
    </div>
    <div class="card">
      ${meets.length===0?'<div class="empty">No meetings recorded yet</div>':`
      <table><thead><tr>
        <th>Meeting No</th><th>Title</th><th>Type</th><th>Project</th><th>Date</th><th>Attendees</th><th>Actions</th><th></th>
      </tr></thead><tbody>
      ${meets.map(m=>`<tr>
        <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(m.meeting_no||'—')}</td>
        <td style="font-weight:600;font-size:11px">${esc(m.title||'—')}</td>
        <td><span style="font-size:9px;background:#3B82F622;color:#3B82F6;border-radius:4px;padding:2px 6px">${esc(m.meeting_type||'General')}</span></td>
        <td style="font-size:10px;color:var(--gold)">${esc(m.project?.project_no||'General')}</td>
        <td style="font-size:10px;color:var(--faint)">${esc(m.meeting_date||'—')}</td>
        <td style="font-size:10px;color:var(--muted)">${esc(m.attendee_count||'—')}</td>
        <td style="text-align:center"><span style="font-size:11px;font-weight:700;color:${(m.action_items||[]).length>0?'#F97316':'var(--faint)'}">${(m.action_items||[]).length}</span></td>
        <td><button data-h-click="h306" data-ha-click="${esc(JSON.stringify([String((m.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px">👁</button></td>
      </tr>`).join('')}
      </tbody></table>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

