// Previously referenced but never defined — print preview of the minutes form (values escaped)
function exportMeetingPDF_preview(){
  const v=id=>document.getElementById(id)?.value||'';
  const w=window.open('','_blank');
  if(!w){ showToast('Allow pop-ups to preview','error'); return; }
  const rows=v('mt-actions').split(/\r?\n/).filter(x=>x.trim()).map(l=>{
    const [a,o,d]=l.split('|').map(x=>esc((x||'').trim())); return `<tr><td>${a}</td><td>${o}</td><td>${d}</td></tr>`; }).join('');
  w.document.write(`<html><head><title>Meeting Minutes — Preview</title><style>body{font-family:Arial,sans-serif;font-size:12px;padding:24px;color:#1E293B}h1{color:#0F1E38;border-bottom:3px solid #C9A84C;padding-bottom:6px;font-size:18px}th{background:#0F1E38;color:#C9A84C;text-align:left;padding:5px}td{border:1px solid #E2E8F0;padding:5px}table{border-collapse:collapse;width:100%}pre{white-space:pre-wrap;font-family:inherit}</style></head><body>
    <h1>Meeting Minutes — Preview</h1>
    <p><b>Attendees:</b> ${esc(v('mt-names'))}</p>
    <h3>Discussion Points</h3><pre>${esc(v('mt-disc'))}</pre>
    <h3>Action Items</h3><table><tr><th>Action</th><th>Owner</th><th>Due</th></tr>${rows||'<tr><td colspan="3">—</td></tr>'}</table>
  </body></html>`);
  w.document.close();
}

async function saveMeeting(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const title=document.getElementById('mt-title').value.trim();
    const date =document.getElementById('mt-date').value;
    const disc =document.getElementById('mt-disc').value.trim();
    if(!title||!date||!disc){showToast('Title, date and discussion required','error');return;}
    // Parse action items
    const actionsRaw=document.getElementById('mt-actions').value.trim();
    const actions=actionsRaw?actionsRaw.split('\n').filter(l=>l.trim()).map(l=>{
      const parts=l.split('|').map(p=>p.trim());
      return {action:parts[0]||l, owner:parts[1]||null, due_date:parts[2]||null, status:'open'};
    }):[];
    const no=await nextRefNo('MTG');
    const {error}=await sb.from('meeting_minutes').insert({
      meeting_no:no, title,
      meeting_type:document.getElementById('mt-type').value,
      project_id:document.getElementById('mt-proj').value||null,
      meeting_date:date,
      location:document.getElementById('mt-loc').value.trim()||null,
      attendee_count:Number(document.getElementById('mt-att').value)||null,
      attendee_names:document.getElementById('mt-names').value.trim()||null,
      discussion_points:disc,
      action_items:actions,
      created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    await writeAudit('meeting_minutes',null,'MEETING_RECORDED',null,{meeting_no:no,title},'Meeting minutes recorded');
    showToast(no+' saved ✓'); closeModal(); loadMeetings();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save Minutes';}}
}

