async function openCloseoutChecklist(projectId, projectNo){
  // Load existing checklist
  const {data:existing}=await sb.from('project_closeout').select('*').eq('project_id',projectId).single();
  const checks=existing?.checklist||{};
  const signedOff=existing?.signed_off||false;

  const cats=[...new Set(CLOSEOUT_CHECKLIST.map(i=>i.cat))];
  const total=CLOSEOUT_CHECKLIST.length;
  const done=CLOSEOUT_CHECKLIST.filter(i=>checks[i.id]?.checked).length;
  const pct=Math.round(done/total*100);

  openModal(`✅ Closeout Checklist — ${projectNo}`,`
    <div style="margin-bottom:12px">
      <div style="display:flex;justify-content:space-between;font-size:11px;color:var(--muted);margin-bottom:4px">
        <span>Completion: ${done}/${total} items</span>
        <span style="font-weight:700;color:${pct===100?'#10B981':'#F97316'}">${pct}%</span>
      </div>
      <div style="background:var(--bdr);border-radius:4px;height:8px;overflow:hidden">
        <div style="height:100%;width:${pct}%;background:${pct===100?'#10B981':'#C9A84C'};border-radius:4px;transition:width .3s"></div>
      </div>
    </div>
    ${signedOff?'<div style="padding:8px;background:#10B98122;border:1px solid #10B98133;border-radius:6px;margin-bottom:10px;font-size:11px;color:#10B981;font-weight:700">✅ This checklist has been signed off</div>':''}
    <div style="max-height:380px;overflow-y:auto" id="closeout-items">
    ${cats.map(cat=>`
      <div style="margin-bottom:12px">
        <div style="font-size:10px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:.5px;margin-bottom:6px">${cat}</div>
        ${CLOSEOUT_CHECKLIST.filter(i=>i.cat===cat).map(item=>`
        <div style="display:flex;align-items:center;gap:8px;padding:6px 8px;border-radius:6px;background:${checks[item.id]?.checked?'#10B98111':'var(--n3)'};margin-bottom:3px">
          <input type="checkbox" id="cl-${esc(item.id)}" ${checks[item.id]?.checked?'checked':''} ${signedOff?'disabled':''}
            data-h-change="h310" data-ha-change="${esc(JSON.stringify([String((projectId)??''),String((item.id)??'')]))}"
            style="width:16px;height:16px;accent-color:#10B981;cursor:pointer;flex-shrink:0"/>
          <label for="cl-${esc(item.id)}" style="font-size:11px;color:${checks[item.id]?.checked?'var(--muted)':'var(--text)'};cursor:pointer;text-decoration:${checks[item.id]?.checked?'line-through':''};flex:1">${esc(item.label)}</label>
          ${checks[item.id]?.checked?`<span style="font-size:9px;color:var(--faint)">${esc(checks[item.id]?.by||'')}</span>`:''}
        </div>`).join('')}
      </div>`).join('')}
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      ${!signedOff&&pct===100?`<button class="btn btn-primary" data-h-click="h311" data-ha-click="${esc(JSON.stringify([String((projectId)??''),String((projectNo)??'')]))}">✅ Sign Off & Close Project</button>`:
        !signedOff?`<button class="btn btn-ghost btn-sm" data-h-click="h312" data-ha-click="${esc(JSON.stringify([String((projectId)??'')]))}">💾 Save Progress</button>`:''}
    </div>`);

  // Store project ID for inline updates
  window._closeoutProjectId = projectId;
}

async function updateCloseoutItem(projectId, itemId, checked){
  // Get existing
  const {data:existing}=await sb.from('project_closeout').select('*').eq('project_id',projectId).single();
  const checks=existing?.checklist||{};
  checks[itemId]={checked, by:currentProfile?.full_name||'—', at:new Date().toISOString()};
  if(existing){
    await sb.from('project_closeout').update({checklist:checks,updated_at:new Date().toISOString()}).eq('project_id',projectId);
  } else {
    await sb.from('project_closeout').insert({project_id:projectId,checklist:checks,created_by:currentProfile?.id});
  }
  // Update progress bar
  const done=CLOSEOUT_CHECKLIST.filter(i=>checks[i.id]?.checked).length;
  const pct=Math.round(done/CLOSEOUT_CHECKLIST.length*100);
  const bar=document.querySelector('#closeout-items')?.previousElementSibling?.querySelector('div:last-child div');
  if(bar) bar.style.width=pct+'%';
}

async function signOffCloseout(projectId, projectNo){
  if(!confirm(`Sign off closeout for ${projectNo} and close the project?`)) return;
  const {data:existing}=await sb.from('project_closeout').select('*').eq('project_id',projectId).single();
  await sb.from('project_closeout').upsert({project_id:projectId,checklist:existing?.checklist||{},signed_off:true,signed_by:currentProfile?.id,signed_at:new Date().toISOString()},{onConflict:'project_id'});
  await sb.from('projects').update({status:'closeout',updated_at:new Date().toISOString()}).eq('id',projectId);
  await writeAudit('projects',projectId,'CLOSEOUT_SIGNED_OFF',{status:'execution'},{status:'closeout'},'Project closeout signed off');
  showToast(`${projectNo} closeout signed off ✓`);
  closeModal();
  loadProjects();
}

async function saveCloseout(projectId){
  showToast('Progress saved ✓');
}

