function t(key){ return TRANSLATIONS[_currentLang]?.[key] || TRANSLATIONS.en[key] || key; }

function toggleLanguage(){
  _currentLang = _currentLang==='en' ? 'ar' : 'en';
  localStorage.setItem('sp360_lang', _currentLang);
  const isAr = _currentLang==='ar';
  document.documentElement.setAttribute('dir', isAr ? 'rtl' : 'ltr');
  document.documentElement.setAttribute('lang', _currentLang);
  document.body.style.fontFamily = isAr ? "'Noto Sans Arabic', 'Segoe UI', sans-serif" : "'Inter', 'Segoe UI', sans-serif";
  // Update nav labels
  Object.entries(TRANSLATIONS[_currentLang]).forEach(([key,val])=>{
    const btn=document.getElementById('nav-'+key);
    if(btn){
      const icon=btn.querySelector('.nav-icon');
      btn.textContent=val;
      if(icon){ btn.insertBefore(icon,btn.firstChild); }
    }
  });
  showToast(isAr?'تم التبديل إلى العربية':'Switched to English');
  // Reload current page
  const activePage=document.querySelector('.page.active');
  if(activePage){ const pageId=activePage.id.replace('page-',''); navTo(pageId,document.getElementById('nav-'+pageId)); }
}

