//  P8-5 · CHANGE ORDER DASHBOARD ENHANCEMENT
// ══════════════════════════════════════════════════════════════
async function loadCODashboard(){
  const {data:cos}=await sb.from('change_orders').select('*,project:projects(project_no,name)').order('created_at',{ascending:false}).limit(200);
  const C=cos||[];
  const pending  =C.filter(c=>c.status==='pending'||c.workflow_status==='submitted');
  const approved =C.filter(c=>c.status==='approved');
  const rejected =C.filter(c=>c.status==='rejected');
  const totalAmt =approved.reduce((s,c)=>s+Number(c.amount||0),0);
  const pendingAmt=pending.reduce((s,c)=>s+Number(c.amount||0),0);

  // By project
  const byProj={};
  C.forEach(c=>{ const k=c.project?.project_no||'General'; if(!byProj[k]){byProj[k]={count:0,amt:0,proj_no:k};} byProj[k].count++; byProj[k].amt+=Number(c.amount||0); });
  const topProjs=Object.values(byProj).sort((a,b)=>b.amt-a.amt).slice(0,5);

  openModal('📊 Change Order Dashboard',`
    <div class="grid4" style="margin-bottom:12px">
      ${[
        ['Total COs',C.length,'#C9A84C','All change orders'],
        ['Pending',pending.length,'#F97316',fmtKWD(pendingAmt)+' pending'],
        ['Approved',approved.length,'#10B981',fmtKWD(totalAmt)+' approved'],
        ['Rejected',rejected.length,'#EF4444','Not proceeding']
      ].map(([l,v,col,sub])=>`<div style="background:${col}11;border:1px solid ${col}33;border-radius:8px;padding:12px;text-align:center">
        <div style="font-size:9px;font-weight:700;color:var(--muted);text-transform:uppercase">${l}</div>
        <div style="font-size:20px;font-weight:900;color:${col}">${v}</div>
        <div style="font-size:9px;color:var(--faint)">${sub}</div>
      </div>`).join('')}
    </div>
    <div style="margin-bottom:12px">
      <div style="font-size:11px;font-weight:700;color:var(--gold);margin-bottom:8px">Top Projects by CO Value</div>
      ${topProjs.map(p=>`
      <div style="display:flex;justify-content:space-between;align-items:center;padding:5px 0;border-bottom:1px solid var(--bdr)">
        <span style="font-size:11px;color:var(--text);font-weight:600">${esc(p.proj_no)}</span>
        <div style="display:flex;gap:12px;font-size:10px">
          <span style="color:var(--muted)">${esc(p.count)} COs</span>
          <span style="color:var(--gold);font-weight:700">${fmtKWD(p.amt)}</span>
        </div>
      </div>`).join('')}
    </div>
    ${pending.length>0?`
    <div>
      <div style="font-size:11px;font-weight:700;color:#F97316;margin-bottom:6px">⚡ Pending Approval</div>
      ${pending.slice(0,5).map(c=>`
      <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 8px;background:#F9731611;border-radius:5px;margin-bottom:4px">
        <div>
          <span style="font-size:11px;font-weight:700;color:var(--gold)">${esc(c.co_no||'—')}</span>
          <span style="font-size:10px;color:var(--muted);margin-left:6px">${esc(c.project?.project_no||'—')}</span>
        </div>
        <span style="font-size:11px;font-weight:700;color:#F97316">${fmtKWD(c.amount||0)}</span>
      </div>`).join('')}
    </div>`:''}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      <button class="btn btn-primary" data-h-click="h235">Go to Projects</button>
    </div>`);
}

// ══════════════════════════════════════════════════════════════
//  P9-1 · ADVANCED ANALYTICS
// ══════════════════════════════════════════════════════════════
async function loadAnalytics(){
  const el=document.getElementById('page-analytics');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Analytics…</div>';
  try{
    const today=new Date();
    const [projR,invR,wfR,ncrR,empR,snapR]=await Promise.all([
      sb.from('projects').select('id,project_no,name,status,cpi,spi,pct,bac,ev,ac,pv,department,start_date,end_date').order('project_no'),
      sb.from('invoices').select('invoice_type,status,net_amount,paid_date,created_at,due_date'),
      sb.from('workflow_items').select('id,status,entity_type,created_at'),
      sb.from('ncrs').select('id,severity,status,department,created_at'),
      sb.from('employees').select('id,department,status'),
      sb.from('project_evm_snapshots').select('project_id,snapshot_date,pv,ev,ac').order('snapshot_date')
    ]);
    const projs=projR.data||[], invs=invR.data||[], wfs=wfR.data||[];
    const ncrs=ncrR.data||[], emps=empR.data||[], snaps=snapR.data||[];

    const active=projs.filter(p=>ACTIVE_STATUSES.includes(p.status));

    // ── Predictive: EAC + Completion Forecast ────────────────
    const eacData=active.map(p=>{
      const cpi=Number(p.cpi)||1;
      const eac=cpi>0?Number(p.ac)+(Number(p.bac)-Number(p.ev))/cpi:Number(p.bac);
      const costOverrun=eac-Number(p.bac);
      const pctLeft=Math.max(100-Number(p.pct||0),0)/100;
      const daysElapsed=p.start_date?Math.ceil((today-new Date(p.start_date))/86400000):0;
      const predictedDays=p.pct>0?Math.round(daysElapsed/(Number(p.pct)/100)):null;
      const predictedEnd=predictedDays&&p.start_date?new Date(new Date(p.start_date).getTime()+predictedDays*86400000):null;
      return {
        project_no:p.project_no, name:(p.name||'').substring(0,30),
        cpi:Number(p.cpi||1), spi:Number(p.spi||1),
        bac:Number(p.bac||0), eac:Math.round(eac),
        costOverrun:Math.round(costOverrun),
        predictedEnd:predictedEnd?predictedEnd.toLocaleDateString('en-GB'):null,
        scheduledEnd:p.end_date?new Date(p.end_date).toLocaleDateString('en-GB'):null,
        risk:cpi<0.9?'critical':cpi<1?'at-risk':'on-track'
      };
    });

    // ── Trend: Monthly Workflow SLA ───────────────────────────
    const wfTrend=[];
    for(let i=5;i>=0;i--){
      const d=new Date(today.getFullYear(),today.getMonth()-i,1);
      const m=d.toISOString().slice(0,7);
      const monthWFs=wfs.filter(w=>w.created_at?.startsWith(m));
      const overdue=monthWFs.filter(w=>w.status==='overdue').length;
      const sla=monthWFs.length>0?Math.round((1-overdue/monthWFs.length)*100):100;
      wfTrend.push({m:d.toLocaleDateString('en-GB',{month:'short',year:'2-digit'}),total:monthWFs.length,overdue,sla});
    }

    // ── Dept performance ─────────────────────────────────────
    const depts=[...new Set(active.map(p=>p.department).filter(Boolean))];
    const deptPerf=depts.map(d=>{
      const dp=active.filter(p=>p.department===d);
      const avgCPI=dp.length?dp.reduce((s,p)=>s+Number(p.cpi||1),0)/dp.length:1;
      const avgPct=dp.length?dp.reduce((s,p)=>s+Number(p.pct||0),0)/dp.length:0;
      return {dept:d,count:dp.length,avgCPI:Number(avgCPI.toFixed(3)),avgPct:Math.round(avgPct)};
    }).sort((a,b)=>b.avgCPI-a.avgCPI);

    // ── Revenue vs Cost trend ─────────────────────────────────
    const revTrend=[];
    for(let i=5;i>=0;i--){
      const d=new Date(today.getFullYear(),today.getMonth()-i,1);
      const m=d.toISOString().slice(0,7);
      const rev=invs.filter(x=>x.invoice_type==='client'&&x.status==='paid'&&x.paid_date?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
      const cost=invs.filter(x=>x.invoice_type!=='client'&&x.status==='paid'&&x.paid_date?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
      revTrend.push({m:d.toLocaleDateString('en-GB',{month:'short',year:'2-digit'}),rev:Math.round(rev),cost:Math.round(cost),gp:Math.round(rev-cost)});
    }
    const maxRev=Math.max(...revTrend.map(r=>Math.max(r.rev,r.cost)),1);

    // ── NCR trend ────────────────────────────────────────────
    const ncrTrend=[];
    for(let i=5;i>=0;i--){
      const d=new Date(today.getFullYear(),today.getMonth()-i,1);
      const m=d.toISOString().slice(0,7);
      const month_ncrs=ncrs.filter(n=>n.created_at?.startsWith(m));
      ncrTrend.push({m:d.toLocaleDateString('en-GB',{month:'short'}),total:month_ncrs.length,critical:month_ncrs.filter(n=>n.severity==='critical').length});
    }

    // ── Predictive alerts ─────────────────────────────────────
    const alerts=[];
    eacData.filter(e=>e.costOverrun>0).forEach(e=>alerts.push({type:'cost',icon:'💰',msg:`${e.project_no}: Cost overrun of ${fmtKWD(e.costOverrun)} predicted (EAC > BAC)`,col:'#EF4444'}));
    eacData.filter(e=>e.cpi<0.85).forEach(e=>alerts.push({type:'cpi',icon:'📉',msg:`${e.project_no}: CPI ${e.cpi.toFixed(2)} — severe cost pressure`,col:'#EF4444'}));
    const overdueARCount=invs.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)&&i.due_date&&new Date(i.due_date)<today).length;
    if(overdueARCount>0) alerts.push({type:'ar',icon:'💳',msg:`${overdueARCount} AR invoice(s) overdue — cash flow risk`,col:'#F97316'});
    const expCerts=[] ; // would need cert data
    if(wfTrend[5]?.sla<80) alerts.push({type:'sla',icon:'⚡',msg:`Workflow SLA ${wfTrend[5].sla}% this month — below 80% threshold`,col:'#F97316'});

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🔬</span>
        <div><h1>Advanced Analytics</h1><div class="sub">Predictive Insights · Trend Analysis · Performance Intelligence</div></div>
      </div>
      <button class="btn btn-ghost btn-sm" data-h-click="h313">🔄 Refresh</button>
    </div>

    <!-- Predictive Alerts -->
    ${alerts.length>0?`
    <div class="card" style="margin-bottom:14px;border-left:3px solid #EF4444">
      <div class="sec-head"><div class="sec-title"><span>🚨</span>Predictive Alerts (${esc(alerts.length)})</div></div>
      ${alerts.slice(0,6).map(a=>`
      <div style="display:flex;align-items:center;gap:8px;padding:7px 0;border-bottom:1px solid var(--bdr)">
        <span style="font-size:16px;flex-shrink:0">${esc(a.icon)}</span>
        <div style="font-size:11px;color:var(--text);flex:1">${esc(a.msg)}</div>
        <span style="font-size:9px;background:${esc(a.col)}22;color:${esc(a.col)};border-radius:4px;padding:2px 7px;font-weight:700">ACTION</span>
      </div>`).join('')}
    </div>`:``}

    <div class="grid2" style="margin-bottom:14px">
      <!-- Revenue vs Cost Trend -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>📈</span>Revenue vs Cost — 6M Trend</div></div>
        <div style="display:flex;align-items:flex-end;gap:6px;height:100px;margin-bottom:8px">
          ${revTrend.map(r=>`
          <div style="flex:1;display:flex;flex-direction:column;gap:2px;align-items:center">
            <div style="width:100%;display:flex;gap:1px;align-items:flex-end;height:80px">
              <div style="flex:1;background:#10B98188;border-radius:2px 2px 0 0;height:${Math.max(r.rev/maxRev*80,2)}px" title="Revenue: ${fmtKWD(r.rev)}"></div>
              <div style="flex:1;background:#EF444488;border-radius:2px 2px 0 0;height:${Math.max(r.cost/maxRev*80,2)}px" title="Cost: ${fmtKWD(r.cost)}"></div>
            </div>
            <div style="font-size:8px;color:var(--faint)">${esc(r.m)}</div>
          </div>`).join('')}
        </div>
        <div style="display:flex;gap:12px;font-size:9px;color:var(--muted)">
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:8px;background:#10B981;border-radius:2px"></span>Revenue</span>
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:8px;background:#EF4444;border-radius:2px"></span>Cost</span>
        </div>
      </div>

      <!-- Workflow SLA Trend -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>⚡</span>Workflow SLA — 6M Trend</div></div>
        <div style="display:flex;align-items:flex-end;gap:6px;height:100px;margin-bottom:8px">
          ${wfTrend.map(w=>`
          <div style="flex:1;display:flex;flex-direction:column;gap:2px;align-items:center">
            <div style="font-size:8px;color:${w.sla>=80?'#10B981':'#EF4444'};font-weight:700">${esc(w.sla)}%</div>
            <div style="width:100%;background:${w.sla>=80?'#10B98188':'#EF444488'};border-radius:2px 2px 0 0;height:${Math.max(w.sla*0.7,2)}px"></div>
            <div style="font-size:8px;color:var(--faint)">${esc(w.m)}</div>
          </div>`).join('')}
        </div>
        <div style="font-size:10px;color:var(--muted)">Target: ≥80% | This month: <b style="color:${wfTrend[5]?.sla>=80?'#10B981':'#EF4444'}">${wfTrend[5]?.sla||0}%</b></div>
      </div>
    </div>

    <!-- Dept Performance -->
    <div class="card" style="margin-bottom:14px">
      <div class="sec-head"><div class="sec-title"><span>🏗</span>Department Performance (CPI)</div></div>
      <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:10px">
        ${deptPerf.map(d=>`
        <div style="background:var(--card2);border:1px solid ${d.avgCPI>=1?'#10B98133':d.avgCPI>=0.9?'#F9731633':'#EF444433'};border-radius:8px;padding:12px;text-align:center">
          <div style="font-size:10px;font-weight:700;color:var(--muted);margin-bottom:4px">${esc(d.dept)}</div>
          <div style="font-size:22px;font-weight:900;color:${d.avgCPI>=1?'#10B981':d.avgCPI>=0.9?'#F97316':'#EF4444'}">${d.avgCPI.toFixed(2)}</div>
          <div style="font-size:9px;color:var(--faint)">${esc(d.count)} projects · avg ${esc(d.avgPct)}% done</div>
        </div>`).join('')}
      </div>
    </div>

    <!-- EAC Prediction Table -->
    <div class="card">
      <div class="sec-head"><div class="sec-title"><span>🔮</span>EAC Prediction & Completion Forecast</div></div>
      ${eacData.length===0?'<div class="empty">No active projects</div>':`
      <div style="overflow-x:auto">
        <table><thead><tr>
          <th>Project</th><th style="text-align:right">BAC</th><th style="text-align:right">EAC</th>
          <th style="text-align:right">Cost Variance</th><th style="text-align:center">CPI</th>
          <th>Predicted End</th><th>Scheduled End</th><th style="text-align:center">Risk</th>
        </tr></thead><tbody>
        ${eacData.map(e=>`<tr>
          <td style="font-weight:600;font-size:11px">${esc(e.project_no)}</td>
          <td style="text-align:right">${fmtKWD(e.bac)}</td>
          <td style="text-align:right;color:${e.eac>e.bac?'#EF4444':'#10B981'};font-weight:700">${fmtKWD(e.eac)}</td>
          <td style="text-align:right;color:${e.costOverrun>0?'#EF4444':'#10B981'};font-weight:700">${e.costOverrun>0?'+':''} ${fmtKWD(Math.abs(e.costOverrun))}</td>
          <td style="text-align:center;font-weight:800;color:${e.cpi>=1?'#10B981':e.cpi>=0.9?'#F97316':'#EF4444'}">${e.cpi.toFixed(3)}</td>
          <td style="font-size:10px;color:${e.predictedEnd&&e.scheduledEnd&&e.predictedEnd>e.scheduledEnd?'#EF4444':'var(--muted)'}">${esc(e.predictedEnd||'N/A')}</td>
          <td style="font-size:10px;color:var(--faint)">${esc(e.scheduledEnd||'—')}</td>
          <td style="text-align:center">${pill(e.risk,e.risk==='on-track'?'#10B981':e.risk==='at-risk'?'#F97316':'#EF4444')}</td>
        </tr>`).join('')}
        </tbody></table>
      </div>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

