async function loadTender(tab='list'){
  const el=document.getElementById('page-tender');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Tenders…</div>';
  try{
    const today=new Date();
    const [tendR,projR]=await Promise.all([
      sb.from('tenders').select('*,project:projects(project_no,name)').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name').order('project_no')
    ]);
    const tends=tendR.data||[], projs=projR.data||[];
    const open=tends.filter(t=>t.status==='open');
    const closing=tends.filter(t=>t.status==='open'&&t.submission_deadline&&Math.ceil((new Date(t.submission_deadline)-today)/86400000)<=7);
    const awarded=tends.filter(t=>t.status==='awarded');
    const totalVal=awarded.reduce((s,t)=>s+Number(t.estimated_value||0),0);

    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='list'?' act':''}" data-h-click="h314">📋 All (${esc(tends.length)})</button>
      <button class="tab${tab==='open'?' act':''}" data-h-click="h315" style="color:${closing.length>0?'#EF4444':'inherit'}">🟢 Open (${esc(open.length)})</button>
      <button class="tab${tab==='awarded'?' act':''}" data-h-click="h316">✅ Awarded (${esc(awarded.length)})</button>
    </div>`;

    const list=tab==='open'?open:tab==='awarded'?awarded:tends;

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📋</span>
        <div><h1>Tender Management</h1><div class="sub">Pre-qualification · Submission · Evaluation · Award</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h317">+ New Tender</button>`:''}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Open Tenders',   open.length,   '#3B82F6', 'Accepting submissions')}
      ${kpi('Closing ≤7d',   closing.length, closing.length>0?'#EF4444':'#10B981', 'Urgent deadline')}
      ${kpi('Awarded',        awarded.length, '#10B981', 'Contracts won')}
      ${kpi('Award Value',    fmtKWD(totalVal),'#C9A84C', 'Total awarded')}
    </div>
    <div class="card">
      ${tabBtns}
      ${list.length===0?'<div class="empty">No tenders found</div>':`
      <table><thead><tr>
        <th>Tender No</th><th>Title</th><th>Client</th><th>Type</th>
        <th style="text-align:right">Est. Value</th><th>Deadline</th>
        <th style="text-align:center">Status</th><th></th>
      </tr></thead><tbody>
      ${list.map(t=>{
        const daysLeft=t.submission_deadline?Math.ceil((new Date(t.submission_deadline)-today)/86400000):null;
        const deadlineColor=daysLeft===null?'var(--faint)':daysLeft<0?'#EF4444':daysLeft<=7?'#F97316':'#10B981';
        return`<tr>
          <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(t.tender_no||'—')}</td>
          <td style="font-weight:600;font-size:11px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(t.title||'—')}</td>
          <td style="font-size:10px;color:var(--muted)">${esc(t.client_name||'—')}</td>
          <td><span style="font-size:9px;background:#8B5CF622;color:#8B5CF6;border-radius:4px;padding:2px 6px">${esc(t.tender_type||'—')}</span></td>
          <td style="text-align:right;font-weight:700">${fmtKWD(t.estimated_value||0)}</td>
          <td style="font-size:10px;color:${deadlineColor};font-weight:700">${esc(t.submission_deadline||'—')}${daysLeft!==null&&t.status==='open'?`<br><span style="font-size:9px">${daysLeft<0?'Closed':daysLeft+'d left'}</span>`:''}</td>
          <td style="text-align:center">${pill(t.status||'open',t.status==='open'?'#3B82F6':t.status==='awarded'?'#10B981':t.status==='submitted'?'#C9A84C':'#94A3B8')}</td>
          <td><button data-h-click="h318" data-ha-click="${esc(JSON.stringify([String((t.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px">👁</button></td>
        </tr>`;}).join('')}
      </tbody></table>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

function openNewTenderModal(){
  const today=new Date().toISOString().split('T')[0];
  openModal('+ New Tender',`
    <div class="form-row">
      <div class="form-field"><label>Tender Title *</label><input id="td-title" placeholder="e.g. CCTV System Supply & Installation"/></div>
      <div class="form-field"><label>Client *</label><input id="td-client" placeholder="Client / Issuer name"/></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Type</label>
        <select id="td-type" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          ${['Open','Selective','Negotiated','Direct Award','Framework'].map(t=>`<option>${t}</option>`).join('')}
        </select>
      </div>
      <div class="form-field"><label>Estimated Value (KWD)</label><input id="td-val" type="number" step="0.001" placeholder="0.000"/></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Issue Date</label><input id="td-issue" type="date" value="${today}"/></div>
      <div class="form-field"><label>Submission Deadline *</label><input id="td-deadline" type="date"/></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Bid Bond Required</label>
        <select id="td-bond" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="no">No</option><option value="yes">Yes</option>
        </select>
      </div>
      <div class="form-field"><label>Bond % of Value</label><input id="td-bond-pct" type="number" step="0.1" placeholder="2.5"/></div>
    </div>
    <div class="form-field"><label>Scope Summary</label>
      <textarea id="td-scope" rows="3" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text);resize:vertical"></textarea>
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h319">Create Tender</button>
    </div>`);
}

async function saveTender(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const title=document.getElementById('td-title').value.trim();
    const client=document.getElementById('td-client').value.trim();
    const deadline=document.getElementById('td-deadline').value;
    if(!title||!client||!deadline){showToast('Title, client and deadline required','error');return;}
    const no=await nextRefNo('TND');
    const {error}=await sb.from('tenders').insert({
      tender_no:no, title, client_name:client,
      tender_type:document.getElementById('td-type').value,
      estimated_value:Number(document.getElementById('td-val').value)||0,
      issue_date:document.getElementById('td-issue').value||null,
      submission_deadline:deadline,
      bid_bond_required:document.getElementById('td-bond').value==='yes',
      bid_bond_pct:Number(document.getElementById('td-bond-pct').value)||null,
      scope_summary:document.getElementById('td-scope').value.trim()||null,
      status:'open', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    await writeAudit('tenders',null,'TENDER_CREATED',null,{tender_no:no,title},'Tender created');
    showToast(no+' created ✓'); closeModal(); loadTender();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Create Tender';}}
}

async function openTenderDetail(id){
  const {data:t}=await sb.from('tenders').select('*').eq('id',id).single();
  if(!t) return;
  const today=new Date();
  const daysLeft=t.submission_deadline?Math.ceil((new Date(t.submission_deadline)-today)/86400000):null;
  openModal(`📋 ${t.tender_no} — ${t.title}`,`
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">
      ${[['Client',t.client_name||'—'],['Type',t.tender_type||'—'],
         ['Est. Value',fmtKWD(t.estimated_value||0)],['Status',pill(t.status,t.status==='open'?'#3B82F6':t.status==='awarded'?'#10B981':'#94A3B8')],
         ['Issue Date',t.issue_date||'—'],['Deadline',t.submission_deadline||'—'],
         ['Days Left',daysLeft!==null?(daysLeft<0?`<span style="color:#EF4444">Closed ${Math.abs(daysLeft)}d ago</span>`:daysLeft+'d'):'-'],
         ['Bid Bond',t.bid_bond_required?`Yes (${esc(t.bid_bond_pct||0)}%)`:'No']
      ].map(([l,v])=>`<div style="background:var(--n3);border-radius:6px;padding:8px">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase">${l}</div>
        <div style="font-size:12px;color:var(--text);margin-top:2px">${v}</div>
      </div>`).join('')}
    </div>
    ${t.scope_summary?`<div style="padding:8px;background:var(--n3);border-radius:6px;font-size:11px;color:var(--muted);margin-bottom:12px"><b>Scope:</b> ${esc(t.scope_summary)}</div>`:''}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      ${can('edit')&&t.status==='open'?`<button class="btn btn-primary" data-h-click="h320" data-ha-click="${esc(JSON.stringify([String((id)??''),String((t.tender_no)??'')]))}">✅ Mark Awarded</button>`:''}
    </div>`);
}

async function awardTender(id,tenderNo){
  if(!confirm(`Award tender ${tenderNo}?`)) return;
  await sb.from('tenders').update({status:'awarded',awarded_at:new Date().toISOString(),awarded_by:currentProfile?.id}).eq('id',id);
  await writeAudit('tenders',id,'TENDER_AWARDED',{status:'open'},{status:'awarded'},'Tender awarded');
  showToast(tenderNo+' awarded ✓'); loadTender();
}

