async function loadInsurance(tab='policies'){
  const el=document.getElementById('page-insurance');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Insurance…</div>';
  try{
    const today=new Date();
    const [polR,bondR,projR]=await Promise.all([
      sb.from('insurance_policies').select('*,project:projects(project_no,name)').order('expiry_date'),
      sb.from('performance_bonds').select('*,project:projects(project_no,name)').order('expiry_date'),
      sb.from('projects').select('id,project_no,name').in('status',ACTIVE_STATUSES).order('project_no')
    ]);
    const pols=polR.data||[], bonds=bondR.data||[], projs=projR.data||[];

    const expPols=pols.filter(p=>p.expiry_date&&Math.ceil((new Date(p.expiry_date)-today)/86400000)<=30&&new Date(p.expiry_date)>=today);
    const expBonds=bonds.filter(b=>b.expiry_date&&Math.ceil((new Date(b.expiry_date)-today)/86400000)<=30&&new Date(b.expiry_date)>=today);
    const expiredPols=pols.filter(p=>p.expiry_date&&new Date(p.expiry_date)<today&&p.status==='active');
    const totalCoverage=pols.filter(p=>p.status==='active').reduce((s,p)=>s+Number(p.insured_value||0),0);

    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='policies'?' act':''}" data-h-click="h321">🛡 Policies (${esc(pols.length)})</button>
      <button class="tab${tab==='bonds'?' act':''}" data-h-click="h322">📜 Bonds (${esc(bonds.length)})</button>
    </div>`;

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🛡</span>
        <div><h1>Insurance & Bonds</h1><div class="sub">Policies · Performance Bonds · Guarantees · Expiry Tracking</div></div>
      </div>
      ${can('create')?`<div style="display:flex;gap:8px">
        <button class="btn btn-ghost btn-sm" data-h-click="h323">+ Policy</button>
        <button class="btn btn-primary btn-sm" data-h-click="h324">+ Bond</button>
      </div>`:''}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Active Policies', pols.filter(p=>p.status==='active').length, '#C9A84C', 'Insurance coverage')}
      ${kpi('Total Coverage', fmtKWD(totalCoverage), '#3B82F6', 'Insured value')}
      ${kpi('Expiring ≤30d', expPols.length+expBonds.length, expPols.length+expBonds.length>0?'#F97316':'#10B981', 'Policies + Bonds')}
      ${kpi('Expired Active', expiredPols.length, expiredPols.length>0?'#EF4444':'#10B981', 'Require renewal')}
    </div>
    ${expPols.length+expBonds.length+expiredPols.length>0?`
    <div class="card" style="margin-bottom:14px;border-left:3px solid #F97316">
      <div class="sec-head"><div class="sec-title"><span>⚠️</span>Expiry Alerts</div></div>
      ${[...expiredPols.map(p=>({...p,_type:'policy',_expired:true})),...expPols.map(p=>({...p,_type:'policy',_expired:false})),...expBonds.map(b=>({...b,_type:'bond',_expired:false}))].map(item=>{
        const daysLeft=item.expiry_date?Math.ceil((new Date(item.expiry_date)-today)/86400000):null;
        return`<div style="display:flex;align-items:center;gap:8px;padding:6px 0;border-bottom:1px solid var(--bdr)">
          <span style="font-size:14px">${item._expired?'🔴':'🟡'}</span>
          <div style="flex:1">
            <div style="font-size:11px;font-weight:700">${esc(item.policy_no||item.bond_no||'—')} — ${esc(item.policy_type||item.bond_type||'—')}</div>
            <div style="font-size:9px;color:var(--muted)">${esc(item.insurer||item.bank_name||'—')} · ${esc(item.project?.project_no||'General')}</div>
          </div>
          <div style="text-align:right;font-size:10px;color:${item._expired?'#EF4444':'#F97316'};font-weight:700">
            ${item._expired?'EXPIRED':daysLeft+'d left'}
          </div>
        </div>`;}).join('')}
    </div>`:''}
    <div class="card">
      ${tabBtns}
      ${tab==='policies'?
        (pols.length===0?'<div class="empty">No insurance policies registered</div>':`
        <table><thead><tr>
          <th>Policy No</th><th>Type</th><th>Insurer</th><th>Project</th>
          <th style="text-align:right">Premium</th><th style="text-align:right">Insured Value</th>
          <th>Expiry</th><th style="text-align:center">Status</th>
        </tr></thead><tbody>
        ${pols.map(p=>{
          const daysLeft=p.expiry_date?Math.ceil((new Date(p.expiry_date)-today)/86400000):null;
          const col=daysLeft===null?'var(--faint)':daysLeft<0?'#EF4444':daysLeft<=30?'#F97316':'var(--muted)';
          return`<tr>
            <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(p.policy_no||'—')}</td>
            <td style="font-size:11px">${esc(p.policy_type||'—')}</td>
            <td style="color:var(--muted)">${esc(p.insurer||'—')}</td>
            <td style="font-size:10px;color:var(--gold)">${esc(p.project?.project_no||'General')}</td>
            <td style="text-align:right">${fmtKWD(p.annual_premium||0)}</td>
            <td style="text-align:right;font-weight:700">${fmtKWD(p.insured_value||0)}</td>
            <td style="color:${col};font-weight:700;font-size:10px">${esc(p.expiry_date||'—')}${daysLeft!==null&&daysLeft<=30?` (${daysLeft<0?'expired':daysLeft+'d'})`:''}</td>
            <td style="text-align:center">${pill(p.status||'active',p.status==='active'?'#10B981':'#94A3B8')}</td>
          </tr>`;}).join('')}
        </tbody></table>`)
        :
        (bonds.length===0?'<div class="empty">No bonds registered</div>':`
        <table><thead><tr>
          <th>Bond No</th><th>Type</th><th>Bank</th><th>Project</th>
          <th style="text-align:right">Amount</th><th>Issue Date</th><th>Expiry</th>
          <th style="text-align:center">Status</th>
        </tr></thead><tbody>
        ${bonds.map(b=>{
          const daysLeft=b.expiry_date?Math.ceil((new Date(b.expiry_date)-today)/86400000):null;
          const col=daysLeft===null?'var(--faint)':daysLeft<0?'#EF4444':daysLeft<=30?'#F97316':'var(--muted)';
          return`<tr>
            <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(b.bond_no||'—')}</td>
            <td style="font-size:11px">${esc(b.bond_type||'—')}</td>
            <td style="color:var(--muted)">${esc(b.bank_name||'—')}</td>
            <td style="font-size:10px;color:var(--gold)">${esc(b.project?.project_no||'General')}</td>
            <td style="text-align:right;font-weight:700">${fmtKWD(b.bond_amount||0)}</td>
            <td style="font-size:10px;color:var(--faint)">${esc(b.issue_date||'—')}</td>
            <td style="color:${col};font-weight:700;font-size:10px">${esc(b.expiry_date||'—')}${daysLeft!==null&&daysLeft<=30?` (${daysLeft<0?'expired':daysLeft+'d'})`:''}</td>
            <td style="text-align:center">${pill(b.status||'active',b.status==='active'?'#10B981':'#94A3B8')}</td>
          </tr>`;}).join('')}
        </tbody></table>`)}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

