async function savePolicy(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const polNo=document.getElementById('pol-no').value.trim();
    const insurer=document.getElementById('pol-insurer').value.trim();
    const expiry=document.getElementById('pol-exp').value;
    if(!polNo||!insurer||!expiry){showToast('Policy No, insurer and expiry required','error');return;}
    const {error}=await sb.from('insurance_policies').insert({
      policy_no:polNo, policy_type:document.getElementById('pol-type').value,
      insurer, project_id:document.getElementById('pol-proj').value||null,
      insured_value:Number(document.getElementById('pol-val').value)||0,
      annual_premium:Number(document.getElementById('pol-prem').value)||0,
      start_date:document.getElementById('pol-start').value||null,
      expiry_date:expiry, status:'active', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Policy saved ✓'); closeModal(); loadInsurance();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save Policy';}}
}

