const b3GetKPI=d=>B3_DKPI[d]||B3_DKPI['Default'];

const B3_BANDS=[
  {min:4.5,lbl:'Outstanding',clr:'#10B981'},
  {min:3.5,lbl:'Exceeds Expectations',clr:'#3B82F6'},
  {min:2.5,lbl:'Meets Expectations',clr:'#C9A84C'},
  {min:1.5,lbl:'Needs Improvement',clr:'#F97316'},
  {min:0,  lbl:'Unsatisfactory',clr:'#EF4444'}];
const b3Band=s=>B3_BANDS.find(b=>s>=b.min)||B3_BANDS[4];
const b3Clr=s=>b3Band(s).clr;
const b3Lbl=s=>b3Band(s).lbl;
