const b3FmtD=d=>d?new Date(d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—';

// B3 tab state
let b3Tab='dashboard';
window._b3Kpis=[];
window._b3Scores={};

// ── MAIN ENTRY POINT ─────────────────────────────────────
async function loadAppraisalB3(tab='dashboard'){
  const el=document.getElementById('page-appraisal');
  if(!el)return;
  b3Tab=tab;
  const tabs=[
    {id:'dashboard',icon:'📊',lbl:'Dashboard'},
    {id:'list',icon:'📋',lbl:'All Appraisals'},
    {id:'new',icon:'➕',lbl:'New Appraisal'},
    {id:'dept',icon:'🏢',lbl:'By Department'},
    {id:'calib',icon:'⚖️',lbl:'Calibration'},
    {id:'trends',icon:'📈',lbl:'Trends'},
    {id:'kpicfg',icon:'⚙️',lbl:'KPI Framework'}];

  el.innerHTML=`
  <div style="margin-bottom:16px">
    <div style="display:flex;align-items:center;gap:10px;margin-bottom:14px">
      <span style="font-size:22px">⭐</span>
      <div><h1 style="font-size:17px;font-weight:800">Performance Scorecard · B3</h1><div style="color:var(--faint);font-size:10px">Department KPI Framework · Weighted Scoring · Calibration</div></div>
    </div>
    <div style="display:flex;gap:4px;flex-wrap:wrap;border-bottom:1px solid var(--bdr);padding-bottom:10px;margin-bottom:16px">
      ${tabs.map(t=>`<button data-h-click="h333" data-ha-click="${esc(JSON.stringify([String((t.id)??'')]))}" style="background:${tab===t.id?'#C9A84C18':'none'};border:1px solid ${tab===t.id?'var(--gold)':'var(--bdr)'};border-radius:6px;padding:5px 12px;font-size:11px;color:${tab===t.id?'var(--gold)':'var(--muted)'};cursor:pointer;font-weight:${tab===t.id?'700':'400'};font-family:inherit">${esc(t.icon)} ${esc(t.lbl)}</button>`).join('')}
    </div>
    <div id="b3-content"><div class="loading">Loading…</div></div>
  </div>`;

  const loaders={dashboard:b3Dashboard,list:b3List,new:b3NewPage,dept:b3DeptAnalysis,calib:b3Calibration,trends:b3Trends,kpicfg:b3KPIConfig};
  if(loaders[tab])loaders[tab]();
}

// ── DASHBOARD ─────────────────────────────────────────────
async function b3Dashboard(){
  const c=document.getElementById('b3-content');
  c.innerHTML='<div class="loading">Loading dashboard…</div>';
  try{
    const[aR,eR]=await Promise.all([
      sb.from('performance_appraisals').select('*,employee:employees(full_name,employee_no,department,position)').order('appraisal_date',{ascending:false}),
      sb.from('employees').select('id,full_name,employee_no,department,status').eq('status','active')
    ]);
    const apps=aR.data||[],emps=eR.data||[];
    const yr=new Date().getFullYear();
    const yrApps=apps.filter(a=>a.appraisal_date?.startsWith(yr));
    const avg=apps.length?apps.reduce((s,a)=>s+Number(a.overall_score||0),0)/apps.length:0;
    const top=apps.filter(a=>Number(a.overall_score||0)>=4).length;
    const pend=emps.filter(e=>!apps.find(a=>a.employee_id===e.id&&a.appraisal_date?.startsWith(yr))).length;
    const depts=[...new Set(emps.map(e=>e.department).filter(Boolean))].sort();

    const dRows=depts.map(d=>{
      const da=yrApps.filter(a=>a.employee?.department===d);
      const de=emps.filter(e=>e.department===d);
      const av=da.length?da.reduce((s,a)=>s+Number(a.overall_score||0),0)/da.length:0;
      const cov=de.length?Math.round(da.length/de.length*100):0;
      const cc=cov>=80?'#10B981':cov>=50?'#C9A84C':'#EF4444';
      return`<tr>
        <td>${b3DeptBadge(d)}</td><td style="text-align:center">${esc(de.length)}</td><td style="text-align:center">${esc(da.length)}</td>
        <td><div style="display:flex;align-items:center;gap:6px">${b3Bar(cov,cc)}<span style="font-size:10px;color:${cc};font-weight:700;min-width:28px">${cov}%</span></div></td>
        <td style="text-align:center">${av>0?`<span style="font-weight:800;color:${b3Clr(av)}">${av.toFixed(2)}</span><div style="font-size:9px;color:${b3Clr(av)}">${b3Lbl(av)}</div>`:'<span style="color:var(--faint)">—</span>'}</td>
      </tr>`;
    }).join('');

    const rRows=apps.slice(0,8).map(a=>{
      const sc=Number(a.overall_score||0);
      return`<tr>
        <td style="font-weight:700">${esc(a.employee?.full_name||'—')}</td>
        <td>${b3DeptBadge(a.employee?.department)}</td>
        <td style="font-size:10px;color:var(--muted)">${esc(a.appraisal_period||'—')}</td>
        <td style="text-align:center"><span style="font-size:15px;font-weight:900;color:${b3Clr(sc)}">${sc>0?sc.toFixed(1):'—'}</span></td>
        <td>${b3Pill(b3Lbl(sc),b3Clr(sc))}</td>
        <td><button data-h-click="h334" data-ha-click="${esc(JSON.stringify([String((a.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px">👁</button></td>
      </tr>`;
    }).join('');

    c.innerHTML=`
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:14px">
      ${kpi('Total',apps.length,'#C9A84C','All time')}
      ${kpi('This Year ('+yr+')',yrApps.length,'#3B82F6',emps.length+' active employees')}
      ${kpi('Avg Score',avg>0?avg.toFixed(2):'—',avg>=3.5?'#10B981':avg>=2.5?'#C9A84C':'#EF4444',avg>0?b3Lbl(avg):'No data')}
      ${kpi('Pending '+yr,pend,pend>0?'#F97316':'#10B981',top+' top performers ≥4.0')}
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
      <div class="card"><div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:12px">Department Coverage · ${yr}</div>
        <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">
          <thead><tr><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Dept</th><th style="text-align:center;padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Staff</th><th style="text-align:center;padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Done</th><th style="padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Coverage</th><th style="text-align:center;padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Avg Score</th></tr></thead>
          <tbody>${dRows||'<tr><td colspan="5" style="text-align:center;padding:16px;color:var(--faint);font-size:11px">No data</td></tr>'}</tbody>
        </table></div>
      </div>
      <div class="card">
        <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px">
          <span style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px">Recent Appraisals</span>
          <button data-h-click="h335" style="background:none;border:1px solid var(--bdr);border-radius:6px;padding:3px 8px;font-size:10px;color:var(--muted);cursor:pointer;font-family:inherit">View All</button>
        </div>
        <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">
          <thead><tr><th style="text-align:left;padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Employee</th><th style="padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Dept</th><th style="padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Period</th><th style="text-align:center;padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Score</th><th style="padding:6px 8px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;border-bottom:1px solid var(--bdr)">Rating</th><th style="padding:6px 8px;border-bottom:1px solid var(--bdr)"></th></tr></thead>
          <tbody>${rRows||'<tr><td colspan="6" style="text-align:center;padding:16px;color:var(--faint);font-size:11px">No appraisals yet</td></tr>'}</tbody>
        </table></div>
      </div>
    </div>`;
  }catch(err){c.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;}
}

// ── LIST ──────────────────────────────────────────────────
async function b3List(filter='all'){
  const c=document.getElementById('b3-content');
  c.innerHTML='<div class="loading">Loading…</div>';
  try{
    const{data:apps}=await sb.from('performance_appraisals').select('*,employee:employees(full_name,employee_no,department,position)').order('appraisal_date',{ascending:false});
    const all=apps||[];
    const depts=[...new Set(all.map(a=>a.employee?.department).filter(Boolean))].sort();
    const periods=[...new Set(all.map(a=>a.appraisal_period).filter(Boolean))].sort().reverse();
    const filt=filter==='all'?all:all.filter(a=>a.employee?.department===filter||a.appraisal_period===filter);

    const rows=filt.map(a=>{
      const sc=Number(a.overall_score||0);
      return`<tr style="border-bottom:1px solid #0F2444">
        <td style="padding:8px 10px;font-weight:700">${esc(a.employee?.full_name||'—')}</td>
        <td style="padding:8px 10px;font-size:10px;color:var(--faint)">${esc(a.employee?.employee_no||'—')}</td>
        <td style="padding:8px 10px">${b3DeptBadge(a.employee?.department)}</td>
        <td style="padding:8px 10px;font-size:10px;color:var(--muted)">${esc(a.appraisal_period||'—')}</td>
        <td style="padding:8px 10px;font-size:10px;color:var(--faint)">${b3FmtD(a.appraisal_date)}</td>
        <td style="padding:8px 10px;text-align:center"><span style="font-size:16px;font-weight:900;color:${b3Clr(sc)}">${sc>0?sc.toFixed(1):'—'}</span></td>
        <td style="padding:8px 10px">${b3Pill(b3Lbl(sc),b3Clr(sc))}</td>
        <td style="padding:8px 10px">${b3Pill(a.status||'draft',a.status==='completed'?'#10B981':'#94A3B8')}</td>
        <td style="padding:8px 10px">
          <button data-h-click="h334" data-ha-click="${esc(JSON.stringify([String((a.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px">👁</button>
          <button data-h-click="h336" data-ha-click="${esc(JSON.stringify([String((a.id)??'')]))}" style="background:none;border:none;color:var(--faint);cursor:pointer;font-size:11px;margin-left:4px">🗑</button>
        </td>
      </tr>`;
    }).join('');

    const thStyle='text-align:left;padding:7px 10px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid var(--bdr);white-space:nowrap';

    c.innerHTML=`
    <div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:8px">
      <button data-h-click="h338" style="background:${filter==='all'?'#C9A84C18':'none'};border:1px solid ${filter==='all'?'var(--gold)':'var(--bdr)'};border-radius:6px;padding:5px 12px;font-size:11px;color:${filter==='all'?'var(--gold)':'var(--muted)'};cursor:pointer;font-family:inherit;font-weight:${filter==='all'?700:400}">All (${esc(all.length)})</button>
      ${depts.map(d=>`<button data-h-click="h337" data-ha-click="${esc(JSON.stringify([String((d)??'')]))}" style="background:${filter===d?'#C9A84C18':'none'};border:1px solid ${filter===d?'var(--gold)':'var(--bdr)'};border-radius:6px;padding:5px 12px;font-size:11px;color:${filter===d?'var(--gold)':'var(--muted)'};cursor:pointer;font-family:inherit;font-weight:${filter===d?700:400}">${esc(d)}</button>`).join('')}
    </div>
    <div style="display:flex;gap:4px;flex-wrap:wrap;margin-bottom:12px">
      ${periods.slice(0,6).map(p=>`<button data-h-click="h337" data-ha-click="${esc(JSON.stringify([String((p)??'')]))}" style="background:${filter===p?'#C9A84C18':'none'};border:1px solid ${filter===p?'var(--gold)':'var(--bdr)'};border-radius:6px;padding:5px 12px;font-size:11px;color:${filter===p?'var(--gold)':'var(--muted)'};cursor:pointer;font-family:inherit;font-weight:${filter===p?700:400}">${esc(p)}</button>`).join('')}
    </div>
    <div class="card" style="padding:0;overflow:hidden">
      <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">
        <thead><tr>
          <th style="${thStyle}">Name</th><th style="${thStyle}">Emp No</th><th style="${thStyle}">Dept</th>
          <th style="${thStyle}">Period</th><th style="${thStyle}">Date</th>
          <th style="${thStyle};text-align:center">Score</th><th style="${thStyle}">Rating</th>
          <th style="${thStyle}">Status</th><th style="${thStyle}"></th>
        </tr></thead>
        <tbody>${rows||'<tr><td colspan="9" style="text-align:center;padding:20px;color:var(--faint);font-size:11px">No records found</td></tr>'}</tbody>
      </table></div>
    </div>`;
  }catch(err){c.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;}
}

async function b3DelApp(id){
  if(!confirm('Delete this appraisal?'))return;
  const{error}=await sb.from('performance_appraisals').delete().eq('id',id);
  if(error){showToast('Error: '+error.message,'error');return;}
  showToast('Deleted ✓');b3List();
}

async function b3ViewApp(id){
  const{data:a}=await sb.from('performance_appraisals').select('*,employee:employees(full_name,employee_no,department,position)').eq('id',id).single();
  if(!a)return;
  const sc=Number(a.overall_score||0);const band=b3Band(sc);
  let kpiHtml='';
  try{
    const n=JSON.parse(a.notes||'{}');
    if(n.kpiDef&&n.kpiScores){
      kpiHtml=`<div style="font-size:9px;font-weight:700;color:var(--gold);margin-bottom:8px;text-transform:uppercase;letter-spacing:.4px">KPI Breakdown</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">
        ${n.kpiDef.map(k=>{const s=n.kpiScores[k.id];if(!s)return'';const col=b3Clr(s);return`<div style="background:var(--card);border:1px solid var(--bdr);border-radius:6px;padding:8px"><div style="font-size:9px;color:var(--muted);margin-bottom:4px">${esc(k.name)}<span style="float:right">×${esc(k.w)}%</span></div><div style="font-size:20px;font-weight:900;color:${col}">${s}</div><div style="height:5px;border-radius:3px;background:#1A3660;overflow:hidden;margin-top:4px"><div style="height:100%;width:${s/5*100}%;background:${col}"></div></div></div>`;}).join('')}
      </div>`;
    }else{
      const std=[['Quality',a.quality_score],['Delivery',a.delivery_score],['Initiative',a.initiative_score],['Teamwork',a.teamwork_score],['Safety',a.safety_score],['Leadership',a.leadership_score]].filter(([,v])=>v!=null);
      if(std.length)kpiHtml=`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-bottom:12px">${std.map(([l,v])=>`<div style="background:var(--n3);border-radius:6px;padding:8px;text-align:center"><div style="font-size:9px;color:var(--muted)">${l}</div><div style="font-size:18px;font-weight:800;color:${b3Clr(Number(v||0))}">${v}</div></div>`).join('')}</div>`;
    }
  }catch(e){}
  openModal(`⭐ ${a.employee?.full_name||'—'} — Appraisal`,`
    <div style="display:flex;gap:14px;align-items:center;padding:12px;background:var(--card);border-radius:8px;margin-bottom:14px;border:1px solid var(--bdr)">
      <div style="text-align:center;flex-shrink:0">
        <div style="font-size:40px;font-weight:900;color:${esc(band.clr)}">${sc>0?sc.toFixed(2):'—'}</div>
        <div style="font-size:9px;font-weight:700;color:${esc(band.clr)}">${esc(band.lbl)}</div>
        <div style="height:6px;border-radius:3px;background:#1A3660;overflow:hidden;width:80px;margin-top:6px"><div style="height:100%;width:${sc/5*100}%;background:${esc(band.clr)}"></div></div>
      </div>
      <div>
        <div style="font-size:13px;font-weight:800">${esc(a.employee?.full_name||'—')}</div>
        <div style="font-size:10px;color:var(--muted)">${esc(a.employee?.employee_no||'')} · ${esc(a.employee?.department||'')} · ${esc(a.employee?.position||'')}</div>
        <div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap">${b3Pill(a.appraisal_period||'—','#94A3B8')} ${b3Pill(a.status||'draft',a.status==='completed'?'#10B981':'#94A3B8')}</div>
        <div style="font-size:10px;color:var(--faint);margin-top:4px">${b3FmtD(a.appraisal_date)}</div>
      </div>
    </div>
    ${kpiHtml}
    ${a.strengths?`<div style="padding:10px;background:var(--card);border-radius:7px;margin-bottom:8px;border-left:3px solid #10B981"><div style="font-size:9px;font-weight:700;color:#10B981;margin-bottom:4px">KEY ACHIEVEMENTS</div><div style="font-size:11px">${esc(a.strengths)}</div></div>`:''}
    ${a.improvements?`<div style="padding:10px;background:var(--card);border-radius:7px;margin-bottom:8px;border-left:3px solid #F97316"><div style="font-size:9px;font-weight:700;color:#F97316;margin-bottom:4px">AREAS FOR IMPROVEMENT</div><div style="font-size:11px">${esc(a.improvements)}</div></div>`:''}
    ${a.development_plan?`<div style="padding:10px;background:var(--card);border-radius:7px;border-left:3px solid #3B82F6"><div style="font-size:9px;font-weight:700;color:#3B82F6;margin-bottom:4px">DEVELOPMENT PLAN</div><div style="font-size:11px">${esc(a.development_plan)}</div></div>`:''}
  `);
}

// ── NEW APPRAISAL ────────────────────────────────────────
async function b3NewPage(){
  const c=document.getElementById('b3-content');
  c.innerHTML='<div class="loading">Loading…</div>';
  try{
    const{data:emps}=await sb.from('employees').select('id,full_name,employee_no,department,position').eq('status','active').order('full_name');
    window._b3Emps=emps||[];
    const yr=new Date().getFullYear();
    const periods=[`Annual ${yr}`,`H1 ${yr}`,`H2 ${yr}`,`Q1 ${yr}`,`Q2 ${yr}`,`Q3 ${yr}`,`Q4 ${yr}`];
    c.innerHTML=`
    <div class="card">
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
        <div>
          <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Employee *</label>
          <select id="b3-emp" data-h-change="h339" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--text);font-size:12px;font-family:inherit;outline:none">
            <option value="">— Select Employee —</option>
            ${(emps||[]).map(e=>`<option value="${esc(e.id)}" data-dept="${esc(e.department||'')}">${esc(e.full_name)} (${esc(e.employee_no||'')})</option>`).join('')}
          </select>
        </div>
        <div>
          <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Appraisal Period *</label>
          <select id="b3-period" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--text);font-size:12px;font-family:inherit;outline:none">
            ${periods.map(p=>`<option>${p}</option>`).join('')}
          </select>
        </div>
      </div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
        <div>
          <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Assessment Type</label>
          <select id="b3-type" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--text);font-size:12px;font-family:inherit;outline:none">
            <option value="manager">Manager Assessment</option>
            <option value="self">Self Assessment</option>
            <option value="360">360° Assessment</option>
          </select>
        </div>
        <div>
          <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Department Detected</label>
          <div id="b3-dept-disp" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--faint);font-size:12px">Select employee above</div>
        </div>
      </div>
      <div id="b3-kpi-section"><div style="text-align:center;padding:20px;color:var(--faint);font-size:12px">Select an employee to load department-specific KPIs</div></div>
      <div id="b3-qual-section" style="display:none">
        <div style="height:1px;background:var(--bdr);margin:14px 0"></div>
        <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
          <div>
            <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Key Achievements</label>
            <textarea id="b3-str" rows="3" placeholder="What did this employee achieve?" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--text);font-size:12px;font-family:inherit;outline:none;resize:vertical"></textarea>
          </div>
          <div>
            <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Areas for Improvement</label>
            <textarea id="b3-imp" rows="3" placeholder="Where can they improve?" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--text);font-size:12px;font-family:inherit;outline:none;resize:vertical"></textarea>
          </div>
        </div>
        <div style="margin-bottom:10px">
          <label style="display:block;color:var(--muted);font-size:10px;font-weight:700;text-transform:uppercase;letter-spacing:.4px;margin-bottom:5px">Development Plan</label>
          <textarea id="b3-plan" rows="2" placeholder="Training, mentoring, next steps…" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:9px 11px;color:var(--text);font-size:12px;font-family:inherit;outline:none;resize:vertical"></textarea>
        </div>
        <div id="b3-prev" style="background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:12px;margin-bottom:12px;display:none">
          <div style="display:flex;align-items:center;gap:14px">
            <div style="text-align:center">
              <div id="b3-big" style="font-size:36px;font-weight:900"></div>
              <div id="b3-lbl" style="font-size:9px;font-weight:700"></div>
            </div>
            <div style="flex:1">
              <div id="b3-bar-wrap" style="height:10px;border-radius:5px;background:#1A3660;overflow:hidden;margin-bottom:6px"><div id="b3-bar" style="height:100%;border-radius:5px;transition:width .3s"></div></div>
              <div id="b3-bkdn" style="font-size:10px;color:var(--muted)"></div>
            </div>
          </div>
        </div>
        <div style="display:flex;gap:10px;justify-content:flex-end">
          <button class="btn btn-ghost" data-h-click="h340">Clear</button>
          <button class="btn btn-primary" data-h-click="h341">Save Appraisal</button>
        </div>
      </div>
    </div>`;
  }catch(err){c.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;}
}

function b3OnEmp(){
  const sel=document.getElementById('b3-emp');
  const opt=sel.options[sel.selectedIndex];
  const dept=opt?opt.dataset.dept:'';
  const dd=document.getElementById('b3-dept-disp');
  if(!sel.value){
    dd.textContent='Select employee above';dd.style.color='var(--faint)';
    document.getElementById('b3-kpi-section').innerHTML='<div style="text-align:center;padding:20px;color:var(--faint);font-size:12px">Select an employee to load department-specific KPIs</div>';
    document.getElementById('b3-qual-section').style.display='none';return;
  }
  dd.textContent=dept||'Unknown';dd.style.color='var(--gold)';
  window._b3Kpis=b3GetKPI(dept);window._b3Scores={};
  b3RenderKPIs(window._b3Kpis);
  document.getElementById('b3-qual-section').style.display='block';
  b3UpdPrev();
}

function b3RenderKPIs(kpis){
  const sec=document.getElementById('b3-kpi-section');
  sec.innerHTML=`<div style="font-size:11px;font-weight:700;color:var(--gold);margin:4px 0 10px">Department KPIs — Star Rating 1 (Poor) → 5 (Outstanding)</div>
  <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:4px">
    ${kpis.map(k=>`<div style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:10px" id="b3kc-${esc(k.id)}">
      <div style="font-size:10px;font-weight:700;color:var(--muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:.4px">${esc(k.name)}<span style="float:right;font-size:9px;color:var(--faint)">×${esc(k.w)}%</span></div>
      <div style="display:flex;align-items:center;gap:4px">
        ${[1,2,3,4,5].map(n=>`<button data-h-click="h342" data-ha-click="${esc(JSON.stringify([String((k.id)??''),n]))}" id="b3s-${esc(k.id)}-${n}" style="background:none;border:none;cursor:pointer;font-size:20px;line-height:1;padding:0;transition:transform .1s" title="${n}">☆</button>`).join('')}
        <span id="b3sv-${esc(k.id)}" style="font-size:12px;font-weight:800;color:var(--gold);margin-left:4px;min-width:16px">—</span>
      </div>
    </div>`).join('')}
  </div>`;
}

function b3SetStar(kid,val){
  window._b3Scores[kid]=val;
  for(let i=1;i<=5;i++){const b=document.getElementById(`b3s-${kid}-${i}`);if(b)b.textContent=i<=val?'★':'☆';}
  const sv=document.getElementById(`b3sv-${kid}`);if(sv){sv.textContent=val;sv.style.color=b3Clr(val);}
  b3UpdPrev();
}

function b3UpdPrev(){
  const kpis=window._b3Kpis,sc=window._b3Scores;
  const filled=kpis.filter(k=>sc[k.id]!==undefined);
  if(!filled.length){document.getElementById('b3-prev').style.display='none';return;}
  const tw=filled.reduce((s,k)=>s+k.w,0);
  const avg=filled.reduce((s,k)=>s+sc[k.id]*k.w,0)/tw;
  const band=b3Band(avg);
  document.getElementById('b3-prev').style.display='block';
  document.getElementById('b3-big').textContent=avg.toFixed(2);document.getElementById('b3-big').style.color=band.clr;
  document.getElementById('b3-lbl').textContent=band.lbl;document.getElementById('b3-lbl').style.color=band.clr;
  const bar=document.getElementById('b3-bar');bar.style.width=avg/5*100+'%';bar.style.background=band.clr;
  document.getElementById('b3-bkdn').innerHTML=filled.map(k=>`${esc(k.name)}: <b style="color:${b3Clr(sc[k.id])}">${sc[k.id]}</b>`).join(' · ');
}

function b3ResetNew(){const sel=document.getElementById('b3-emp');if(sel){sel.value='';b3OnEmp();}}

async function b3SaveNew(){
  const empId=document.getElementById('b3-emp')?.value;
  if(!empId){showToast('Select an employee first','error');return;}
  const kpis=window._b3Kpis,sc=window._b3Scores;
  const filled=kpis.filter(k=>sc[k.id]!==undefined);
  if(filled.length<Math.ceil(kpis.length/2)){showToast('Score at least half the KPIs','error');return;}
  const tw=filled.reduce((s,k)=>s+k.w,0);
  const overall=filled.reduce((s,k)=>s+sc[k.id]*k.w,0)/tw;
  const kpiScores={};kpis.forEach(k=>{if(sc[k.id])kpiScores[k.id]=sc[k.id];});
  const row={
    employee_id:empId,
    appraisal_period:document.getElementById('b3-period')?.value,
    appraisal_date:new Date().toISOString().split('T')[0],
    overall_score:Math.round(overall*100)/100,
    strengths:document.getElementById('b3-str')?.value.trim()||null,
    improvements:document.getElementById('b3-imp')?.value.trim()||null,
    development_plan:document.getElementById('b3-plan')?.value.trim()||null,
    status:'completed',
    appraiser_id:currentProfile?.id||null,
    created_by:currentProfile?.id||null,
    notes:JSON.stringify({type:document.getElementById('b3-type')?.value||'manager',kpiScores,kpiDef:kpis.map(k=>({id:k.id,name:k.name,w:k.w}))})
  };
  if(kpis[0])row.quality_score=sc[kpis[0].id]||null;
  if(kpis[1])row.delivery_score=sc[kpis[1].id]||null;
  if(kpis[2])row.initiative_score=sc[kpis[2].id]||null;
  if(kpis[3])row.teamwork_score=sc[kpis[3].id]||null;
  if(kpis[4])row.safety_score=sc[kpis[4].id]||null;
  if(kpis[5])row.leadership_score=sc[kpis[5].id]||null;
  const{error}=await sb.from('performance_appraisals').insert(row);
  if(error){showToast('Error: '+error.message,'error');return;}
  showToast('Appraisal saved ✓');b3ResetNew();loadAppraisalB3('list');
}

// ── DEPT ANALYSIS ─────────────────────────────────────────
async function b3DeptAnalysis(){
  const c=document.getElementById('b3-content');
  c.innerHTML='<div class="loading">Loading…</div>';
  try{
    const[aR,eR]=await Promise.all([
      sb.from('performance_appraisals').select('*,employee:employees(full_name,department)').order('appraisal_date',{ascending:false}),
      sb.from('employees').select('id,department,status').eq('status','active')
    ]);
    const apps=aR.data||[],emps=eR.data||[];
    const depts=[...new Set(emps.map(e=>e.department).filter(Boolean))].sort();
    const cards=depts.map(d=>{
      const da=apps.filter(a=>a.employee?.department===d);
      const de=emps.filter(e=>e.department===d);
      const av=da.length?da.reduce((s,a)=>s+Number(a.overall_score||0),0)/da.length:0;
      const band=av>0?b3Band(av):null;
      const kpis=b3GetKPI(d);
      const dist=[5,4,3,2,1].map(n=>({n,cnt:da.filter(a=>Math.round(a.overall_score||0)===n).length,pct:da.length?Math.round(da.filter(a=>Math.round(a.overall_score||0)===n).length/da.length*100):0}));
      const top3=[...da].sort((a,b)=>b.overall_score-a.overall_score).slice(0,3);
      return`<div class="card">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;margin-bottom:12px">
          <div><div style="font-size:13px;font-weight:800">${esc(d)}</div><div style="font-size:9px;color:var(--muted);margin-top:1px">${esc(de.length)} employees · ${esc(da.length)} appraised</div></div>
          ${av>0?`<div style="text-align:right"><div style="font-size:20px;font-weight:900;color:${esc(band.clr)}">${av.toFixed(2)}</div><div style="font-size:9px;color:${esc(band.clr)};font-weight:700">${esc(band.lbl)}</div></div>`:'<span style="font-size:10px;color:var(--faint)">No data</span>'}
        </div>
        <div style="font-size:9px;color:var(--faint);margin-bottom:5px;text-transform:uppercase;letter-spacing:.4px;font-weight:700">KPI Criteria</div>
        <div style="display:flex;flex-wrap:wrap;gap:4px;margin-bottom:10px">${kpis.map(k=>`<span style="background:var(--n3);border:1px solid var(--bdr);border-radius:4px;padding:2px 6px;font-size:9px;color:var(--muted)">${esc(k.name)} <b style="color:var(--faint)">×${esc(k.w)}%</b></span>`).join('')}</div>
        ${da.length?`
        <div style="font-size:9px;color:var(--faint);margin-bottom:4px;text-transform:uppercase;letter-spacing:.4px;font-weight:700">Score Distribution</div>
        ${dist.map(d=>`<div style="display:flex;align-items:center;gap:6px;margin-bottom:3px"><div style="font-size:9px;color:var(--muted);width:10px;text-align:right">${esc(d.n)}</div><div style="flex:1;height:14px;background:var(--n3);border-radius:3px;overflow:hidden"><div style="height:100%;width:${esc(d.pct)}%;background:${b3Clr(d.n)};border-radius:3px"></div></div><div style="font-size:9px;color:var(--faint);min-width:32px">${esc(d.cnt)} (${esc(d.pct)}%)</div></div>`).join('')}
        ${top3.length?`<div style="font-size:9px;color:var(--faint);margin-top:8px;margin-bottom:4px;text-transform:uppercase;letter-spacing:.4px;font-weight:700">Top Performers</div>
        ${top3.map((a,i)=>`<div style="display:flex;align-items:center;gap:8px;padding:5px 7px;background:var(--card);border-radius:5px;margin-bottom:3px"><span style="font-size:11px">${['🥇','🥈','🥉'][i]}</span><div style="flex:1;font-size:10px;font-weight:700">${esc(a.employee?.full_name||'—')}</div><div style="font-size:12px;font-weight:900;color:${b3Clr(Number(a.overall_score||0))}">${Number(a.overall_score||0).toFixed(1)}</div></div>`).join('')}`:''}
        `:`<div style="text-align:center;padding:12px;color:var(--faint);font-size:11px">No appraisals yet</div>`}
      </div>`;
    }).join('');
    c.innerHTML=`<div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:14px">${cards||'<div class="empty">No department data</div>'}</div>`;
  }catch(err){c.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;}
}

// ── CALIBRATION ────────────────────────────────────────────
async function b3Calibration(){
  const c=document.getElementById('b3-content');
  c.innerHTML='<div class="loading">Loading…</div>';
  try{
    const{data:apps}=await sb.from('performance_appraisals').select('*,employee:employees(full_name,department)').order('overall_score',{ascending:false});
    const all=apps||[];
    const calBands=[
      {lbl:'Outstanding',min:4.5,clr:'#10B981',tgt:'5–10%'},
      {lbl:'Exceeds',min:3.5,clr:'#3B82F6',tgt:'20–25%'},
      {lbl:'Meets',min:2.5,clr:'#C9A84C',tgt:'55–65%'},
      {lbl:'Needs Impr.',min:1.5,clr:'#F97316',tgt:'10–15%'},
      {lbl:'Unsatisfactory',min:0,clr:'#EF4444',tgt:'<5%'}];
    const total=all.length||1;
    const calRows=calBands.map((b,i)=>{
      const next=calBands[i-1];
      const grp=all.filter(a=>{const sc=Number(a.overall_score||0);return sc>=b.min&&(!next||sc<next.min);});
      return{b,grp,pct:Math.round(grp.length/total*100)};
    });
    const segs=calRows.map(r=>`<div style="flex:1;border-radius:5px;padding:8px 6px;text-align:center;background:${esc(r.b.clr)}15;border:1px solid ${esc(r.b.clr)}33"><div style="font-size:16px;font-weight:900;color:${esc(r.b.clr)}">${esc(r.grp.length)}</div><div style="font-size:8px;font-weight:700;color:${esc(r.b.clr)};text-transform:uppercase;letter-spacing:.3px;margin-top:2px">${esc(r.b.lbl)}</div><div style="font-size:9px;color:var(--muted);margin-top:2px">${esc(r.pct)}%</div><div style="font-size:8px;color:var(--faint);margin-top:2px">Target: ${esc(r.b.tgt)}</div></div>`).join('');
    const thS='text-align:left;padding:7px 10px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid var(--bdr);white-space:nowrap';
    const rows=all.map((a,i)=>{const sc=Number(a.overall_score||0);const band=b3Band(sc);return`<tr style="border-bottom:1px solid #0F2444"><td style="padding:7px 10px;color:var(--faint);font-size:10px">${i+1}</td><td style="padding:7px 10px;font-weight:700">${esc(a.employee?.full_name||'—')}</td><td style="padding:7px 10px">${b3DeptBadge(a.employee?.department)}</td><td style="padding:7px 10px;font-size:10px;color:var(--muted)">${esc(a.appraisal_period||'—')}</td><td style="padding:7px 10px;text-align:center;font-size:18px;font-weight:900;color:${esc(band.clr)}">${sc>0?sc.toFixed(2):'—'}</td><td style="padding:7px 10px">${b3Pill(band.lbl,band.clr)}</td></tr>`;}).join('');
    c.innerHTML=`
    <div class="card" style="margin-bottom:14px">
      <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px;margin-bottom:10px">Rating Band Distribution · ${esc(all.length)} total appraisals</div>
      <div style="display:flex;gap:4px;margin-bottom:10px">${segs}</div>
      <div style="font-size:10px;color:var(--faint)">💡 Target distribution follows a bell curve. Majority should fall in Meets Expectations.</div>
    </div>
    <div class="card" style="padding:0;overflow:hidden">
      <div style="padding:12px 14px;border-bottom:1px solid var(--bdr)"><span style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px">Full Ranking — Highest to Lowest</span></div>
      <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">
        <thead><tr><th style="${thS}">#</th><th style="${thS}">Employee</th><th style="${thS}">Dept</th><th style="${thS}">Period</th><th style="${thS};text-align:center">Score</th><th style="${thS}">Rating</th></tr></thead>
        <tbody>${rows||'<tr><td colspan="6" style="text-align:center;padding:16px;color:var(--faint)">No data</td></tr>'}</tbody>
      </table></div>
    </div>`;
  }catch(err){c.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;}
}

// ── TRENDS ─────────────────────────────────────────────────
async function b3Trends(){
  const c=document.getElementById('b3-content');
  c.innerHTML='<div class="loading">Loading…</div>';
  try{
    const{data:apps}=await sb.from('performance_appraisals').select('*,employee:employees(full_name,department)').order('appraisal_date',{ascending:true});
    const all=apps||[];
    const byP={};
    all.forEach(a=>{const p=a.appraisal_period||'Unknown';if(!byP[p])byP[p]=[];byP[p].push(Number(a.overall_score||0));});
    const pLbls=Object.keys(byP).reverse();
    const thS='text-align:left;padding:7px 10px;color:var(--muted);font-size:9px;font-weight:700;text-transform:uppercase;letter-spacing:.5px;border-bottom:1px solid var(--bdr);white-space:nowrap';
    const pRows=pLbls.map(p=>{
      const sc=byP[p];const av=sc.reduce((s,v)=>s+v,0)/sc.length;const band=b3Band(av);
      return`<tr style="border-bottom:1px solid #0F2444">
        <td style="padding:7px 10px;font-weight:700">${esc(p)}</td>
        <td style="padding:7px 10px;text-align:center">${esc(sc.length)}</td>
        <td style="padding:7px 10px;text-align:center"><span style="font-size:16px;font-weight:900;color:${esc(band.clr)}">${av.toFixed(2)}</span></td>
        <td style="padding:7px 10px"><div style="display:flex;align-items:center;gap:6px">${b3Bar(av/5*100,band.clr)} ${b3Pill(band.lbl,band.clr)}</div></td>
        <td style="padding:7px 10px;text-align:center">${Math.max(...sc).toFixed(1)}</td>
        <td style="padding:7px 10px;text-align:center">${Math.min(...sc).toFixed(1)}</td>
      </tr>`;
    }).join('');
    const empMap={};
    all.forEach(a=>{const k=a.employee_id;if(!empMap[k])empMap[k]={name:a.employee?.full_name,dept:a.employee?.department,records:[]};empMap[k].records.push({period:a.appraisal_period,score:Number(a.overall_score||0),date:a.appraisal_date});});
    const multi=Object.values(empMap).filter(e=>e.records.length>1).sort((a,b)=>b.records.length-a.records.length).slice(0,15);
    const tRows=multi.map(e=>{
      const sorted=[...e.records].sort((a,b)=>new Date(a.date)-new Date(b.date));
      const first=sorted[0].score,last=sorted[sorted.length-1].score,delta=last-first;
      const tr=delta>0.2?'▲':delta<-0.2?'▼':'▶';
      const tc=delta>0.2?'#10B981':delta<-0.2?'#EF4444':'var(--muted)';
      const band=b3Band(last);
      return`<tr style="border-bottom:1px solid #0F2444">
        <td style="padding:7px 10px;font-weight:700">${esc(e.name||'—')}</td>
        <td style="padding:7px 10px">${b3DeptBadge(e.dept)}</td>
        <td style="padding:7px 10px;text-align:center">${esc(e.records.length)}</td>
        <td style="padding:7px 10px">${sorted.map(r=>`<span style="font-size:9px;color:var(--faint);margin-right:4px">${esc(r.period?.slice(0,7)||'')} <b style="color:${b3Clr(r.score)}">${r.score.toFixed(1)}</b></span>`).join('')}</td>
        <td style="padding:7px 10px;text-align:center;font-weight:800;color:${esc(band.clr)}">${last.toFixed(2)}</td>
        <td style="padding:7px 10px;text-align:center;color:${tc};font-size:14px">${tr} <span style="font-size:10px">${delta>=0?'+':''}${delta.toFixed(2)}</span></td>
      </tr>`;
    }).join('');
    c.innerHTML=`
    <div class="card" style="margin-bottom:14px;padding:0;overflow:hidden">
      <div style="padding:12px 14px;border-bottom:1px solid var(--bdr)"><span style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px">Score by Appraisal Period</span></div>
      <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">
        <thead><tr><th style="${thS}">Period</th><th style="${thS};text-align:center">Count</th><th style="${thS};text-align:center">Avg Score</th><th style="${thS}">Distribution</th><th style="${thS};text-align:center">High</th><th style="${thS};text-align:center">Low</th></tr></thead>
        <tbody>${pRows||'<tr><td colspan="6" style="text-align:center;padding:16px;color:var(--faint)">No data</td></tr>'}</tbody>
      </table></div>
    </div>
    ${multi.length?`<div class="card" style="padding:0;overflow:hidden">
      <div style="padding:12px 14px;border-bottom:1px solid var(--bdr);display:flex;align-items:center;justify-content:space-between"><span style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase;letter-spacing:.5px">Individual Trajectory (Multi-Period)</span><span style="font-size:10px;color:var(--faint)">${esc(multi.length)} employees</span></div>
      <div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:11px">
        <thead><tr><th style="${thS}">Employee</th><th style="${thS}">Dept</th><th style="${thS};text-align:center">Periods</th><th style="${thS}">History</th><th style="${thS};text-align:center">Latest</th><th style="${thS};text-align:center">Trend</th></tr></thead>
        <tbody>${tRows}</tbody>
      </table></div>
    </div>`:''}`;
  }catch(err){c.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`;}
}

// ── KPI FRAMEWORK CONFIG ───────────────────────────────────
function b3KPIConfig(){
  const c=document.getElementById('b3-content');
  const cards=Object.keys(B3_DKPI).map(d=>{
    const kpis=B3_DKPI[d];const tw=kpis.reduce((s,k)=>s+k.w,0);
    return`<div class="card"><div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:12px"><span style="font-size:12px;font-weight:800">${esc(d)}</span><span style="font-size:10px;color:${tw===100?'#10B981':'#F97316'};font-weight:700">Σ ${tw}% ${tw===100?'✓':'⚠️'}</span></div>
    ${kpis.map(k=>`<div style="display:flex;align-items:center;gap:8px;margin-bottom:6px"><div style="flex:1"><div style="font-size:11px;font-weight:600">${esc(k.name)}</div><div style="font-size:9px;color:var(--faint)">${esc(k.id)}</div></div><div style="background:#C9A84C22;border:1px solid #C9A84C33;border-radius:4px;padding:2px 8px;font-size:10px;font-weight:700;color:var(--gold)">${esc(k.w)}%</div></div>`).join('')}</div>`;
  }).join('');
  c.innerHTML=`
  <div style="background:var(--card2);border:1px solid var(--bdr);border-radius:8px;padding:12px;margin-bottom:14px;font-size:11px;color:var(--muted)">
    💡 Each department has tailored KPIs weighted to sum to 100%. KPIs load automatically when selecting an employee. To modify, update the <code style="background:var(--n3);padding:1px 4px;border-radius:3px;font-size:10px">B3_DKPI</code> object in the source.
  </div>
  <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:12px">${cards}</div>`;
}

// ══════════════════════════════════════════════════════════════
//  P9-5 · BUDGET PLANNING
// ══════════════════════════════════════════════════════════════
async function loadBudget(tab='overview'){
  const el=document.getElementById('page-budget');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Budget…</div>';
  try{
    const today=new Date();
    const year=today.getFullYear();
    const [projR,budgetR,invR]=await Promise.all([
      sb.from('projects').select('id,project_no,name,bac,ac,ev,pct,status,department').order('project_no'),
      sb.from('project_budgets').select('*,project:projects(project_no,name,department)').order('budget_year',{ascending:false}),
      sb.from('invoices').select('invoice_type,status,net_amount,created_at,project_id')
    ]);
    const projs=projR.data||[], budgets=budgetR.data||[], invs=invR.data||[];

    // Aggregate budgets vs actual per project
    const budgetSummary=projs.map(p=>{
      const pb=budgets.filter(b=>b.project_id===p.id&&b.budget_year===year);
      const totalBudget=pb.reduce((s,b)=>s+Number(b.budget_amount||0),0);
      const spent=Number(p.ac||0);
      const variance=totalBudget-spent;
      const pct=totalBudget>0?Math.round(spent/totalBudget*100):0;
      return {
        project_no:p.project_no, name:(p.name||'').substring(0,30),
        department:p.department, status:p.status,
        bac:Number(p.bac||0), totalBudget, spent, variance, pct,
        overBudget:spent>totalBudget&&totalBudget>0
      };
    }).filter(p=>ACTIVE_STATUSES.includes(p.status));

    const totalBudgetAll=budgetSummary.reduce((s,p)=>s+p.totalBudget,0);
    const totalSpentAll=budgetSummary.reduce((s,p)=>s+p.spent,0);
    const overBudgetCount=budgetSummary.filter(p=>p.overBudget).length;

    // Monthly budget vs actual for current year
    const monthlyData=[];
    for(let i=0;i<12;i++){
      const m=`${year}-${String(i+1).padStart(2,'0')}`;
      const actual=invs.filter(x=>x.invoice_type!=='client'&&x.status==='paid'&&x.created_at?.startsWith(m)).reduce((s,x)=>s+Number(x.net_amount),0);
      const budget=budgets.filter(b=>b.budget_year===year&&b.budget_month===i+1).reduce((s,b)=>s+Number(b.budget_amount||0),0);
      monthlyData.push({m:new Date(year,i).toLocaleDateString('en-GB',{month:'short'}),budget:Math.round(budget),actual:Math.round(actual)});
    }
    const maxMonthly=Math.max(...monthlyData.map(m=>Math.max(m.budget,m.actual)),1);

    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='overview'?' act':''}" data-h-click="h343">📊 Overview</button>
      <button class="tab${tab==='projects'?' act':''}" data-h-click="h344">🏗 By Project</button>
      <button class="tab${tab==='monthly'?' act':''}" data-h-click="h345">📅 Monthly</button>
    </div>`;

    let body='';
    if(tab==='overview'){
      body=`
      <div class="grid4" style="margin-bottom:14px">
        ${kpi('Total Budget', fmtKWD(totalBudgetAll), '#C9A84C', year+' planned')}
        ${kpi('Total Spent',  fmtKWD(totalSpentAll),  totalSpentAll>totalBudgetAll?'#EF4444':'#10B981', 'Actual cost')}
        ${kpi('Variance',     fmtKWD(totalBudgetAll-totalSpentAll), (totalBudgetAll-totalSpentAll)>=0?'#10B981':'#EF4444', 'Budget - Actual')}
        ${kpi('Over Budget',  overBudgetCount, overBudgetCount>0?'#EF4444':'#10B981', 'Projects over budget')}
      </div>
      <!-- Monthly chart -->
      <div style="margin-bottom:14px">
        <div style="font-size:11px;font-weight:700;color:var(--gold);margin-bottom:8px">Budget vs Actual — Monthly (${year})</div>
        <div style="display:flex;align-items:flex-end;gap:4px;height:80px;margin-bottom:6px">
          ${monthlyData.map(m=>`
          <div style="flex:1;display:flex;flex-direction:column;gap:2px;align-items:center">
            <div style="width:100%;display:flex;gap:1px;align-items:flex-end;height:65px">
              <div style="flex:1;background:#3B82F677;border-radius:2px 2px 0 0;height:${Math.max(m.budget/maxMonthly*65,2)}px" title="Budget: ${fmtKWD(m.budget)}"></div>
              <div style="flex:1;background:${m.actual>m.budget&&m.budget>0?'#EF4444':'#10B981'}88;border-radius:2px 2px 0 0;height:${Math.max(m.actual/maxMonthly*65,2)}px" title="Actual: ${fmtKWD(m.actual)}"></div>
            </div>
            <div style="font-size:8px;color:var(--faint)">${esc(m.m)}</div>
          </div>`).join('')}
        </div>
        <div style="display:flex;gap:12px;font-size:9px;color:var(--muted)">
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:8px;background:#3B82F6;border-radius:2px"></span>Budget</span>
          <span style="display:flex;align-items:center;gap:4px"><span style="width:10px;height:8px;background:#10B981;border-radius:2px"></span>Actual</span>
        </div>
      </div>`;
    } else if(tab==='projects'){
      body=budgetSummary.length===0?'<div class="empty">No active projects</div>':`
      <div style="display:flex;justify-content:flex-end;margin-bottom:8px">
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h346">+ Add Budget Line</button>`:''}
      </div>
      <table><thead><tr>
        <th>Project</th><th>Dept</th><th style="text-align:right">BAC</th>
        <th style="text-align:right">Budget ${year}</th><th style="text-align:right">Spent</th>
        <th style="text-align:right">Variance</th><th style="text-align:center">%</th><th style="text-align:center">Status</th>
      </tr></thead><tbody>
      ${budgetSummary.map(p=>`<tr>
        <td style="font-weight:700;font-size:11px">${esc(p.project_no)}</td>
        <td style="color:var(--muted);font-size:10px">${esc(p.department||'—')}</td>
        <td style="text-align:right">${fmtKWD(p.bac)}</td>
        <td style="text-align:right;color:#3B82F6;font-weight:700">${p.totalBudget>0?fmtKWD(p.totalBudget):'<span style="color:var(--faint)">Not set</span>'}</td>
        <td style="text-align:right;font-weight:700">${fmtKWD(p.spent)}</td>
        <td style="text-align:right;font-weight:700;color:${p.variance>=0?'#10B981':'#EF4444'}">${p.variance>=0?'+':''}${fmtKWD(p.variance)}</td>
        <td style="text-align:center">
          <div style="display:flex;align-items:center;gap:4px;justify-content:center">
            <div style="width:40px;background:var(--bdr);border-radius:3px;height:5px;overflow:hidden">
              <div style="height:100%;width:${Math.min(p.pct,100)}%;background:${p.overBudget?'#EF4444':'#10B981'};border-radius:3px"></div>
            </div>
            <span style="font-size:10px;color:${p.overBudget?'#EF4444':'var(--muted)'}">${esc(p.pct)}%</span>
          </div>
        </td>
        <td style="text-align:center">${p.overBudget?pill('Over Budget','#EF4444'):pill('On Budget','#10B981')}</td>
      </tr>`).join('')}
      </tbody></table>`;
    } else {
      body=`<table><thead><tr>
        <th>Month</th><th style="text-align:right">Budget</th><th style="text-align:right">Actual</th>
        <th style="text-align:right">Variance</th><th style="text-align:center">Status</th>
      </tr></thead><tbody>
      ${monthlyData.map(m=>`<tr>
        <td style="font-weight:600">${esc(m.m)} ${year}</td>
        <td style="text-align:right;color:#3B82F6;font-weight:700">${m.budget>0?fmtKWD(m.budget):'<span style="color:var(--faint)">—</span>'}</td>
        <td style="text-align:right;font-weight:700">${m.actual>0?fmtKWD(m.actual):'<span style="color:var(--faint)">—</span>'}</td>
        <td style="text-align:right;font-weight:700;color:${m.budget>0&&m.actual>m.budget?'#EF4444':'#10B981'}">${m.budget>0?(m.budget-m.actual>=0?'+':'')+fmtKWD(m.budget-m.actual):'—'}</td>
        <td style="text-align:center">${m.budget>0?(m.actual>m.budget?pill('Over','#EF4444'):pill('On Track','#10B981')):'<span style="color:var(--faint)">No budget</span>'}</td>
      </tr>`).join('')}
      </tbody></table>`;
    }

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">💵</span>
        <div><h1>Budget Planning</h1><div class="sub">Project Budgets · Monthly Planning · Variance Analysis · ${year}</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h346">+ Budget Line</button>`:''}
    </div>
    <div class="card">${tabBtns}${body}</div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

