async function saveBudgetLine(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const projId=document.getElementById('bgt-proj').value;
    const amt=Number(document.getElementById('bgt-amt').value);
    if(!projId||!amt){showToast('Project and amount required','error');return;}
    const month=Number(document.getElementById('bgt-month').value);
    const {error}=await sb.from('project_budgets').insert({
      project_id:projId,
      budget_year:Number(document.getElementById('bgt-year').value),
      budget_month:month||null,
      budget_category:document.getElementById('bgt-cat').value,
      budget_amount:amt,
      notes:document.getElementById('bgt-notes').value.trim()||null,
      created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Budget line saved ✓'); closeModal(); loadBudget();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save';}}
}

// ══════════════════════════════════════════════════════════════
//  P9-6 · NOTIFICATION SCHEDULING
//  Auto-send notifications based on triggers + schedule
// ══════════════════════════════════════════════════════════════
const NOTIF_TRIGGERS = [
  {id:'cert_expiry_30',  icon:'🏆', name:'Certification Expiry',    desc:'Send when employee certification expires in ≤30 days',       interval_days:30},
  {id:'insurance_exp_30',icon:'🛡', name:'Insurance Policy Expiry', desc:'Send when policy/bond expires in ≤30 days',                  interval_days:30},
  {id:'contract_exp_30', icon:'📜', name:'Contract Expiry',         desc:'Send when contract expires in ≤30 days',                     interval_days:30},
  {id:'tender_deadline', icon:'📋', name:'Tender Deadline',         desc:'Send 7 days before tender submission deadline',              interval_days:7},
  {id:'maintenance_due', icon:'🔧', name:'Maintenance Due',         desc:'Send when asset maintenance is due in ≤7 days',              interval_days:7},
  {id:'ar_overdue_7',    icon:'💰', name:'AR Overdue Alert',        desc:'Send when AR invoice is >7 days past due',                   interval_days:7},
  {id:'weekly_evm_auto', icon:'📊', name:'Weekly EVM Auto-send',    desc:'Auto-send EVM summary every Monday',                         interval_days:7},
];

function openNotifScheduler(){
  const stored=JSON.parse(localStorage.getItem('sp360_notif_schedule')||'{}');
  openModal('🔔 Notification Scheduler',`
    <div style="font-size:11px;color:var(--muted);margin-bottom:12px">
      Enable automatic notifications based on system events and schedules.
    </div>
    <div id="sched-list">
    ${NOTIF_TRIGGERS.map(t=>{
      const enabled=stored[t.id]?.enabled||false;
      return`<div style="display:flex;align-items:center;gap:10px;padding:10px 0;border-bottom:1px solid var(--bdr)">
        <span style="font-size:18px;flex-shrink:0">${esc(t.icon)}</span>
        <div style="flex:1">
          <div style="font-size:12px;font-weight:700;color:var(--text)">${esc(t.name)}</div>
          <div style="font-size:10px;color:var(--muted)">${esc(t.desc)}</div>
        </div>
        <label style="display:flex;align-items:center;gap:6px;cursor:pointer;flex-shrink:0">
          <input type="checkbox" id="sched-${esc(t.id)}" ${enabled?'checked':''} style="width:16px;height:16px;accent-color:#C9A84C"/>
          <span style="font-size:10px;color:${enabled?'#10B981':'var(--faint)'}">${enabled?'ON':'OFF'}</span>
        </label>
      </div>`;}).join('')}
    </div>
    <div style="margin-top:12px;padding:10px;background:var(--n3);border-radius:6px;font-size:10px;color:var(--muted)">
      💡 Scheduled notifications run when you open the ERP. Enable email notifications via the Email Notification Center for external delivery.
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h348">Save Schedule</button>
    </div>`);
}

function saveNotifSchedule(){
  const schedule={};
  NOTIF_TRIGGERS.forEach(t=>{
    const cb=document.getElementById('sched-'+t.id);
    if(cb) schedule[t.id]={enabled:cb.checked, interval_days:t.interval_days};
  });
  localStorage.setItem('sp360_notif_schedule', JSON.stringify(schedule));
  showToast('Notification schedule saved ✓');
  closeModal();
  // Run immediately
  runScheduledNotifications();
}

// Tables referenced by optional features that may not exist yet in this database.
// A 404 (PGRST205 / relation missing) is remembered for 24h so the browser stops requesting it.
const _MISSING_KEY='sp360_missing_tables';
function _missingTables(){ try{ const o=JSON.parse(localStorage.getItem(_MISSING_KEY)||'{}'); const now=Date.now(); return Object.fromEntries(Object.entries(o).filter(([,t])=>now-t<864e5)); }catch(_){ return {}; } }
function tableKnownMissing(t){ return !!_missingTables()[t]; }
function noteMissingTable(t,err){
  if(!err) return false;
  const missing=err.code==='PGRST205'||err.code==='42P01'||/does not exist|Could not find the table/i.test(err.message||'');
  if(missing){ try{ const o=_missingTables(); o[t]=Date.now(); localStorage.setItem(_MISSING_KEY,JSON.stringify(o)); }catch(_){} console.warn('[SP360] table missing in database:',t); }
  return missing;
}
async function safeSelect(table, build){
  if(tableKnownMissing(table)) return {data:[],error:null,skipped:true};
  const r=await build(sb.from(table));
  if(r.error && noteMissingTable(table,r.error)) return {data:[],error:null,skipped:true};
  return r;
}

async function runScheduledNotifications(){
  const schedule=JSON.parse(localStorage.getItem('sp360_notif_schedule')||'{}');
  const enabled=Object.entries(schedule).filter(([,v])=>v?.enabled);
  if(enabled.length===0) return;

  const today=new Date();
  let triggered=0;

  for(const [triggerId,config] of enabled){
    try{
      const days=config.interval_days||30;
      const cutoff=new Date(today.getTime()+days*86400000).toISOString().split('T')[0];

      if(triggerId==='cert_expiry_30'){
        const {data}=await safeSelect('employee_certifications',q=>q.select('*,employee:employees(full_name)').lte('expiry_date',cutoff).gte('expiry_date',today.toISOString().split('T')[0]).eq('status','active'));
        if(data?.length>0){ showToast(`🏆 ${data.length} certification(s) expiring in ${days}d`); triggered++; }
      }
      if(triggerId==='insurance_exp_30'){
        const [{data:pols},{data:bonds}]=await Promise.all([
          safeSelect('insurance_policies',q=>q.select('policy_no').lte('expiry_date',cutoff).gte('expiry_date',today.toISOString().split('T')[0]).eq('status','active')),
          safeSelect('performance_bonds',q=>q.select('bond_no').lte('expiry_date',cutoff).gte('expiry_date',today.toISOString().split('T')[0]).eq('status','active'))
        ]);
        const cnt=(pols?.length||0)+(bonds?.length||0);
        if(cnt>0){ showToast(`🛡 ${cnt} insurance/bond(s) expiring in ${days}d`); triggered++; }
      }
      if(triggerId==='ar_overdue_7'){
        const {data}=await sb.from('invoices').select('id').eq('invoice_type','client').not('status','in','(paid,cancelled)').lt('due_date',today.toISOString().split('T')[0]);
        if(data?.length>0){ showToast(`💰 ${data.length} AR invoice(s) overdue`); triggered++; }
      }
      if(triggerId==='tender_deadline'){
        const {data}=await safeSelect('tenders',q=>q.select('tender_no').lte('submission_deadline',cutoff).gte('submission_deadline',today.toISOString().split('T')[0]).eq('status','open'));
        if(data?.length>0){ showToast(`📋 ${data.length} tender deadline(s) in ${days}d`); triggered++; }
      }
      if(triggerId==='maintenance_due'){
        const {data}=await safeSelect('asset_maintenance',q=>q.select('id').lte('scheduled_date',cutoff).gte('scheduled_date',today.toISOString().split('T')[0]).eq('status','scheduled'));
        if(data?.length>0){ showToast(`🔧 ${data.length} maintenance task(s) due in ${days}d`); triggered++; }
      }
      if(triggerId==='weekly_evm_auto'){
        const dayOfWeek=today.getDay();
        const lastRun=localStorage.getItem('sp360_last_evm_auto');
        const todayStr=today.toISOString().split('T')[0];
        if(dayOfWeek===1&&lastRun!==todayStr){
          localStorage.setItem('sp360_last_evm_auto',todayStr);
          showToast('📊 Weekly EVM auto-notification queued');
          triggered++;
        }
      }
    }catch(e){ console.warn('Notification trigger failed:',triggerId,e.message); }
  }

  if(triggered>0) console.log(`[SP360] ${triggered} scheduled notification(s) triggered`);
}

// Hook into enterApp
const _origEnterApp_notif = typeof enterApp === 'function' ? enterApp : null;

// ══════════════════════════════════════════════════════════════
//  P10-1 · PROJECT DEPENDENCIES
//  Finish-to-Start / Start-to-Start linking in Gantt
// ══════════════════════════════════════════════════════════════
async function loadProjectDependencies(projectId, projectNo){
  const [{data:tasks},{data:deps}] = await Promise.all([
    sb.from('project_tasks').select('id,task_no,title,start_date,end_date,status,pct,predecessor_id').eq('project_id',projectId).order('task_no'),
    sb.from('project_dependencies').select('*').eq('project_id',projectId)
  ]);
  const T=tasks||[], D=deps||[];

  openModal(`🔗 Project Dependencies — ${projectNo}`,`
    <div style="font-size:11px;color:var(--muted);margin-bottom:10px">
      Define task dependencies to control project sequencing and critical path.
    </div>
    ${T.length===0?`<div class="empty">No tasks found. Add tasks to this project first.</div>`:`
    <div style="overflow-x:auto;max-height:350px;overflow-y:auto">
      <table><thead><tr>
        <th>Task</th><th>Title</th><th>Start</th><th>End</th><th>Status</th><th>Predecessor</th><th>Type</th>
      </tr></thead><tbody>
      ${T.map(t=>{
        const dep=D.find(d=>d.successor_id===t.id);
        const pred=dep?T.find(p=>p.id===dep.predecessor_id):null;
        return`<tr>
          <td style="color:var(--gold);font-size:10px;font-weight:700">${esc(t.task_no||'—')}</td>
          <td style="font-size:11px;font-weight:600">${esc(t.title||'—')}</td>
          <td style="font-size:10px;color:var(--faint)">${esc(t.start_date||'—')}</td>
          <td style="font-size:10px;color:var(--faint)">${esc(t.end_date||'—')}</td>
          <td>${pill(t.status||'pending',t.status==='completed'?'#10B981':t.status==='in_progress'?'#3B82F6':'#94A3B8')}</td>
          <td style="font-size:10px;color:var(--muted)">${pred?esc(pred.task_no+' — '+pred.title.substring(0,20)):'<span style="color:var(--faint)">None</span>'}</td>
          <td style="font-size:10px;color:var(--muted)">${dep?esc(dep.dependency_type||'FS'):'—'}</td>
        </tr>`;}).join('')}
      </tbody></table>
    </div>
    <div style="margin-top:10px;padding:8px;background:var(--n3);border-radius:6px">
      <div style="font-size:10px;font-weight:700;color:var(--gold);margin-bottom:6px">Add Dependency</div>
      <div style="display:flex;gap:8px;flex-wrap:wrap">
        <select id="dep-pred" style="flex:1;min-width:120px;background:var(--card);border:1px solid var(--bdr);border-radius:6px;padding:6px;color:var(--text);font-size:10px">
          <option value="">Predecessor task</option>
          ${T.map(t=>`<option value="${esc(t.id)}">${esc(t.task_no)} — ${esc(t.title.substring(0,25))}</option>`).join('')}
        </select>
        <select id="dep-succ" style="flex:1;min-width:120px;background:var(--card);border:1px solid var(--bdr);border-radius:6px;padding:6px;color:var(--text);font-size:10px">
          <option value="">Successor task</option>
          ${T.map(t=>`<option value="${esc(t.id)}">${esc(t.task_no)} — ${esc(t.title.substring(0,25))}</option>`).join('')}
        </select>
        <select id="dep-type" style="background:var(--card);border:1px solid var(--bdr);border-radius:6px;padding:6px;color:var(--text);font-size:10px">
          <option value="FS">FS — Finish to Start</option>
          <option value="SS">SS — Start to Start</option>
          <option value="FF">FF — Finish to Finish</option>
          <option value="SF">SF — Start to Finish</option>
        </select>
        <button data-h-click="h349" data-ha-click="${esc(JSON.stringify([String((projectId)??''),String((projectNo)??'')]))}" class="btn btn-primary btn-sm">Link</button>
      </div>
    </div>`}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
    </div>`);
}

async function saveDependency(projectId, projectNo){
  const predId=document.getElementById('dep-pred').value;
  const succId=document.getElementById('dep-succ').value;
  const type  =document.getElementById('dep-type').value;
  if(!predId||!succId){showToast('Select both predecessor and successor','error');return;}
  if(predId===succId){showToast('Task cannot depend on itself','error');return;}
  const {error}=await sb.from('project_dependencies').insert({
    project_id:projectId, predecessor_id:predId, successor_id:succId,
    dependency_type:type, created_by:currentProfile?.id
  });
  if(error){showToast('Error: '+error.message,'error');return;}
  showToast('Dependency linked ✓');
  loadProjectDependencies(projectId, projectNo);
}

