async function assignEquipment(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Assigning…';}
  try{
    const assetId=document.getElementById('eq-asset').value;
    const projId =document.getElementById('eq-proj').value;
    if(!assetId||!projId){showToast('Equipment and project required','error');return;}
    const {data:proj}=await sb.from('projects').select('project_no').eq('id',projId).single();
    const {error}=await sb.from('assets').update({
      project_id:projId, location:proj?.project_no||'Site',
      updated_at:new Date().toISOString()
    }).eq('id',assetId);
    if(error){showToast('Error: '+error.message,'error');return;}
    await writeAudit('assets',assetId,'EQUIPMENT_ASSIGNED',null,{project_id:projId},'Equipment assigned to site');
    showToast('Equipment assigned ✓');
    loadEquipmentTracking();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Assign';}}
}

// ══════════════════════════════════════════════════════════════
//  P10-3 · CORRESPONDENCE LOG
// ══════════════════════════════════════════════════════════════
async function loadCorrespondence(tab){
  tab=tab||'all';
  var el=document.getElementById('page-correspondence');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Correspondence...</div>';
  try{
    var today=new Date();
    var r1=await sb.from('correspondence').select('*,project:projects(project_no,name)').order('correspondence_date',{ascending:false});
    var corrs=r1.data||[];
    var incoming=corrs.filter(function(c){return c.direction==='incoming';});
    var outgoing=corrs.filter(function(c){return c.direction==='outgoing';});
    var pending=corrs.filter(function(c){return c.status==='pending_reply';});
    var overdue=corrs.filter(function(c){return c.status==='pending_reply'&&c.reply_due_date&&new Date(c.reply_due_date)<today;});
    var list=tab==='incoming'?incoming:tab==='outgoing'?outgoing:tab==='pending'?pending:tab==='overdue'?overdue:corrs;
    var tc={letter:'#3B82F6',email:'#10B981',fax:'#8B5CF6',notice:'#EF4444',memo:'#C9A84C',report:'#F97316'};

    // Build page
    var html='<div class="page-head"><div class="page-head-left"><span style="font-size:22px">\u2709\uFE0F</span>'
      +'<div><h1>Correspondence Log</h1><div class="sub">Letters \xb7 Emails \xb7 Notices \xb7 Memos</div></div></div>'
      +'<div style="display:flex;gap:8px">'
      +(can('create')?'<button class="btn btn-primary btn-sm" data-h-click="h353">+ Log Correspondence</button>':'')
      +'<button class="btn btn-ghost btn-sm" data-h-click="h354">Export CSV</button>'
      +'</div></div>';

    html+='<div class="grid4" style="margin-bottom:14px">'
      +kpi('Total',corrs.length,'#C9A84C','All')
      +kpi('Incoming',incoming.length,'#3B82F6','Received')
      +kpi('Outgoing',outgoing.length,'#10B981','Sent')
      +kpi('Overdue Reply',overdue.length,overdue.length>0?'#EF4444':'#10B981','Past due')
      +'</div>';

    if(overdue.length>0){
      html+='<div style="background:#EF444411;border:1px solid #EF444433;border-radius:9px;padding:12px 16px;margin-bottom:14px">'
        +'<div style="font-size:11px;font-weight:700;color:#EF4444;margin-bottom:8px">'+overdue.length+' Overdue Reply Items</div>'
        +'<div style="display:flex;flex-wrap:wrap;gap:6px">';
      for(var oi=0;oi<Math.min(overdue.length,5);oi++){
        var oc=overdue[oi];
        var odays=Math.ceil((today-new Date(oc.reply_due_date))/86400000);
        html+='<span style="background:var(--card);border:1px solid #EF444444;border-radius:6px;padding:5px 10px;font-size:10px;cursor:pointer" data-id="'+esc(oc.id)+'" data-h-click="h355">'
          +esc(oc.ref_no||'--')+' - '+esc((oc.subject||'').slice(0,30))
          +' <span style="color:#EF4444">'+odays+'d overdue</span></span>';
      }
      html+='</div></div>';
    }

    html+='<div class="card">'
      +'<div class="tabs">'
      +'<button class="tab'+(tab==='all'?' act':'')+'" data-t="all" data-h-click="h356">All ('+corrs.length+')</button>'
      +'<button class="tab'+(tab==='incoming'?' act':'')+'" data-t="incoming" data-h-click="h356">Incoming ('+incoming.length+')</button>'
      +'<button class="tab'+(tab==='outgoing'?' act':'')+'" data-t="outgoing" data-h-click="h356">Outgoing ('+outgoing.length+')</button>'
      +'<button class="tab'+(tab==='pending'?' act':'')+'" data-t="pending" data-h-click="h356">Pending ('+pending.length+')</button>'
      +'<button class="tab'+(tab==='overdue'?' act':'')+'" data-t="overdue" data-h-click="h356" style="color:'+(overdue.length>0?'#EF4444':'inherit')+'">Overdue ('+overdue.length+')</button>'
      +'</div>'
      +'<div style="display:flex;gap:8px;margin-bottom:10px">'
      +'<input id="corr-search" placeholder="Search ref, subject, party..." data-h-input="h357" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;width:240px;font-family:inherit"/>'
      +'<select id="corr-type-filter" data-h-change="h358" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;font-family:inherit">'
      +'<option value="">All Types</option><option value="letter">Letter</option><option value="email">Email</option>'
      +'<option value="fax">Fax</option><option value="notice">Notice</option><option value="memo">Memo</option><option value="report">Report</option>'
      +'</select></div>';

    if(list.length===0){
      html+='<div class="empty">No correspondence found</div>';
    } else {
      html+='<div style="overflow-x:auto"><table class="tbl"><thead><tr>'
        +'<th>Ref No</th><th>Subject</th><th>Type</th><th>Dir</th>'
        +'<th>Party</th><th>Project</th><th>Date</th><th>Reply Due</th><th>Status</th><th></th>'
        +'</tr></thead><tbody id="corr-tbody">';
      for(var ri=0;ri<list.length;ri++){
        var cc=list[ri];
        var isOv=cc.status==='pending_reply'&&cc.reply_due_date&&new Date(cc.reply_due_date)<today;
        var dLeft=cc.reply_due_date?Math.ceil((new Date(cc.reply_due_date)-today)/86400000):null;
        var dText=cc.reply_due_date?(isOv?Math.abs(dLeft)+'d late':(dLeft===0?'Today':dLeft+'d left')):'--';
        html+='<tr data-ref="'+esc((cc.ref_no||'').toLowerCase())+'" data-subj="'+esc((cc.subject||'').toLowerCase())+'" data-party="'+esc((cc.party_name||'').toLowerCase())+'" data-type="'+esc(cc.corr_type||'')+'" style="background:'+(isOv?'#EF444408':'')+'">'
          +'<td style="color:var(--gold);font-weight:700;font-size:10px">'+esc(cc.ref_no||'--')+'</td>'
          +'<td style="font-weight:600;font-size:11px;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">'+esc(cc.subject||'--')+'</td>'
          +'<td><span style="font-size:9px;background:'+(tc[cc.corr_type]||'#94A3B8')+'22;color:'+(tc[cc.corr_type]||'#94A3B8')+';border-radius:4px;padding:2px 6px">'+esc(cc.corr_type||'--')+'</span></td>'
          +'<td><span style="font-size:9px;background:'+(cc.direction==='incoming'?'#3B82F622':'#10B98122')+';color:'+(cc.direction==='incoming'?'#3B82F6':'#10B981')+';border-radius:4px;padding:2px 6px">'+(cc.direction==='incoming'?'In':'Out')+'</span></td>'
          +'<td style="font-size:10px;color:var(--muted)">'+esc(cc.party_name||'--')+'</td>'
          +'<td style="font-size:10px;color:var(--gold)">'+esc(cc.project?cc.project.project_no:'General')+'</td>'
          +'<td style="font-size:10px;color:var(--faint)">'+esc(cc.correspondence_date||'--')+'</td>'
          +'<td style="font-size:10px;color:'+(isOv?'#EF4444':(dLeft!==null&&dLeft<=3?'#F97316':'var(--muted)'))+'">'+(cc.reply_due_date?dText:'--')+'</td>'
          +'<td>'+pill(cc.status||'filed',cc.status==='pending_reply'?'#F97316':cc.status==='replied'?'#10B981':'#94A3B8')+'</td>'
          +'<td style="display:flex;gap:3px">'
          +'<button data-id="'+esc(cc.id)+'" data-h-click="h355" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:10px">View</button>'
          +(can('edit')&&cc.status==='pending_reply'?'<button data-id="'+esc(cc.id)+'" data-h-click="h359" style="background:none;border:none;color:#10B981;cursor:pointer;font-size:10px">Done</button>':'')
          +'</td></tr>';
      }
      html+='</tbody></table></div>';
    }
    html+='</div>';
    el.innerHTML=html;
  }catch(err){ el.innerHTML='<div class="empty">Error: '+esc(err.message)+'</div>'; }
}

function filterCorrTable(q){
  var type=(document.getElementById('corr-type-filter')||{}).value||'';
  document.querySelectorAll('#corr-tbody tr').forEach(function(tr){
    var mq=!q||tr.dataset.ref.includes(q.toLowerCase())||tr.dataset.subj.includes(q.toLowerCase())||tr.dataset.party.includes(q.toLowerCase());
    var mt=!type||tr.dataset.type===type;
    tr.style.display=(mq&&mt)?'':'none';
  });
}

function exportCorrespondenceCSV(){
  var rows=[['Ref No','Subject','Type','Dir','Party','Project','Date','Reply Due','Status']];
  document.querySelectorAll('#corr-tbody tr').forEach(function(tr){
    var cells=[...tr.querySelectorAll('td')].map(function(td){return td.textContent.trim();});
    if(cells.length>=9) rows.push(cells.slice(0,9));
  });
  var csv=rows.map(function(r){return r.map(function(v){return '"'+String(v).replace(/"/g,'""')+'"';}).join(',');}).join('\n');
  var a=document.createElement('a');
  a.href='data:text/csv;charset=utf-8,'+encodeURIComponent(csv);
  a.download='Correspondence_'+new Date().toISOString().slice(0,10)+'.csv';
  a.click();
  showToast('CSV exported','success');
}


