async function saveCorrespondence(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const subj=document.getElementById('cor-subj').value.trim();
    const party=document.getElementById('cor-party').value.trim();
    const date=document.getElementById('cor-date').value;
    if(!subj||!party||!date){showToast('Subject, party and date required','error');return;}
    const no=await nextRefNo('COR');
    const {error}=await sb.from('correspondence').insert({
      ref_no:no, subject:subj,
      corr_type:document.getElementById('cor-type').value,
      direction:document.getElementById('cor-dir').value,
      party_name:party,
      correspondence_date:date,
      project_id:document.getElementById('cor-proj').value||null,
      external_ref:document.getElementById('cor-extref').value.trim()||null,
      status:document.getElementById('cor-status').value,
      summary:document.getElementById('cor-summary').value.trim()||null,
      created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    await writeAudit('correspondence',null,'CORRESPONDENCE_LOGGED',null,{ref_no:no,subject:subj},'Correspondence logged');
    showToast(no+' logged ✓'); closeModal(); loadCorrespondence();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save';}}
}

async function openCorrDetail(id){
  const {data:c}=await sb.from('correspondence').select('*,project:projects(project_no,name)').eq('id',id).single();
  if(!c) return;
  const typeColors={'letter':'#3B82F6','email':'#10B981','fax':'#8B5CF6','notice':'#EF4444','memo':'#C9A84C','report':'#F97316'};
  openModal(`✉️ ${c.ref_no} — ${c.subject}`,`
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:12px">
      ${[['Type',`<span style="color:${typeColors[c.corr_type]||'#94A3B8'};font-weight:700;text-transform:capitalize">${esc(c.corr_type||'—')}</span>`],
         ['Direction',c.direction==='incoming'?'📥 Incoming':'📤 Outgoing'],
         ['Party',c.party_name||'—'],['Date',c.correspondence_date||'—'],
         ['Project',c.project?.project_no||'General'],['External Ref',c.external_ref||'—'],
         ['Status',pill(c.status||'filed',c.status==='pending_reply'?'#F97316':c.status==='replied'?'#10B981':'#94A3B8')],
         ['Logged by',c.created_by||'—']
      ].map(([l,v])=>`<div style="background:var(--n3);border-radius:6px;padding:8px">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase">${l}</div>
        <div style="font-size:12px;color:var(--text);margin-top:2px">${v}</div>
      </div>`).join('')}
    </div>
    ${c.summary?`<div style="padding:10px;background:var(--n3);border-radius:6px;font-size:11px;color:var(--text);white-space:pre-wrap">${esc(c.summary)}</div>`:''}
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      ${can('edit')&&c.status==='pending_reply'?`<button class="btn btn-primary" data-h-click="h361" data-ha-click="${esc(JSON.stringify([String((id)??'')]))}">✅ Mark Replied</button>`:''}
    </div>`);
}

async function markCorrReplied(id){
  await sb.from('correspondence').update({status:'replied',updated_at:new Date().toISOString()}).eq('id',id);
  showToast('Marked as replied ✓');
  loadCorrespondence();
}

// ══════════════════════════════════════════════════════════════
//  P10-4 · KPI CUSTOM TARGETS + BENCHMARKING
// ══════════════════════════════════════════════════════════════
async function loadBenchmark(){
  const el=document.getElementById('page-benchmark');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Benchmark…</div>';
  try{
    const today=new Date();
    const [projR,invR,wfR,ncrR]=await Promise.all([
      sb.from('projects').select('id,status,cpi,spi,pct,bac,ev,ac').in('status',ACTIVE_STATUSES),
      sb.from('invoices').select('invoice_type,status,net_amount,due_date'),
      sb.from('workflow_items').select('id,status'),
      sb.from('ncrs').select('id,status,severity')
    ]);
    const projs=projR.data||[], invs=invR.data||[], wfs=wfR.data||[], ncrs=ncrR.data||[];

    // Load custom targets
    const savedTargets=JSON.parse(localStorage.getItem('sp360_kpi_targets')||'{}');

    const totalEV=projs.reduce((s,p)=>s+Number(p.ev),0);
    const totalAC=projs.reduce((s,p)=>s+Number(p.ac),0);
    const totalPV=projs.reduce((s,p)=>s+Number(p.pv||0),0);
    const portCPI=totalAC>0?totalEV/totalAC:1;
    const portSPI=totalPV>0?totalEV/totalPV:1;
    const rev=invs.filter(i=>i.invoice_type==='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
    const cost=invs.filter(i=>i.invoice_type!=='client'&&i.status==='paid').reduce((s,i)=>s+Number(i.net_amount),0);
    const gpPct=rev>0?((rev-cost)/rev*100):0;
    const overdueAR=invs.filter(i=>i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)&&i.due_date&&new Date(i.due_date)<today).length;
    const wfSLA=wfs.length>0?Math.round((1-wfs.filter(w=>w.status==='overdue').length/wfs.length)*100):100;
    const openNCR=ncrs.filter(n=>n.status==='open').length;
    const critNCR=ncrs.filter(n=>n.status==='open'&&n.severity==='critical').length;
    const avgPct=projs.length?projs.reduce((s,p)=>s+Number(p.pct||0),0)/projs.length:0;

    // Industry benchmarks
    const INDUSTRY_BENCHMARKS={
      cpi:{label:'Portfolio CPI', value:portCPI.toFixed(3), target:savedTargets.cpi||1.00, industry:1.00, unit:'ratio', higher:true},
      spi:{label:'Portfolio SPI', value:portSPI.toFixed(3), target:savedTargets.spi||1.00, industry:1.00, unit:'ratio', higher:true},
      gp_pct:{label:'GP Margin %',   value:gpPct.toFixed(1),  target:savedTargets.gp_pct||25, industry:20,  unit:'%',    higher:true},
      wf_sla:{label:'Workflow SLA %',value:wfSLA,             target:savedTargets.wf_sla||90, industry:85,  unit:'%',    higher:true},
      overdue_ar:{label:'Overdue AR', value:overdueAR,        target:savedTargets.overdue_ar||0,industry:0,  unit:'invoices',higher:false},
      open_ncr:{label:'Open NCRs',   value:openNCR,           target:savedTargets.open_ncr||0,industry:2,   unit:'count',higher:false},
      crit_ncr:{label:'Critical NCRs',value:critNCR,          target:savedTargets.crit_ncr||0,industry:0,   unit:'count',higher:false},
      avg_progress:{label:'Avg % Complete',value:avgPct.toFixed(1),target:savedTargets.avg_progress||50,industry:50,unit:'%',higher:true},
    };

    const compareColor=(val,target,higher)=>{
      const v=Number(val), t=Number(target);
      return higher?(v>=t?'#10B981':v>=t*0.9?'#F97316':'#EF4444'):(v<=t?'#10B981':v<=t*1.1?'#F97316':'#EF4444');
    };

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📐</span>
        <div><h1>Benchmarking & KPI Targets</h1><div class="sub">SP360 Actuals vs Custom Targets vs Industry Standards</div></div>
      </div>
      <button class="btn btn-ghost btn-sm" data-h-click="h362">⚙️ Set Targets</button>
    </div>

    <!-- Legend -->
    <div style="display:flex;gap:16px;margin-bottom:12px;flex-wrap:wrap;font-size:10px;color:var(--muted)">
      <span style="display:flex;align-items:center;gap:4px"><span style="width:12px;height:12px;background:#1E3A5F;border:2px solid #C9A84C;border-radius:2px"></span>SP360 Actual</span>
      <span style="display:flex;align-items:center;gap:4px"><span style="width:12px;height:12px;background:#3B82F622;border:2px solid #3B82F6;border-radius:2px"></span>Your Target</span>
      <span style="display:flex;align-items:center;gap:4px"><span style="width:12px;height:12px;background:#8B5CF622;border:2px solid #8B5CF6;border-radius:2px"></span>Industry Standard</span>
    </div>

    <div style="display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:12px">
      ${Object.entries(INDUSTRY_BENCHMARKS).map(([key,kpi])=>{
        const col=compareColor(kpi.value,kpi.target,kpi.higher);
        const maxVal=Math.max(Number(kpi.value),Number(kpi.target),Number(kpi.industry))||1;
        const actPct=Math.min(Number(kpi.value)/maxVal*100,100);
        const tgtPct=Math.min(Number(kpi.target)/maxVal*100,100);
        const indPct=Math.min(Number(kpi.industry)/maxVal*100,100);
        return`<div style="border:1px solid var(--bdr);border-left:3px solid ${col};border-radius:8px;padding:14px;background:var(--card2)">
          <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:8px">
            <div style="font-size:10px;font-weight:700;color:var(--muted);text-transform:uppercase">${esc(kpi.label)}</div>
            <div style="font-size:18px;font-weight:900;color:${col}">${esc(kpi.value)}${kpi.unit==='%'?'%':''}</div>
          </div>
          <!-- Actual bar -->
          <div style="margin-bottom:4px">
            <div style="display:flex;justify-content:space-between;font-size:9px;color:var(--faint);margin-bottom:2px"><span>Actual</span><span style="color:${col}">${esc(kpi.value)} ${esc(kpi.unit)}</span></div>
            <div style="background:var(--bdr);border-radius:3px;height:6px;overflow:hidden"><div style="height:100%;width:${actPct.toFixed(0)}%;background:${col};border-radius:3px"></div></div>
          </div>
          <!-- Target bar -->
          <div style="margin-bottom:4px">
            <div style="display:flex;justify-content:space-between;font-size:9px;color:var(--faint);margin-bottom:2px"><span>Your Target</span><span style="color:#3B82F6">${esc(kpi.target)} ${esc(kpi.unit)}</span></div>
            <div style="background:var(--bdr);border-radius:3px;height:6px;overflow:hidden"><div style="height:100%;width:${tgtPct.toFixed(0)}%;background:#3B82F6;border-radius:3px"></div></div>
          </div>
          <!-- Industry bar -->
          <div>
            <div style="display:flex;justify-content:space-between;font-size:9px;color:var(--faint);margin-bottom:2px"><span>Industry</span><span style="color:#8B5CF6">${esc(kpi.industry)} ${esc(kpi.unit)}</span></div>
            <div style="background:var(--bdr);border-radius:3px;height:6px;overflow:hidden"><div style="height:100%;width:${indPct.toFixed(0)}%;background:#8B5CF6;border-radius:3px"></div></div>
          </div>
        </div>`;}).join('')}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

function openCustomTargetsModal(){
  const saved=JSON.parse(localStorage.getItem('sp360_kpi_targets')||'{}');
  const fields=[
    ['cpi',       'Portfolio CPI Target',    saved.cpi||1.00,    '0.001'],
    ['spi',       'Portfolio SPI Target',    saved.spi||1.00,    '0.001'],
    ['gp_pct',    'GP Margin % Target',      saved.gp_pct||25,   '0.1'],
    ['wf_sla',    'Workflow SLA % Target',   saved.wf_sla||90,   '1'],
    ['overdue_ar','Max Overdue AR Target',   saved.overdue_ar||0,'1'],
    ['open_ncr',  'Max Open NCR Target',     saved.open_ncr||0,  '1'],
    ['crit_ncr',  'Max Critical NCR Target', saved.crit_ncr||0,  '1'],
    ['avg_progress','Avg Progress % Target', saved.avg_progress||50,'1'],
  ];
  openModal('⚙️ Customize KPI Targets',`
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">
      ${fields.map(([id,label,val,step])=>`
      <div class="form-field">
        <label style="font-size:10px">${label}</label>
        <input id="tgt-${id}" type="number" step="${step}" value="${val}" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:6px;padding:8px;color:var(--text)"/>
      </div>`).join('')}
    </div>
    <div style="margin-top:10px;padding:8px;background:var(--n3);border-radius:6px;font-size:10px;color:var(--muted)">
      Targets are saved locally and used across Scorecard, Analytics, and Benchmark pages.
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-ghost btn-sm" data-h-click="h363">Reset Defaults</button>
      <button class="btn btn-primary" data-h-click="h364">Save Targets</button>
    </div>`);
}

function saveCustomTargets(){
  const fields=['cpi','spi','gp_pct','wf_sla','overdue_ar','open_ncr','crit_ncr','avg_progress'];
  const targets={};
  fields.forEach(id=>{
    const el=document.getElementById('tgt-'+id);
    if(el) targets[id]=Number(el.value);
  });
  localStorage.setItem('sp360_kpi_targets',JSON.stringify(targets));
  showToast('KPI targets saved ✓');
  closeModal();
  loadBenchmark();
}

function resetCustomTargets(){
  localStorage.removeItem('sp360_kpi_targets');
  showToast('Targets reset to defaults');
  closeModal();
  loadBenchmark();
}

