function _logImport(action, dataset, ok, rows){
  const log=JSON.parse(localStorage.getItem('sp360_import_log')||'[]');
  log.push({action,dataset,ok,rows,ts:new Date().toLocaleString('en-GB')});
  localStorage.setItem('sp360_import_log',JSON.stringify(log.slice(-50)));
}

async function exportDataset(id, format){
  showToast(`Exporting ${id} as ${format.toUpperCase()}…`);
  try{
    let data=[], cols=[], label=id;

    if(id==='projects'){
      const {data:r}=await sb.from('projects').select('project_no,name,client,department,status,pct,cpi,spi,bac,ev,ac,pv,start_date,end_date').order('project_no');
      data=r||[]; cols=Object.keys(data[0]||{}); label='Projects';
    } else if(id==='invoices'){
      const {data:r}=await sb.from('invoices').select('invoice_no,invoice_type,client_name,vendor_name,project_id,net_amount,status,invoice_date,due_date,paid_date').order('created_at',{ascending:false});
      data=r||[]; cols=Object.keys(data[0]||{}); label='Invoices';
    } else if(id==='employees'){
      const {data:r}=await sb.from('employees').select('employee_no,full_name,department,position,status,employment_type,join_date').order('employee_no');
      data=r||[]; cols=Object.keys(data[0]||{}); label='Employees';
    } else if(id==='vendors'){
      const {data:r}=await sb.from('vendors').select('vendor_code,name,category,contact_person,email,phone,is_approved,status').order('vendor_code');
      data=r||[]; cols=Object.keys(data[0]||{}); label='Vendors';
    } else if(id==='ncrs'){
      const {data:r}=await sb.from('ncrs').select('ncr_no,severity,status,department,description,created_at').order('created_at',{ascending:false});
      data=r||[]; cols=Object.keys(data[0]||{}); label='NCRs';
    } else if(id==='workflow'){
      const {data:r}=await sb.from('workflow_items').select('ref_no,entity_type,title,current_step,status,created_at,due_date').order('created_at',{ascending:false});
      data=r||[]; cols=Object.keys(data[0]||{}); label='Workflow';
    } else if(id==='contracts'){
      const {data:r}=await sb.from('contracts').select('contract_no,title,contract_type,client_name,contract_value,start_date,end_date,status').order('contract_no');
      data=r||[]; cols=Object.keys(data[0]||{}); label='Contracts';
    } else if(id==='assets'){
      const {data:r}=await sb.from('assets').select('asset_no,asset_name,category,serial_number,purchase_value,book_value,condition,status,location').order('asset_no');
      data=r||[]; cols=Object.keys(data[0]||{}); label='Assets';
    }

    if(!data.length){showToast('No data found','error');return;}

    if(format==='csv'){
      const csv=[cols.join(','),...data.map(r=>cols.map(c=>{const v=r[c]; return typeof v==='string'&&v.includes(',')?`"${v}"`:v??'';}).join(','))].join('\n');
      const blob=new Blob([csv],{type:'text/csv'});
      const url=URL.createObjectURL(blob);
      const a=document.createElement('a'); a.href=url; a.download=`SP360_${label}_${new Date().toISOString().split('T')[0]}.csv`; a.click();
      URL.revokeObjectURL(url);
    } else {
      const wb=new ExcelJS.Workbook(); wb.creator='SP360 v4.1'; wb.created=new Date();
      const ws=wb.addWorksheet(label);
      xlTitleBlock(ws,`SP360 v4.1 — ${label} Export`,`Generated: ${new Date().toLocaleDateString('en-GB')} · ${data.length} records`,cols.length);
      const hdr=ws.addRow(cols.map(c=>c.replace(/_/g,' ').replace(/\b\w/g,l=>l.toUpperCase())));
      hdr.eachCell(cell=>{cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1E3A5F'}};cell.font={bold:true,color:{argb:'FFC9A84C'},name:'Calibri',size:10};cell.border=XL.thinBorder;cell.alignment={horizontal:'center'};});
      ws.columns=cols.map(()=>({width:18}));
      data.forEach((r,i)=>{
        const row=ws.addRow(cols.map(c=>r[c]!=null?r[c]:''));
        row.eachCell(cell=>{cell.border=XL.thinBorder;cell.font={name:'Calibri',size:10};});
        if(i%2===0) row.eachCell(c=>{if(!c.fill?.fgColor?.argb) c.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFF8FAFC'}};});
      });
      ws.views=[{state:'frozen',ySplit:5}];
      await xlSave(wb,`SP360_${label}_${new Date().toISOString().split('T')[0]}.xlsx`);
    }

    _logImport(`Export ${format.toUpperCase()}`,label,true,data.length);
    showToast(`${label} exported (${data.length} rows) ✓`);
  }catch(e){
    showToast('Export error: '+e.message,'error');
    _logImport(`Export ${format.toUpperCase()}`,id,false);
  }
}

async function downloadImportTemplate(id){
  const templates={
    projects_import:{cols:['project_no','name','client','department','bac','pct','ac','ev','start_date','end_date','status'],sample:['SP360-NEW-001','New Project Name','Client Corp','Security',100000,25,25000,25000,'2026-01-01','2026-12-31','execution']},
    employees_import:{cols:['employee_no','full_name','department','position','employment_type','join_date'],sample:['EMP-100','John Smith','IT','Engineer','permanent','2026-01-01']},
    invoices_import:{cols:['invoice_no','invoice_type','client_name','net_amount','invoice_date','due_date','status'],sample:['INV-C-NEW-001','client','Client Corp',5000,'2026-09-01','2026-10-01','pending']},
    assets_import:{cols:['asset_name','category','serial_number','purchase_value','purchase_date','location','condition'],sample:['Generator Gen-01','Heavy Equipment','SN-12345',15000,'2026-01-01','Main Warehouse','good']},
  };
  const tpl=templates[id];
  if(!tpl){showToast('Template not available','error');return;}
  const wb=new ExcelJS.Workbook(); wb.creator='SP360 v4.1'; wb.created=new Date();
  const ws=wb.addWorksheet('Import Template');
  ws.addRow(['SP360 v4.1 — Import Template — '+id.replace(/_/g,' ')]).getCell(1).font={bold:true,color:{argb:'FF1E3A5F'},size:12};
  ws.addRow(['NOTE: Delete this row and the row above before importing. Do NOT change column headers.']);
  const hdr=ws.addRow(tpl.cols);
  hdr.eachCell(cell=>{cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF1E3A5F'}};cell.font={bold:true,color:{argb:'FFC9A84C'},name:'Calibri',size:10};cell.border=XL.thinBorder;});
  const sampleRow=ws.addRow(tpl.sample);
  sampleRow.eachCell(cell=>{cell.fill={type:'pattern',pattern:'solid',fgColor:{argb:'FFFFF3CD'}};cell.font={name:'Calibri',size:10,italic:true};});
  ws.columns=tpl.cols.map(()=>({width:20}));
  await xlSave(wb,`SP360_Template_${id}.xlsx`);
  showToast('Template downloaded ✓');
}

async function handleImportFile(file, importId){
  if(!file) return;
  const statusEl=document.getElementById('import-status-'+importId);
  if(statusEl) statusEl.textContent='⏳ Reading file…';

  try{
    // Read with ExcelJS
    const wb=new ExcelJS.Workbook();
    const arrayBuffer=await file.arrayBuffer();
    await wb.xlsx.load(arrayBuffer);
    const ws=wb.worksheets[0];
    const rows=[];
    ws.eachRow({includeEmpty:false},(row,ri)=>{
      if(ri<=3) return; // skip title + note + header rows
      const vals=[];
      row.eachCell({includeEmpty:true},cell=>{ vals.push(cell.value!=null?String(cell.value).trim():''); });
      if(vals.some(v=>v)) rows.push(vals);
    });

    if(!rows.length){showToast('No data rows found','error');return;}

    // Preview first 3 rows
    if(statusEl) statusEl.innerHTML=`<span style="color:#C9A84C">✓ Found ${esc(rows.length)} rows — review and confirm</span>`;

    openModal(`📥 Import Preview — ${importId.replace(/_/g,' ')}`,`
      <div style="margin-bottom:8px;font-size:11px;color:var(--muted)">First 3 rows of ${esc(rows.length)} total. Verify data before importing.</div>
      <div style="overflow-x:auto;max-height:200px;overflow-y:auto">
        <table style="font-size:10px"><tbody>
          ${rows.slice(0,3).map(r=>`<tr>${r.map(cell=>`<td style="padding:4px 8px;border:1px solid var(--bdr)">${esc(cell||'—')}</td>`).join('')}</tr>`).join('')}
        </tbody></table>
      </div>
      <div style="margin-top:10px;padding:8px;background:#F9731622;border:1px solid #F9731633;border-radius:6px;font-size:10px;color:#F97316">
        ⚠️ Import will attempt to upsert records. Existing records with same reference number will be updated.
        Always backup your data before bulk imports.
      </div>
      <div class="modal-foot">
        <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
        <button class="btn btn-primary" data-h-click="h373" data-ha-click="${esc(JSON.stringify([rows,String((importId)??'')]))}">✅ Confirm Import (${esc(rows.length)} rows)</button>
      </div>`);

  }catch(e){
    if(statusEl) statusEl.innerHTML=`<span style="color:#EF4444">✗ ${esc(e.message)}</span>`;
    showToast('File read error: '+e.message,'error');
  }
}

async function executeImport(rows, importId){
  showToast(`Importing ${rows.length} rows…`);
  let success=0, errors=0;

  for(const row of rows){
    try{
      if(importId==='projects_import'){
        const [projNo,name,client,dept,bac,pct,ac,ev,start,end,status]=row;
        if(!projNo||!name) continue;
        const cpi=Number(ac)>0?Number(ev)/Number(ac):1;
        const {error}=await sb.from('projects').upsert({project_no:projNo,name,client:client||null,department:dept||null,bac:Number(bac)||0,pct:Number(pct)||0,ac:Number(ac)||0,ev:Number(ev)||0,cpi:Number(cpi.toFixed(3)),start_date:start||null,end_date:end||null,status:status||'execution'},{onConflict:'project_no'});
        if(error){errors++;console.warn('Import error:',projNo,error.message);}else success++;
      } else if(importId==='employees_import'){
        const [empNo,fullName,dept,pos,empType,joinDate]=row;
        if(!empNo||!fullName) continue;
        const {error}=await sb.from('employees').upsert({employee_no:empNo,full_name:fullName,department:dept||null,position:pos||null,employment_type:empType||'permanent',join_date:joinDate||null,status:'active'},{onConflict:'employee_no'});
        if(error){errors++;} else success++;
      } else if(importId==='invoices_import'){
        const [invNo,type,client,amount,invDate,dueDate,status]=row;
        if(!invNo||!amount) continue;
        const {error}=await sb.from('invoices').upsert({invoice_no:invNo,invoice_type:type||'client',client_name:client||null,net_amount:Number(amount)||0,invoice_date:invDate||null,due_date:dueDate||null,status:status||'pending'},{onConflict:'invoice_no'});
        if(error){errors++;} else success++;
      } else if(importId==='assets_import'){
        const [name,cat,serial,val,purchDate,loc,cond]=row;
        if(!name) continue;
        const no=await nextRefNo('AST');
        const {error}=await sb.from('assets').insert({asset_no:no,asset_name:name,category:cat||'Other',serial_number:serial||null,purchase_value:Number(val)||0,book_value:Number(val)||0,purchase_date:purchDate||null,location:loc||null,condition:cond||'good',status:'active',created_by:currentProfile?.id});
        if(error){errors++;} else success++;
      }
    }catch(e){ errors++; }
  }

  _logImport('Import',importId,errors===0,success);
  showToast(`Import complete: ${success} success, ${errors} errors`);
  if(success>0) loadImportExport();
}

