async function openVariationOrderDetail(coId){
  const {data:co}=await sb.from('change_orders')
    .select('*,project:projects(project_no,name,bac,contract_value,client)')
    .eq('id',coId).single();
  if(!co) return;

  const {data:vos}=await sb.from('variation_order_items')
    .select('*').eq('co_id',coId).order('item_no');
  const items=vos||[];

  const totalLabor   =items.reduce((s,i)=>s+Number(i.labor_cost||0),0);
  const totalMaterial=items.reduce((s,i)=>s+Number(i.material_cost||0),0);
  const totalPlant   =items.reduce((s,i)=>s+Number(i.plant_cost||0),0);
  const totalOverhead=items.reduce((s,i)=>s+Number(i.overhead_cost||0),0);
  const totalVO      =items.reduce((s,i)=>s+Number(i.total_cost||0),0);

  openModal(`📋 Variation Order Detail — ${co.co_no}`,`
    <div style="display:grid;grid-template-columns:1fr 1fr 1fr;gap:8px;margin-bottom:12px">
      ${[['Project',co.project?.project_no||'—'],['Client',co.project?.client||'—'],
         ['VO Status',pill(co.status||'pending',co.status==='approved'?'#10B981':co.status==='rejected'?'#EF4444':'#F97316')],
         ['Original Contract',fmtKWD(co.project?.contract_value||0)],
         ['VO Amount',`<span style="font-weight:900;color:${Number(co.amount)>=0?'#C9A84C':'#EF4444'}">${fmtKWD(co.amount||0)}</span>`],
         ['Revised Contract',fmtKWD((Number(co.project?.contract_value||0))+(Number(co.amount||0)))]
      ].map(([l,v])=>`<div style="background:var(--n3);border-radius:6px;padding:8px">
        <div style="font-size:9px;color:var(--muted);font-weight:700;text-transform:uppercase">${l}</div>
        <div style="font-size:11px;color:var(--text);margin-top:2px">${v}</div>
      </div>`).join('')}
    </div>

    ${co.description?`<div style="padding:8px;background:var(--n3);border-radius:6px;font-size:11px;color:var(--muted);margin-bottom:12px"><b>Description:</b> ${esc(co.description)}</div>`:''}

    <!-- Cost Breakdown -->
    ${items.length>0?`
    <div style="font-size:11px;font-weight:700;color:var(--gold);margin-bottom:8px">Cost Breakdown</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin-bottom:12px">
      ${[['Labor',totalLabor,'#3B82F6'],['Materials',totalMaterial,'#10B981'],['Plant',totalPlant,'#F97316'],['Overhead',totalOverhead,'#8B5CF6']].map(([l,v,col])=>`
      <div style="background:${col}11;border:1px solid ${col}33;border-radius:6px;padding:8px;text-align:center">
        <div style="font-size:9px;color:var(--muted)">${l}</div>
        <div style="font-size:13px;font-weight:800;color:${col}">${fmtKWD(v)}</div>
      </div>`).join('')}
    </div>
    <table><thead><tr><th>#</th><th>Item Description</th><th>Unit</th><th style="text-align:right">Qty</th><th style="text-align:right">Rate</th><th style="text-align:right">Total</th></tr></thead><tbody>
    ${items.map(i=>`<tr>
      <td style="color:var(--gold);font-size:10px">${esc(i.item_no||'—')}</td>
      <td style="font-size:11px">${esc(i.description||'—')}</td>
      <td style="font-size:10px;color:var(--muted)">${esc(i.unit||'LS')}</td>
      <td style="text-align:right">${Number(i.quantity||1).toFixed(2)}</td>
      <td style="text-align:right">${fmtKWD(i.unit_rate||0)}</td>
      <td style="text-align:right;font-weight:700;color:var(--gold)">${fmtKWD(i.total_cost||0)}</td>
    </tr>`).join('')}
    <tr style="background:var(--n3)"><td colspan="5" style="font-weight:800;text-align:right;padding:8px">TOTAL VO AMOUNT:</td><td style="text-align:right;font-weight:900;font-size:13px;color:var(--gold)">${fmtKWD(totalVO)}</td></tr>
    </tbody></table>`:'<div class="empty">No cost items — add items for detailed breakdown</div>'}

    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
      ${can('create')?`<button class="btn btn-primary" data-h-click="h374" data-ha-click="${esc(JSON.stringify([String((coId)??''),String((co.co_no)??'')]))}">+ Add Item</button>`:''}
    </div>`);
}

