async function saveVOItem(e,coId,coNo){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const desc=document.getElementById('voi-desc').value.trim();
    if(!desc){showToast('Description required','error');return;}
    const qty=Number(document.getElementById('voi-qty').value)||1;
    const rate=Number(document.getElementById('voi-rate').value)||0;
    const labor=Number(document.getElementById('voi-labor').value)||0;
    const mat  =Number(document.getElementById('voi-mat').value)||0;
    const plant=Number(document.getElementById('voi-plant').value)||0;
    const oh   =Number(document.getElementById('voi-oh').value)||0;
    const total=rate>0?qty*rate:(labor+mat+plant+oh)||qty*rate;
    const {error}=await sb.from('variation_order_items').insert({
      co_id:coId, item_no:document.getElementById('voi-no').value.trim()||null,
      description:desc, unit:document.getElementById('voi-unit').value.trim()||'LS',
      quantity:qty, unit_rate:rate, total_cost:total,
      labor_cost:labor||null, material_cost:mat||null, plant_cost:plant||null, overhead_cost:oh||null,
      created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('VO item added ✓');
    openVariationOrderDetail(coId);
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Add Item';}}
}

