async function loadSiteDiary(tab='list'){
  const el=document.getElementById('page-sitediary');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Site Diary…</div>';
  try{
    const today=new Date().toISOString().split('T')[0];
    const [diaryR,projR]=await Promise.all([
      sb.from('site_diary').select('*,project:projects(project_no,name)').order('diary_date',{ascending:false}),
      sb.from('projects').select('id,project_no,name').in('status',ACTIVE_STATUSES).order('project_no')
    ]);
    const entries=diaryR.data||[], projs=projR.data||[];
    const thisWeek=entries.filter(e=>{ const d=new Date(e.diary_date); return (new Date()-d)/86400000<=7; });

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📔</span>
        <div><h1>Site Diary</h1><div class="sub">Daily Site Records · Weather · Labour · Activities · Issues</div></div>
      </div>
      <div style="display:flex;gap:8px">
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h376">+ Today's Entry</button>`:''}
      </div>
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total Entries',  entries.length,    '#C9A84C', 'All recorded')}
      ${kpi('This Week',      thisWeek.length,   '#3B82F6', 'Last 7 days')}
      ${kpi('Projects',       new Set(entries.map(e=>e.project_id).filter(Boolean)).size, '#10B981', 'With diary entries')}
      ${kpi('Today',          entries.filter(e=>e.diary_date===today).length, '#F97316', 'Entries for today')}
    </div>
    <div class="card">
      ${entries.length===0?'<div class="empty">No site diary entries yet — record today\'s activities</div>':`
      <table><thead><tr>
        <th>Date</th><th>Project</th><th>Weather</th><th>Labour</th>
        <th>Activities Summary</th><th>Issues</th><th style="text-align:center">Photos</th><th></th>
      </tr></thead><tbody>
      ${entries.map(e=>`<tr>
        <td style="font-weight:700;color:var(--gold);font-size:10px">${esc(e.diary_date||'—')}</td>
        <td style="font-size:10px;color:var(--gold)">${esc(e.project?.project_no||'General')}</td>
        <td style="font-size:10px">
          <span style="font-size:14px">${e.weather==='sunny'?'☀️':e.weather==='cloudy'?'⛅':e.weather==='rainy'?'🌧️':e.weather==='stormy'?'⛈️':e.weather==='sandstorm'?'🌪️':'—'}</span>
          ${esc(e.weather||'')}
          ${e.temperature?`<span style="color:var(--faint)">${esc(e.temperature)}°C</span>`:''}
        </td>
        <td style="font-size:10px;color:var(--muted)">${esc(e.total_labour||'—')} workers</td>
        <td style="font-size:10px;max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(e.activities_summary||'—')}</td>
        <td style="font-size:10px;color:${(e.issues_count||0)>0?'#EF4444':'var(--faint)'}">${(e.issues_count||0)>0?`⚠️ ${esc(e.issues_count)}`:'None'}</td>
        <td style="text-align:center;font-size:10px;color:var(--faint)">${esc(e.photos_count||0)}</td>
        <td><button data-h-click="h377" data-ha-click="${esc(JSON.stringify([String((e.id)??'')]))}" style="background:none;border:none;color:var(--gold);cursor:pointer;font-size:11px">👁</button></td>
      </tr>`).join('')}
      </tbody></table>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

