async function exportDiaryPDF(id){
  const {data:e}=await sb.from('site_diary').select('*,project:projects(project_no,name)').eq('id',id).single();
  if(!e) return;
  const {jsPDF}=window.jspdf;
  const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});
  doc.setFillColor(30,58,95); doc.rect(0,0,210,32,'F');
  doc.setTextColor(201,168,76); doc.setFontSize(16); doc.setFont('helvetica','bold');
  doc.text('SITE DIARY',14,13);
  doc.setTextColor(255,255,255); doc.setFontSize(11);
  doc.text(`${e.project?.project_no||'General'} · ${e.diary_date}`,14,22);
  doc.setTextColor(148,163,184); doc.setFontSize(9); doc.setFont('helvetica','normal');
  doc.text(`Weather: ${e.weather||'—'} ${e.temperature||''}°C · Labour: ${e.total_labour||'—'} · Issues: ${e.issues_count||0}`,14,29);
  let y=42;
  doc.setFontSize(10); doc.setFont('helvetica','bold'); doc.setTextColor(30,58,95);
  doc.text('ACTIVITIES PERFORMED',14,y); y+=7;
  doc.setFont('helvetica','normal'); doc.setTextColor(15,23,42); doc.setFontSize(9);
  doc.splitTextToSize(e.activities_summary||'—',178).forEach(l=>{doc.text(l,14,y);y+=5;});
  if(e.issues_description){ y+=4; doc.setFont('helvetica','bold'); doc.setTextColor(239,68,68); doc.text('ISSUES / DELAYS',14,y); y+=7;
    doc.setFont('helvetica','normal'); doc.setTextColor(15,23,42); doc.splitTextToSize(e.issues_description,178).forEach(l=>{doc.text(l,14,y);y+=5;}); }
  if(e.materials_delivered){ y+=4; doc.setFont('helvetica','bold'); doc.setTextColor(30,58,95); doc.text('MATERIALS DELIVERED',14,y); y+=7;
    doc.setFont('helvetica','normal'); doc.setTextColor(15,23,42); doc.text(e.materials_delivered,14,y); }
  doc.setFontSize(8); doc.setTextColor(148,163,184);
  doc.text(`SP360 v4.1 · Smart Projects 360 Kuwait · ${new Date().toLocaleDateString('en-GB')}`,105,290,'center');
  doc.save(`SiteDiary_${e.project?.project_no||'General'}_${e.diary_date}.pdf`);
  showToast('Diary PDF exported ✓');
}

// ══════════════════════════════════════════════════════════════
//  P11-3 · PUNCH LIST
// ══════════════════════════════════════════════════════════════
async function loadPunchList(tab='open'){
  const el=document.getElementById('page-punchlist');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Punch List…</div>';
  try{
    const today=new Date();
    const [punchR,projR]=await Promise.all([
      sb.from('punch_list').select('*,project:projects(project_no,name)').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name').in('status',ACTIVE_STATUSES).order('project_no')
    ]);
    const items=punchR.data||[], projs=projR.data||[];
    const open=items.filter(i=>i.status==='open');
    const inProgress=items.filter(i=>i.status==='in_progress');
    const closed=items.filter(i=>i.status==='closed');
    const overdue=items.filter(i=>i.status!=='closed'&&i.due_date&&new Date(i.due_date)<today);

    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='open'?' act':''}" data-h-click="h380" style="color:${open.length>0?'#F97316':'inherit'}">🔴 Open (${esc(open.length)})</button>
      <button class="tab${tab==='in_progress'?' act':''}" data-h-click="h381">🟡 In Progress (${esc(inProgress.length)})</button>
      <button class="tab${tab==='closed'?' act':''}" data-h-click="h382">✅ Closed (${esc(closed.length)})</button>
      <button class="tab${tab==='all'?' act':''}" data-h-click="h383">📋 All (${esc(items.length)})</button>
    </div>`;

    const list=tab==='open'?open:tab==='in_progress'?inProgress:tab==='closed'?closed:items;
    const catColors={'electrical':'#F97316','civil':'#8B5CF6','mechanical':'#3B82F6','finishing':'#10B981','safety':'#EF4444','other':'#94A3B8'};

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">📌</span>
        <div><h1>Punch List</h1><div class="sub">Defect Tracking · Snagging · Close-out Items</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h384">+ Add Item</button>`:''}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Open',       open.length,       open.length>0?'#EF4444':'#10B981', 'Require action')}
      ${kpi('In Progress',inProgress.length, '#F97316', 'Being addressed')}
      ${kpi('Closed',     closed.length,     '#10B981', 'Completed')}
      ${kpi('Overdue',    overdue.length,     overdue.length>0?'#EF4444':'#10B981', 'Past due date')}
    </div>
    <div class="card">
      ${tabBtns}
      ${list.length===0?`<div class="empty">No ${tab} punch list items</div>`:`
      <table><thead><tr>
        <th>Item No</th><th>Description</th><th>Category</th><th>Location</th>
        <th>Project</th><th>Priority</th><th>Due</th>
        <th style="text-align:center">Status</th><th></th>
      </tr></thead><tbody>
      ${list.map(i=>{
        const daysLeft=i.due_date?Math.ceil((new Date(i.due_date)-today)/86400000):null;
        const prioColor=i.priority==='critical'?'#EF4444':i.priority==='high'?'#F97316':i.priority==='medium'?'#C9A84C':'#94A3B8';
        return`<tr>
          <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(i.item_no||'—')}</td>
          <td style="font-size:11px;font-weight:600;max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(i.description||'—')}</td>
          <td><span style="font-size:9px;background:${(catColors[i.category]||'#94A3B8')}22;color:${catColors[i.category]||'#94A3B8'};border-radius:4px;padding:2px 6px;text-transform:capitalize">${esc(i.category||'other')}</span></td>
          <td style="font-size:10px;color:var(--muted)">${esc(i.location||'—')}</td>
          <td style="font-size:10px;color:var(--gold)">${esc(i.project?.project_no||'—')}</td>
          <td><span style="font-size:9px;background:${prioColor}22;color:${prioColor};border-radius:4px;padding:2px 6px;font-weight:700;text-transform:capitalize">${esc(i.priority||'low')}</span></td>
          <td style="font-size:10px;color:${daysLeft!==null&&daysLeft<0?'#EF4444':daysLeft!==null&&daysLeft<=3?'#F97316':'var(--faint)'};font-weight:700">
            ${esc(i.due_date||'—')}${daysLeft!==null&&i.status!=='closed'?`<br><span style="font-size:9px">${daysLeft<0?Math.abs(daysLeft)+'d late':daysLeft+'d'}</span>`:''}
          </td>
          <td style="text-align:center">${pill(i.status||'open',i.status==='closed'?'#10B981':i.status==='in_progress'?'#F97316':'#EF4444')}</td>
          <td style="white-space:nowrap">
            ${i.status!=='closed'?`<button data-h-click="h385" data-ha-click="${esc(JSON.stringify([String((i.id)??''),String((i.status==='open'?'in_progress':'closed')??''),String((tab)??'')]))}" style="background:none;border:none;color:${i.status==='open'?'#F97316':'#10B981'};cursor:pointer;font-size:12px" title="${i.status==='open'?'Start':'Close'}">${i.status==='open'?'▶':'✅'}</button>`:''}
          </td>
        </tr>`;}).join('')}
      </tbody></table>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

function openNewPunchModal(){
  const projs=window._cachedProjects||[];
  const today=new Date(); today.setDate(today.getDate()+7);
  const dueDefault=today.toISOString().split('T')[0];
  openModal('📌 Add Punch List Item',`
    <div class="form-row">
      <div class="form-field"><label>Description *</label><input id="pl-desc" placeholder="Describe the defect or incomplete work"/></div>
      <div class="form-field"><label>Category *</label>
        <select id="pl-cat" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          ${['electrical','civil','mechanical','finishing','safety','other'].map(c=>`<option value="${c}">${c.charAt(0).toUpperCase()+c.slice(1)}</option>`).join('')}
        </select>
      </div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Project</label>
        <select id="pl-proj" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="">— Select —</option>
          ${projs.map(p=>`<option value="${esc(p.id)}">${esc(p.project_no)}</option>`).join('')}
        </select>
      </div>
      <div class="form-field"><label>Location / Zone</label><input id="pl-loc" placeholder="e.g. Floor 2 — Room 201"/></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Priority</label>
        <select id="pl-prio" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="low">Low</option><option value="medium">Medium</option>
          <option value="high">High</option><option value="critical">Critical</option>
        </select>
      </div>
      <div class="form-field"><label>Due Date</label><input id="pl-due" type="date" value="${dueDefault}"/></div>
    </div>
    <div class="form-field"><label>Responsible Party</label><input id="pl-resp" placeholder="Subcontractor or team responsible"/></div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h386">Add Item</button>
    </div>`);
}

async function savePunchItem(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const desc=document.getElementById('pl-desc').value.trim();
    if(!desc){showToast('Description required','error');return;}
    const no=await nextRefNo('PL');
    const {error}=await sb.from('punch_list').insert({
      item_no:no, description:desc,
      category:document.getElementById('pl-cat').value,
      project_id:document.getElementById('pl-proj').value||null,
      location:document.getElementById('pl-loc').value.trim()||null,
      priority:document.getElementById('pl-prio').value,
      due_date:document.getElementById('pl-due').value||null,
      responsible_party:document.getElementById('pl-resp').value.trim()||null,
      status:'open', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast(no+' added ✓'); closeModal(); loadPunchList('open');
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Add Item';}}
}

async function updatePunchStatus(id, newStatus, tab){
  const {error}=await sb.from('punch_list').update({
    status:newStatus,
    closed_at:newStatus==='closed'?new Date().toISOString():null,
    closed_by:newStatus==='closed'?currentProfile?.id:null
  }).eq('id',id);
  if(error){showToast('Error: '+error.message,'error');return;}
  showToast(newStatus==='closed'?'Item closed ✓':'Item started ✓');
  loadPunchList(tab||'open');
}

// ══════════════════════════════════════════════════════════════
//  P11-4 · INVOICE MATCHING
//  Match supplier invoices against POs and MRVs
// ══════════════════════════════════════════════════════════════
async function openInvoiceMatchingModal(invoiceId){
  const [{data:inv},{data:pos}]=await Promise.all([
    sb.from('invoices').select('*,vendor:vendors(vendor_name)').eq('id',invoiceId).single(),
    sb.from('purchase_orders').select('id,po_no,total_amount,status,vendor_id').eq('status','approved').order('po_no')
  ]);
  if(!inv) return;
  const vendorPOs=(pos||[]).filter(p=>p.vendor_id===inv.vendor_id);

  openModal(`🔗 Invoice Matching — ${inv.invoice_no}`,`
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-bottom:14px">
      <div style="padding:12px;background:var(--n3);border-radius:8px">
        <div style="font-size:10px;font-weight:700;color:var(--gold);margin-bottom:8px">INVOICE</div>
        <div style="font-size:12px;font-weight:700">${esc(inv.invoice_no)}</div>
        <div style="font-size:11px;color:var(--muted)">${esc(inv.vendor?.vendor_name||'—')}</div>
        <div style="font-size:16px;font-weight:900;color:var(--gold);margin-top:6px">${fmtKWD(inv.net_amount||0)}</div>
        <div style="font-size:9px;color:var(--faint)">${esc(inv.invoice_date||'—')}</div>
      </div>
      <div style="padding:12px;background:var(--n3);border-radius:8px">
        <div style="font-size:10px;font-weight:700;color:var(--gold);margin-bottom:8px">MATCHING STATUS</div>
        ${inv.po_id?`<div style="color:#10B981;font-weight:700;font-size:12px">✅ Matched to PO</div><div style="font-size:10px;color:var(--muted)">PO ID: ${esc(inv.po_id)}</div>`:
        `<div style="color:#F97316;font-weight:700;font-size:12px">⚠️ Not matched to PO</div><div style="font-size:10px;color:var(--muted)">Select a PO below to match</div>`}
      </div>
    </div>

    ${vendorPOs.length>0?`
    <div style="font-size:11px;font-weight:700;color:var(--gold);margin-bottom:8px">Matching POs from same vendor:</div>
    ${vendorPOs.map(po=>`
    <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:${inv.po_id===po.id?'#10B98111':'var(--n3)'};border:1px solid ${inv.po_id===po.id?'#10B98133':'var(--bdr)'};border-radius:6px;margin-bottom:6px">
      <div style="flex:1">
        <div style="font-size:11px;font-weight:700;color:var(--gold)">${esc(po.po_no)}</div>
        <div style="font-size:10px;color:var(--muted)">${fmtKWD(po.total_amount||0)} · ${esc(po.status)}</div>
      </div>
      <div style="text-align:right;font-size:10px;color:${Math.abs(Number(inv.net_amount)-Number(po.total_amount))/Math.max(Number(po.total_amount),1)<0.1?'#10B981':'#F97316'}">
        ${Math.abs(Number(inv.net_amount)-Number(po.total_amount))/Math.max(Number(po.total_amount),1)<0.01?'✅ Exact match':
          Math.abs(Number(inv.net_amount)-Number(po.total_amount))/Math.max(Number(po.total_amount),1)<0.1?'≈ Close match':'⚠️ Amount differs'}
      </div>
      ${inv.po_id!==po.id?`<button data-h-click="h387" data-ha-click="${esc(JSON.stringify([String((invoiceId)??''),String((po.id)??''),String((po.po_no)??'')]))}" class="btn btn-primary btn-sm" style="font-size:9px">Link</button>`:'<span style="font-size:10px;color:#10B981;font-weight:700">Linked ✓</span>'}
    </div>`).join('')}`:'<div class="empty">No approved POs found for this vendor</div>'}

    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Close</button>
    </div>`);
}

async function matchInvoiceToPO(invoiceId, poId, poNo){
  const {error}=await sb.from('invoices').update({po_id:poId,updated_at:new Date().toISOString()}).eq('id',invoiceId);
  if(error){showToast('Error: '+error.message,'error');return;}
  await writeAudit('invoices',invoiceId,'INVOICE_MATCHED',{po_id:null},{po_id:poId},'Invoice matched to '+poNo);
  showToast('Invoice matched to '+poNo+' ✓');
  const invModal=document.querySelector('.modal-content');
  if(invModal) openInvoiceMatchingModal(invoiceId);
}

// ══════════════════════════════════════════════════════════════
//  P11-5 · EMPLOYEE EXPENSES
// ══════════════════════════════════════════════════════════════
async function loadExpenses(tab='pending'){
  const el=document.getElementById('page-expenses');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Expenses…</div>';
  try{
    const [expR,empR]=await Promise.all([
      sb.from('employee_expenses').select('*,employee:employees(full_name,employee_no,department)').order('expense_date',{ascending:false}),
      sb.from('employees').select('id,full_name,employee_no,department').eq('status','active').order('full_name')
    ]);
    const exps=expR.data||[], emps=empR.data||[];
    const pending  =exps.filter(e=>e.status==='pending');
    const approved =exps.filter(e=>e.status==='approved');
    const rejected =exps.filter(e=>e.status==='rejected');
    const paid     =exps.filter(e=>e.status==='paid');
    const totalPending=pending.reduce((s,e)=>s+Number(e.amount||0),0);
    const totalPaid   =paid.reduce((s,e)=>s+Number(e.amount||0),0);

    const list=tab==='pending'?pending:tab==='approved'?approved:tab==='rejected'?rejected:tab==='paid'?paid:exps;
    const tabBtns=`<div class="tabs">
      <button class="tab${tab==='pending'?' act':''}" data-h-click="h388" style="color:${pending.length>0?'#F97316':'inherit'}">⏳ Pending (${esc(pending.length)})</button>
      <button class="tab${tab==='approved'?' act':''}" data-h-click="h389">✅ Approved (${esc(approved.length)})</button>
      <button class="tab${tab==='paid'?' act':''}" data-h-click="h390">💳 Paid (${esc(paid.length)})</button>
      <button class="tab${tab==='all'?' act':''}" data-h-click="h391">📋 All (${esc(exps.length)})</button>
    </div>`;

    const catColors={'travel':'#3B82F6','meals':'#10B981','accommodation':'#8B5CF6','equipment':'#F97316','training':'#C9A84C','other':'#94A3B8'};

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🧾</span>
        <div><h1>Employee Expenses</h1><div class="sub">Claims · Approvals · Reimbursements</div></div>
      </div>
      <div style="display:flex;gap:8px">
        ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h392">+ Submit Expense</button>`:''}
      </div>
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Pending Claims',   pending.length,     '#F97316', fmtKWD(totalPending)+' total')}
      ${kpi('Approved',         approved.length,    '#10B981', 'Ready to pay')}
      ${kpi('Total Paid',       fmtKWD(totalPaid),  '#C9A84C', 'Reimbursed')}
      ${kpi('Employees',        new Set(exps.map(e=>e.employee_id)).size, '#3B82F6', 'With claims')}
    </div>
    <div class="card">
      ${tabBtns}
      ${list.length===0?`<div class="empty">No ${tab} expense claims</div>`:`
      <table><thead><tr>
        <th>Ref</th><th>Employee</th><th>Category</th><th>Description</th>
        <th>Date</th><th style="text-align:right">Amount</th>
        <th style="text-align:center">Status</th><th></th>
      </tr></thead><tbody>
      ${list.map(exp=>`<tr>
        <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(exp.expense_no||'—')}</td>
        <td style="font-weight:600;font-size:11px">${esc(exp.employee?.full_name||'—')}</td>
        <td><span style="font-size:9px;background:${(catColors[exp.category]||'#94A3B8')}22;color:${catColors[exp.category]||'#94A3B8'};border-radius:4px;padding:2px 6px;text-transform:capitalize">${esc(exp.category||'other')}</span></td>
        <td style="font-size:10px;color:var(--muted);max-width:180px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${esc(exp.description||'—')}</td>
        <td style="font-size:10px;color:var(--faint)">${esc(exp.expense_date||'—')}</td>
        <td style="text-align:right;font-weight:700;color:var(--gold)">${fmtKWD(exp.amount||0)}</td>
        <td style="text-align:center">${pill(exp.status||'pending',exp.status==='paid'?'#10B981':exp.status==='approved'?'#3B82F6':exp.status==='rejected'?'#EF4444':'#F97316')}</td>
        <td style="white-space:nowrap">
          ${can('approve')&&exp.status==='pending'?`
          <button data-h-click="h393" data-ha-click="${esc(JSON.stringify([String((exp.id)??''),String((tab)??'')]))}" style="background:none;border:none;color:#10B981;cursor:pointer;font-size:12px" title="Approve">✅</button>
          <button data-h-click="h394" data-ha-click="${esc(JSON.stringify([String((exp.id)??''),String((tab)??'')]))}" style="background:none;border:none;color:#EF4444;cursor:pointer;font-size:12px" title="Reject">✗</button>`:''}
          ${can('approve')&&exp.status==='approved'?`<button data-h-click="h395" data-ha-click="${esc(JSON.stringify([String((exp.id)??''),String((tab)??'')]))}" style="background:none;border:none;color:#C9A84C;cursor:pointer;font-size:10px;font-weight:700" title="Mark Paid">PAY</button>`:''}
        </td>
      </tr>`).join('')}
      </tbody></table>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

