const DASHBOARD_WIDGETS = [
  {id:'kpi_row1',      label:'KPI Row 1 (Portfolio Value, CPI, SPI, GP)',  default:true},
  {id:'kpi_row2',      label:'KPI Row 2 (AR, Approvals, NCRs, BAC)',       default:true},
  {id:'perf_gauges',   label:'Performance Gauge Charts (CPI/SPI)',          default:true},
  {id:'status_donut',  label:'Project Status Donut Chart',                 default:true},
  {id:'rag_donut',     label:'Portfolio RAG Status Donut',                  default:true},
  {id:'scurve',        label:'Portfolio S-Curve (EVM)',                     default:true},
  {id:'finance_chart', label:'Finance Overview Bar Chart',                  default:true},
  {id:'dept_chart',    label:'BAC by Department Chart',                     default:true},
  {id:'evm_table',     label:'Project EVM Summary Table',                  default:true},
  {id:'approval_queue',label:'Approval Queue',                              default:true},
];

function getDashboardPrefs(){
  const saved=localStorage.getItem('sp360_dashboard_prefs');
  if(saved) return JSON.parse(saved);
  const defaults={};
  DASHBOARD_WIDGETS.forEach(w=>{ defaults[w.id]=w.default; });
  return defaults;
}

function openDashboardCustomizer(){
  const prefs=getDashboardPrefs();
  openModal('⚙️ Customize Dashboard',`
    <div style="font-size:11px;color:var(--muted);margin-bottom:12px">
      Choose which widgets to show on your dashboard. Changes apply immediately.
    </div>
    <div style="display:flex;flex-direction:column;gap:8px">
      ${DASHBOARD_WIDGETS.map(w=>`
      <div style="display:flex;align-items:center;gap:10px;padding:8px 10px;background:var(--n3);border-radius:6px">
        <input type="checkbox" id="dw-${esc(w.id)}" ${prefs[w.id]!==false?'checked':''}
          style="width:16px;height:16px;accent-color:#C9A84C;cursor:pointer"/>
        <label for="dw-${esc(w.id)}" style="font-size:11px;color:var(--text);cursor:pointer;flex:1">${esc(w.label)}</label>
      </div>`).join('')}
    </div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-ghost btn-sm" data-h-click="h401">Reset</button>
      <button class="btn btn-primary" data-h-click="h402">Apply</button>
    </div>`);
}

function saveDashboardPrefs(){
  const prefs={};
  DASHBOARD_WIDGETS.forEach(w=>{
    const cb=document.getElementById('dw-'+w.id);
    if(cb) prefs[w.id]=cb.checked;
  });
  localStorage.setItem('sp360_dashboard_prefs',JSON.stringify(prefs));
  showToast('Dashboard preferences saved ✓');
  closeModal();
  loadDashboard();
}

function resetDashboardPrefs(){
  localStorage.removeItem('sp360_dashboard_prefs');
  showToast('Dashboard reset to defaults ✓');
  closeModal();
  loadDashboard();
}

// Apply prefs to hide/show sections — called inside loadDashboard
function applyDashboardPrefs(html){
  const prefs=getDashboardPrefs();
  // Widget IDs map to section IDs in the rendered HTML
  if(prefs.kpi_row2===false) html=html.replace(/<!-- WIDGET:kpi_row2 -->[\s\S]*?<!-- \/WIDGET:kpi_row2 -->/,'');
  return html;
}

