async function createFromTemplate(e, templateId){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Creating…';}
  try{
    const t=PROJECT_TEMPLATES.find(x=>x.id===templateId);
    const name=document.getElementById('tpl-name').value.trim();
    const client=document.getElementById('tpl-client').value.trim();
    const val=Number(document.getElementById('tpl-val').value);
    if(!name||!client||!val){showToast('Name, client and value required','error');return;}
    const no=await nextRefNo('SP360');
    const {data:proj,error}=await sb.from('projects').insert({
      project_no:no, name, client,
      department:t.defaults.department,
      status:t.defaults.status,
      contract_value:val, bac:val,
      start_date:document.getElementById('tpl-start').value||null,
      end_date:document.getElementById('tpl-end').value||null,
      pct:0, cpi:1, ev:0, ac:0, pv:0,
      created_by:currentProfile?.id
    }).select('id').single();
    if(error){showToast('Error: '+error.message,'error');return;}

    // Create tasks from template
    if(proj?.id&&t.tasks.length>0){
      const taskInserts=t.tasks.map((task,i)=>({
        project_id:proj.id, task_no:`T${String(i+1).padStart(2,'0')}`,
        title:task, status:'pending', pct:0,
        created_by:currentProfile?.id
      }));
      await sb.from('project_tasks').insert(taskInserts);
    }

    await writeAudit('projects',proj?.id,'PROJECT_CREATED_FROM_TEMPLATE',null,{project_no:no,template:templateId},'Project created from template');
    showToast(`${no} created with ${t.tasks.length} tasks ✓`);
    closeModal();
    navTo('projects',document.getElementById('nav-projects'));
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Create Project';}}
}

async function generateDocTemplate(templateName){
  const {jsPDF}=window.jspdf;
  const doc=new jsPDF({orientation:'portrait',unit:'mm',format:'a4'});
  const today=new Date().toLocaleDateString('en-GB',{day:'numeric',month:'long',year:'numeric'});

  doc.setFillColor(30,58,95); doc.rect(0,0,210,38,'F');
  doc.setTextColor(201,168,76); doc.setFontSize(16); doc.setFont('helvetica','bold');
  doc.text(templateName.toUpperCase(),14,16);
  doc.setTextColor(255,255,255); doc.setFontSize(10); doc.setFont('helvetica','normal');
  doc.text('Smart Projects 360 · Kuwait',14,25);
  doc.text(`Document No: ___________    Date: ${today}`,14,32);

  let y=48;
  const addSection=(title,fields)=>{
    if(y>250){doc.addPage();y=20;}
    doc.setFillColor(241,245,249); doc.rect(14,y-5,182,8,'F');
    doc.setTextColor(30,58,95); doc.setFont('helvetica','bold'); doc.setFontSize(10);
    doc.text(title,16,y); y+=10;
    fields.forEach(f=>{
      doc.setFont('helvetica','normal'); doc.setTextColor(71,85,105); doc.setFontSize(9);
      doc.text(f+':',16,y); doc.setTextColor(15,23,42);
      doc.setDrawColor(200,210,220); doc.line(50,y+1,196,y+1);
      y+=8;
    });
    y+=4;
  };

  if(templateName==='Project Charter'){
    addSection('PROJECT INFORMATION',['Project No','Project Name','Client','Department','Project Manager']);
    addSection('SCOPE & OBJECTIVES',['Scope Summary','Key Deliverables','Exclusions']);
    addSection('TIMELINE & BUDGET',['Start Date','Planned Completion','Contract Value (KWD)','Contingency (KWD)']);
    addSection('AUTHORIZATION',['Prepared by','Reviewed by','Approved by (PMO)','Client Signature']);
  } else if(templateName==='Transmittal Letter'){
    addSection('TRANSMITTAL DETAILS',['To (Name/Title)','Organization','Project','Transmittal No']);
    addSection('DOCUMENT LIST',['Document No','Document Title','Revision','Copies']);
    addSection('REMARKS',['Purpose','Action Required','Response Required by']);
    addSection('AUTHORIZATION',['Transmitted by','Date','Signature']);
  } else if(templateName==='Handover Certificate'){
    addSection('PROJECT DETAILS',['Project No','Project Name','Contract Value (KWD)','Completion Date']);
    addSection('SCOPE CONFIRMATION',['Scope Completed','Punch List Items','Outstanding Issues']);
    addSection('FINANCIAL SUMMARY',['Final Account Value','Retention Amount','Retention Release Date']);
    addSection('SIGNATORIES',['Contractor Representative','Client Representative','Date of Handover']);
  } else {
    addSection('GENERAL INFORMATION',['Project','Prepared by','Date','Reference']);
    addSection('DETAILS',['Description','Scope','Notes','Action Required']);
    addSection('AUTHORIZATION',['Prepared by','Approved by','Date']);
  }

  doc.setFontSize(8); doc.setTextColor(148,163,184);
  const pages=doc.getNumberOfPages();
  for(let i=1;i<=pages;i++){
    doc.setPage(i);
    doc.text(`SP360 v4.1 · ${templateName} Template · Page ${i}/${pages} · Confidential`,105,290,'center');
  }

  doc.save(`SP360_Template_${templateName.replace(/\s+/g,'_')}.pdf`);
  showToast(`${templateName} template downloaded ✓`);
}

