// Previously referenced but never defined (button threw ReferenceError) — implemented.
async function applyCustomTemplate(id){
  try{
    const {data:row,error}=await sb.from('project_templates').select('*').eq('id',id).single();
    if(error||!row) throw error||new Error('Template not found');
    let tasks=row.tasks??row.template_data?.tasks??row.task_list??[];
    if(typeof tasks==='string'){ try{ tasks=JSON.parse(tasks); }catch(_){ tasks=tasks.split(/\r?\n/); } }
    tasks=(Array.isArray(tasks)?tasks:[]).map(t=>typeof t==='string'?t:(t?.title||t?.name||'')).map(t=>String(t).trim()).filter(Boolean);
    const tid='custom-'+row.id;
    const tpl={id:tid,name:row.template_name||row.name||'Custom Template',icon:'📁',color:'#C9A84C',
      defaults:{department:row.department||row.template_data?.department||null,status:row.status||'planning'},tasks};
    const ix=PROJECT_TEMPLATES.findIndex(x=>x.id===tid);
    if(ix>=0) PROJECT_TEMPLATES[ix]=tpl; else PROJECT_TEMPLATES.push(tpl);
    applyProjectTemplate(tid);
  }catch(e){ showToast('Template error: '+(e?.message||e),'error'); }
}

async function deleteCustomTemplate(id){
  if(!confirm('Delete this template?')) return;
  await sb.from('project_templates').delete().eq('id',id);
  showToast('Template deleted'); loadTemplates();
}

