//  P12-3 · SLA MANAGEMENT
// ══════════════════════════════════════════════════════════════
async function loadSLA(){
  const el=document.getElementById('page-sla');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading SLA…</div>';
  try{
    const today=new Date();
    const [slaR,wfR]=await Promise.all([
      sb.from('sla_definitions').select('*').order('priority'),
      sb.from('workflow_items').select('id,ref_no,entity_type,status,created_at,due_date,current_step').order('created_at',{ascending:false}).limit(200)
    ]);
    const slas=slaR.data||[], wfs=wfR.data||[];

    // Default SLAs if none defined
    const defaultSLAs=[
      {id:'def1',entity_type:'purchase_order',   sla_name:'PO Approval',           target_hours:24,  escalation_hours:48,  priority:1},
      {id:'def2',entity_type:'invoice',           sla_name:'Invoice Review',        target_hours:48,  escalation_hours:72,  priority:2},
      {id:'def3',entity_type:'change_order',      sla_name:'Change Order Review',   target_hours:72,  escalation_hours:120, priority:3},
      {id:'def4',entity_type:'document_review',   sla_name:'Document Review',       target_hours:48,  escalation_hours:96,  priority:2},
      {id:'def5',entity_type:'rfq',               sla_name:'RFQ Response',          target_hours:168, escalation_hours:240, priority:4},
    ];
    const activeSLAs=slas.length>0?slas:defaultSLAs;

    // Calculate compliance per type
    const slaCompliance=activeSLAs.map(sla=>{
      const typeWFs=wfs.filter(w=>w.entity_type===sla.entity_type||sla.entity_type==='*');
      const targetMs=sla.target_hours*3600000;
      const compliant=typeWFs.filter(w=>{
        if(!w.created_at) return true;
        const age=today-new Date(w.created_at);
        return w.status==='approved'||w.status==='rejected'||age<=targetMs;
      }).length;
      const breach=typeWFs.filter(w=>{
        if(!w.created_at) return false;
        const age=today-new Date(w.created_at);
        return (w.status==='pending'||w.status==='overdue')&&age>targetMs;
      });
      const pct=typeWFs.length>0?Math.round(compliant/typeWFs.length*100):100;
      return {...sla, total:typeWFs.length, compliant, breach:breach.length, pct};
    });

    const overallPct=wfs.length>0?Math.round(wfs.filter(w=>w.status!=='overdue').length/wfs.length*100):100;
    const totalBreaches=slaCompliance.reduce((s,x)=>s+x.breach,0);

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">⏱</span>
        <div><h1>SLA Management</h1><div class="sub">Service Level Agreements · Compliance Tracking · Breach Alerts</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h410">+ Define SLA</button>`:''}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Overall SLA', overallPct+'%', overallPct>=90?'#10B981':overallPct>=75?'#F97316':'#EF4444', 'Compliance rate')}
      ${kpi('Total Items',  wfs.length,    '#C9A84C', 'Workflow items tracked')}
      ${kpi('SLA Breaches', totalBreaches, totalBreaches>0?'#EF4444':'#10B981', 'Items over target')}
      ${kpi('SLA Rules',    activeSLAs.length, '#3B82F6', 'Defined rules')}
    </div>

    <!-- Compliance per type -->
    <div class="card" style="margin-bottom:14px">
      <div class="sec-head"><div class="sec-title"><span>📊</span>SLA Compliance by Type</div></div>
      ${slaCompliance.map(sla=>`
      <div style="margin-bottom:12px">
        <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px">
          <div>
            <span style="font-size:11px;font-weight:700;color:var(--text)">${esc(sla.sla_name)}</span>
            <span style="font-size:9px;color:var(--muted);margin-left:6px">Target: ${esc(sla.target_hours)}h</span>
          </div>
          <div style="text-align:right">
            <span style="font-size:13px;font-weight:900;color:${sla.pct>=90?'#10B981':sla.pct>=75?'#F97316':'#EF4444'}">${esc(sla.pct)}%</span>
            ${sla.breach>0?`<span style="font-size:9px;color:#EF4444;margin-left:6px">⚠️ ${esc(sla.breach)} breach(es)</span>`:''}
          </div>
        </div>
        <div style="background:var(--bdr);border-radius:4px;height:8px;overflow:hidden">
          <div style="height:100%;width:${esc(sla.pct)}%;background:${sla.pct>=90?'#10B981':sla.pct>=75?'#F97316':'#EF4444'};border-radius:4px;transition:width .3s"></div>
        </div>
        <div style="font-size:9px;color:var(--faint);margin-top:2px">${esc(sla.total)} items · ${esc(sla.compliant)} compliant · ${esc(sla.breach)} breached</div>
      </div>`).join('')}
    </div>

    <!-- Breach details -->
    ${totalBreaches>0?`
    <div class="card" style="border-left:3px solid #EF4444">
      <div class="sec-head"><div class="sec-title"><span>🚨</span>SLA Breaches — Immediate Action Required</div></div>
      <table><thead><tr><th>Ref</th><th>Type</th><th>Step</th><th>Age</th><th>Target</th><th style="text-align:center">Status</th></tr></thead><tbody>
      ${wfs.filter(w=>{
        const sla=activeSLAs.find(s=>s.entity_type===w.entity_type);
        if(!sla||!w.created_at) return false;
        return (w.status==='pending'||w.status==='overdue')&&(today-new Date(w.created_at))>sla.target_hours*3600000;
      }).slice(0,15).map(w=>{
        const sla=activeSLAs.find(s=>s.entity_type===w.entity_type)||{target_hours:48};
        const ageH=Math.round((today-new Date(w.created_at))/3600000);
        return`<tr>
          <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(w.ref_no||'—')}</td>
          <td style="font-size:10px">${esc(w.entity_type||'—')}</td>
          <td style="font-size:10px;color:var(--muted)">${esc(w.current_step||'—')}</td>
          <td style="font-size:10px;color:#EF4444;font-weight:700">${ageH}h</td>
          <td style="font-size:10px;color:var(--faint)">${esc(sla.target_hours)}h limit</td>
          <td style="text-align:center">${pill('Breached','#EF4444')}</td>
        </tr>`;}).join('')}
      </tbody></table>
    </div>`:'<div class="card" style="text-align:center;padding:20px;border-left:3px solid #10B981"><div style="font-size:24px;margin-bottom:6px">✅</div><div style="font-size:13px;font-weight:700;color:#10B981">No SLA Breaches</div><div style="font-size:11px;color:var(--muted)">All workflow items within target response times</div></div>'}`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

