async function loadRetention(){
  const el=document.getElementById('page-retention');
  if(!el) return;
  el.innerHTML='<div class="loading">Loading Retention…</div>';
  try{
    const today=new Date();
    const [retR,projR]=await Promise.all([
      sb.from('retention_records').select('*,project:projects(project_no,name,client,contract_value)').order('created_at',{ascending:false}),
      sb.from('projects').select('id,project_no,name,client,contract_value,status').in('status',[...ACTIVE_STATUSES,'completed']).order('project_no')
    ]);
    const rets=retR.data||[], projs=projR.data||[];

    const totalHeld=rets.filter(r=>r.status==='held').reduce((s,r)=>s+Number(r.amount||0),0);
    const totalReleased=rets.filter(r=>r.status==='released').reduce((s,r)=>s+Number(r.amount||0),0);
    const dueSoon=rets.filter(r=>r.status==='held'&&r.release_date&&Math.ceil((new Date(r.release_date)-today)/86400000)<=30);

    el.innerHTML=`
    <div class="page-head">
      <div class="page-head-left"><span style="font-size:22px">🔒</span>
        <div><h1>Retention Management</h1><div class="sub">Deferred Payments · Release Tracking · Cash Flow Impact</div></div>
      </div>
      ${can('create')?`<button class="btn btn-primary btn-sm" data-h-click="h412">+ Add Retention</button>`:''}
    </div>
    <div class="grid4" style="margin-bottom:14px">
      ${kpi('Total Held',      fmtKWD(totalHeld),     '#F97316', 'Retention withheld')}
      ${kpi('Total Released',  fmtKWD(totalReleased),  '#10B981', 'Paid out')}
      ${kpi('Due ≤30 Days',    dueSoon.length,          dueSoon.length>0?'#C9A84C':'#10B981', 'Release expected')}
      ${kpi('Records',         rets.length,              '#3B82F6', 'All retention entries')}
    </div>

    ${dueSoon.length>0?`
    <div class="card" style="margin-bottom:14px;border-left:3px solid #C9A84C">
      <div class="sec-head"><div class="sec-title"><span>📅</span>Retention Due for Release (≤30 days)</div></div>
      ${dueSoon.map(r=>{
        const daysLeft=Math.ceil((new Date(r.release_date)-today)/86400000);
        return`<div style="display:flex;align-items:center;gap:10px;padding:7px 0;border-bottom:1px solid var(--bdr)">
          <div style="flex:1">
            <div style="font-size:11px;font-weight:700;color:var(--gold)">${esc(r.project?.project_no||'—')} — ${esc(r.retention_type||'—')}</div>
            <div style="font-size:10px;color:var(--muted)">${esc(r.project?.client||'—')}</div>
          </div>
          <div style="text-align:right">
            <div style="font-size:13px;font-weight:700;color:var(--gold)">${fmtKWD(r.amount||0)}</div>
            <div style="font-size:9px;color:${daysLeft<=7?'#EF4444':'#C9A84C'}">${daysLeft}d left</div>
          </div>
          ${can('edit')?`<button data-h-click="h413" data-ha-click="${esc(JSON.stringify([String((r.id)??'')]))}" class="btn btn-primary btn-sm" style="font-size:9px">Release</button>`:''}
        </div>`;}).join('')}
    </div>`:''}

    <div class="card">
      <div class="sec-head"><div class="sec-title"><span>📋</span>All Retention Records</div></div>
      ${rets.length===0?'<div class="empty">No retention records. Add retention when issuing invoices.</div>':`
      <div style="overflow-x:auto">
        <table><thead><tr>
          <th>Project</th><th>Client</th><th>Type</th>
          <th style="text-align:right">Amount</th><th style="text-align:right">%</th>
          <th>Due Date</th><th style="text-align:center">Status</th><th></th>
        </tr></thead><tbody>
        ${rets.map(r=>{
          const daysLeft=r.release_date?Math.ceil((new Date(r.release_date)-today)/86400000):null;
          return`<tr>
            <td style="color:var(--gold);font-weight:700;font-size:10px">${esc(r.project?.project_no||'—')}</td>
            <td style="font-size:10px;color:var(--muted)">${esc(r.project?.client||r.client_name||'—')}</td>
            <td><span style="font-size:9px;background:${r.retention_type==='AR'?'#10B98122':'#3B82F622'};color:${r.retention_type==='AR'?'#10B981':'#3B82F6'};border-radius:4px;padding:2px 6px">${esc(r.retention_type||'—')}</span></td>
            <td style="text-align:right;font-weight:700;color:var(--gold)">${fmtKWD(r.amount||0)}</td>
            <td style="text-align:right;color:var(--muted)">${esc(r.pct||'—')}%</td>
            <td style="font-size:10px;color:${daysLeft!==null&&r.status==='held'&&daysLeft<=30?'#C9A84C':'var(--faint)'};font-weight:${daysLeft!==null&&daysLeft<=30?'700':'400'}">
              ${esc(r.release_date||'—')}${daysLeft!==null&&r.status==='held'?`<br><span style="font-size:9px">${daysLeft<0?'Overdue':daysLeft+'d'}</span>`:''}
            </td>
            <td style="text-align:center">${pill(r.status||'held',r.status==='released'?'#10B981':r.status==='partial'?'#3B82F6':'#F97316')}</td>
            <td>${r.status==='held'&&can('edit')?`<button data-h-click="h413" data-ha-click="${esc(JSON.stringify([String((r.id)??'')]))}" style="background:none;border:none;color:#10B981;cursor:pointer;font-size:11px" title="Release">✅</button>`:''}
            </td>
          </tr>`;}).join('')}
        </tbody></table>
      </div>`}
    </div>`;
  }catch(err){ el.innerHTML=`<div class="empty">Error: ${esc(err.message)}</div>`; }
}

function openNewRetentionModal(){
  const projs=window._cachedProjects||[];
  openModal('+ Add Retention Record',`
    <div class="form-row">
      <div class="form-field"><label>Project *</label>
        <select id="ret-proj" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="">— Select Project —</option>
          ${projs.map(p=>`<option value="${esc(p.id)}">${esc(p.project_no)} — ${esc(p.name)}</option>`).join('')}
        </select>
      </div>
      <div class="form-field"><label>Type</label>
        <select id="ret-type" style="width:100%;background:var(--card);border:1px solid var(--bdr);border-radius:8px;padding:10px;color:var(--text)">
          <option value="AR">AR Retention (from Client)</option>
          <option value="AP">AP Retention (to Subcon)</option>
        </select>
      </div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Retention % *</label><input id="ret-pct" type="number" step="0.1" placeholder="5" data-h-input="h414"/></div>
      <div class="form-field"><label>Base Amount (KWD)</label><input id="ret-base" type="number" step="0.001" placeholder="Contract value" data-h-input="h414"/></div>
    </div>
    <div class="form-row">
      <div class="form-field"><label>Retention Amount (KWD)</label><input id="ret-amt" type="number" step="0.001" placeholder="Auto-calculated"/></div>
      <div class="form-field"><label>Expected Release Date</label><input id="ret-date" type="date"/></div>
    </div>
    <div class="form-field"><label>Notes</label><input id="ret-notes" placeholder="e.g. Per Clause 14.3 of contract"/></div>
    <div class="modal-foot">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h415">Save</button>
    </div>`);
}

function calcRetAmt(){
  const pct=Number(document.getElementById('ret-pct')?.value||0);
  const base=Number(document.getElementById('ret-base')?.value||0);
  const amtEl=document.getElementById('ret-amt');
  if(amtEl&&pct>0&&base>0) amtEl.value=(base*pct/100).toFixed(3);
}

async function saveRetention(e){
  const btn=e?.target; if(btn){btn.disabled=true;btn.textContent='Saving…';}
  try{
    const projId=document.getElementById('ret-proj').value;
    const amt=Number(document.getElementById('ret-amt').value);
    if(!projId||!amt){showToast('Project and amount required','error');return;}
    const {error}=await sb.from('retention_records').insert({
      project_id:projId,
      retention_type:document.getElementById('ret-type').value,
      pct:Number(document.getElementById('ret-pct').value)||null,
      amount:amt,
      release_date:document.getElementById('ret-date').value||null,
      notes:document.getElementById('ret-notes').value.trim()||null,
      status:'held', created_by:currentProfile?.id
    });
    if(error){showToast('Error: '+error.message,'error');return;}
    showToast('Retention recorded ✓'); closeModal(); loadRetention();
  }catch(e2){showToast('Error: '+e2.message,'error');}
  finally{if(btn){btn.disabled=false;btn.textContent='Save';}}
}

async function releaseRetention(id){
  if(!confirm('Mark retention as released?')) return;
  const {error}=await sb.from('retention_records').update({
    status:'released', released_at:new Date().toISOString(), released_by:currentProfile?.id
  }).eq('id',id);
  if(error){showToast('Error: '+error.message,'error');return;}
  showToast('Retention released ✓');
  loadRetention();
}

