function toggleFAB(){
  _fabOpen=!_fabOpen;
  const main=document.getElementById('fab-main');
  if(main) main.style.transform=_fabOpen?'rotate(45deg)':'rotate(0)';
  document.querySelectorAll('.fab-action').forEach(a=>{
    a.style.display=_fabOpen?'flex':'none';
  });
}

