// ── Shared CRM helpers ────────────────────────────────────────
function crmBadge(text,color){
  // P0-2: text is DB-sourced → escaped; color restricted to hex to block attribute injection
  const c=/^#[0-9A-Fa-f]{3,8}$/.test(String(color||''))?color:'#94A3B8';
  return `<span style="background:${c}22;color:${c};border:1px solid ${c}44;border-radius:4px;padding:1px 7px;font-size:10px;font-weight:700">${esc(text)}</span>`;
}
function stageColor(s){
  return {prospect:'#3B82F6',proposal:'#F97316',negotiation:'#8B5CF6',won:'#10B981',lost:'#EF4444'}[s]||'#94A3B8';
}
function leadStatusColor(s){
  return {new:'#3B82F6',contacted:'#F97316',qualified:'#8B5CF6',converted:'#10B981',lost:'#EF4444',dropped:'#94A3B8'}[s]||'#94A3B8';
}
function kwd(v){ return (v||0).toLocaleString('en-KW',{minimumFractionDigits:3,maximumFractionDigits:3})+' KD'; }
function fmtDate(d){ return d?new Date(d).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}):'—'; }

// Auto-number helpers
// P1: atomic numbering ONLY via next_ref_no() RPC (row-locked upsert on ref_sequences).
// No count()/MAX+1 fallback — a failed RPC must stop the save, never produce a duplicate number.
// DB UNIQUE constraints on *_no columns are the final guard (see sp360_security_migration.sql).
async function nextRefNo(prefix){
  const {data,error}=await sb.rpc('next_ref_no',{p_prefix:prefix});
  if(error||!data){
    const err=new Error(`Could not allocate a ${prefix} number — nothing was saved. (${error?.message||'empty result'})`);
    err.name='NumberingError'; throw err;
  }
  return data;
}
async function nextCRMNo(_table, _seqName, prefix){ return nextRefNo(prefix); } // kept for backward compatibility
// Atomic business conversion (one DB transaction: lock source → guard → number → insert → mark source).
// See sp360_phase2_conversions.sql. Returns the inserted row.
async function rpcConvert(kind, sourceId, row, prefix=null){
  const {data,error}=await sb.rpc('sp360_convert',{p_kind:kind,p_source_id:String(sourceId),p_row:row,p_prefix:prefix});
  if(error){
    const e=new Error(error.code==='23505'?error.message:(error.message||'Conversion failed'));
    e.code=error.code; throw e;
  }
  return data;
}

// Insert a row whose reference number comes from next_ref_no(); on UNIQUE violation (23505 — e.g. a legacy
// manually-typed number already occupies the slot) draw the next number and retry, max 3 attempts.
async function insertWithRefNo(table, col, prefix, row, select='id'){
  let lastErr;
  for(let attempt=0; attempt<3; attempt++){
    const no=await nextRefNo(prefix);
    const {data,error}=await sb.from(table).insert({...row,[col]:no}).select(select).single();
    if(!error) return {no,data};
    lastErr=error;
    if(error.code!=='23505') break;
  }
  throw lastErr;
}

