function filterCustTable(q){
  const type = document.getElementById('cust-filter-type')?.value||'';
  document.querySelectorAll('#cust-table tbody tr[data-name]').forEach(tr=>{
    const matchQ = !q || tr.dataset.name.includes(q.toLowerCase()) || tr.dataset.city.includes(q.toLowerCase());
    const matchT = !type || tr.dataset.type===type;
    tr.style.display = (matchQ && matchT)?'':'none';
  });
}

