async function updateCustomer(id){
  try {
    const {error} = await sb.from('crm_customers').update({
      name: document.getElementById('ec-name')?.value?.trim(),
      type: document.getElementById('ec-type')?.value,
      industry: document.getElementById('ec-industry')?.value||null,
      city: document.getElementById('ec-city')?.value||null,
      cr_no: document.getElementById('ec-cr')?.value||null,
      vat_no: document.getElementById('ec-vat')?.value||null,
      credit_limit: parseFloat(document.getElementById('ec-credit')?.value||0)||null,
      payment_terms: parseInt(document.getElementById('ec-terms')?.value||30)||30,
      billing_address: document.getElementById('ec-addr')?.value||null,
      status: document.getElementById('ec-status')?.value,
      rating: document.getElementById('ec-rating')?.value?parseInt(document.getElementById('ec-rating').value):null,
      updated_at: new Date().toISOString()
    }).eq('id',id);
    if(error) throw error;
    closeModal(); showToast('✅ Customer updated','success'); loadCRMCustomers();
  } catch(e){ showToast('Error: '+e.message,'error'); }
}

// ── CRM LEADS ─────────────────────────────────────────────────
async function loadCRMLeads(){
  const el = document.getElementById('page-crm-leads');
  el.innerHTML = `<div class="loading">Loading leads…</div>`;
  try {
    const {data:leads, error} = await sb.from('crm_leads')
      .select('*,customer:crm_customers(name),assignee:user_profiles!assigned_to(full_name)')
      .order('created_at',{ascending:false});
    if(error) throw error;

    const byStatus = {};
    leads.forEach(l=>{ byStatus[l.status]=(byStatus[l.status]||0)+1; });

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><div>
        <h1>💡 Leads</h1>
        <div class="sub">Lead tracking — ${esc(leads.length)} total leads</div>
      </div></div>
      <div style="display:flex;gap:8px">
        ${can('create')?`<button class="btn btn-primary" data-h-click="h428">+ New Lead</button>`:''}
        <button class="btn btn-ghost" data-h-click="h431">↻ Refresh</button>
      </div>
    </div>

    <div class="grid4" style="margin-bottom:18px">
      ${['new','contacted','qualified','converted'].map(s=>`
        <div class="kpi">
          <div class="kpi-label" style="text-transform:capitalize">${s}</div>
          <div class="kpi-val" style="color:${leadStatusColor(s)}">${byStatus[s]||0}</div>
        </div>`).join('')}
    </div>

    <div style="background:var(--card2);border:1px solid var(--bdr);border-radius:11px;overflow:hidden">
      <div style="padding:12px 16px;border-bottom:1px solid var(--bdr);display:flex;gap:8px">
        <input placeholder="🔍 Search leads…" data-h-input="h432" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:7px 12px;color:var(--text);font-size:12px;width:260px;font-family:inherit"/>
        <select data-h-change="h433" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:7px 10px;color:var(--text);font-size:12px;font-family:inherit">
          <option value="">All Statuses</option>
          ${['new','contacted','qualified','converted','lost','dropped'].map(s=>`<option value="${s}">${s}</option>`).join('')}
        </select>
      </div>
      <div style="overflow-x:auto">
        <table class="tbl"><thead><tr>
          <th>Lead No</th><th>Title</th><th>Customer</th><th>Source</th>
          <th>Est. Value</th><th>Status</th><th>Close Date</th><th>Assigned To</th><th>Actions</th>
        </tr></thead>
        <tbody id="leads-tbody">
          ${leads.length===0?`<tr><td colspan="9" style="text-align:center;color:var(--muted);padding:32px">No leads yet</td></tr>`:''}
          ${leads.map(l=>`
          <tr data-status="${esc(l.status)}">
            <td><span style="font-family:monospace;color:var(--gold)">${esc(l.lead_no)}</span></td>
            <td style="font-weight:600">${esc(l.title)}</td>
            <td style="color:var(--muted)">${esc(l.customer?.name||l.customer_name_raw||'—')}</td>
            <td style="color:var(--muted)">${esc((l.source||'—').replace('_',' '))}</td>
            <td style="color:var(--gold)">${kwd(l.estimated_value)}</td>
            <td>${crmBadge(l.status,leadStatusColor(l.status))}</td>
            <td style="color:var(--muted)">${fmtDate(l.expected_close_date)}</td>
            <td style="color:var(--muted)">${esc(l.assignee?.full_name||'—')}</td>
            <td>
              ${can('edit')&&l.status==='qualified'?`<button class="btn btn-xs" style="background:#10B98122;color:#10B981;border:1px solid #10B98144;border-radius:5px;padding:2px 8px;font-size:10px;cursor:pointer" data-h-click="h429" data-ha-click="${esc(JSON.stringify([String((l.id)??'')]))}">→ Convert</button>`:''}
              ${can('edit')?`<button class="btn-icon" data-h-click="h430" data-ha-click="${esc(JSON.stringify([String((l.id)??'')]))}">✏️</button>`:''}
            </td>
          </tr>`).join('')}
        </tbody></table>
      </div>
    </div>`;

    // Update badge
    const newCount = byStatus['new']||0;
    const badge = document.getElementById('leads-badge');
    if(badge){ badge.textContent=newCount; badge.style.display=newCount>0?'':'none'; }
  } catch(e){ pageError('page-crm-leads',e); }
}

function filterLeadsByStatus(status){
  document.querySelectorAll('#leads-tbody tr[data-status]').forEach(tr=>{
    tr.style.display = !status||tr.dataset.status===status?'':'none';
  });
}

function filterTable(tbodyId, q, cols){
  document.querySelectorAll(`#${tbodyId} tr`).forEach(tr=>{
    const cells = tr.querySelectorAll('td');
    const match = !q || cols.some(i=>cells[i]?.textContent.toLowerCase().includes(q.toLowerCase()));
    tr.style.display = match?'':'none';
  });
}

