async function saveNewLead(){
  const title = document.getElementById('nl-title')?.value?.trim();
  if(!title){ showToast('Lead title is required','error'); return; }
  try {
    const custId = document.getElementById('nl-cust')?.value||null;
    const {no} = await insertWithRefNo('crm_leads','lead_no','LEAD',{
      title,
      customer_id: custId||null,
      customer_name_raw: !custId?document.getElementById('nl-cust-raw')?.value||null:null,
      source: document.getElementById('nl-source')?.value,
      category: document.getElementById('nl-cat')?.value||null,
      estimated_value: parseFloat(document.getElementById('nl-val')?.value||0),
      expected_close_date: document.getElementById('nl-date')?.value||null,
      assigned_to: document.getElementById('nl-assign')?.value||null,
      notes: document.getElementById('nl-notes')?.value||null,
      created_by: currentProfile?.id
    });
    closeModal(); showToast(`✅ Lead ${no} created`,'success'); loadCRMLeads();
  } catch(e){ showToast('Error: '+e.message,'error'); }
}

