async function convertLeadToOpportunity(leadId){
  const {data:l} = await sb.from('crm_leads').select('*,customer:crm_customers(name)').eq('id',leadId).single();
  if(!l){ showToast('Lead not found','error'); return; }
  if(!l.customer_id){ showToast('Please link this lead to a customer first before converting','warning'); return; }
  // P1-A: Conversion dialog with auto-set stage/probability
  showModal(`
    <div class="modal-head"><h2>🎯 Convert Lead → Opportunity</h2></div>
    <div class="modal-body">
      <div style="background:var(--bg2);border-radius:8px;padding:12px;margin-bottom:16px;font-size:13px">
        <strong>Lead:</strong> ${esc(l.title||l.company||'—')} &nbsp;|&nbsp;
        <strong>Customer:</strong> ${esc(l.customer?.name||'—')} &nbsp;|&nbsp;
        <strong>Est. Value:</strong> ${fmtKWD(l.estimated_value||0)}
      </div>
      <div class="form-row">
        <label>Opportunity Title *</label>
        <input id="cl-title" value="${(l.title||''). replace(/"/g,'&quot;')}" style="width:100%">
      </div>
      <div class="form-row" style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div>
          <label>Stage</label>
          <select id="cl-stage" style="width:100%">
            <option value="qualification" selected>Qualification (10%)</option>
            <option value="prospect">Prospect (25%)</option>
            <option value="proposal">Proposal (50%)</option>
            <option value="negotiation">Negotiation (75%)</option>
          </select>
        </div>
        <div>
          <label>Probability %</label>
          <input id="cl-prob" type="number" min="0" max="100" value="10" style="width:100%">
        </div>
      </div>
      <div class="form-row" style="display:grid;grid-template-columns:1fr 1fr;gap:12px">
        <div>
          <label>Estimated Value (KWD)</label>
          <input id="cl-val" type="number" min="0" step="0.001" value="${esc(l.estimated_value||0)}" style="width:100%">
        </div>
        <div>
          <label>Expected Close Date</label>
          <input id="cl-close" type="date" value="${esc(l.expected_close_date||'')}" style="width:100%">
        </div>
      </div>
      <div class="form-row">
        <label>Lead Source</label>
        <select id="cl-source" style="width:100%">
          <option value="">— Select —</option>
          <option value="inbound">Inbound Inquiry</option>
          <option value="referral">Referral</option>
          <option value="cold_call">Cold Call</option>
          <option value="exhibition">Exhibition / Event</option>
          <option value="tender">Tender / Bid</option>
          <option value="existing_client">Existing Client</option>
          <option value="other">Other</option>
        </select>
      </div>
      <div class="modal-foot" style="display:flex;gap:8px;justify-content:flex-end;margin-top:20px">
        <button class="btn" data-h-click="h61">Cancel</button>
        <button class="btn btn-primary" data-h-click="h436" data-ha-click="${esc(JSON.stringify([String((leadId)??'')]))}">Convert to Opportunity ▶</button>
      </div>
    </div>
  `);
  setTimeout(()=>{
    document.getElementById('cl-stage')?.addEventListener('change', function(){
      const map={qualification:10,prospect:25,proposal:50,negotiation:75};
      const el=document.getElementById('cl-prob'); if(el) el.value=map[this.value]||10;
    });
  },100);
}

async function doConvertLead(leadId){
  const title=document.getElementById('cl-title')?.value?.trim();
  if(!title){ showToast('Title is required','error'); return; }
  const stage=document.getElementById('cl-stage')?.value||'qualification';
  const prob=Math.min(100,Math.max(0,Number(document.getElementById('cl-prob')?.value)||10));
  const val=Math.max(0,Number(document.getElementById('cl-val')?.value)||0);
  const close=document.getElementById('cl-close')?.value||null;
  const source=document.getElementById('cl-source')?.value||null;
  const {data:l}=await sb.from('crm_leads').select('*').eq('id',leadId).single();
  if(!l){ showToast('Lead not found','error'); return; }
  try {
    const fcastCat=prob>=75?'commit':prob>=50?'best_case':'pipeline';
    // P2: atomic — opportunity insert + lead status in one transaction; double conversion is refused
    const opp=await rpcConvert('lead_to_opp', leadId, {
      title,
      customer_id:l.customer_id, category:l.category,
      estimated_value:val, probability:prob, stage,
      lead_source:source, assigned_to:l.assigned_to,
      expected_close_date:close, forecast_category:fcastCat,
      created_by:currentProfile?.id
    });
    const no=opp?.opp_no;
    await writeAudit('crm_opportunities',opp?.id,'OPP_CREATED_FROM_LEAD',null,
      {opp_no:no,lead_id:leadId,stage,probability:prob,estimated_value:val},
      `Lead ${l.lead_no||leadId} converted to opportunity`);
    closeModal();
    showToast(`✅ Lead converted → Opportunity ${no}`,'success');
    loadCRMLeads();
  } catch(e){ showToast('Error: '+e.message,'error'); }
}

// ── CRM OPPORTUNITIES ─────────────────────────────────────────
async function loadCRMOpportunities(){
  const el = document.getElementById('page-crm-opportunities');
  el.innerHTML = `<div class="loading">Loading opportunities…</div>`;
  try {
    const {data:opps, error} = await sb.from('crm_opportunities')
      .select('*,customer:crm_customers(name),assignee:user_profiles!assigned_to(full_name)')
      .order('created_at',{ascending:false});
    if(error) throw error;

    const active = opps.filter(o=>!['won','lost'].includes(o.stage));
    const totalPipeline = active.reduce((s,o)=>s+o.estimated_value,0);
    const weighted = active.reduce((s,o)=>s+(o.estimated_value*(o.probability/100)),0);

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><div>
        <h1>🎯 Opportunities</h1>
        <div class="sub">Sales opportunities — ${esc(opps.length)} total · ${esc(active.length)} active</div>
      </div></div>
      <div style="display:flex;gap:8px">
        ${can('create')?`<button class="btn btn-primary" data-h-click="h437">+ New Opportunity</button>`:''}
        <button class="btn btn-ghost" data-h-click="h440">↻ Refresh</button>
      </div>
    </div>

    <div class="grid4" style="margin-bottom:18px">
      <div class="kpi"><div class="kpi-label">Total Pipeline</div><div class="kpi-val" style="font-size:14px;color:var(--gold)">${kwd(totalPipeline)}</div></div>
      <div class="kpi"><div class="kpi-label">Weighted Pipeline</div><div class="kpi-val" style="font-size:14px;color:var(--violet)">${kwd(weighted)}</div></div>
      <div class="kpi"><div class="kpi-label">Active Opps</div><div class="kpi-val" style="color:var(--blue)">${esc(active.length)}</div></div>
      <div class="kpi"><div class="kpi-label">Won This Year</div><div class="kpi-val" style="color:var(--green)">${opps.filter(o=>o.stage==='won').length}</div></div>
    </div>

    <div style="background:var(--card2);border:1px solid var(--bdr);border-radius:11px;overflow:hidden">
      <div style="padding:12px 16px;border-bottom:1px solid var(--bdr);display:flex;gap:8px">
        <input placeholder="🔍 Search opportunities…" data-h-input="h441" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:7px 12px;color:var(--text);font-size:12px;width:260px;font-family:inherit"/>
        <select data-h-change="h442" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:7px 10px;color:var(--text);font-size:12px;font-family:inherit">
          <option value="">All Stages</option>
          ${['qualification','prospect','proposal','negotiation','won','lost'].map(s=>`<option value="${s}">${s}</option>`).join('')}
        </select>
      </div>
      <div style="overflow-x:auto">
        <table class="tbl"><thead><tr>
          <th>Opp No</th><th>Title</th><th>Customer</th><th>Value</th>
          <th>Probability</th><th>Stage</th><th>Forecast</th><th>Next Action</th><th>Close Date</th><th>Owner</th><th>Actions</th>
        </tr></thead>
        <tbody id="opps-tbody">
          ${opps.length===0?`<tr><td colspan="9" style="text-align:center;color:var(--muted);padding:32px">No opportunities yet</td></tr>`:''}
          ${opps.map(o=>`
          <tr data-stage="${esc(o.stage)}">
            <td><span style="font-family:monospace;color:var(--gold)">${esc(o.opp_no)}</span></td>
            <td style="font-weight:600">${esc(o.title)}</td>
            <td style="color:var(--muted)">${esc(o.customer?.name||'—')}</td>
            <td style="color:var(--gold)">${kwd(o.estimated_value)}</td>
            <td>
              <div style="display:flex;align-items:center;gap:6px">
                <div style="flex:1;height:6px;background:var(--card);border-radius:3px">
                  <div style="width:${esc(o.probability)}%;height:100%;background:${stageColor(o.stage)};border-radius:3px"></div>
                </div>
                <span style="font-size:10px;color:var(--muted)">${esc(o.probability)}%</span>
              </div>
            </td>
            <td>${crmBadge(o.stage,stageColor(o.stage))}</td>
            <td>${o.forecast_category?crmBadge(o.forecast_category.replace('_',' '),o.forecast_category==='commit'?'#10B981':o.forecast_category==='best_case'?'#3B82F6':o.forecast_category==='omitted'?'#EF4444':'#94A3B8'):'—'}</td>
            <td style="color:var(--muted);font-size:10px;max-width:140px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis" title="${esc(o.next_action||'')}">
              ${o.next_action?`<span style="color:${o.next_action_date&&new Date(o.next_action_date)<new Date()?'#EF4444':'var(--muted)'}">${esc(o.next_action.slice(0,25))}${o.next_action.length>25?'…':''}</span>`:'—'}
              ${o.next_action_date?`<div style="font-size:9px;color:var(--faint)">${fmtDate(o.next_action_date)}</div>`:''}
            </td>
            <td style="color:var(--muted)">${fmtDate(o.expected_close_date)}</td>
            <td style="color:var(--muted)">${esc(o.assignee?.full_name||'—')}</td>
            <td>
              ${can('edit')?`<button class="btn-icon" data-h-click="h438" data-ha-click="${esc(JSON.stringify([String((o.id)??'')]))}">✏️</button>`:''}
              ${can('create')&&!['won','lost'].includes(o.stage)?`<button class="btn btn-xs" style="background:#10B98122;color:#10B981;border:1px solid #10B98144;border-radius:5px;padding:2px 8px;font-size:10px;cursor:pointer" data-h-click="h439" data-ha-click="${esc(JSON.stringify([String((o.id)??'')]))}">→ Quote</button>`:''}
            </td>
          </tr>`).join('')}
        </tbody></table>
      </div>
    </div>`;
  } catch(e){ pageError('page-crm-opportunities',e); }
}

function filterOppsByStage(stage){
  document.querySelectorAll('#opps-tbody tr[data-stage]').forEach(tr=>{
    tr.style.display = !stage||tr.dataset.stage===stage?'':'none';
  });
}

