async function saveNewOpportunity(){
  const title = document.getElementById('no-title')?.value?.trim();
  const custId = document.getElementById('no-cust')?.value;
  if(!title){ showToast('Title is required','error'); return; }
  if(!custId){ showToast('Please select a customer','error'); return; }
  try {
    const {data:oppRef,error:refErr} = await sb.rpc('next_ref_no',{p_prefix:'OPP'});
    if(refErr||!oppRef){ showToast('Error generating opportunity number','error'); return; }
    const {error} = await sb.from('crm_opportunities').insert({
      opp_no: oppRef,
      title,
      customer_id: custId,
      category: document.getElementById('no-cat')?.value||null,
      estimated_value: parseFloat(document.getElementById('no-val')?.value||0),
      probability: parseInt(document.getElementById('no-prob')?.value||50),
      stage: document.getElementById('no-stage')?.value||'prospect',
      lead_source: document.getElementById('no-source')?.value||null,
      forecast_category: document.getElementById('no-forecast')?.value||'pipeline',
      next_action: document.getElementById('no-nextaction')?.value||null,
      next_action_date: document.getElementById('no-nextdate')?.value||null,
      expected_close_date: document.getElementById('no-close')?.value||null,
      bid_deadline: document.getElementById('no-bid')?.value||null,
      assigned_to: document.getElementById('no-assign')?.value||null,
      notes: document.getElementById('no-notes')?.value||null,
      created_by: currentProfile?.id
    });
    if(error) throw error;
    closeModal(); showToast(`✅ Opportunity ${oppRef} created`,'success'); loadCRMOpportunities();
  } catch(e){ showToast('Error: '+e.message,'error'); }
}

