async function saveNewMilestone(){
  const projId = document.getElementById('nm-proj')?.value;
  const name   = document.getElementById('nm-name')?.value?.trim();
  const date   = document.getElementById('nm-date')?.value;
  if(!projId){ showToast('Please select a project','error'); return; }
  if(!name)  { showToast('Milestone name is required','error'); return; }
  if(!date)  { showToast('Planned date is required','error'); return; }
  try {
    const {error} = await sb.from('project_milestones').insert({
      project_id:   projId,
      name,
      planned_date: date,
      weight:       parseFloat(document.getElementById('nm-weight')?.value||0),
      notes:        document.getElementById('nm-notes')?.value||null,
      status:       'pending'
    });
    if(error) throw error;
    closeModal();
    showToast('✅ Milestone added','success');
    loadProjects('milestones');
  } catch(e){ showToast('Error: '+e.message,'error'); }
}

async function achieveMilestone(id){
  const today = new Date().toISOString().split('T')[0];
  const {error} = await sb.from('project_milestones')
    .update({status:'achieved', actual_date:today})
    .eq('id',id);
  if(error){ showToast('Error: '+error.message,'error'); return; }
  showToast('✅ Milestone achieved!','success');
  loadProjects('milestones');
}

async function delayMilestone(id){
  const {error} = await sb.from('project_milestones')
    .update({status:'delayed'})
    .eq('id',id);
  if(error){ showToast('Error: '+error.message,'error'); return; }
  showToast('⚠️ Milestone marked as delayed','warning');
  loadProjects('milestones');
}

