// ── VENDOR PORTAL SUMMARY ────────────────────────────────────
async function openVendorPortal(){
  try {
    const [vendR, poR, invR] = await Promise.all([
      sb.from('vendors').select('*').order('vendor_code'),
      sb.from('purchase_orders').select('*,vendor:vendors(vendor_code,name)').order('created_at',{ascending:false}).limit(100),
      sb.from('invoices').select('id,vendor_id,net_amount,status,invoice_type').eq('invoice_type','supplier').limit(200)
    ]);
    const vendors = vendR.data||[], pos = poR.data||[], invs = invR.data||[];
    const approved    = vendors.filter(v=>v.is_approved);
    const totalPO     = pos.reduce((s,p)=>s+Number(p.po_value||0),0);
    const totalPaid   = invs.filter(i=>i.status==='paid').reduce((s,i)=>s+Number(i.net_amount||0),0);
    const outstanding = invs.filter(i=>!['paid','cancelled'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount||0),0);

    openModal('🏭 Vendor Portal Summary',`
      <div class="grid4" style="margin-bottom:14px">
        <div class="kpi" style="padding:12px"><div class="kpi-label">Total Vendors</div><div class="kpi-val">${esc(vendors.length)}</div></div>
        <div class="kpi" style="padding:12px"><div class="kpi-label">Approved</div><div class="kpi-val" style="color:var(--green)">${esc(approved.length)}</div></div>
        <div class="kpi" style="padding:12px"><div class="kpi-label">Total PO Value</div><div class="kpi-val" style="font-size:13px;color:var(--gold)">${fmtKWD(totalPO)}</div></div>
        <div class="kpi" style="padding:12px"><div class="kpi-label">Outstanding AP</div><div class="kpi-val" style="font-size:13px;color:var(--orange)">${fmtKWD(outstanding)}</div></div>
      </div>

      <div style="font-size:10px;font-weight:700;color:var(--gold);text-transform:uppercase;margin-bottom:8px">Vendor Performance Summary</div>
      <div style="max-height:360px;overflow-y:auto">
        ${vendors.length===0?`<div style="text-align:center;padding:24px;color:var(--muted)">No vendors registered yet — add vendors in Procurement</div>`:`
        <table class="tbl"><thead><tr>
          <th>Code</th><th>Vendor</th><th>Category</th><th>Status</th>
          <th style="text-align:right">Open POs</th>
          <th style="text-align:right">PO Value</th>
          <th style="text-align:right">Outstanding</th>
          <th style="text-align:center">Rating</th>
        </tr></thead><tbody>
        ${vendors.map(v=>{
          const vPOs = pos.filter(p=>p.vendor_id===v.id);
          const vInvs = invs.filter(i=>i.vendor_id===v.id&&!['paid','cancelled'].includes(i.status));
          const vPOVal = vPOs.reduce((s,p)=>s+Number(p.po_value||0),0);
          const vOutstanding = vInvs.reduce((s,i)=>s+Number(i.net_amount||0),0);
          const openPOs = vPOs.filter(p=>!['received','cancelled'].includes(p.status)).length;
          return `<tr>
            <td style="font-family:monospace;color:var(--gold);font-size:10px">${esc(v.vendor_code||'—')}</td>
            <td style="font-weight:600">${esc(v.name||v.vendor_name||'—')}</td>
            <td style="color:var(--muted);font-size:10px">${esc(v.category||v.vendor_type||'—')}</td>
            <td>${pill(v.is_approved?'approved':v.status||'pending',v.is_approved?'#10B981':v.status==='blacklisted'?'#EF4444':'#F97316')}</td>
            <td style="text-align:right;color:${openPOs>0?'var(--orange)':'var(--muted)'}">${openPOs}</td>
            <td style="text-align:right;color:var(--gold)">${fmtKWD(vPOVal)}</td>
            <td style="text-align:right;color:${vOutstanding>0?'var(--orange)':'var(--muted)'}">${fmtKWD(vOutstanding)}</td>
            <td style="text-align:center">${v.rating?'⭐'.repeat(v.rating):'—'}</td>
          </tr>`;
        }).join('')}
        </tbody></table>`}
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:14px">
        <button class="btn btn-ghost" data-h-click="h61">Close</button>
        <button class="btn btn-primary" data-h-click="h464">Open Procurement →</button>
      </div>
    `);
  } catch(e){ showToast('Error loading vendor data: '+e.message,'error'); }
}

// ══════════════════════════════════════════════════════════════
//  P13 — TIME TRACKING MODULE
// ══════════════════════════════════════════════════════════════
async function loadTimeTracking(){
  const el = document.getElementById('page-timetracking');
  el.innerHTML = `<div class="loading">Loading timesheets…</div>`;
  try {
    const [tsR, projR, empR] = await Promise.all([
      sb.from('timesheets').select('*,employee:employees(emp_no,full_name,department),project:projects(project_no,name)').order('created_at',{ascending:false}).limit(200),
      sb.from('projects').select('id,project_no,name').in('status',['planning','execution','monitoring','closeout']).order('project_no'),
      sb.from('employees').select('id,emp_no,full_name,department').eq('status','active').order('full_name')
    ]);
    const ts = tsR.data||[], projs = projR.data||[], emps = empR.data||[];
    const totalHours = ts.reduce((s,t)=>s+Number(t.hours_regular||0)+Number(t.hours_overtime||0),0);
    const thisMonth  = ts.filter(t=>t.period===new Date().toISOString().slice(0,7));
    const monthHours = thisMonth.reduce((s,t)=>s+Number(t.hours_regular||0)+Number(t.hours_overtime||0),0);
    const pending    = ts.filter(t=>t.status==='submitted').length;

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><div>
        <h1>⏱ Time Tracking</h1>
        <div class="sub">Timesheets per project — ${esc(ts.length)} records</div>
      </div></div>
      <div style="display:flex;gap:8px">
        ${can('create')?`<button class="btn btn-primary" data-h-click="h465">+ Log Hours</button>`:''}
        <button class="btn btn-ghost" data-h-click="h468">↻ Refresh</button>
      </div>
    </div>
    <div class="grid4" style="margin-bottom:18px">
      ${kpi('Total Hours Logged', totalHours.toFixed(1)+'h', '#3B82F6')}
      ${kpi('This Month', monthHours.toFixed(1)+'h', '#8B5CF6')}
      ${kpi('Pending Approval', pending, pending>0?'#F97316':'#10B981')}
      ${kpi('Active Employees', emps.length, '#10B981')}
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:14px">
      <!-- Hours by Project -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🏗</span>Hours by Project</div></div>
        ${projs.map(p=>{
          const pHours = ts.filter(t=>t.project_id===p.id).reduce((s,t)=>s+Number(t.hours_regular||0)+Number(t.hours_overtime||0),0);
          const pct = totalHours>0?Math.round(pHours/totalHours*100):0;
          return pHours>0?`
          <div style="margin-bottom:8px">
            <div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:3px">
              <span style="color:var(--muted)">${esc(p.project_no)}</span>
              <span style="color:var(--gold);font-weight:700">${pHours.toFixed(1)}h</span>
            </div>
            <div style="height:6px;background:var(--n3);border-radius:3px">
              <div style="width:${pct}%;height:100%;background:var(--gold);border-radius:3px"></div>
            </div>
          </div>`:''}).join('')||'<div style="color:var(--muted);font-size:11px">No hours logged yet</div>'}
      </div>
      <!-- Hours by Employee -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>👤</span>Top Contributors</div></div>
        ${emps.map(e=>{
          const eHours = ts.filter(t=>t.employee_id===e.id).reduce((s,t)=>s+Number(t.hours_regular||0)+Number(t.hours_overtime||0),0);
          return {e,h:eHours};
        }).filter(x=>x.h>0).sort((a,b)=>b.h-a.h).slice(0,6).map(({e,h})=>`
          <div style="display:flex;justify-content:space-between;align-items:center;padding:6px 0;border-bottom:1px solid var(--bdr)">
            <div>
              <div style="font-size:11px;font-weight:600">${esc(e.full_name)}</div>
              <div style="font-size:10px;color:var(--muted)">${esc(e.department||'—')}</div>
            </div>
            <div style="font-size:12px;font-weight:700;color:var(--blue)">${h.toFixed(1)}h</div>
          </div>`).join('')||'<div style="color:var(--muted);font-size:11px">No hours logged yet</div>'}
      </div>
    </div>

    <div style="background:var(--card2);border:1px solid var(--bdr);border-radius:11px;overflow:hidden">
      <div style="padding:12px 16px;border-bottom:1px solid var(--bdr);display:flex;gap:8px;align-items:center">
        <span style="font-size:11px;font-weight:700;color:var(--gold)">All Timesheet Entries</span>
        <input placeholder="🔍 Search…" data-h-input="h469" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;width:200px;font-family:inherit;margin-left:auto"/>
      </div>
      <div style="overflow-x:auto">
        <table class="tbl"><thead><tr>
          <th>Period</th><th>Employee</th><th>Project</th><th>Activity</th>
          <th style="text-align:right">Regular</th><th style="text-align:right">Overtime</th>
          <th style="text-align:right">Total</th><th>Status</th>
          ${can('edit')?'<th></th>':''}
        </tr></thead>
        <tbody id="ts-tbody">
          ${ts.length===0?`<tr><td colspan="9" style="text-align:center;color:var(--muted);padding:32px">No timesheets yet</td></tr>`:''}
          ${ts.map(t=>`
          <tr>
            <td style="color:var(--muted);font-family:monospace;font-size:10px">${esc(t.period||'—')}</td>
            <td><div style="font-size:11px;font-weight:600">${esc(t.employee?.full_name||'—')}</div><div style="font-size:10px;color:var(--muted)">${esc(t.employee?.emp_no||'')}</div></td>
            <td style="color:var(--gold);font-size:10px">${esc(t.project?.project_no||'—')}<br><span style="color:var(--muted)">${esc(t.project?.name||'')}</span></td>
            <td style="color:var(--muted);font-size:10px">${esc(t.activity||'—')}</td>
            <td style="text-align:right;color:var(--text)">${Number(t.hours_regular||0).toFixed(1)}h</td>
            <td style="text-align:right;color:${Number(t.hours_overtime)>0?'#F97316':'var(--muted)'}">${Number(t.hours_overtime||0).toFixed(1)}h</td>
            <td style="text-align:right;font-weight:700;color:var(--blue)">${(Number(t.hours_regular||0)+Number(t.hours_overtime||0)).toFixed(1)}h</td>
            <td>${pill(t.status,t.status==='approved'?'#10B981':t.status==='submitted'?'#3B82F6':t.status==='rejected'?'#EF4444':'#94A3B8')}</td>
            ${can('edit')?`<td>
              ${t.status==='submitted'?`<button class="btn-icon" title="Approve" data-h-click="h466" data-ha-click="${esc(JSON.stringify([String((t.id)??'')]))}">✅</button>`:''}
              ${t.status==='draft'?`<button class="btn-icon" title="Submit" data-h-click="h467" data-ha-click="${esc(JSON.stringify([String((t.id)??'')]))}">📤</button>`:''}
            </td>`:''}
          </tr>`).join('')}
        </tbody></table>
      </div>
    </div>`;
  } catch(e){ pageError('page-timetracking',e); }
}

async function openLogTimeModal(){
  const [projR, empR] = await Promise.all([
    sb.from('projects').select('id,project_no,name').in('status',['planning','execution','monitoring','closeout']).order('project_no'),
    sb.from('employees').select('id,emp_no,full_name').eq('status','active').order('full_name')
  ]);
  const period = new Date().toISOString().slice(0,7);
  openModal('⏱ Log Hours',`
    <div class="form-grid">
      <div class="form-field"><label>Employee *</label>
        <select id="lt-emp">
          <option value="">— Select Employee —</option>
          ${(empR.data||[]).map(e=>`<option value="${esc(e.id)}">${esc(e.full_name)} (${esc(e.emp_no)})</option>`).join('')}
        </select>
      </div>
      <div class="form-field"><label>Project *</label>
        <select id="lt-proj">
          <option value="">— Select Project —</option>
          ${(projR.data||[]).map(p=>`<option value="${esc(p.id)}">${esc(p.project_no)} — ${esc(p.name)}</option>`).join('')}
        </select>
      </div>
      <div class="form-field"><label>Period (YYYY-MM)</label>
        <input id="lt-period" value="${period}" placeholder="2026-09"/>
      </div>
      <div class="form-field"><label>Activity</label>
        <input id="lt-activity" placeholder="e.g. Installation, Testing, Design"/>
      </div>
      <div class="form-field"><label>Regular Hours</label>
        <input id="lt-reg" type="number" min="0" max="200" step="0.5" value="0"/>
      </div>
      <div class="form-field"><label>Overtime Hours</label>
        <input id="lt-ot" type="number" min="0" max="100" step="0.5" value="0"/>
      </div>
    </div>
    <div style="display:flex;gap:8px;justify-content:flex-end;margin-top:16px">
      <button class="btn btn-ghost" data-h-click="h61">Cancel</button>
      <button class="btn btn-primary" data-h-click="h470">Log Hours</button>
    </div>
  `);
}

async function saveTimesheet(){
  const empId  = document.getElementById('lt-emp')?.value;
  const projId = document.getElementById('lt-proj')?.value;
  const period = document.getElementById('lt-period')?.value?.trim();
  if(!empId)  { showToast('Select an employee','error'); return; }
  if(!projId) { showToast('Select a project','error'); return; }
  if(!period) { showToast('Period is required','error'); return; }
  try {
    const {error} = await sb.from('timesheets').insert({
      employee_id:     empId,
      project_id:      projId,
      period,
      activity:        document.getElementById('lt-activity')?.value||null,
      hours_regular:   parseFloat(document.getElementById('lt-reg')?.value||0),
      hours_overtime:  parseFloat(document.getElementById('lt-ot')?.value||0),
      status:          'draft',
      approved_by:     null
    });
    if(error) throw error;
    closeModal(); showToast('✅ Hours logged','success'); loadTimeTracking();
  } catch(e){ showToast('Error: '+e.message,'error'); }
}

async function submitTimesheet(id){
  await sb.from('timesheets').update({status:'submitted'}).eq('id',id);
  showToast('📤 Timesheet submitted for approval','info'); loadTimeTracking();
}
async function approveTimesheet(id){
  await sb.from('timesheets').update({status:'approved',approved_by:currentProfile?.id}).eq('id',id);
  showToast('✅ Timesheet approved','success'); loadTimeTracking();
}

// ══════════════════════════════════════════════════════════════
//  P13 — FINANCIAL RATIOS MODULE
// ══════════════════════════════════════════════════════════════
async function loadFinancialRatios(){
  const el = document.getElementById('page-ratios');
  el.innerHTML = `<div class="loading">Calculating financial ratios…</div>`;
  try {
    const [invR, projR, poR] = await Promise.all([
      sb.from('invoices').select('*'),
      sb.from('projects').select('id,project_no,name,bac,ac,ev,pv,contract_value,status'),
      sb.from('purchase_orders').select('*')
    ]);
    const invs = invR.data||[], projs = projR.data||[], pos = poR.data||[];

    // ── Revenue & Cost ────────────────────────────────────────
    const clientInvs = invs.filter(i=>i.invoice_type==='client');
    const supplierInvs = invs.filter(i=>i.invoice_type==='supplier');
    const totalRevenue = clientInvs.filter(i=>['paid','partially_paid'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount||0),0);
    const totalAR      = clientInvs.filter(i=>!['paid','cancelled'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount||0),0);
    const totalAP      = supplierInvs.filter(i=>!['paid','cancelled'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount||0),0);
    const totalCost    = supplierInvs.filter(i=>['paid','partially_paid'].includes(i.status)).reduce((s,i)=>s+Number(i.net_amount||0),0);
    const grossProfit  = totalRevenue - totalCost;
    const gpMargin     = totalRevenue>0 ? (grossProfit/totalRevenue*100) : 0;

    // ── EVM Portfolio ─────────────────────────────────────────
    const activeProjs = projs.filter(p=>['planning','execution','monitoring','closeout'].includes(p.status));
    const totalBAC = activeProjs.reduce((s,p)=>s+Number(p.bac||0),0);
    const totalAC  = activeProjs.reduce((s,p)=>s+Number(p.ac||0),0);
    const totalEV  = activeProjs.reduce((s,p)=>s+Number(p.ev||0),0);
    const totalPV  = activeProjs.reduce((s,p)=>s+Number(p.pv||0),0);
    const portCPI  = totalAC>0 ? totalEV/totalAC : 1;
    const portSPI  = totalPV>0 ? totalEV/totalPV : 1;
    const portEAC  = portCPI>0 ? totalBAC/portCPI : totalBAC;
    const portVAC  = totalBAC - portEAC;
    const portCV   = totalEV - totalAC;
    const portSV   = totalEV - totalPV;

    // ── Liquidity ─────────────────────────────────────────────
    const arTurnover  = totalRevenue>0&&totalAR>0 ? totalRevenue/totalAR : 0;
    const apTurnover  = totalCost>0&&totalAP>0   ? totalCost/totalAP    : 0;
    const dso         = arTurnover>0 ? 365/arTurnover : 0;
    const dpo         = apTurnover>0 ? 365/apTurnover : 0;
    const cashCycle   = dso - dpo;
    const totalContractVal = projs.reduce((s,p)=>s+Number(p.contract_value||0),0);
    const backlog     = totalContractVal - totalRevenue;

    const ratioCard = (label,value,benchmark,color,desc,fmt='num')=>`
      <div style="background:var(--card);border:1px solid var(--bdr);border-radius:9px;padding:14px">
        <div style="font-size:10px;color:var(--muted);margin-bottom:6px;text-transform:uppercase;letter-spacing:.3px">${label}</div>
        <div style="font-size:22px;font-weight:900;color:${color};margin-bottom:4px">${fmt==='pct'?value.toFixed(1)+'%':fmt==='kwd'?fmtKWD(value):fmt==='days'?value.toFixed(0)+'d':value.toFixed(3)}</div>
        <div style="font-size:10px;color:var(--faint);margin-bottom:6px">${desc}</div>
        <div style="font-size:9px;padding:2px 7px;background:${color}22;color:${color};border-radius:4px;display:inline-block;font-weight:700">${benchmark}</div>
      </div>`;

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><div>
        <h1>📐 Financial Ratios</h1>
        <div class="sub">Analytical KPIs — ${new Date().toLocaleDateString('en-GB',{month:'long',year:'numeric'})}</div>
      </div></div>
      <div style="display:flex;gap:8px">
        <button class="btn btn-ghost" data-h-click="h471">📄 Export PDF</button>
        <button class="btn btn-ghost" data-h-click="h472">↻ Refresh</button>
      </div>
    </div>

    <!-- Profitability -->
    <div style="margin-bottom:6px;font-size:10px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:.5px">💰 Profitability</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px">
      ${ratioCard('Gross Profit Margin', gpMargin, gpMargin>=20?'✅ Healthy':gpMargin>=10?'⚠️ Moderate':'🔴 Low', gpMargin>=20?'#10B981':gpMargin>=10?'#F97316':'#EF4444','(Revenue − Cost) / Revenue','pct')}
      ${ratioCard('Gross Profit', grossProfit, grossProfit>=0?'✅ Positive':'🔴 Negative', grossProfit>=0?'#10B981':'#EF4444','Collected Revenue − Paid Cost','kwd')}
      ${ratioCard('Total Revenue', totalRevenue,'Collected invoices',totalRevenue>0?'#3B82F6':'#94A3B8','Paid client invoices to date','kwd')}
      ${ratioCard('Backlog', backlog,'Work yet to invoice',backlog>0?'#8B5CF6':'#94A3B8','Contract Value − Collected','kwd')}
    </div>

    <!-- EVM Portfolio -->
    <div style="margin-bottom:6px;font-size:10px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:.5px">⚡ Portfolio EVM Ratios</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px">
      ${ratioCard('Portfolio CPI', portCPI, portCPI>=1?'✅ On Budget':portCPI>=0.9?'⚠️ At Risk':'🔴 Over Budget', portCPI>=1?'#10B981':portCPI>=0.9?'#F97316':'#EF4444','EV / AC — Cost efficiency')}
      ${ratioCard('Portfolio SPI', portSPI, portSPI>=1?'✅ On Schedule':portSPI>=0.9?'⚠️ At Risk':'🔴 Behind', portSPI>=1?'#10B981':portSPI>=0.9?'#F97316':'#EF4444','EV / PV — Schedule efficiency')}
      ${ratioCard('Cost Variance', portCV, portCV>=0?'✅ Under Budget':'🔴 Over Budget', portCV>=0?'#10B981':'#EF4444','EV − AC (portfolio)','kwd')}
      ${ratioCard('VAC', portVAC, portVAC>=0?'✅ Saving expected':'🔴 Overrun expected', portVAC>=0?'#10B981':'#EF4444','BAC − EAC forecast','kwd')}
    </div>

    <!-- Liquidity -->
    <div style="margin-bottom:6px;font-size:10px;font-weight:700;color:var(--gold);text-transform:uppercase;letter-spacing:.5px">🔄 Liquidity & Cash Cycle</div>
    <div style="display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:18px">
      ${ratioCard('DSO', dso, dso<=60?'✅ Good':dso<=90?'⚠️ Moderate':'🔴 Slow collection', dso<=60?'#10B981':dso<=90?'#F97316':'#EF4444','Days Sales Outstanding','days')}
      ${ratioCard('DPO', dpo, dpo<=60?'✅ Good':'⚠️ Review', dpo<=60?'#10B981':'#F97316','Days Payable Outstanding','days')}
      ${ratioCard('Cash Cycle', cashCycle, cashCycle<=30?'✅ Efficient':cashCycle<=60?'⚠️ Moderate':'🔴 Review','#8B5CF6','DSO − DPO (days to convert)','days')}
      ${ratioCard('AR/AP Ratio', totalAP>0?totalAR/totalAP:0, totalAR/Math.max(totalAP,1)>=1?'✅ AR > AP':'⚠️ AP > AR', totalAR>=totalAP?'#10B981':'#F97316','Outstanding AR vs AP balance')}
    </div>

    <!-- Project-by-project -->
    <div style="background:var(--card2);border:1px solid var(--bdr);border-radius:11px;overflow:hidden">
      <div style="padding:12px 16px;border-bottom:1px solid var(--bdr)">
        <span style="font-size:11px;font-weight:700;color:var(--gold)">Project-Level Financial Ratios</span>
      </div>
      <div style="overflow-x:auto">
        <table class="tbl"><thead><tr>
          <th>Project</th><th style="text-align:right">BAC</th><th style="text-align:right">AC</th>
          <th style="text-align:right">EV</th><th style="text-align:center">CPI</th>
          <th style="text-align:center">SPI</th><th style="text-align:right">EAC</th>
          <th style="text-align:right">VAC</th>
        </tr></thead><tbody>
        ${activeProjs.map(p=>{
          const cpi = Number(p.ac)>0 ? Number(p.ev)/Number(p.ac) : 1;
          const spi = Number(p.pv)>0 ? Number(p.ev)/Number(p.pv) : 1;
          const eac = cpi>0 ? Number(p.bac)/cpi : Number(p.bac);
          const vac = Number(p.bac) - eac;
          return `<tr>
            <td><div style="font-size:11px;font-weight:600">${esc(p.project_no)}</div><div style="font-size:10px;color:var(--muted)">${esc(p.name)}</div></td>
            <td style="text-align:right;color:var(--muted)">${fmtKWD(p.bac)}</td>
            <td style="text-align:right;color:var(--muted)">${fmtKWD(p.ac)}</td>
            <td style="text-align:right;color:var(--blue)">${fmtKWD(p.ev)}</td>
            <td style="text-align:center"><span style="font-weight:700;color:${cpi>=1?'#10B981':cpi>=0.9?'#F97316':'#EF4444'}">${cpi.toFixed(3)}</span></td>
            <td style="text-align:center"><span style="font-weight:700;color:${spi>=1?'#10B981':spi>=0.9?'#F97316':'#EF4444'}">${spi.toFixed(3)}</span></td>
            <td style="text-align:right;color:var(--orange)">${fmtKWD(eac)}</td>
            <td style="text-align:right;color:${vac>=0?'#10B981':'#EF4444'};font-weight:700">${fmtKWD(vac)}</td>
          </tr>`;
        }).join('')}
        </tbody></table>
      </div>
    </div>`;
  } catch(e){ pageError('page-ratios',e); }
}

