async function loadBulkOperations(){
  const el = document.getElementById('page-bulk');
  el.innerHTML = `<div class="loading">Loading bulk operations…</div>`;
  try {
    const [projR, empR, vendR, custR] = await Promise.all([
      sb.from('projects').select('id,project_no,name,status,priority,pm_id').order('project_no'),
      sb.from('employees').select('id,emp_no,full_name,status,department').order('full_name'),
      sb.from('vendors').select('id,vendor_code,name,is_approved,status').order('vendor_code'),
      sb.from('crm_customers').select('id,customer_no,name,status,rating').order('customer_no')
    ]);

    el.innerHTML = `
    <div class="page-head">
      <div class="page-head-left"><div>
        <h1>⚡ Bulk Operations</h1>
        <div class="sub">Mass updates across Projects, Employees, Vendors, Customers</div>
      </div></div>
    </div>

    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">

      <!-- Bulk: Projects -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🏗</span>Projects — Bulk Status Update</div></div>
        <div style="margin-bottom:10px;font-size:11px;color:var(--muted)">Select projects and update status or priority in one action.</div>
        <div style="margin-bottom:10px;display:flex;gap:8px;align-items:center">
          <select id="bulk-proj-status" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;font-family:inherit">
            <option value="">— Set Status —</option>
            ${['planning','execution','monitoring','closeout','on_hold','completed'].map(s=>`<option value="${s}">${s}</option>`).join('')}
          </select>
          <select id="bulk-proj-priority" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;font-family:inherit">
            <option value="">— Set Priority —</option>
            ${['critical','high','medium','low'].map(s=>`<option value="${s}">${s}</option>`).join('')}
          </select>
          <button class="btn btn-primary btn-sm" data-h-click="h473">Apply</button>
        </div>
        <div style="max-height:280px;overflow-y:auto">
          ${(projR.data||[]).map(p=>`
          <label style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--card);border-radius:6px;margin-bottom:4px;cursor:pointer">
            <input type="checkbox" class="bulk-proj-cb" value="${esc(p.id)}" style="accent-color:var(--gold)"/>
            <div style="flex:1">
              <div style="font-size:11px;font-weight:600">${esc(p.project_no)} — ${esc(p.name)}</div>
              <div style="font-size:10px;color:var(--muted)">${esc(p.status)} · ${esc(p.priority)}</div>
            </div>
          </label>`).join('')}
        </div>
        <div style="margin-top:8px;display:flex;gap:6px">
          <button class="btn btn-ghost btn-sm" data-h-click="h474">Select All</button>
          <button class="btn btn-ghost btn-sm" data-h-click="h475">Clear</button>
        </div>
      </div>

      <!-- Bulk: Customers -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🏢</span>Customers — Bulk Status Update</div></div>
        <div style="margin-bottom:10px;font-size:11px;color:var(--muted)">Update customer status or rating in bulk.</div>
        <div style="margin-bottom:10px;display:flex;gap:8px;align-items:center">
          <select id="bulk-cust-status" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;font-family:inherit">
            <option value="">— Set Status —</option>
            ${['active','inactive','blacklisted'].map(s=>`<option value="${s}">${s}</option>`).join('')}
          </select>
          <button class="btn btn-primary btn-sm" data-h-click="h476">Apply</button>
        </div>
        <div style="max-height:280px;overflow-y:auto">
          ${(custR.data||[]).map(c=>`
          <label style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--card);border-radius:6px;margin-bottom:4px;cursor:pointer">
            <input type="checkbox" class="bulk-cust-cb" value="${esc(c.id)}" style="accent-color:var(--gold)"/>
            <div style="flex:1">
              <div style="font-size:11px;font-weight:600">${esc(c.customer_no)} — ${esc(c.name)}</div>
              <div style="font-size:10px;color:var(--muted)">${esc(c.status)} · ${c.rating?'⭐'.repeat(c.rating):'Unrated'}</div>
            </div>
          </label>`).join('')}
        </div>
        <div style="margin-top:8px;display:flex;gap:6px">
          <button class="btn btn-ghost btn-sm" data-h-click="h477">Select All</button>
          <button class="btn btn-ghost btn-sm" data-h-click="h478">Clear</button>
        </div>
      </div>

      <!-- Bulk: Vendors -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>🏭</span>Vendors — Bulk Approval</div></div>
        <div style="margin-bottom:10px;font-size:11px;color:var(--muted)">Approve or blacklist multiple vendors at once.</div>
        <div style="margin-bottom:10px;display:flex;gap:8px">
          <button class="btn btn-primary btn-sm" data-h-click="h479">✅ Approve Selected</button>
          <button class="btn btn-ghost btn-sm" style="color:#EF4444;border-color:#EF444433" data-h-click="h480">🚫 Blacklist Selected</button>
        </div>
        <div style="max-height:280px;overflow-y:auto">
          ${(vendR.data||[]).map(v=>`
          <label style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--card);border-radius:6px;margin-bottom:4px;cursor:pointer">
            <input type="checkbox" class="bulk-vend-cb" value="${esc(v.id)}" style="accent-color:var(--gold)"/>
            <div style="flex:1">
              <div style="font-size:11px;font-weight:600">${esc(v.vendor_code||'—')} — ${esc(v.name||v.vendor_name||'—')}</div>
              <div style="font-size:10px;color:var(--muted)">${v.is_approved?'✅ Approved':'⏳ Pending'}</div>
            </div>
          </label>`).join('')||'<div style="color:var(--muted);font-size:11px">No vendors registered</div>'}
        </div>
        <div style="margin-top:8px;display:flex;gap:6px">
          <button class="btn btn-ghost btn-sm" data-h-click="h481">Select All</button>
          <button class="btn btn-ghost btn-sm" data-h-click="h482">Clear</button>
        </div>
      </div>

      <!-- Bulk: Employees -->
      <div class="card">
        <div class="sec-head"><div class="sec-title"><span>👥</span>Employees — Bulk Status Update</div></div>
        <div style="margin-bottom:10px;font-size:11px;color:var(--muted)">Update employee status across departments.</div>
        <div style="margin-bottom:10px;display:flex;gap:8px;align-items:center">
          <select id="bulk-emp-status" style="background:var(--card);border:1px solid var(--bdr);border-radius:7px;padding:6px 10px;color:var(--text);font-size:11px;font-family:inherit">
            <option value="">— Set Status —</option>
            ${['active','on_leave','resigned','terminated'].map(s=>`<option value="${s}">${s}</option>`).join('')}
          </select>
          <button class="btn btn-primary btn-sm" data-h-click="h483">Apply</button>
        </div>
        <div style="max-height:280px;overflow-y:auto">
          ${(empR.data||[]).map(e=>`
          <label style="display:flex;align-items:center;gap:8px;padding:6px 8px;background:var(--card);border-radius:6px;margin-bottom:4px;cursor:pointer">
            <input type="checkbox" class="bulk-emp-cb" value="${esc(e.id)}" style="accent-color:var(--gold)"/>
            <div style="flex:1">
              <div style="font-size:11px;font-weight:600">${esc(e.emp_no)} — ${esc(e.full_name)}</div>
              <div style="font-size:10px;color:var(--muted)">${esc(e.department||'—')} · ${esc(e.status)}</div>
            </div>
          </label>`).join('')||'<div style="color:var(--muted);font-size:11px">No employees registered</div>'}
        </div>
        <div style="margin-top:8px;display:flex;gap:6px">
          <button class="btn btn-ghost btn-sm" data-h-click="h484">Select All</button>
          <button class="btn btn-ghost btn-sm" data-h-click="h485">Clear</button>
        </div>
      </div>
    </div>`;
  } catch(e){ pageError('page-bulk',e); }
}

async function bulkUpdateProjects(){
  const ids=[...document.querySelectorAll('.bulk-proj-cb:checked')].map(c=>c.value);
  if(!ids.length){ showToast('Select at least one project','warning'); return; }
  const status   = document.getElementById('bulk-proj-status')?.value;
  const priority = document.getElementById('bulk-proj-priority')?.value;
  if(!status&&!priority){ showToast('Select a status or priority to apply','warning'); return; }
  if(!confirm(`Update ${ids.length} project(s)?`)) return;
  const update={updated_at:new Date().toISOString()};
  if(status)   update.status=status;
  if(priority) update.priority=priority;
  const {error}=await sb.from('projects').update(update).in('id',ids);
  if(error){ showToast('Error: '+error.message,'error'); return; }
  showToast(`✅ ${ids.length} project(s) updated`,'success'); loadBulkOperations();
}

async function bulkUpdateCustomers(){
  const ids=[...document.querySelectorAll('.bulk-cust-cb:checked')].map(c=>c.value);
  if(!ids.length){ showToast('Select at least one customer','warning'); return; }
  const status=document.getElementById('bulk-cust-status')?.value;
  if(!status){ showToast('Select a status to apply','warning'); return; }
  if(!confirm(`Update ${ids.length} customer(s) to "${status}"?`)) return;
  const {error}=await sb.from('crm_customers').update({status,updated_at:new Date().toISOString()}).in('id',ids);
  if(error){ showToast('Error: '+error.message,'error'); return; }
  showToast(`✅ ${ids.length} customer(s) updated`,'success'); loadBulkOperations();
}

async function bulkApproveVendors(approve){
  const ids=[...document.querySelectorAll('.bulk-vend-cb:checked')].map(c=>c.value);
  if(!ids.length){ showToast('Select at least one vendor','warning'); return; }
  const action=approve?'approve':'blacklist';
  if(!confirm(`${action} ${ids.length} vendor(s)?`)) return;
  const update=approve?{is_approved:true,status:'active'}:{is_approved:false,status:'blacklisted'};
  const {error}=await sb.from('vendors').update(update).in('id',ids);
  if(error){ showToast('Error: '+error.message,'error'); return; }
  showToast(`✅ ${ids.length} vendor(s) ${action}d`,'success'); loadBulkOperations();
}

async function bulkUpdateEmployees(){
  const ids=[...document.querySelectorAll('.bulk-emp-cb:checked')].map(c=>c.value);
  if(!ids.length){ showToast('Select at least one employee','warning'); return; }
  const status=document.getElementById('bulk-emp-status')?.value;
  if(!status){ showToast('Select a status to apply','warning'); return; }
  if(!confirm(`Update ${ids.length} employee(s) to "${status}"?`)) return;
  const {error}=await sb.from('employees').update({status,updated_at:new Date().toISOString()}).in('id',ids);
  if(error){ showToast('Error: '+error.message,'error'); return; }
  showToast(`✅ ${ids.length} employee(s) updated`,'success'); loadBulkOperations();
}

// ── FINANCIAL RATIOS PDF EXPORT ───────────────────────────────
async function exportRatiosPDF(){
  showToast('Opening print view...','info');
  try {
    var el = document.getElementById('page-ratios');
    var now = new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'});
    var printWin = window.open('','_blank');
    var html = '<html><head><title>SP360 Financial Ratios</title>'
      + '<style>'
      + 'body{font-family:Arial,sans-serif;font-size:11px;padding:20px;color:#1E293B}'
      + 'h1{color:#0F1E38;border-bottom:3px solid #C9A84C;padding-bottom:8px}'
      + 'table{width:100%;border-collapse:collapse;margin:12px 0}'
      + 'th{background:#0F1E38;color:#C9A84C;padding:6px 8px;text-align:left}'
      + 'td{border:1px solid #E2E8F0;padding:5px 8px}'
      + 'tr:nth-child(even){background:#F8FAFC}'
      + '@media print{body{padding:10px}}'
      + '</style></head>'
      + '<body>'
      + '<h1>SP360 v4.1 — Financial Ratios Report</h1>'
      + '<p style="color:#94A3B8;font-size:10px">Smart Projects 360 · Kuwait · ' + now + '</p>'
      + el.innerHTML
      + '</body></html>';
    printWin.document.write(html);
    printWin.document.close();
    setTimeout(function(){ printWin.print(); }, 800);
    showToast('Print dialog opened — save as PDF','success');
  } catch(e){
    showToast('Error: '+e.message,'error');
  }
}



async function loadWeeklyReport(){
  var el = document.getElementById('page-weekly');
  if(!el) return;
  el.innerHTML = '<div class="loading">Generating weekly report...</div>';
  try {
    var weekStart = new Date();
    weekStart.setDate(weekStart.getDate() - weekStart.getDay() + 1);
    var weekEnd = new Date(weekStart); weekEnd.setDate(weekStart.getDate() + 6);
    var fmtD = function(d){ return d.toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'}); };
    var period = fmtD(weekStart) + ' — ' + fmtD(weekEnd);
    var safeQ = async function(fn){ try{ var r=await fn(); return r.data||[]; }catch(e){ return []; }};
    var results = await Promise.all([
      safeQ(function(){ return sb.from('projects').select('id,project_no,name,status,cpi,spi'); }),
      safeQ(function(){ return sb.from('invoices').select('id,invoice_type,net_amount,status,due_date'); }),
      safeQ(function(){ return sb.from('workflow_items').select('id,status'); }),
      safeQ(function(){ return sb.from('ncrs').select('id,severity,status'); }),
      safeQ(function(){ return sb.from('project_milestones').select('id,name,planned_date,status,project_id'); }),
      safeQ(function(){ return sb.from('crm_opportunities').select('id,stage,estimated_value,probability'); }),
      safeQ(function(){ return sb.from('crm_leads').select('id,status,created_at'); }),
      safeQ(function(){ return sb.from('timesheets').select('id,hours_regular,hours_overtime,period,status'); }),
      safeQ(function(){ return sb.from('purchase_orders').select('id,status,po_value'); })
    ]);
    var projs=results[0], invs=results[1], wfs=results[2], ncrs=results[3];
    var msData=results[4], crmOpps=results[5], crmLeads=results[6], tsData=results[7], pos=results[8];
    var today = new Date();
    var curPeriod = today.toISOString().slice(0,7);
    var activeProjs = projs.filter(function(p){ return ['planning','execution','monitoring','closeout'].includes(p.status); });
    var portCPI = activeProjs.length ? activeProjs.reduce(function(s,p){ return s+Number(p.cpi||1); },0)/activeProjs.length : 1;
    var portSPI = activeProjs.length ? activeProjs.reduce(function(s,p){ return s+Number(p.spi||1); },0)/activeProjs.length : 1;
    var critProjs = activeProjs.filter(function(p){ return Number(p.cpi||1)<0.9||Number(p.spi||1)<0.9; });
    var overdueMs = msData.filter(function(m){ return m.status==='pending'&&m.planned_date&&new Date(m.planned_date)<today; });
    var dueMs = msData.filter(function(m){ return m.status==='pending'&&m.planned_date&&(new Date(m.planned_date)-today)/86400000<=7; });
    var totalAR = invs.filter(function(i){ return i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status); }).reduce(function(s,i){ return s+Number(i.net_amount); },0);
    var overdueAR = invs.filter(function(i){ return i.invoice_type==='client'&&!['paid','cancelled'].includes(i.status)&&i.due_date&&new Date(i.due_date)<today; });
    var openNCR = ncrs.filter(function(n){ return n.status==='open'; });
    var critNCR = ncrs.filter(function(n){ return n.status==='open'&&n.severity==='critical'; });
    var pipeline = crmOpps.filter(function(o){ return !['won','lost'].includes(o.stage); }).reduce(function(s,o){ return s+Number(o.estimated_value); },0);
    var monthHours = tsData.filter(function(t){ return t.period===curPeriod; }).reduce(function(s,t){ return s+Number(t.hours_regular||0)+Number(t.hours_overtime||0); },0);
    var rag = function(v,g,w){ return v>=g?'#10B981':v>=w?'#F97316':'#EF4444'; };
    var mRow = function(l,v,s,col){
      return '<div style="display:flex;justify-content:space-between;padding:7px 0;border-bottom:1px solid var(--bdr)">'
        +'<span style="font-size:11px;color:var(--muted)">'+l+'</span>'
        +'<div style="text-align:right"><span style="font-size:13px;font-weight:700;color:'+(col||'var(--text)')+'">'+v+'</span>'
        +(s?'<div style="font-size:9px;color:var(--faint)">'+s+'</div>':'')+'</div></div>';
    };
    var msRows = '';
    var msList = overdueMs.concat(dueMs).slice(0,8);
    for(var mi=0;mi<msList.length;mi++){
      var m=msList[mi];
      var proj=null;
      for(var pi=0;pi<projs.length;pi++){ if(projs[pi].id===m.project_id){ proj=projs[pi]; break; }}
      var dDiff=Math.ceil((new Date(m.planned_date)-today)/86400000);
      var isOv=dDiff<0;
      msRows+='<tr style="background:'+(isOv?'#EF444408':'#F9731608')+'">'
        +'<td style="color:var(--gold);font-size:10px">'+esc(proj?proj.project_no:'--')+'</td>'
        +'<td style="font-weight:600;font-size:11px">'+esc(m.name)+'</td>'
        +'<td style="font-size:10px">'+new Date(m.planned_date).toLocaleDateString('en-GB',{day:'2-digit',month:'short',year:'numeric'})+'</td>'
        +'<td style="font-size:10px;font-weight:700;color:'+(isOv?'#EF4444':'#F97316')+'">'+(isOv?Math.abs(dDiff)+'d overdue':dDiff+'d left')+'</td>'
        +'</tr>';
    }
    el.innerHTML = '<div class="page-head"><div class="page-head-left"><div>'
      +'<h1>Executive Weekly Report</h1>'
      +'<div class="sub">Auto-generated - '+period+'</div>'
      +'</div></div>'
      +'<div style="display:flex;gap:8px">'
      +'<button class="btn btn-ghost" data-h-click="h486">Print / PDF</button>'
      +'<button class="btn btn-ghost" data-h-click="h487">Refresh</button>'
      +'</div></div>'
      +'<div id="weekly-report-content">'
      +'<div style="background:var(--card2);border:1px solid var(--bdr);border-radius:11px;padding:16px 20px;margin-bottom:14px">'
      +'<div style="font-size:10px;color:var(--gold);font-weight:700;text-transform:uppercase;margin-bottom:10px">Executive Summary</div>'
      +'<div style="display:grid;grid-template-columns:repeat(6,1fr);gap:8px">'
      +'<div style="text-align:center;padding:9px;background:var(--card);border-radius:7px;border:1px solid var(--bdr)"><div style="font-size:9px;color:var(--muted)">Active Projects</div><div style="font-size:16px;font-weight:800;color:var(--blue)">'+activeProjs.length+'</div></div>'
      +'<div style="text-align:center;padding:9px;background:var(--card);border-radius:7px;border:1px solid var(--bdr)"><div style="font-size:9px;color:var(--muted)">Portfolio CPI</div><div style="font-size:16px;font-weight:800;color:'+rag(portCPI,1,0.9)+'">'+portCPI.toFixed(2)+'</div></div>'
      +'<div style="text-align:center;padding:9px;background:var(--card);border-radius:7px;border:1px solid var(--bdr)"><div style="font-size:9px;color:var(--muted)">Portfolio SPI</div><div style="font-size:16px;font-weight:800;color:'+rag(portSPI,1,0.9)+'">'+portSPI.toFixed(2)+'</div></div>'
      +'<div style="text-align:center;padding:9px;background:var(--card);border-radius:7px;border:1px solid var(--bdr)"><div style="font-size:9px;color:var(--muted)">Outstanding AR</div><div style="font-size:13px;font-weight:800;color:'+(overdueAR.length>0?'#EF4444':'var(--gold)')+'">'+fmtKWD(totalAR)+'</div></div>'
      +'<div style="text-align:center;padding:9px;background:var(--card);border-radius:7px;border:1px solid var(--bdr)"><div style="font-size:9px;color:var(--muted)">CRM Pipeline</div><div style="font-size:13px;font-weight:800;color:var(--violet)">'+fmtKWD(pipeline)+'</div></div>'
      +'<div style="text-align:center;padding:9px;background:var(--card);border-radius:7px;border:1px solid var(--bdr)"><div style="font-size:9px;color:var(--muted)">Open NCRs</div><div style="font-size:16px;font-weight:800;color:'+(critNCR.length>0?'#EF4444':openNCR.length>0?'#F97316':'#10B981')+'">'+openNCR.length+'</div></div>'
      +'</div></div>'
      +'<div style="display:grid;grid-template-columns:1fr 1fr;gap:14px">'
      +'<div class="card"><div style="font-size:11px;font-weight:800;color:#3B82F6;margin-bottom:10px">Project Controls</div>'
      +mRow('Active Projects',activeProjs.length,projs.filter(function(p){return p.status==='completed';}).length+' completed')
      +mRow('Portfolio CPI',portCPI.toFixed(3),'',rag(portCPI,1,0.9))
      +mRow('Portfolio SPI',portSPI.toFixed(3),'',rag(portSPI,1,0.9))
      +mRow('At-Risk Projects',critProjs.length,'CPI or SPI < 0.90',critProjs.length>0?'#EF4444':'#10B981')
      +mRow('Overdue Milestones',overdueMs.length,dueMs.length+' due in 7 days',overdueMs.length>0?'#EF4444':'#10B981')
      +'</div>'
      +'<div class="card"><div style="font-size:11px;font-weight:800;color:#10B981;margin-bottom:10px">Finance</div>'
      +mRow('Outstanding AR',fmtKWD(totalAR),'','var(--gold)')
      +mRow('Overdue AR',overdueAR.length+' invoices','',overdueAR.length>0?'#EF4444':'#10B981')
      +mRow('Pending Approvals',wfs.filter(function(w){return w.status==='pending'||w.status==='overdue';}).length,'in workflow')
      +mRow('Open POs',pos.filter(function(p){return !['received','cancelled'].includes(p.status);}).length,'')
      +'</div>'
      +'<div class="card"><div style="font-size:11px;font-weight:800;color:#8B5CF6;margin-bottom:10px">CRM Pipeline</div>'
      +mRow('Active Pipeline',fmtKWD(pipeline),'','var(--violet)')
      +mRow('Opportunities',crmOpps.filter(function(o){return !['won','lost'].includes(o.stage);}).length,'active')
      +mRow('In Negotiation',crmOpps.filter(function(o){return o.stage==='negotiation';}).length,'','#8B5CF6')
      +mRow('Won Total',crmOpps.filter(function(o){return o.stage==='won';}).length,'converted','#10B981')
      +'</div>'
      +'<div class="card"><div style="font-size:11px;font-weight:800;color:#F97316;margin-bottom:10px">QHSE & Operations</div>'
      +mRow('Open NCRs',openNCR.length,'',openNCR.length>0?'#F97316':'#10B981')
      +mRow('Critical NCRs',critNCR.length,'',critNCR.length>0?'#EF4444':'#10B981')
      +mRow('Man-Hours This Month',monthHours.toFixed(0)+'h','','var(--blue)')
      +mRow('Pending Timesheets',tsData.filter(function(t){return t.status==='submitted';}).length,'awaiting approval')
      +'</div>'
      +'</div>'
      +(msList.length>0?'<div class="card" style="margin-top:14px"><div style="font-size:11px;font-weight:700;color:#EF4444;margin-bottom:8px">Upcoming & Overdue Milestones</div><table class="tbl"><thead><tr><th>Project</th><th>Milestone</th><th>Planned</th><th>Status</th></tr></thead><tbody>'+msRows+'</tbody></table></div>':'')
      +'<div style="text-align:center;padding:14px;color:var(--faint);font-size:10px;margin-top:14px;border-top:1px solid var(--bdr)">Auto-generated by SP360 v4.1 - Smart Projects 360 - Kuwait - '+new Date().toLocaleString('en-GB')+'</div>'
      +'</div>';
  } catch(ex){ pageError('page-weekly',ex); }
}

function printWeeklyReport(){
  var content = document.getElementById('weekly-report-content');
  if(!content){ showToast('Report not loaded yet','warning'); return; }
  var printWin = window.open('','_blank');
  var now = new Date().toLocaleDateString('en-GB',{day:'2-digit',month:'long',year:'numeric'});
  printWin.document.write('<html><head><title>SP360 Weekly Report</title>'
    +'<style>body{font-family:Arial,sans-serif;font-size:11px;padding:20px;color:#1E293B;background:#fff}'
    +'h1{color:#0F1E38;font-size:16px}.card{border:1px solid #E2E8F0;border-radius:8px;padding:14px;margin-bottom:12px;break-inside:avoid}'
    +'table{width:100%;border-collapse:collapse}th{background:#0F1E38;color:#C9A84C;padding:5px 8px;font-size:10px}td{border:1px solid #E2E8F0;padding:4px 7px;font-size:10px}'
    +'@media print{body{padding:10px}}</style></head><body>'
    +'<h1>SP360 v4.1 - Executive Weekly Report</h1>'
    +'<p style="color:#94A3B8;font-size:10px">Smart Projects 360 - Kuwait - '+now+'</p>'
    +content.innerHTML
    +'</body></html>');
  printWin.document.close();
  setTimeout(function(){ printWin.print(); }, 600);
}


