(function(){
  const TYPES=['click','change','input','keydown','keyup','dragover','dragleave','drop','submit','focusin','focusout'];
  const run=(type,ev)=>{
    const attr='data-h-'+type, path=[];
    for(let n=ev.target; n && n.nodeType===1; n=n.parentElement){ if(n.hasAttribute(attr)) path.push(n); }
    for(const n of path){
      const fn=__H[n.getAttribute(attr)];
      if(typeof fn!=='function') continue;
      let args=[];
      const raw=n.getAttribute('data-ha-'+type);
      if(raw){ try{ args=JSON.parse(raw); }catch(e){ console.error('Bad handler args',e); } }
      let r;
      try{ r=fn.call(n,ev,args); }catch(e){ console.error(e); setTimeout(()=>{ throw e; }); }
      if(r===false) ev.preventDefault();
      if(ev.cancelBubble) break;   // event.stopPropagation() inside a handler stops outer handlers, as before
    }
  };
  TYPES.forEach(t=>document.addEventListener(t,ev=>run(t,ev)));
})();
